// Generated — per-app "Try it yourself" guide built around each app's surprise: missions {do, wow} (what to do, what surprises you), two ways to bring that surprise into your own app, one question. KO/EN.
// Rewritten on 2026-10-17 for the 264 apps in the ADA archive and field guide, using only facts in insights-data.js, wow-data.js and the field guide observation points.
window.TRY_DATA = {"written":"2026-10-17","apps":{"grug":{"time":5,"setup":null,"missions":[{"do":{"ko":"오늘의 문구가 뜰 때 아무것도 누르지 말고 마지막 획까지 지켜본 뒤, 상태 표시줄과 위젯 글자도 살펴보세요.","en":"When today's lesson appears, touch nothing and watch until the last stroke, then look at the status bar and widget text too."},"wow":{"ko":"글자가 찍히는 게 아니라 두 사람이 직접 만든 엔진이 손글씨 획을 한 획씩 그려요. 상태 표시줄과 위젯까지 같은 손글씨예요.","en":"The letters aren't stamped on; an engine the two-person team built draws each handwritten stroke one at a time. Even the status bar and widget share that hand."}},{"do":{"ko":"릴리스 노트와 탭 바의 날짜처럼 보통 시스템 글꼴이 나올 자리를 일부러 찾아 열어 보세요.","en":"Deliberately seek out places where you'd expect the system font, like the release notes and the tab bar dates."},"wow":{"ko":"평범한 iOS 화면이 나올 거라 예상한 곳까지 손글씨가 이어져요. 일러스트 목소리가 표준 UI 표면까지 퍼질 수 있다는 증거예요.","en":"The handwriting carries on exactly where you expected plain iOS UI. It proves an illustrated voice can extend into standard system surfaces."}},{"do":{"ko":"문구 위에 직접 그림을 그려 공유하고 홈 화면 위젯에 고정해 보세요. 로그인 없이 되는지도 확인해 보세요.","en":"Draw on the lesson, share it and pin it to a Home Screen widget. Notice whether any login is required."},"wow":{"ko":"로그인도 클라우드 동기화도 없이 하루 한 문구, 그리기, 공유, 위젯이 전부예요. 기능이 적은데도 작은 의식처럼 느껴져요.","en":"No login, no cloud sync: one lesson a day, drawing, sharing and a widget are all there is. So little, yet it feels like a tiny ritual."}}],"make":[{"ko":"짧은 문구 하나를 SVG 경로로 만들고 SwiftUI의 trim 애니메이션으로 한 획씩 써지게 해 보세요.","en":"Turn one short phrase into an SVG path and use a SwiftUI trim animation so it writes itself stroke by stroke."},{"ko":"내 앱에서 시스템 글꼴이 그대로 보이는 곳 세 군데(날짜, 빈 화면, 설정 등)를 찾아 브랜드 목소리로 바꾼 목업을 만들어 보세요.","en":"Find three places in your app where the stock system font shows (dates, empty states, settings) and mock them up in your brand's voice."}],"ask":{"ko":"손글씨가 문구 하나가 아니라 상태 표시줄까지 이어질 때 왜 앱이 훨씬 살아 있다고 느껴질까요?","en":"Why does the app feel so much more alive when the handwriting reaches all the way to the status bar, not just the quote?"}},"Sago Mini Jinja's Garden":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요하고, 3~6세 아이와 함께 해 보면 가장 잘 보여요.","en":"Requires Apple Arcade, and it shows best when you play it with a child aged 3 to 6."},"missions":[{"do":{"ko":"3~6세 아이에게 아무 설명 없이 화면을 건네고, 아이가 스와이프로 정원을 돌아다니는 모습을 지켜보세요.","en":"Hand the device to a 3 to 6 year old with no explanation and watch them swipe their way around the garden."},"wow":{"ko":"글을 못 읽어도 스와이프만으로 3D 정원을 누비며 씨 뿌리고, 요리하고, 수확해요. 이 게임 하나가 같은 해 ADA 인터랙션 수상과 포용성 결선을 받았어요.","en":"Without reading a word, the child roams a 3D garden, planting, cooking and harvesting by swiping. This one game won ADA Interaction and was an Inclusivity finalist the same year."}},{"do":{"ko":"일부러 할 일을 끝내지 말고 한참 딴짓을 하거나 엉뚱한 곳을 돌아다녀 보세요.","en":"Deliberately leave tasks unfinished and wander off to random places for a while."},"wow":{"ko":"타이머도 실패 상태도 없어서 아무것도 망가지지 않아요. 과제가 열려 있어 아이가 자기 속도로 놀 수 있어요.","en":"With no timers and no fail states, nothing ever breaks. Tasks are open-ended, so kids play at their own pace."}},{"do":{"ko":"비행기 모드로 바꾸고 다시 정원에 들어가 보세요. Apple TV가 있다면 컨트롤러로 TV에서도 열어 보세요.","en":"Switch to Airplane Mode and go back into the garden. If you have an Apple TV, open it there with a controller too."},"wow":{"ko":"광고도 없고 오프라인에서도 온전히 돌아가요. 같은 정원을 가족 TV에서 컨트롤러로 할 수도 있어요.","en":"It has no ads and plays fully offline. The same garden also runs on the family TV with a controller."}}],"make":[{"ko":"글자 없이 스와이프 하나로만 움직이는 화면을 프로토타입으로 만들고 처음 보는 사람에게 설명 없이 건네 보세요.","en":"Prototype a screen that works with a single swipe and no text, then hand it to someone new without explaining anything."},{"ko":"내 앱에서 실패나 시간 제한이 뜨는 곳을 하나 골라, 그냥 계속 해 볼 수 있는 상태로 바꾼 흐름을 그려 보세요.","en":"Pick one place in your app that shows a failure or time limit and sketch a flow where the user can simply keep trying."}],"ask":{"ko":"실패와 타이머를 없앴는데도 아이가 계속 놀게 만드는 동기는 어디서 나올까요?","en":"With failure and timers removed, where does the motivation to keep playing come from?"}},"Tide Guide: Charts & Tables":{"time":10,"setup":null,"missions":[{"do":{"ko":"아침, 한낮, 해 질 녘처럼 다른 시간에 앱을 열어 배경 색을 비교해 보세요.","en":"Open the app at different times, such as morning, midday and sunset, and compare the background colors."},"wow":{"ko":"팔레트가 실제 하늘색을 따라 하루 동안 바뀌어요. 시계를 보지 않아도 테마만으로 지금이 몇 시쯤인지 느껴져요.","en":"The palette follows the real color of the sky through the day. Without checking a clock, the theme alone tells you roughly what time it is."}},{"do":{"ko":"전면 조수 차트를 열고 곡선을 손가락으로 천천히 훑어 보세요.","en":"Open the full-screen tide chart and slowly drag your finger along the curve."},"wow":{"ko":"손가락을 따라 시간별 수위가 정확히 읽히고 데이터 위에 커스텀 애니메이션이 얹혀 있어요. 표가 아니라 물이 움직이는 느낌이에요.","en":"Hour-by-hour water height reads out exactly under your finger, with custom animation layered on the data. It feels like moving water, not a table."}},{"do":{"ko":"조수 곡선과 같은 화면에서 해와 달 정보를 찾아보세요.","en":"Look for the Sun and Moon data on the same view as the tide curve."},"wow":{"ko":"일출과 일몰, 월출과 월몰, 박명, 달의 위상까지 조수 곡선 옆에 함께 그려져 하루 전체가 한 화면에 읽혀요.","en":"Sunrise and sunset, moonrise and moonset, twilight and moon phase are drawn beside the tide curve, so the whole day reads in one view."}},{"do":{"ko":"홈 화면 위젯을 추가하거나 Live Activity를 켜서 앱을 열지 않고 조수를 확인해 보세요.","en":"Add a Home Screen widget or start a Live Activity and check the tide without opening the app."},"wow":{"ko":"위젯, 다이내믹 아일랜드의 Live Activity, Siri, 단축어, 제어 센터까지 앱이 플랫폼 구석구석에 닿아 있어요.","en":"Widgets, a Live Activity in the Dynamic Island, Siri, Shortcuts and Control Center: the app reaches into every corner of the platform."}}],"make":[{"ko":"내 앱 배경색을 현재 시각에 따라 바꾸는 SwiftUI 뷰를 만들고 아침, 낮, 밤 세 단계로 확인해 보세요.","en":"Build a SwiftUI view that changes your app's background with the current time and check it at morning, day and night."},{"ko":"Swift Charts 차트 하나에 드래그 제스처를 붙여 손가락 위치의 값을 바로 보여 주는 스크러빙을 구현해 보세요.","en":"Add a drag gesture to one Swift Charts chart so it shows the value under your finger as you scrub."}],"ask":{"ko":"색이 시간을 알려 주는 방식은 숫자로 시간을 보여 주는 것과 무엇이 다를까요?","en":"How is letting color tell the time different from showing the time as numbers?"}},"Cyberpunk 2077 Ultimate Edition":{"time":30,"setup":{"ko":"Apple silicon Mac 전용이고 ₩92,900이에요. 헤드 트래킹 공간 음향을 느끼려면 AirPods가 있으면 좋아요.","en":"Mac only, for Apple silicon, at ₩92,900. AirPods let you feel the head-tracked Spatial Audio."},"missions":[{"do":{"ko":"Apple silicon Mac에서 Mac 전용 프리셋 그대로 게임을 시작해 붐비는 거리로 나가 보세요.","en":"Start the game on an Apple silicon Mac with its Mac-specific preset and head out into a crowded street."},"wow":{"ko":"PC에서도 그래픽카드를 혹사시키던 오픈월드 AAA 게임이 Mac App Store에서 그대로 돌아가요. M1 이상 전 기종을 지원해요.","en":"An open-world AAA game that strains graphics cards even on PC runs as-is from the Mac App Store, on every Apple silicon Mac from M1 up."}},{"do":{"ko":"그래픽 설정에 MetalFX 관련 옵션이 보이면 켜고 끄며 움직임의 부드러움을 비교해 보세요.","en":"If you see MetalFX options in the graphics settings, toggle them and compare how smooth motion feels."},"wow":{"ko":"Metal 4 프레임 보간은 렌더링한 두 프레임마다 한 프레임을 생성해, 업스케일링과 함께 Ultra에서 최대 120fps를 노려요.","en":"Metal 4 Frame Interpolation generates one frame for every two rendered, aiming for up to 120 fps on Ultra with upscaling."}},{"do":{"ko":"AirPods를 끼고 게임 속에서 고개를 천천히 좌우로 돌려 보세요.","en":"Put on AirPods and slowly turn your head left and right during play."},"wow":{"ko":"헤드 트래킹 공간 음향이 내장돼 있어 소리가 장면에 붙어 있어요. 플랫폼 기능을 체크 항목이 아니라 아트 디렉션으로 썼어요.","en":"Head-tracked Spatial Audio is built in, so sound stays anchored to the scene. Platform features are used as art direction, not checkboxes."}},{"do":{"ko":"사람과 물건이 빽빽한 실내에 들어가 주변을 천천히 둘러보세요.","en":"Walk into a dense, cluttered interior and look around slowly."},"wow":{"ko":"Apple이 기술적으로 까다롭다고 한 실내, 캐릭터, 차량 디자인이 Mac GPU가 어디까지 그릴 수 있는지 보여 줘요.","en":"The interiors, characters and vehicles Apple called technically demanding show how much a Mac GPU can render."}}],"make":[{"ko":"내 게임이나 앱에서 기기 칩을 확인해 기본 그래픽 품질을 자동으로 고르는 프리셋 로직을 간단히 만들어 보세요.","en":"Write simple preset logic in your game or app that checks the device's chip and picks a default graphics quality."},{"ko":"PHASE나 AVAudioEngine으로 효과음 하나를 공간의 한 지점에 배치하고 AirPods로 고개를 돌리며 들어 보세요.","en":"Use PHASE or AVAudioEngine to place one sound at a point in space and listen with AirPods while turning your head."}],"ask":{"ko":"칩별 프리셋은 PC 이식작을 어렵게 느끼게 하던 무엇을 덜어 줬을까요?","en":"What burden that usually makes PC ports intimidating did the per-chip presets remove?"}},"Evolve: Daily Self-Care Coach":{"time":10,"setup":null,"missions":[{"do":{"ko":"처음 시작할 때 나오는 개인화 질문에 답하며 콘텐츠의 말투가 누구를 향하는지 살펴보세요.","en":"Answer the personalization questions at the start and notice who the content's tone is speaking to."},"wow":{"ko":"일반 멘탈헬스 앱에서 2021년 LGBTQ+ 우선으로 방향을 튼 앱이라, 커밍아웃 지원처럼 주류 웰니스 앱이 놓친 맥락이 바로 보여요.","en":"It pivoted from a general mental health app to LGBTQ+ first in 2021, so context mainstream wellness apps miss, like coming-out support, shows up right away."}},{"do":{"ko":"기분이나 습관 기록을 하루 일부러 건너뛴 뒤 다시 열어 보세요.","en":"Deliberately skip a day of mood or habit tracking, then open the app again."},"wow":{"ko":"'압박 없는 진전'을 내세워 유연한 일정과 적응형 알림으로 짜여 있어요. 신경다양인 사용자를 기준으로 설계했어요.","en":"It is built around 'progress without pressure', with flexible scheduling and adaptive reminders designed with neurodivergent users in mind."}},{"do":{"ko":"iPhone 설정에서 큰 글자, 다크 모드, 동작 줄이기, 고대비를 켜고 앱을 다시 둘러보세요.","en":"In iPhone Settings, turn on larger text, dark mode, Reduce Motion and high contrast, then browse the app again."},"wow":{"ko":"색 없이도 구분되게 만든 화면이 이 설정들에서도 버텨요. 이 지원이 ADA 포용성 부문 후보에 오른 바탕이에요.","en":"Screens designed to differentiate without color hold up under all these settings. That support fed its ADA Inclusivity nomination."}}],"make":[{"ko":"내 앱의 온보딩 질문 하나를 특정 커뮤니티의 언어로 다시 써서 원래 문장과 나란히 비교해 보세요.","en":"Rewrite one onboarding question in your app in the language of a specific community and compare it side by side with the original."},{"ko":"기록을 놓친 날 사용자를 탓하지 않는 문구와 화면 하나를 만들어 보세요.","en":"Design one screen and message for a missed day that doesn't blame the user."}],"ask":{"ko":"대상을 좁혔는데 왜 그 사람들에게는 더 크게 와닿을까요?","en":"Why does narrowing the audience make the app land harder for the people it serves?"}},"Gears & Goo":{"time":20,"setup":{"ko":"Apple Vision Pro 전용이고 Apple Arcade 구독이 필요해요. 컨트롤러는 없어도 돼요.","en":"Apple Vision Pro only and requires Apple Arcade. No controller needed."},"missions":[{"do":{"ko":"컨트롤러 없이 유닛을 바라본 채 손가락을 집어 들어 올리고, 기울어진 공중 섬 전장을 내려다보세요.","en":"With no controller, look at a unit and pinch to pick it up, then look down over the tilted floating-island battlefield."},"wow":{"ko":"보고 집기만 하면 유닛이 손에 들려요. 지저분한 실제 책상 대신 눈높이에 맞게 기울어진 공중 섬이라 목도 편하고 전장 전체가 보여요.","en":"Just look and pinch and the unit is in your hand. Instead of a messy real desk, the island floats tilted toward you, easy on the neck with the whole field in view."}},{"do":{"ko":"메뉴 항목을 눈으로 보고 집는 방식으로 빠르게 연달아 골라 보세요.","en":"Pick several menu items in quick succession by looking and pinching."},"wow":{"ko":"개발사는 시선과 집기로 메뉴를 고르는 게 데스크톱 마우스보다 빠르다는 걸 발견했어요.","en":"The developer found gaze-plus-pinch menu selection to be faster than a desktop mouse."}},{"do":{"ko":"유닛을 정확한 자리에 떨어뜨려 보고, 놓기 직전의 위치 표시를 살펴보세요.","en":"Try to drop a unit on an exact spot and watch the placement indicator just before you let go."},"wow":{"ko":"레이저 포인터 같은 배치 표시가 손 추적의 부정확함을 메워 줘서 정밀하게 놓을 수 있어요.","en":"A laser-pointer-style indicator compensates for the imprecision of hand tracking, so placement feels precise."}},{"do":{"ko":"고개를 돌려 전장 주변 소리를 들어 보며 금속, 돌, 반투명 슬라임이 내 방과 어울리는지 보세요.","en":"Turn your head to listen around the battlefield and see how metal, stone and translucent slime sit in your room."},"wow":{"ko":"재질이 패스스루 화면과 섞이도록 렌더링되고, 공간 음향이 디오라마 주변에 혼돈을 배치해요.","en":"Materials are rendered to blend with passthrough, and spatial audio spreads the chaos around the diorama."}}],"make":[{"ko":"visionOS 프로토타입에서 콘텐츠를 테이블 높이 대신 위로 기울인 판 위에 올려 보고 목 각도를 비교해 보세요.","en":"In a visionOS prototype, put content on an upward-tilted board instead of at table height and compare the neck angle."},{"ko":"손 추적 입력에 놓일 위치를 미리 보여 주는 표시를 붙이고 정밀도가 어떻게 달라지는지 확인해 보세요.","en":"Add an indicator that previews where a hand-tracked drop will land and see how precision changes."}],"ask":{"ko":"실제 책상을 포기한 결정이 왜 오히려 더 좋은 경험이 됐을까요?","en":"Why did giving up on the real desk end up making the experience better?"}},"Ahoy! From Picardy":{"time":20,"setup":{"ko":"Apple Vision Pro 전용이고 ₩7,700이에요. 무대 주위를 걸어 다닐 공간이 있으면 좋아요.","en":"Apple Vision Pro only, at ₩7,700. Have enough room to walk around the stage."},"missions":[{"do":{"ko":"무대를 띄운 뒤 일어나서 디오라마 주위를 한 바퀴 걸으며 모형과 배경을 가까이 들여다보세요.","en":"Once the stage appears, stand up, walk all the way around the diorama and look closely at the models and backdrops."},"wow":{"ko":"손으로 만든 미니어처를 3D 스캔하고 배경까지 손으로 칠했어요. 디지털 기기 안에 수작업 디오라마가 그대로 들어앉아 있어요.","en":"Handmade miniatures were 3D-scanned and even the backdrops were hand-painted. A handcrafted diorama sits whole inside a digital device."}},{"do":{"ko":"이야기 도중 무대를 옮겨 보고, 정면이 아닌 옆이나 뒤에서 장면을 봐 보세요.","en":"Move the stage mid-story and watch a scene from the side or back instead of the front."},"wow":{"ko":"평평한 프레임 대신 공간으로 구도를 짜서 어느 각도에서 봐도 장면이 성립해요.","en":"Composition uses space instead of a flat frame, so the scene works from any angle."}},{"do":{"ko":"16분 동안 끊지 말고 음악을 따라가며, 손을 써야 하는 순간이 오면 반응해 보세요.","en":"Watch the full 16 minutes without stopping, following the music, and respond when a moment invites your hand."},"wow":{"ko":"게임이 아니라 음악이 이끄는 공간 단편 영화이고 은은한 인터랙션이 끼어들어요. 한 번 앉은 자리에서 끝나는 길이예요.","en":"It's a music-driven spatial short film, not a game, with subtle interactive moments, sized for a single sitting."}}],"make":[{"ko":"손으로 만든 작은 물건 하나를 iPhone 3D 스캔 앱으로 스캔해 AR로 내 책상 위에 띄워 보세요.","en":"Scan one small handmade object with a 3D scanning app on iPhone and place it on your desk in AR."},{"ko":"내 앱 화면 하나를 깊이별 층으로 나눠, 옆에서 봐도 의미가 있는 구도를 스케치해 보세요.","en":"Split one screen of your app into depth layers and sketch a composition that still makes sense viewed from the side."}],"ask":{"ko":"손으로 만든 질감은 헤드셋 안에서 왜 더 강하게 느껴질까요?","en":"Why does a handmade texture feel even stronger inside a headset?"}},"WHAT THE CAR?":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires Apple Arcade."},"missions":[{"do":{"ko":"첫 몇 레벨을 연달아 해 보며 매 레벨 차가 무엇으로 바뀌는지 미리 맞혀 보세요.","en":"Play the first few levels back to back and try to guess what the car will turn into each time."},"wow":{"ko":"차에 다리가 돋아 달리고, 점프하고, 벽을 오르기도 해요. 레벨마다 '차'의 뜻을 뒤집는 개그가 거의 100가지예요.","en":"The car sprouts legs to run, jump and even climb walls. Nearly 100 different gags each flip what 'car' means."}},{"do":{"ko":"화면의 기어 스틱과 핸들만으로 조작해 보고, 컨트롤러가 있다면 바꿔서도 해 보세요.","en":"Play using only the on-screen gear stick and steering wheel, then switch to a controller if you have one."},"wow":{"ko":"메커닉은 엉뚱해도 조작은 기어와 핸들뿐이라 터치에서도 무슨 일이 일어나는지 바로 읽혀요.","en":"However absurd the mechanic, the controls stay a gear stick and a wheel, so what's happening reads instantly even on touch."}},{"do":{"ko":"글자를 읽지 않는다는 생각으로 한 에피소드를 해 보고, 무엇 때문에 웃었는지 떠올려 보세요.","en":"Play one episode as if you couldn't read, then recall what actually made you laugh."},"wow":{"ko":"텍스트가 거의 없이 시각 개그와 물리 개그만으로 웃겨서 언어와 나이를 가리지 않아요.","en":"With almost no text, visual and physics gags carry the humor, so it works across languages and ages."}}],"make":[{"ko":"내 앱의 핵심 동작 하나를 정하고 그 의미를 비튼 변형 세 개를 종이 프로토타입으로 만들어 보세요.","en":"Pick one core action in your app and paper-prototype three variations that twist what it means."},{"ko":"글자 없이 결과만 보고 웃음이나 놀람이 나오는 짧은 애니메이션 하나를 만들어 보세요.","en":"Make one short animation that gets a laugh or a surprise from the result alone, with no text."}],"ask":{"ko":"매 레벨 규칙이 바뀌는데도 헷갈리지 않는 이유는 무엇일까요?","en":"Why doesn't it get confusing even though the rules change every level?"}},"Copilot Money":{"time":15,"setup":{"ko":"미국 스토어 앱이고, 미국 금융 계좌 연결과 구독이 필요해요.","en":"A US App Store app that needs US financial accounts to link and a subscription."},"missions":[{"do":{"ko":"계좌를 연결하고 대시보드를 열어, Mint 종료 뒤 갈 곳을 찾던 사용자 입장에서 첫 화면을 봐 보세요.","en":"Link your accounts, open the dashboard and look at it as a Mint user searching for a new home after the shutdown."},"wow":{"ko":"Mint 종료 발표 뒤 4개월 동안 앞선 4년보다 더 성장했고 발표 당일이 회사 최고의 날이었어요. 광고 없는 네이티브 화면이 그 대안이었어요.","en":"In the four months after Mint's shutdown was announced it grew more than in the previous four years, and announcement day was its best ever. An ad-free native app was the alternative."}},{"do":{"ko":"자동 분류된 거래 하나를 일부러 다른 카테고리로 고친 뒤, 비슷한 거래가 어떻게 분류되는지 지켜보세요.","en":"Deliberately recategorize one automatically sorted transaction, then watch how similar transactions get sorted."},"wow":{"ko":"머신러닝이 내 수정에 맞춰 개인화돼요. Copilot은 이 방식으로 직접 재분류하는 일을 50% 줄였다고 말해요.","en":"The machine learning personalizes to your corrections. Copilot says this cut manual recategorization by 50%."}},{"do":{"ko":"새 거래 확인 대기열을 열어 하나씩 확인해 보세요.","en":"Open the review queue for new transactions and confirm them one by one."},"wow":{"ko":"자동화를 조용히 믿지 않고 확인을 요청해요. 장부 정리를 시키지 않으면서도 사용자를 흐름 안에 둬요.","en":"Instead of silently trusting automation, it asks you to confirm, keeping you in the loop without making you do bookkeeping."}}],"make":[{"ko":"자동 분류 결과 옆에 확인과 수정 버튼을 둔 리스트를 만들고, 수정이 다음 추천에 반영되는 흐름을 목업으로 그려 보세요.","en":"Build a list with confirm and edit buttons next to each auto-sorted item, and mock up how an edit feeds the next suggestion."},{"ko":"경쟁 서비스가 사라질 때 넘어오는 사용자가 첫 화면에서 확인하고 싶을 것 세 가지를 적고 배치해 보세요.","en":"List three things users switching from a closing competitor would want to check on your first screen, and lay them out."}],"ask":{"ko":"AI가 틀릴 수 있는 곳에 확인 단계를 둔 것이 왜 오히려 신뢰를 높일까요?","en":"Why does adding a confirmation step where the AI might be wrong actually increase trust?"}},"The Wreck":{"time":30,"setup":{"ko":"무료로 받을 수 있지만 슬픔과 상실을 다루는 이야기라 조용한 시간에 해 보는 게 좋아요.","en":"Free to download, but it deals with grief and loss, so play it at a quiet time."},"missions":[{"do":{"ko":"첫 대화를 이어 가다가 주인공이 버거워지는 순간까지 가서 무슨 일이 일어나는지 지켜보세요.","en":"Carry the first conversation forward until the protagonist becomes overwhelmed, and watch what happens."},"wow":{"ko":"Junon이 감당하지 못하면 '사고'가 나고 그 대화를 다시 살아요. 스팀 첫 달 약 1,000장 팔린 게임이 같은 해 ADA와 App Store 어워드를 받았어요.","en":"When Junon is overwhelmed she 'crashes' and relives the conversation. A game that sold about 1,000 copies in its first Steam month won both an ADA and an App Store Award the same year."}},{"do":{"ko":"대답을 고르는 대신 화면에 떠오른 생각 단어를 눌러 대화를 이어 가 보세요.","en":"Instead of picking a reply, tap the thought words that surface on screen to move the conversation forward."},"wow":{"ko":"대사 선택지가 아니라 속마음을 뜻하는 단어를 눌러서, 인물의 머릿속을 직접 헤매는 느낌이 들어요.","en":"You tap words that stand for inner thoughts rather than reply options, so it feels like navigating the character's mind."}},{"do":{"ko":"기억 장면이 시작되면 서두르지 말고 3D로 연출된 장면을 끝까지 살펴보세요.","en":"When a memory sequence begins, don't rush; take in the 3D staging to the end."},"wow":{"ko":"영화처럼 연출된 3D 기억 장면이 비주얼 노벨 형식을 깨고 각 깨달음에 무게를 실어요.","en":"Cinematic 3D memory sequences break up the visual-novel format and give each revelation weight."}}],"make":[{"ko":"내 앱의 실패 순간 하나를 끝이 아니라 다시 해 보는 루프로 바꾼 흐름을 그려 보세요.","en":"Sketch a flow that turns one failure moment in your app into a loop you get to retry, not an ending."},{"ko":"선택지 버튼 대신 문장 속 단어를 눌러 진행하는 대화 화면 하나를 프로토타입으로 만들어 보세요.","en":"Prototype a dialogue screen where you advance by tapping words inside a sentence instead of choice buttons."}],"ask":{"ko":"같은 대화를 다시 사는 루프가 트라우마를 다루는 이야기에 왜 잘 맞을까요?","en":"Why does a loop of reliving the same conversation suit a story about trauma so well?"}},"djay":{"time":15,"setup":{"ko":"수상한 손 제스처 경험은 Apple Vision Pro 버전에서만 할 수 있고, iPhone에서는 턴테이블과 Neural Mix를 해 볼 수 있어요.","en":"The award-winning hand-gesture experience needs Apple Vision Pro; on iPhone you can try the turntables and Neural Mix."},"missions":[{"do":{"ko":"보컬이 뚜렷한 곡 하나를 불러온 뒤 Neural Mix로 보컬만 남기거나 드럼만 빼 보세요.","en":"Load a song with clear vocals, then use Neural Mix to keep only the vocals or drop just the drums."},"wow":{"ko":"아무 곡이나 보컬, 드럼, 악기가 실시간으로 분리돼요. 2020년에 이미 iPhone 안에서 이걸 해냈어요.","en":"Any song splits into vocals, drums and instruments in real time. It was already doing this inside an iPhone in 2020."}},{"do":{"ko":"턴테이블 화면에서 두 곡을 덱에 올리고 자동 믹스를 켜 보세요.","en":"On the turntable screen, load two songs onto the decks and turn on automatic mixing."},"wow":{"ko":"턴테이블 메타포와 자동 믹스 덕분에 장비 없는 초보자도 첫 믹스를 성공해요. DJ의 진입 장벽이 확 낮아져요.","en":"The turntable metaphor and auto mix let a beginner with no gear land a first mix. DJing's barrier to entry drops sharply."}},{"do":{"ko":"Vision Pro가 있다면 3D 턴테이블의 바늘을 손으로 옮기고, 한 손을 귀에 대 미리 듣기를 해 보세요.","en":"If you have a Vision Pro, move the needle on a 3D turntable by hand and raise a hand to your ear to preview a track."},"wow":{"ko":"손으로 레코드를 긁고, 귀에 손을 대는 몸짓만으로 헤드폰 미리 듣기가 돼요. 음악 라이브러리는 눈과 집기로 넘겨요.","en":"You scratch vinyl with your hands, and raising a hand to your ear previews in headphones. The library is browsed with your eyes and pinches."}}],"make":[{"ko":"보컬과 반주가 따로 있는 스템 파일 두 개를 AVAudioEngine으로 동시에 재생하고 각각 켜고 끄는 토글을 만들어 보세요.","en":"Play two stem files, vocals and backing, in sync with AVAudioEngine and add a toggle for each."},{"ko":"귀에 손을 대는 것처럼 실제 몸짓 하나를 골라 내 앱 기능과 연결하는 아이디어를 세 가지 적어 보세요.","en":"Pick a real-world gesture, like a hand to the ear, and write three ideas for linking it to a feature in your app."}],"ask":{"ko":"스템 분리가 전문가 기능이 아니라 초보자의 진입 장벽을 낮추는 기능이 된 이유는 무엇일까요?","en":"Why did stem separation become a way to lower the beginner's barrier rather than a pro feature?"}},"Ancient Board Game Collection":{"time":15,"setup":null,"missions":[{"do":{"ko":"게임 목록에서 라트룬쿨리와 바이킹 체스(흐네프타플)를 차례로 열어 보드 그림을 비교해 보세요.","en":"From the game list, open Latrunculi and then Viking chess (Hnefatafl) and compare the board artwork."},"wow":{"ko":"오스트리아 집에서 혼자 만든 앱인데 2,000년 된 게임까지 9개를 담고, 각 게임의 출신 지역 아티스트에게 보드를 맡겼어요.","en":"One person built it at home in Austria, packing in nine games up to 2,000 years old and hiring an artist from each game's home region."}},{"do":{"ko":"VoiceOver를 켜고 눈을 감은 채 AI와 한 판을 끝까지 해 보세요.","en":"Turn on VoiceOver, close your eyes and play a full game against the AI."},"wow":{"ko":"앱 전체가 VoiceOver만으로 완전히 플레이돼요. Apple이 동급 최고라 한 수준이라 앞을 못 봐도 전략 게임을 즐길 수 있어요.","en":"The whole app is fully playable with VoiceOver alone, at a level Apple called best-in-class, so blind players can enjoy strategy games."}},{"do":{"ko":"고대비 보드로 바꾸고, 말이 색이 아니라 모양이나 글자로 구분되는지 확인해 보세요.","en":"Switch to a high-contrast board and check whether pieces are told apart by shape or text rather than color."},"wow":{"ko":"색에만 기대지 않아서 저시력이나 색맹 사용자도 말을 헷갈리지 않아요.","en":"Because it doesn't rely on color alone, low-vision and color-blind players never mix up pieces."}},{"do":{"ko":"처음 보는 게임 하나를 골라 3~4문장 설명과 짧은 규칙 애니메이션만 보고 바로 시작해 보세요.","en":"Pick a game you've never heard of and start right after its three or four sentence explanation and short rules animation."},"wow":{"ko":"수천 년 된 낯선 규칙이 몇 문장과 짧은 애니메이션만으로 이해되고, 언제든 다시 볼 수 있어요.","en":"Unfamiliar rules thousands of years old make sense from a few sentences and a short animation you can replay anytime."}}],"make":[{"ko":"내 앱 화면 하나를 VoiceOver를 켜고 눈 감은 채 끝까지 써 보고, 막히는 곳마다 접근성 레이블을 붙여 보세요.","en":"Use one screen of your app with VoiceOver on and eyes closed, adding an accessibility label wherever you get stuck."},{"ko":"색으로만 구분되는 요소 하나를 찾아 모양이나 글자로도 구분되게 바꿔 보세요.","en":"Find one element distinguished only by color and make it distinguishable by shape or text too."}],"ask":{"ko":"접근성을 먼저 설계한 것이 보는 사람에게도 더 좋은 게임을 만든 이유는 무엇일까요?","en":"Why did designing for accessibility first also make a better game for sighted players?"}},"Shuffles by Pinterest":{"time":10,"setup":null,"missions":[{"do":{"ko":"콜라주 하나를 만든 뒤, 초대 코드 하나로 다섯 명만 부를 수 있다면 누구에게 보낼지 골라 보세요.","en":"Make one collage, then decide who you'd send it to if one invite code could only bring in five people."},"wow":{"ko":"정식 출시도 안 한 초대제 앱이 2022년 8월 미국 라이프스타일 1위에 올랐어요. 코드 하나에 다섯 명만 초대돼 틱톡에서 코드 쟁탈전이 벌어졌어요.","en":"An unlaunched, invite-only app hit number one in US Lifestyle in August 2022. Each code invited just five people, sparking a scramble for codes on TikTok."}},{"do":{"ko":"내 카메라로 찍은 사진에서 물건 하나를 한 번 탭으로 오려 콜라주에 붙여 보세요.","en":"Cut one object out of a photo from your own camera with a single tap and drop it into a collage."},"wow":{"ko":"한 번 탭에 물건만 떨어져 나와 콜라주가 스티커 붙이기처럼 빠르고 손맛 있게 돼요.","en":"One tap lifts the object out, turning collage-making into a fast, tactile sticker workflow."}},{"do":{"ko":"오려 낸 요소에 흔들기나 회전 같은 움직임을 주고 음악을 깔아 보세요.","en":"Give a cutout a motion like shake or spin and set the collage to music."},"wow":{"ko":"흔들기, 회전, 펄스, 스위블과 음악으로 정지된 콜라주가 공유할 만한 짧은 모션 작품이 돼요.","en":"Shake, spin, pulse, swivel and music turn a still collage into a short, shareable motion piece."}},{"do":{"ko":"Pinterest 이미지에서 가져온 물건을 눌러 원래 핀으로 가 보세요.","en":"Tap an object you pulled from a Pinterest image and follow it back to its original pin."},"wow":{"ko":"콜라주 속 물건이 원래 핀과 연결돼 있어 자기표현이 바로 발견과 쇼핑으로 이어져요.","en":"Objects stay linked to their pins, so self-expression leads straight into discovery and shopping."}}],"make":[{"ko":"Vision 프레임워크의 피사체 분리 기능으로 사진에서 물건을 오려 내는 화면을 만들어 보세요.","en":"Build a screen that cuts an object out of a photo using the Vision framework's subject lifting."},{"ko":"초대 코드 하나당 인원을 제한하는 흐름을 목업으로 그리고, 코드를 받는 사람이 무엇을 느낄지 적어 보세요.","en":"Mock up an invite flow with a limited number of people per code and write down what the recipient would feel."}],"ask":{"ko":"초대 인원을 다섯 명으로 묶은 제한이 왜 오히려 수요를 키웠을까요?","en":"Why did capping each invite at five people grow demand instead of limiting it?"}},"Gentler Streak Health Fitness":{"time":10,"setup":{"ko":"Apple Watch가 있으면 가장 잘 느낄 수 있어요. 핵심 기록은 무료이고 프리미엄 단계가 따로 있어요.","en":"Best with an Apple Watch. Core tracking is free, with a separate premium tier."},"missions":[{"do":{"ko":"앱을 열고 오늘의 추천 활동을 본 뒤, 고정 목표가 아니라 최근 기록과 회복에 맞춘 제안인지 살펴보세요.","en":"Open the app, look at today's suggested activity and notice that it comes from your recent history and recovery, not a fixed goal."},"wow":{"ko":"마케팅 예산 없이 부트스트랩으로 운영하는 슬로베니아 작은 팀이 이 다정한 방식으로 Apple Watch 올해의 앱과 2024 ADA까지 받았어요.","en":"A small bootstrapped team in Slovenia with no marketing budget took this gentle approach to Apple Watch App of the Year and a 2024 ADA."}},{"do":{"ko":"쉬는 날을 하루 가진 뒤 다음 날 앱을 열어 보세요.","en":"Take a rest day, then open the app the next day."},"wow":{"ko":"연속 기록이 끊겼다고 혼내는 대신 휴식을 권해요. 쉬어도 죄책감이 들지 않는 운동 앱이에요.","en":"Instead of scolding you for breaking a streak, it encourages rest. It's a fitness app that doesn't make rest feel like failure."}},{"do":{"ko":"Activity Path를 열어 지금 내가 개인 기준선 대비 어디에 있는지 확인해 보세요.","en":"Open the Activity Path and check where you are relative to your personal baseline."},"wow":{"ko":"숫자만 보여 주지 않고 건강한 구간 안인지 설명해 줘요. Yorhart가 내 심장이 하고 싶은 말을 다정하게 전해요.","en":"It explains whether you're in a healthy zone instead of just showing numbers, and Yorhart voices what your heart would tell you."}},{"do":{"ko":"월간 요약을 열어 내가 누구와 비교되는지 확인해 보세요.","en":"Open the Monthly Summary and see who you're being compared with."},"wow":{"ko":"다른 사람이 아니라 과거의 나와 비교해요.","en":"It compares you with your past self, not with other people."}}],"make":[{"ko":"내 앱에서 연속 기록이 끊기는 화면을 찾아, 쉬는 날을 칭찬하는 문구로 바꾼 버전을 만들어 보세요.","en":"Find the streak-broken screen in your app and make a version that praises the rest day instead."},{"ko":"숫자 하나를 개인 평균 대비 구간으로 보여 주는 작은 차트를 Swift Charts로 만들어 보세요.","en":"Use Swift Charts to show one number as a band relative to the user's own average."}],"ask":{"ko":"목표를 강요하지 않는 앱을 왜 더 오래 쓰게 될까요?","en":"Why do people stick with an app longer when it doesn't force goals on them?"}},"Navi":{"time":15,"setup":{"ko":"대화할 사람이 한 명 더 필요해요. 대면 자막은 상대 기기에도 Navi가 있어야 하고, 번역은 구독 기능이에요.","en":"You need a second person. In-person captions need Navi on their device too, and translation is a subscription feature."},"missions":[{"do":{"ko":"다른 사람과 FaceTime을 걸고 SharePlay로 Navi를 켠 뒤 평소처럼 말해 보세요.","en":"Start a FaceTime call with someone, turn on Navi through SharePlay and just talk."},"wow":{"ko":"말하는 대로 FaceTime 화면에 자막이 떠요. 1인 개발자가 SharePlay 발표 24시간 만에 만든 아이디어로, Apple Live Captions보다 반년 앞섰어요.","en":"Subtitles appear on the FaceTime call as you speak. A solo developer prototyped it within 24 hours of SharePlay's announcement, half a year before Apple's Live Captions."}},{"do":{"ko":"번역을 켜고 상대에게 다른 언어로 말해 달라고 해 보세요.","en":"Turn on translation and ask the other person to speak in a different language."},"wow":{"ko":"들어오는 자막이 20개 이상 언어로 실시간 번역되고 소리 내어 읽어 주기도 해요. 앱 하나가 청각 장벽과 언어 장벽을 함께 풀어요.","en":"Incoming subtitles are translated in real time into 20+ languages and can be read aloud. One app tackles both hearing and language barriers."}},{"do":{"ko":"옆 사람과 둘 다 Navi를 열고 마주 앉아 대화해 보세요.","en":"Both open Navi, sit face to face with someone and have a conversation."},"wow":{"ko":"가까운 기기끼리 직접 연결돼 대면 대화의 자막이 모두의 화면에 바로 떠요.","en":"Nearby devices connect directly, so captions of the in-person conversation show up instantly on everyone's screen."}}],"make":[{"ko":"Speech 프레임워크로 마이크 입력을 실시간 자막으로 띄우는 화면 하나를 만들어 보세요.","en":"Use the Speech framework to build one screen that shows microphone input as live captions."},{"ko":"최근 발표된 Apple API 하나를 골라, 접근성 문제 하나를 푸는 아이디어를 종이 프로토타입으로 만들어 보세요.","en":"Pick one recently announced Apple API and paper-prototype an idea that solves one accessibility problem with it."}],"ask":{"ko":"새 API가 나온 바로 그날 만든 것이 왜 이렇게 큰 차이를 만들었을까요?","en":"Why did building on a new API the day it shipped make such a difference?"}},"Slopes":{"time":15,"setup":{"ko":"실제 기록은 스키장에서만 할 수 있고 Apple Watch가 있으면 좋아요. 비시즌이라면 지도와 기록 화면 위주로 살펴보세요.","en":"Real tracking only works at a ski resort, ideally with an Apple Watch. Off season, focus on the maps and log screens."},"missions":[{"do":{"ko":"스키장에서 기록을 시작하고 폰을 주머니에 넣은 채 리프트와 슬로프를 몇 번 오가 보세요.","en":"At a ski resort, start recording, keep your phone in your pocket and ride a few lifts and runs."},"wow":{"ko":"GPS가 활강과 리프트를 알아서 나눠 기록해요. 첫 2년간 1만 600달러를 벌던 1인 앱이 투자 없이 9년을 버텨 연 매출 100만 달러를 넘겼어요.","en":"GPS splits runs from lifts on its own. A solo app that earned $10,600 in its first two years held on for nine years without investors and passed $1M a year."}},{"do":{"ko":"기록한 활강 하나를 3D 리조트 지도에서 다시 재생해 보세요.","en":"Replay one recorded run on the 3D resort map."},"wow":{"ko":"SceneKit으로 만든 3D 지도에 내 활강이 프로필과 함께 되살아나요. 2,000곳 넘는 리조트의 인터랙티브 지도가 있어요.","en":"Your run comes back to life with its profile on a SceneKit 3D map. Interactive trail maps cover 2,000+ resorts."}},{"do":{"ko":"장갑을 낀 채 Apple Watch로 기록을 켜고, 데이터가 약한 곳에서도 기록되는지 확인해 보세요.","en":"Start recording on Apple Watch with gloves on and check whether it keeps logging where cellular coverage is weak."},"wow":{"ko":"워치 자동 잠금이 실수로 눌리는 걸 막고, 셀룰러가 약해도 GPS만으로 기록돼요.","en":"Apple Watch auto-lock prevents accidental taps, and tracking works on GPS alone when coverage is poor."}}],"make":[{"ko":"내 앱의 기록 기능에서 시작 버튼 외에 없앨 수 있는 입력을 모두 지운 흐름을 그려 보세요.","en":"Sketch your app's logging flow with every input removed except the start button."},{"ko":"시즌 패스나 하루 패스처럼 사용 시기에 맞춘 요금 화면을 목업으로 만들어 보세요.","en":"Mock up a pricing screen that matches when people use the app, like a season pass or a day pass."}],"ask":{"ko":"리프트 위에서 폰을 꺼낼 필요가 없게 만든 것이 왜 가장 중요한 설계였을까요?","en":"Why was removing the need to pull out your phone on the chairlift the most important design decision?"}},"Alien: Isolation":{"time":20,"setup":{"ko":"처음 두 미션은 무료이고 전체 게임은 인앱 구입 한 번으로 열려요. 헤드폰을 끼고 해 보세요.","en":"The first two missions are free and one in-app purchase unlocks the full game. Play with headphones."},"missions":[{"do":{"ko":"헤드폰을 끼고 무료 첫 미션을 시작해, 화면을 가까이 들여다보며 조명과 물체 가장자리를 살펴보세요.","en":"Put on headphones, start the free first mission and look closely at the lighting and the edges of objects."},"wow":{"ko":"BAFTA 오디오상을 받은 콘솔 공포 게임이 7개 DLC까지 통째로 iPhone에 왔어요. 새 안티앨리어싱 덕에 일부는 원작보다 낫다고 해요.","en":"A BAFTA audio-winning console horror game arrived on iPhone whole, all seven DLCs included. The developer says new anti-aliasing makes parts look better than the original."}},{"do":{"ko":"외계 생명체를 마주치면 숨어서 여러 번 지켜보고, 매번 같은 방식으로 움직이는지 확인해 보세요.","en":"When you encounter the Alien, hide and watch it several times, checking whether it moves the same way each time."},"wow":{"ko":"대본 없는 행동 AI가 플레이어를 만날수록 새 행동을 풀어서 예측할 수 없어요. 모바일에서도 그대로 보존됐어요.","en":"Unscripted behavioral AI unlocks new behaviors as it meets you, so it never becomes predictable, and it survives intact on mobile."}},{"do":{"ko":"터치 설정에서 화면 버튼과 조이스틱의 크기와 위치를 내 손에 맞게 옮겨 보세요.","en":"In the touch settings, resize and reposition the on-screen buttons and joystick to fit your hands."},"wow":{"ko":"모든 화면 버튼과 조이스틱의 크기와 위치를 바꿀 수 있어요. 컨트롤러나 iPad 마우스와 키보드로도 할 수 있어요.","en":"Every on-screen button and joystick can be resized and moved. It also plays with a controller or iPad mouse and keyboard."}}],"make":[{"ko":"내 앱의 터치 컨트롤 하나를 사용자가 끌어서 옮기고 크기를 바꿀 수 있게 만들어 보세요.","en":"Make one touch control in your app draggable and resizable by the user."},{"ko":"화면 하나에 효과음 하나만 넣어 긴장감이 얼마나 달라지는지 헤드폰으로 비교해 보세요.","en":"Add a single sound effect to one screen and compare with headphones how much the tension changes."}],"ask":{"ko":"공포 게임에서 소리가 화면보다 더 큰 역할을 하는 이유는 무엇일까요?","en":"Why does sound do more of the work than visuals in a horror game?"}},"A Monster's Expedition":{"time":15,"setup":{"ko":"앱 스토어에서 내려가서 지금은 받을 수 없어요. 개발사가 공개한 트레일러와 스크린샷으로 경험해 보세요.","en":"It has left the App Store, so experience it through the developer's own trailer and screenshots."},"missions":[{"do":{"ko":"공개 트레일러에서 괴물이 처음 통나무를 미는 장면을 찾아, 글자 설명이 하나라도 나오는지 지켜보세요.","en":"In the public trailer, find the moment the monster first pushes a log and watch for any text explanation at all."},"wow":{"ko":"글자 튜토리얼 없이 통나무가 구르고 서고 다리가 되는 규칙을 실험만으로 깨닫게 해요. 3년 넘게 다듬은 퍼즐이에요.","en":"With no text tutorial, you figure out how logs roll, stand and bridge purely by experimenting. It took over three years to make."}},{"do":{"ko":"스크린샷에서 여러 섬이 이어진 장면을 찾아, 갈 수 있는 길이 하나뿐인지 살펴보세요.","en":"Find a screenshot showing many connected islands and check whether there's only one way forward."},"wow":{"ko":"수백 개 섬으로 된 열린 군도라 막힌 퍼즐은 건너뛰고 나중에 돌아올 수 있어요.","en":"It's an open archipelago of hundreds of islands, so you can skip a stuck puzzle and come back later."}},{"do":{"ko":"스크린샷 한 장을 골라 각 통나무가 서 있는지 누워 있는지 한눈에 구분되는지 확인해 보세요.","en":"Pick one screenshot and check whether you can tell at a glance which logs are standing and which are lying down."},"wow":{"ko":"모든 타일과 통나무 상태가 모호하지 않게 그려져 있어요. 이 명확함이 ADA 포용성 인정을 뒷받침했어요.","en":"Every tile and log state is unambiguous. That clarity supported its ADA Inclusivity recognition."}},{"do":{"ko":"트레일러와 스크린샷에서 박물관 전시물 장면을 찾아보세요.","en":"Look for the museum exhibit scenes in the trailer and screenshots."},"wow":{"ko":"괴물들이 인간의 물건을 해석한 전시물이 퍼즐 흐름을 끊지 않고 가벼운 웃음을 줘요.","en":"Exhibits interpreting human objects add light humor without interrupting the puzzle flow."}}],"make":[{"ko":"내 앱 기능 하나를 글자 설명 없이, 실패해도 바로 되돌릴 수 있는 작은 연습 화면으로 가르치는 프로토타입을 만들어 보세요.","en":"Prototype a small practice screen that teaches one feature with no text, where any mistake can be undone instantly."},{"ko":"내 화면의 상태 표시 하나를 골라 색 외에 모양으로도 구분되게 다시 그려 보세요.","en":"Pick one state indicator in your UI and redraw it so it differs by shape as well as color."}],"ask":{"ko":"글자 없이 규칙을 깨닫는 순간이 설명을 읽는 것보다 왜 더 기억에 남을까요?","en":"Why is discovering a rule without text more memorable than reading an explanation?"}},"CARROT Weather":{"time":10,"setup":null,"missions":[{"do":{"ko":"성격을 Professional로 두고 예보를 읽은 뒤, Homicidal이나 Overkill로 바꿔 같은 예보를 다시 읽어 보세요.","en":"Read the forecast with the personality on Professional, then switch to Homicidal or Overkill and read the same forecast again."},"wow":{"ko":"같은 날씨 데이터가 사람 놀리는 AI 캐릭터의 대사로 완전히 다른 목소리가 돼요. 1인 개발자가 말투를 사용자 설정으로 만들었어요.","en":"The same weather data becomes a totally different voice from a snarky AI character. A solo developer turned tone into a user setting."}},{"do":{"ko":"앱 곳곳을 둘러보며 업적이나 비밀 장소를 찾아보세요.","en":"Explore around the app hunting for achievements or secret locations."},"wow":{"ko":"80개 넘는 업적과 150곳 넘는 비밀 장소가 있어 날씨 앱을 여는 일 자체가 놀이가 돼요.","en":"With 80+ achievements and 150+ secret locations, simply opening a weather app becomes play."}},{"do":{"ko":"레이아웃을 편집해 섹션에 보일 데이터 항목을 바꾸고, 예보 데이터 출처도 다른 곳으로 바꿔 보세요.","en":"Edit the layout to change which data points each section shows, and switch the forecast data source too."},"wow":{"ko":"섹션마다 보일 항목을 고를 수 있고, Foreca나 AccuWeather, Apple Weather처럼 믿는 출처를 직접 골라요.","en":"You choose what appears in each section and pick the source you trust, such as Foreca, AccuWeather or Apple Weather."}}],"make":[{"ko":"내 앱의 알림 문구 하나를 진지한 버전과 장난스러운 버전으로 쓰고, 설정 토글로 바꾸는 화면을 만들어 보세요.","en":"Write one of your app's notifications in a serious and a playful version, and build a settings toggle that switches between them."},{"ko":"내 앱에 숨겨진 업적 하나를 정하고, 그걸 발견했을 때 뜨는 화면을 만들어 보세요.","en":"Define one hidden achievement in your app and build the screen that appears when someone finds it."}],"ask":{"ko":"데이터가 똑같은데도 말투 하나로 앱을 고르게 되는 이유는 무엇일까요?","en":"Why would people choose an app for its tone of voice when the data is identical?"}},"Loóna":{"time":15,"setup":{"ko":"무료 체험 뒤 구독이 필요해요. 잠들기 전 저녁에 해 보는 게 좋아요.","en":"Subscription after a free trial. Try it in the evening before bed."},"missions":[{"do":{"ko":"잠들기 전 Sleepscape 하나를 시작해 3D 장면을 색칠하며 이야기와 소리를 따라가 보세요.","en":"Before bed, start a Sleepscape and color the 3D scene while following the story and sound."},"wow":{"ko":"색칠, 내레이션, 사운드스케이프가 하나의 저녁 의식으로 묶여요. AR 앱 MSQRD 팀이 만들어 Google Play 올해의 앱과 ADA를 모두 받았어요.","en":"Coloring, narration and soundscape are bundled into one evening ritual. Built by the MSQRD AR team, it won both Google Play App of the Year and an ADA."}},{"do":{"ko":"세션 중에 글꼴, 색, 움직임 속도가 낮에 쓰는 다른 앱과 어떻게 다른지 눈여겨보세요.","en":"During a session, notice how the type, colors and motion speed differ from the apps you use by day."},"wow":{"ko":"글자, 색, 애니메이션, 3D까지 각성을 낮추도록 조율돼 있어요. Apple이 시각과 그래픽 부문 수상 이유로 꼽은 점이에요.","en":"Type, color, animation and 3D are all tuned to lower arousal, which Apple cited in its Visuals and Graphics award."}},{"do":{"ko":"생각이 많은 밤에 소리만 듣지 말고 색칠하는 손을 계속 움직여 보세요.","en":"On a night when your mind is racing, keep your hands busy coloring instead of only listening."},"wow":{"ko":"단순한 손동작이 불안한 머리에 할 일을 줘요. 소리만 트는 수면 앱과 달리 잠들기 전 불안을 겨냥해요.","en":"A simple hand task gives a restless mind something to do. Unlike apps that just play sounds, it targets pre-sleep anxiety."}}],"make":[{"ko":"내 앱 화면 하나를 밤 버전으로 만들어 애니메이션을 느리게 하고 대비와 채도를 낮춰 보세요.","en":"Make a night version of one screen in your app with slower animation and lower contrast and saturation."},{"ko":"가만히 듣기만 하는 기능에 손으로 하는 작은 동작 하나를 더한 프로토타입을 만들어 보세요.","en":"Prototype a listen-only feature with one small hands-on action added."}],"ask":{"ko":"잠들기 전에 무언가를 하게 만드는 것이 왜 가만히 듣는 것보다 효과적일까요?","en":"Why is giving people something to do before sleep more effective than having them just listen?"}},"Looom":{"time":20,"setup":{"ko":"₩17,000 유료 앱이에요. Apple Pencil이 있으면 필압과 두 번 탭 지우기를 쓸 수 있어요.","en":"A paid app at ₩17,000. With an Apple Pencil you get pressure and double-tap to erase."},"missions":[{"do":{"ko":"타임라인을 찾지 말고 프레임 몇 장을 그린 뒤, 루프가 재생되는 동안 BPM을 바꿔 보세요.","en":"Don't look for a timeline; draw a few frames, then change the BPM while the loop plays."},"wow":{"ko":"타임라인도 키프레임도 없이 악기를 연주하듯 루프를 그려요. 스스로 개발자라 여기지 않는 두 사람이 본업 틈틈이 1년 반 만에 만들었어요.","en":"No timeline, no keyframes: you draw loops as if playing an instrument. Two people who don't see themselves as developers built it on the side in a year and a half."}},{"do":{"ko":"한 장을 그리고 스와이프해 새 셀로 넘어간 뒤, 희미하게 남은 이전 그림을 따라 다음 동작을 그려 보세요.","en":"Draw one frame, swipe to a new cel and trace the faint previous drawing to draw the next pose."},"wow":{"ko":"이전 그림이 희미하게 남는 어니언 스킨 덕분에 메뉴 하나 없이 핵심 루프가 돌아가요.","en":"Onion skinning keeps the previous drawing faintly visible, so the core loop runs without a single menu."}},{"do":{"ko":"복잡한 패널 대신 장난감 같은 기어와 노브를 돌려 재생을 조작해 보세요.","en":"Control playback by turning the toy-like gears and knobs instead of hunting for panels."},"wow":{"ko":"촘촘한 타임라인 패널 자리에 장난감 같은 물리 컨트롤이 있어 초보자도 겁먹지 않아요.","en":"Toy-like physical controls replace dense timeline panels, so beginners aren't intimidated."}}],"make":[{"ko":"내 앱의 슬라이더 하나를 돌리는 노브 컨트롤로 바꾼 SwiftUI 프로토타입을 만들어 보세요.","en":"Build a SwiftUI prototype that replaces one slider in your app with a rotating knob."},{"ko":"이미지 네 장을 BPM에 맞춰 반복 재생하고 BPM을 바꿀 수 있는 작은 루프 플레이어를 만들어 보세요.","en":"Build a tiny loop player that cycles four images at a set BPM and lets you change the BPM."}],"ask":{"ko":"시간을 BPM으로 다루니 애니메이션이 왜 덜 어렵게 느껴질까요?","en":"Why does treating time as BPM make animation feel less daunting?"}},"Peloton":{"time":10,"setup":{"ko":"미국 스토어 앱이에요. 바이크나 트레드 없이 앱 멤버십만으로 해 볼 수 있어요.","en":"A US App Store app. You can try it with just the app membership, no bike or treadmill."},"missions":[{"do":{"ko":"바이크나 트레드 없이 앱만 설치해, 기기가 없는 사람에게 앱이 무엇을 먼저 보여 주는지 따라가 보세요.","en":"Install just the app, with no bike or treadmill, and follow what it shows first to someone without the hardware."},"wow":{"ko":"하드웨어와 앱 구독을 분리해서 기기 없이도 앱 멤버십만으로 라이브와 온디맨드 클래스를 들을 수 있어요.","en":"Hardware and app subscriptions are split, so the app membership alone gets you live and on-demand classes with no equipment."}},{"do":{"ko":"라이브 클래스에 들어가 리더보드를 켜 두고 운동해 보세요.","en":"Join a live class and work out with the leaderboard on."},"wow":{"ko":"리더보드, 강사의 실시간 호명, 마일스톤 배지 덕분에 집에서 혼자 하는 운동인데도 함께 달리는 기분이 들어요.","en":"Leaderboards, live instructor shout-outs and milestone badges make a solo home workout feel like riding with others."}}],"make":[{"ko":"내 앱에서 하드웨어나 유료 기능 없이도 가치를 느낄 수 있는 첫 화면을 그려 보세요.","en":"Sketch a first screen for your app that delivers value without hardware or paid features."},{"ko":"혼자 쓰는 기능에 지금 같이 하는 사람 수나 실시간 응원 한 줄을 붙인 목업을 만들어 보세요.","en":"Mock up a solo feature with a live count of people doing it now or a single line of real-time encouragement."}],"ask":{"ko":"기기 없이 앱만 쓰는 사람에게 먼저 보여 주는 것이 왜 하드웨어와 구독 모델에 중요할까요?","en":"Why does what you show app-only users first matter so much in a hardware plus subscription model?"}},"Tinder":{"time":10,"setup":null,"missions":[{"do":{"ko":"카드 몇 장을 좌우로 스와이프하며 결정 하나에 몇 초가 걸리는지 세어 보세요.","en":"Swipe a few cards left and right and count how many seconds each decision takes."},"wow":{"ko":"카드 덱 넘기기에서 착안한 스와이프 하나로 관심 표현이 끝나서 탐색 비용이 극단적으로 낮아요.","en":"A single swipe, inspired by flipping through a deck of cards, completes the expression of interest, so browsing costs almost nothing."}},{"do":{"ko":"매치가 될 때까지 스와이프를 이어 가며 그 순간의 피드백을 지켜보세요.","en":"Keep swiping until you get a match and watch the feedback at that moment."},"wow":{"ko":"둘 중 하나로 줄인 결정이 쌓이다가 매치 순간의 피드백이 그 짧은 결정들에 보상을 줘요.","en":"Decisions cut down to one of two build up, and the feedback at the moment of a match rewards all those quick choices."}},{"do":{"ko":"실수로 왼쪽으로 넘긴 뒤 되돌리기를 눌러 보세요.","en":"Swipe left by mistake, then try to undo it."},"wow":{"ko":"Rewind 같은 기능이 무료 사용자가 불편을 느끼는 바로 그 지점에 맞춰 상위 유료 티어에 들어가 있어요.","en":"Features like Rewind sit in higher paid tiers, placed exactly where free users feel the pain."}}],"make":[{"ko":"내 앱의 목록 하나를 카드 스택으로 바꾸고 좌우 스와이프로 두 가지 선택만 하게 하는 SwiftUI 프로토타입을 만들어 보세요.","en":"Build a SwiftUI prototype that turns one list in your app into a card stack with only two swipe choices."},{"ko":"내 앱에서 사용자가 가장 아쉬워하는 순간 하나를 골라, 그 자리에 둘 유료 기능을 적어 보세요.","en":"Pick the moment users feel most frustrated in your app and write down the paid feature that would sit there."}],"ask":{"ko":"선택지를 둘로 줄인 것이 왜 결정을 더 쉽고 반복하고 싶게 만들었을까요?","en":"Why did cutting the choice down to two make deciding easier and more repeatable?"}},"TapTapSee":{"time":5,"setup":{"ko":"VoiceOver를 켜고 해 보면 설계 의도가 가장 잘 느껴져요.","en":"Turn on VoiceOver to feel the design intent best."},"missions":[{"do":{"ko":"VoiceOver를 켜고 눈을 감은 채 화면 오른쪽을 두 번 탭해 앞에 있는 물건을 찍어 보세요.","en":"Turn on VoiceOver, close your eyes and double-tap the right side of the screen to photograph the object in front of you."},"wow":{"ko":"몇 초 안에 물건을 식별해 소리 내어 읽어 줘요. 버튼이 사실상 하나뿐이라 결과 화면을 볼 필요가 없어요.","en":"Within seconds it identifies the object and reads it aloud. With essentially one button, there's no need to look at a result screen."}},{"do":{"ko":"같은 물건의 각도를 바꿔 다시 찍거나, 왼쪽을 두 번 탭해 동영상으로 찍어 보세요.","en":"Shoot the same object from another angle, or double-tap the left side to record a video instead."},"wow":{"ko":"2D와 3D 사물을 어느 각도에서든 식별하도록 설계했고, 최대 10초 동영상도 인식해요.","en":"It's designed to identify 2D and 3D objects from any angle, and it recognizes videos up to 10 seconds."}}],"make":[{"ko":"내 앱의 핵심 기능 하나를 화면 아무 곳이나 두 번 탭하면 실행되게 만들고 VoiceOver로 시험해 보세요.","en":"Make one core feature in your app trigger by double-tapping anywhere on screen, and test it with VoiceOver."},{"ko":"결과를 화면에 보여 주는 대신 AVSpeechSynthesizer로 읽어 주는 버전을 만들어 보세요.","en":"Build a version that reads the result aloud with AVSpeechSynthesizer instead of showing it on screen."}],"ask":{"ko":"버튼을 하나로 줄인 것이 화면을 볼 수 있는 사람에게도 편한 이유는 무엇일까요?","en":"Why is reducing it to one button easier for sighted people too?"}},"Overcast":{"time":10,"setup":null,"missions":[{"do":{"ko":"말이 많은 팟캐스트 하나를 Smart Speed 없이 듣다가, 켜고 같은 구간을 다시 들어 보세요.","en":"Listen to a talky podcast without Smart Speed, then turn it on and replay the same section."},"wow":{"ko":"말 사이 침묵만 줄여서 목소리는 그대로인데 청취 시간이 짧아져요. 단순 배속과 달라요.","en":"It trims only the silences between words, so voices sound unchanged while listening time shrinks. It's not just a faster playback rate."}},{"do":{"ko":"볼륨이 작게 녹음된 에피소드에서 Voice Boost를 켜 보세요.","en":"Turn on Voice Boost on an episode that was recorded quietly."},"wow":{"ko":"방송 수준으로 음량을 평준화해서 에피소드마다 들쭉날쭉한 볼륨이 맞춰져요.","en":"It normalizes loudness to broadcast level, evening out volume that varies from episode to episode."}},{"do":{"ko":"재생 속도를 0.1 단위로 올리고 내리며 커스텀 스크러버를 손가락으로 움직여 보세요.","en":"Nudge the playback speed in 0.1 steps and drag the custom scrubber with your finger."},"wow":{"ko":"손가락 크기에 맞춘 커스텀 컨트롤이라 표준 슬라이더보다 정밀하게 조작돼요.","en":"Custom controls sized for fingers give more precise control than a standard slider."}}],"make":[{"ko":"AVAudioEngine으로 오디오를 1.5배로 재생하는 버전과 무음 구간만 건너뛰는 버전을 만들어 비교해 들어 보세요.","en":"Use AVAudioEngine to build one version that plays audio at 1.5x and one that only skips silent stretches, then compare by ear."},{"ko":"내 앱의 표준 슬라이더 하나를 손가락 크기에 맞춘 커스텀 컨트롤로 바꿔 보세요.","en":"Replace one standard slider in your app with a custom control sized for a finger."}],"ask":{"ko":"빠르게 재생하는 것보다 침묵을 줄이는 것이 왜 더 자연스럽게 들릴까요?","en":"Why does cutting silence sound more natural than simply playing faster?"}},"Google Sheets":{"time":10,"setup":{"ko":"Google 계정이 필요하고, 동시 편집을 보려면 함께할 사람이나 두 번째 기기가 있으면 좋아요.","en":"Needs a Google account, plus a second person or device to see co-editing."},"missions":[{"do":{"ko":"시트 링크를 다른 사람이나 두 번째 기기로 보내고, 둘이 동시에 가까운 셀을 편집해 보세요.","en":"Send the sheet link to another person or a second device and edit nearby cells at the same time."},"wow":{"ko":"글자 단위로 변경이 바로 보이고 각자의 커서와 선택 영역이 색으로 표시돼 누가 어디를 만지는지 드러나요.","en":"Changes appear character by character, and each person's cursor and selection are color-coded, so you can see who is touching what."}},{"do":{"ko":"저장 버튼을 찾지 말고 값을 고친 뒤 바로 앱을 닫았다가, 다시 열어 버전 기록을 확인해 보세요.","en":"Don't look for a save button; change a value, close the app right away, then reopen it and check the version history."},"wow":{"ko":"입력하는 즉시 자동 저장되고 버전 기록이 남아 '저장'이라는 개념 자체가 사라졌어요.","en":"Everything saves as you type and version history is kept, so the very idea of 'saving' is gone."}},{"do":{"ko":"비행기 모드로 바꾸고 셀 몇 개를 고친 뒤 다시 연결해 보세요.","en":"Switch to Airplane Mode, edit a few cells, then reconnect."},"wow":{"ko":"오프라인에서 고친 내용이 다시 연결되면 동기화돼요. 모바일에서도 수식 입력과 정렬까지 돼요.","en":"Edits made offline sync once you reconnect, and mobile still supports formulas and sorting."}}],"make":[{"ko":"내 앱의 저장 버튼 하나를 없애고, 입력할 때마다 자동 저장되며 '저장됨' 표시만 뜨게 바꿔 보세요.","en":"Remove one save button in your app and make it autosave on every edit with just a 'Saved' indicator."},{"ko":"두 사용자의 선택 위치를 서로 다른 색으로 보여 주는 목업 화면을 만들어 보세요.","en":"Mock up a screen that shows two users' selections in different colors."}],"ask":{"ko":"다른 사람의 커서가 보이는 것만으로 협업이 왜 더 안심이 될까요?","en":"Why does simply seeing someone else's cursor make collaborating feel safer?"}},"오늘의집":{"time":10,"setup":null,"missions":[{"do":{"ko":"집들이 사진 하나를 열고 가구에 붙은 상품 태그를 눌러 보세요.","en":"Open a house-tour photo and tap a product tag on one of the pieces of furniture."},"wow":{"ko":"사진을 보다가 태그 하나로 바로 그 상품 페이지로 넘어가요. 광고가 아니라 실제 사용자의 집에서 상품을 발견하게 돼요.","en":"One tag takes you straight from the photo to that product's page. You discover products in real people's homes, not in ads."}},{"do":{"ko":"3D 방꾸미기로 마음에 드는 가구를 가상의 방에 놓아 보세요.","en":"Use the 3D room decorating feature to place a piece of furniture you like in a virtual room."},"wow":{"ko":"사기 전에 가구가 공간에 맞는지 미리 볼 수 있어서 구매 전 불안이 줄어요.","en":"You can see whether furniture fits the space before buying, which eases pre-purchase worry."}},{"do":{"ko":"사고 싶은 것 없이 피드를 둘러보며 스크랩만 해 보고, 어느새 상품 페이지에 와 있는지 보세요.","en":"Browse the feed with nothing in mind, just scrapping things, and notice when you end up on a product page."},"wow":{"ko":"피드, 태그, 스크랩 중심 구조라 목적 없이 둘러보던 사람도 자연스럽게 구매 여정에 들어와요.","en":"Built around feeds, tags and scraps, it draws aimless browsers naturally into the buying journey."}}],"make":[{"ko":"사진 위 특정 위치에 탭할 수 있는 태그를 올리고 누르면 상세 화면으로 가는 SwiftUI 프로토타입을 만들어 보세요.","en":"Build a SwiftUI prototype with tappable tags placed on a photo that open a detail screen."},{"ko":"내 앱의 콘텐츠 화면 하나에서 바로 행동으로 이어질 연결 지점 하나를 찾아 표시해 보세요.","en":"Find and mark one spot on a content screen in your app that could link straight to an action."}],"ask":{"ko":"광고보다 다른 사람 집 사진 속 상품을 더 믿게 되는 이유는 무엇일까요?","en":"Why do we trust a product in someone's home photo more than one in an ad?"}},"Blippo+":{"time":20,"setup":{"ko":"Mac 전용이고 ₩19,000 일회성 유료 앱이에요.","en":"Mac only, a one-time purchase at ₩19,000."},"missions":[{"do":{"ko":"채널을 천천히 돌리며 화면을 가까이 들여다보고 주사선과 색 번짐을 찾아보세요.","en":"Flip channels slowly, lean in close and look for scanlines and color bleed."},"wow":{"ko":"셰이더 필터가 아니라 실제 아날로그 방송 장비로 찍은 실사라 노이즈가 진짜예요. 촬영에 1년, 후반 작업에 또 1년이 걸렸어요.","en":"It's live action shot on real analog broadcast gear, not a shader, so the noise is real. Filming took a year and post-production another."}},{"do":{"ko":"썸네일 목록을 찾지 말고 채널을 계속 넘기며 프로그램을 우연히 만나 보세요.","en":"Don't look for a thumbnail grid; keep flipping channels and stumble onto shows by chance."},"wow":{"ko":"앱 전체가 가짜 케이블 TV라 핵심 인터랙션이 채널 서핑 그 자체예요. 큼직한 채널 번호와 문자 정보 화면까지 허구를 지켜요.","en":"The whole app is a fake cable TV, so channel surfing is the core interaction. Oversized channel numbers and teletext-style pages keep the fiction intact."}},{"do":{"ko":"광고와 뉴스를 그냥 넘기지 말고 보면서 Planet Blip이 어떤 곳인지 메모해 보세요.","en":"Don't skip the ads and news; watch them and jot down what Planet Blip seems to be like."},"wow":{"ko":"이야기를 설명하지 않고 광고, 뉴스, 쇼 조각으로 행성의 문화와 미스터리를 스스로 맞춰 가게 해요.","en":"Nothing is explained; you piece together the planet's culture and mystery from ads, news and shows."}},{"do":{"ko":"신호 보정을 한동안 무시하고 화면이 어떻게 변하는지 지켜보세요.","en":"Ignore the signal calibration for a while and watch what happens to the picture."},"wow":{"ko":"보정을 미루면 신호가 나빠지는 장치가 있어서 오래된 TV를 직접 만지는 감각까지 살아나요.","en":"A signal-calibration mechanic degrades if ignored, bringing back the feel of tending an old TV."}}],"make":[{"ko":"내 앱의 목록 화면을 채널 넘기기처럼 하나씩만 넘기는 방식으로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype your app's list screen as a one-at-a-time flip, like changing channels."},{"ko":"앱의 설정 화면 하나를 앱의 세계관에 맞는 글꼴과 장식으로 다시 그려 보세요.","en":"Redraw one settings screen in your app with type and decoration that belong to the app's world."}],"ask":{"ko":"고르는 대신 넘기게 만든 것이 왜 더 보고 싶게 만들까요?","en":"Why does making you flip rather than choose make you want to keep watching?"}},"Sid Meier's Civilization VII":{"time":30,"setup":{"ko":"Apple Arcade 구독이 필요하고 A17 Pro 이상 칩을 쓴 기기에서만 실행돼요.","en":"Requires Apple Arcade and a device with an A17 Pro-class chip or newer."},"missions":[{"do":{"ko":"iPhone에서 한 게임을 몇 턴 진행한 뒤, iPad나 Mac에서 같은 게임을 이어서 열어 보세요.","en":"Play a few turns of a game on iPhone, then continue the same game on an iPad or Mac."},"wow":{"ko":"모바일 축소판이 아니라 본편이 기기를 바꿔도 크로스 세이브로 이어져요. 게임 규모 때문에 A17 Pro 이상 칩을 요구해요.","en":"It's the full game, not a mobile cut-down, and cross-save carries it between devices. Its scale demands an A17 Pro-class chip or newer."}},{"do":{"ko":"터치로 유닛을 옮기고 도시를 관리한 뒤, iPad나 Mac에서 마우스나 컨트롤러로 바꿔 해 보세요.","en":"Move units and manage cities by touch, then switch to a mouse or controller on iPad or Mac."},"wow":{"ko":"같은 게임이 입력 장치에 맞춰 바뀌어서 한 가지 조작 방식을 강요하지 않아요.","en":"The same game adapts to the input device instead of forcing one control scheme."}},{"do":{"ko":"다음 시대로 넘어가는 순간까지 진행해 내 문명이 어떻게 바뀌는지 보세요.","en":"Play until the move into the next age and see how your civilization changes."},"wow":{"ko":"Ages 시스템에서 문명이 시대마다 진화해요. 주류 게임에서 보기 드문 지도자와 문명이 많아 Apple이 문화적 표현을 짚었어요.","en":"In the Ages system civilizations evolve each era, and Apple singled out its rarely seen leaders and civilizations for cultural representation."}}],"make":[{"ko":"내 앱 상태를 iCloud 키-값 저장소에 저장해 두 기기에서 같은 화면으로 이어지는지 확인해 보세요.","en":"Save your app's state to iCloud key-value storage and check that two devices resume on the same screen."},{"ko":"화면 하나를 터치, 키보드, 컨트롤러로 조작할 때 각각 무엇이 달라야 하는지 표로 적어 보세요.","en":"Make a table of what needs to change on one screen for touch, keyboard and controller input."}],"ask":{"ko":"긴 전략 게임에서 기기를 넘나드는 이어하기가 왜 결정적일까요?","en":"Why is picking up across devices so crucial for a long strategy game?"}},"Grand Mountain Adventure 2":{"time":10,"setup":{"ko":"무료로 받고 전체 게임은 한 번의 결제로 열려요.","en":"Free to download, with a one-time unlock for the full game."},"missions":[{"do":{"ko":"첫 슬로프에서 왼쪽, 오른쪽, 점프만으로 카빙하고 뛰어 보세요.","en":"On the first slope, carve and jump using only left, right and jump."},"wow":{"ko":"입력이 세 가지뿐인데 스키 타는 몸의 감각과 그대로 맞아요. 스노보더 삼형제 스튜디오의 이 시리즈를 3,000만 명 넘게 플레이했어요.","en":"Just three inputs, yet they map right onto how skiing feels. This series from three snowboarding brothers has been played by over 30 million people."}},{"do":{"ko":"정해진 코스를 벗어나 숲이나 백컨트리 쪽으로 아무 데나 내려가 보세요.","en":"Leave the marked runs and head down anywhere into the forest or backcountry."},"wow":{"ko":"여러 리조트와 숲, 백컨트리를 어디로든 탈 수 있는 열린 세계라 코스 목록이 아니에요.","en":"It's an open world of resorts, forests and backcountry you can ride anywhere, not a list of courses."}},{"do":{"ko":"리프트를 타고 오르며 다른 스키어와 도전 과제를 살펴보세요.","en":"Ride a lift up and look at the other skiers and the challenges around you."},"wow":{"ko":"리프트, NPC 스키어, 도전 과제 같은 리조트 디테일에 스노보더들의 실제 경험이 녹아 있어요.","en":"Resort details like lifts, NPC skiers and challenges reflect the developers' first-hand experience as snowboarders."}}],"make":[{"ko":"내 게임이나 앱의 핵심 조작을 입력 세 개 이하로 줄인 버전을 프로토타입으로 만들어 보세요.","en":"Prototype a version of your game or app with the core controls reduced to three inputs or fewer."},{"ko":"화면 왼쪽과 오른쪽 터치를 방향에, 두 손가락 터치를 점프에 연결한 테스트 씬을 만들어 보세요.","en":"Build a test scene where left and right screen touches steer and a two-finger touch jumps."}],"ask":{"ko":"몇 초 만에 배우는 조작이 왜 오래 지나도 실력 차이를 만들 수 있을까요?","en":"How can controls learned in seconds still leave room for skill to show over time?"}},"Arknights: Endfield":{"time":30,"setup":{"ko":"무료지만 가챠 과금이 있어요. 헤드폰이 있으면 공간 음향을 느낄 수 있어요.","en":"Free to play with gacha monetization. Headphones let you hear the Spatial Audio."},"missions":[{"do":{"ko":"공장 설비를 많이 지어 둔 지역에서 캐릭터를 움직이며 화면이 얼마나 부드러운지 살펴보세요.","en":"Move your characters through an area packed with the factory equipment you've built and see how smooth it stays."},"wow":{"ko":"캐릭터 한 명에 폴리곤 8만~10만 개, 내가 지은 설비까지 계속 그려져요. 모바일판은 렌더링 후보 50만 개를 컬링으로 수만 개로 줄여요.","en":"Each character has 80,000 to 100,000 polygons, plus all the equipment you build. The mobile version culls 500,000 render candidates down to tens of thousands."}},{"do":{"ko":"실시간 전투를 하다가 공장 자동화 화면으로 넘어가 생산 라인을 이어 보세요.","en":"Switch from real-time combat to the factory automation layer and connect a production line."},"wow":{"ko":"실시간 분대 3D 전투와 본격적인 공장 자동화가 한 게임에 있어 전략파와 건설파 모두 자기 루프를 가져요.","en":"Real-time squad 3D combat and full factory automation live in one game, so both strategists and builders get a core loop."}},{"do":{"ko":"지원 기기라면 레이 트레이싱을 켜고 헤드폰을 낀 채 넓은 환경을 탐험해 보세요.","en":"On a supported device, turn on ray tracing, put on headphones and explore a large environment."},"wow":{"ko":"하드웨어 가속 레이 트레이싱과 공간 음향을 써서 Apple silicon 그래픽 기능을 보여 주는 드문 가챠 RPG예요.","en":"With hardware-accelerated ray tracing and Spatial Audio, it's one of the few gacha RPGs to showcase Apple silicon graphics."}}],"make":[{"ko":"SpriteKit이나 SceneKit 씬에 오브젝트 수천 개를 놓고, 화면 밖 오브젝트를 숨길 때 프레임이 어떻게 달라지는지 비교해 보세요.","en":"Place thousands of objects in a SpriteKit or SceneKit scene and compare frame rates with off-screen objects hidden."},{"ko":"PC급 복잡한 화면 하나를 골라 iPhone 화면에 맞게 줄일 때 꼭 남길 요소 세 개를 골라 보세요.","en":"Take one complex PC-class screen and pick the three elements you must keep when scaling it down for iPhone."}],"ask":{"ko":"그려야 할 것을 줄이는 기술이 왜 그리는 기술만큼 중요할까요?","en":"Why is the skill of drawing less as important as the skill of drawing well?"}},"Train Fitness":{"time":20,"setup":{"ko":"Apple Watch(또는 AirPods)와 근력 운동을 할 공간이 필요해요. 지금은 Motra라는 이름으로 바뀌었어요.","en":"Needs an Apple Watch (or AirPods) and space for strength training. It has since been rebranded as Motra."},"missions":[{"do":{"ko":"Apple Watch를 차고 운동을 시작한 뒤 화면을 한 번도 건드리지 말고 근력 운동 몇 세트를 해 보세요.","en":"Wear your Apple Watch, start a workout and do a few strength sets without touching the screen once."},"wow":{"ko":"끝나고 보면 동작과 횟수가 자동으로 기록돼 있어요. Watch와 AirPods 움직임만으로 470종 이상을 인식하는 하버드대·토론토대 연구 기술이에요.","en":"When you finish, the exercises and reps are already logged. Research from Harvard and the University of Toronto lets it recognize 470+ exercises from Watch and AirPods motion alone."}},{"do":{"ko":"한 세트는 눈을 감은 채 해 보고 기록이 똑같이 남는지 확인해 보세요.","en":"Do one set with your eyes closed and check whether it's logged just the same."},"wow":{"ko":"화면 조작이 필요 없어서 시각장애인이나 작은 터치 영역이 힘든 사람에게도 잘 맞아요. 접근성이 핵심 설계에서 저절로 따라와요.","en":"Since no screen interaction is needed, it suits blind and low-vision users or anyone who struggles with small targets. Accessibility falls out of the core design."}},{"do":{"ko":"운동 모드 목록에서 휠체어 운동이나 사지 차이 모드를 찾아보세요.","en":"Look through the workout modes for the wheelchair and limb-difference modes."},"wow":{"ko":"한 가지 몸을 가정하지 않고 휠체어 운동과 사지 차이가 있는 사용자를 위한 전용 모드를 따로 뒀어요.","en":"Instead of assuming one body type, it has dedicated modes for wheelchair workouts and limb differences."}}],"make":[{"ko":"Core Motion으로 iPhone이나 Watch의 가속도 값을 읽어 반복 동작 횟수를 세는 간단한 카운터를 만들어 보세요.","en":"Use Core Motion to read accelerometer data from an iPhone or Watch and build a simple repetition counter."},{"ko":"내 앱에서 사용자가 직접 입력하는 값 하나를 센서나 자동 감지로 대체할 수 있는지 적어 보세요.","en":"Write down whether one value users type into your app could be replaced by a sensor or automatic detection."}],"ask":{"ko":"입력을 없앤 것이 왜 접근성까지 함께 해결했을까요?","en":"Why did removing input also solve accessibility?"}},"Taobao":{"time":15,"setup":{"ko":"수상한 3D 상품 경험은 Apple Vision Pro 버전에서만 할 수 있어요.","en":"The award-winning 3D product experience is only on the Apple Vision Pro version."},"missions":[{"do":{"ko":"Vision Pro에서 냉장고 같은 큰 상품을 실제 크기로 거실에 놓고, 다른 상품을 옆에 나란히 띄워 보세요.","en":"On Vision Pro, place a large product like a refrigerator at real size in your living room and open another one beside it."},"wow":{"ko":"실물에 견줄 만한 3D 모델이 실제 크기로 놓여 맞는지 바로 보여요. 중국 최대 쇼핑 앱이 Vision Pro 중국 출시 전에 먼저 냈어요.","en":"A 3D model comparable to the real thing sits at true size, so you see at once whether it fits. China's largest shopping app shipped it before Vision Pro even launched in China."}},{"do":{"ko":"3D 상품을 돌려 가며 재질과 마감을 가까이 들여다보세요.","en":"Rotate a 3D product and inspect its material and finish up close."},"wow":{"ko":"어느 각도에서든 소재, 질감, 마감을 살필 수 있을 만큼 정교하게 그려져요.","en":"It's rendered in enough detail to inspect material, texture and finish from any angle."}},{"do":{"ko":"샤오미 전기차 시승이나 DJI 드론 시험 비행 같은 몰입형 체험을 실행해 보세요.","en":"Launch an immersive try-out such as a Xiaomi EV test drive or a DJI drone test flight."},"wow":{"ko":"보기만 하는 게 아니라 쇼핑 앱 안에서 차를 몰아 보고 드론을 날려 보는 체험까지 해요.","en":"It goes beyond viewing: inside a shopping app you test drive a car and fly a drone."}}],"make":[{"ko":"USDZ 모델 하나를 AR Quick Look으로 실제 크기로 띄워 내 방에 맞는지 확인해 보세요.","en":"Open one USDZ model at real size with AR Quick Look and check whether it fits your room."},{"ko":"사양표로 비교하는 화면 하나를 골라, 두 물건을 나란히 놓고 보는 공간 비교로 다시 스케치해 보세요.","en":"Take one spec-sheet comparison screen and re-sketch it as a spatial side-by-side of two objects."}],"ask":{"ko":"실제 크기로 놓아 보는 것이 사양표 숫자보다 왜 더 확신을 줄까요?","en":"Why does placing something at real size give more confidence than the numbers on a spec sheet?"}},"Feather: Draw in 3D":{"time":20,"setup":{"ko":"iPad 전용이고 ₩25,000 일회성 유료 앱이에요. Apple Pencil이 필요해요.","en":"iPad only, a one-time purchase at ₩25,000. You need an Apple Pencil."},"missions":[{"do":{"ko":"3D 가이드 면을 하나 먼저 그리고, 손가락으로 장면을 돌려 가며 그 면 위에 Pencil로 선을 그어 보세요.","en":"First draw a 3D guide surface, then rotate the scene with your fingers while drawing strokes on it with Pencil."},"wow":{"ko":"꼭짓점도 돌출도 몰라도 공간에 선이 그려져요. HCI 박사 연구를 제품으로 만든 이 방식에 픽사·디즈니 아티스트까지 베타 16만 명이 몰렸어요.","en":"You draw in space without knowing vertices or extrusions. This approach, built from HCI PhD research, drew 160,000+ beta users including Pixar and Disney artists."}},{"do":{"ko":"Pencil로 그리는 중에 다른 손가락으로 장면을 돌리고 확대해 보세요.","en":"While drawing with Pencil, orbit and zoom the scene with your other hand's fingers."},"wow":{"ko":"Pencil은 그리고 손가락은 돌리고 옮기는 역할이 깔끔하게 나뉘어 손이 헷갈리지 않아요.","en":"Pencil draws while fingers orbit and pan, a clean split of roles that never confuses your hands."}},{"do":{"ko":"구나 원기둥 같은 기본 도형을 바탕으로 스케치한 뒤 AR 뷰어로 내 책상 위에 띄워 보세요.","en":"Sketch on top of a primitive like a sphere or cylinder, then place it on your desk with the AR viewer."},"wow":{"ko":"간결한 화면 뒤에 기본 도형, 대칭, 3D 리퀴파이 같은 기능이 숨어 있고, 스케치를 실제 공간에 놓아 볼 수 있어요.","en":"Behind the minimal interface hide primitives, mirroring and 3D Liquify, and you can set your sketch in the real world."}}],"make":[{"ko":"그리기 프로토타입에서 Pencil 입력은 그리기, 손가락 입력은 화면 이동으로 나눠 보세요.","en":"In a drawing prototype, assign Pencil input to drawing and finger input to moving the canvas."},{"ko":"어려운 작업 하나를 먼저 기준을 만들고 그 위에 작업하는 두 단계로 쪼갠 흐름을 그려 보세요.","en":"Sketch a flow that splits one hard task into two steps: set up a guide, then work on top of it."}],"ask":{"ko":"두 단계로 나눈 것이 3D 드로잉의 어려움을 어떻게 없앴을까요?","en":"How did splitting it into two steps remove what makes 3D drawing hard?"}},"Hello Kitty Island Adventure":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요. 하루 제한이 실시간으로 초기화되니 이틀에 나눠 해 보면 좋아요.","en":"Requires Apple Arcade. Daily limits reset in real time, so try it across two days."},"missions":[{"do":{"ko":"산리오 캐릭터에게 선물을 주며 우정을 쌓다가 하루 제한에 닿으면, 다음 날 다시 들어와 보세요.","en":"Build friendships by giving gifts to Sanrio characters until you hit the daily limit, then come back the next day."},"wow":{"ko":"하루 제한이 실시간으로 초기화되고 돈으로 건너뛸 타이머가 없어요. 이 리듬으로 Arcade 리뷰 11만 개 넘게 평점 4.9를 받았어요.","en":"Daily limits reset in real time, with no timers to pay past. That rhythm earned a 4.9 rating from over 110,000 Arcade reviews."}},{"do":{"ko":"친구와 협동 플레이로 같은 섬을 함께 돌아다녀 보세요.","en":"Explore the same island together with a friend in co-op."},"wow":{"ko":"탐험, 퍼즐, 제작, 낚시, 집 꾸미기가 섞여 있어 플레이어마다 돌아올 이유가 달라요.","en":"Exploration, puzzles, crafting, fishing and home decorating mix together, so every kind of player finds a reason to return."}},{"do":{"ko":"Apple TV나 Mac에서도 열어 컨트롤러로 해 보세요.","en":"Open it on an Apple TV or Mac too and play with a controller."},"wow":{"ko":"앱 하나가 iPhone, iPad, Mac, Apple TV를 아우르며 터치, 컨트롤러, 큰 화면에 맞춰 UI가 바뀌어요.","en":"One app spans iPhone, iPad, Mac and Apple TV, with the UI adapting to touch, controller and big-screen play."}}],"make":[{"ko":"내 앱의 핵심 행동 하나에 하루 횟수 제한과 실시간 초기화를 붙인 흐름을 그려 보세요.","en":"Sketch a flow that gives one core action in your app a daily limit that resets in real time."},{"ko":"매일 한 번 선물을 주고받는 작은 화면을 프로토타입으로 만들어 보세요.","en":"Prototype a small screen for giving and receiving one gift a day."}],"ask":{"ko":"오늘 할 수 있는 양을 제한한 것이 왜 오히려 매일 돌아오게 만들까요?","en":"Why does limiting how much you can do today make you come back every day?"}},"SmartGym":{"time":15,"setup":{"ko":"핵심을 느끼려면 Apple Watch가 필요해요. 적응형 트레이너는 7일 체험이 있는 프리미엄 구독 기능이에요.","en":"You need an Apple Watch to feel the core idea. The adaptive trainer is a premium subscription feature with a 7-day trial."},"missions":[{"do":{"ko":"iPhone은 두고 Apple Watch만 찬 채 운동 하나를 처음부터 끝까지 기록해 보세요.","en":"Leave your iPhone behind and log a full workout with only your Apple Watch."},"wow":{"ko":"iPhone도 인터넷도 없이 워치만으로 돌아가요. 브라질의 1인 개발자가 처음부터 워치 우선으로 설계해 모든 기능을 손목에 넣었어요.","en":"It runs on the watch alone, no iPhone or internet. A solo developer in Brazil designed it Watch-first and put every feature on the wrist."}},{"do":{"ko":"운동을 몇 번 기록한 뒤 AI Smart Trainer가 다음 운동을 어떻게 바꾸는지 보세요.","en":"After logging a few workouts, see how the AI Smart Trainer changes your next one."},"wow":{"ko":"고정된 계획이 아니라 내 기록에 맞춰 다음 운동을 조정하고 주기화를 적용해요.","en":"Instead of a static plan, it adapts upcoming workouts to your logged performance and applies periodization."}},{"do":{"ko":"처음 해 보는 운동 하나를 골라 애니메이션 시연을 보고 따라 해 보세요.","en":"Pick an exercise you've never done, watch its animated demo and follow along."},"wow":{"ko":"730개 넘는 애니메이션 시연과 130개 넘는 기본 루틴이 있어 초보자도 바로 따라 할 수 있어요.","en":"With 730+ animated demos and 130+ pre-built workouts, even beginners can follow along right away."}}],"make":[{"ko":"내 앱의 기능 하나를 watchOS 앱으로 옮겨 iPhone 없이도 동작하는지 확인해 보세요.","en":"Move one feature of your app into a watchOS app and confirm it works without the iPhone."},{"ko":"손목에서 탭 세 번 이하로 끝나는 기록 흐름을 그려 보세요.","en":"Sketch a logging flow that finishes on the wrist in three taps or fewer."}],"ask":{"ko":"워치를 먼저 설계한 것은 iPhone 앱을 워치로 옮기는 것과 무엇이 달랐을까요?","en":"How is designing for the watch first different from porting an iPhone app to it?"}},"How We Feel":{"time":10,"setup":null,"missions":[{"do":{"ko":"지금 기분을 색 격자에서 골라 정확한 단어를 찾고, 끝까지 쓰며 광고나 결제 화면이 나오는지 보세요.","en":"Pick your current mood on the color grid to find the exact word, and use it to the end watching for any ad or paywall."},"wow":{"ko":"예일대 무드 미터 격자로 감정을 정확한 단어로 짚어요. Pinterest 공동창업자와 예일대 팀이 만든 비영리 앱이라 광고도 구독도 없어요.","en":"Yale's Mood Meter grid pins a feeling to a precise word. Made by a Pinterest co-founder and a Yale team as a nonprofit, it has no ads or subscriptions."}},{"do":{"ko":"감정을 고른 다음 제안되는 짧은 영상 전략 하나를 바로 따라 해 보세요.","en":"After naming an emotion, follow one of the short video strategies it suggests right away."},"wow":{"ko":"인지 재구성, 움직임, 마음챙김, 사회적 연결 네 갈래의 영상 전략으로 알아차림이 바로 행동이 돼요.","en":"Video strategies in four approaches, reframing, movement, mindfulness and social connection, turn awareness straight into action."}},{"do":{"ko":"며칠 기록한 뒤 건강 데이터를 연결해 감정 기록 위에 수면과 운동이 겹쳐 보이게 해 보세요.","en":"After a few days of check-ins, connect your health data so sleep and exercise overlay your emotion history."},"wow":{"ko":"수면과 운동 데이터가 감정 기록 위에 겹쳐져 패턴을 스스로 발견하게 돼요.","en":"Sleep and exercise data overlay your emotions, so you spot the patterns yourself."}},{"do":{"ko":"친구 한 명에게 지금 기분을 실시간으로 공유해 보세요.","en":"Share how you feel right now with one friend in real time."},"wow":{"ko":"감정 체크인이 가벼운 사회적 의식이 돼요. 이 점으로 사회적 영향 부문 결선에 올랐어요.","en":"Emotional check-ins become a lightweight social ritual, the reason it was a Social Impact finalist."}}],"make":[{"ko":"내 앱의 이모지 선택지를 두 축 격자로 바꾸고 칸마다 감정 단어를 넣은 프로토타입을 만들어 보세요.","en":"Prototype a two-axis grid with an emotion word in each cell to replace your app's emoji picker."},{"ko":"기록이 끝난 직후 바로 할 수 있는 행동 하나를 제안하는 화면을 만들어 보세요.","en":"Build a screen that suggests one immediate action right after a check-in is logged."}],"ask":{"ko":"감정에 정확한 이름을 붙이는 것만으로 왜 기분이 달라질까요?","en":"Why does simply giving a feeling its exact name change how you feel?"}},"Blackbox":{"time":15,"setup":{"ko":"2024년 수상작인 Vision Pro 버전은 $9.99 유료 앱이고, iPhone에서는 원래의 iOS 게임으로 해 볼 수 있어요.","en":"The 2024 award-winning Vision Pro version is a $9.99 paid app; on iPhone you can play the original iOS game."},"missions":[{"do":{"ko":"첫 퍼즐을 열고 화면은 누르지 말고 볼륨, 밝기, 충전처럼 기기 자체로 할 수 있는 일을 해 보세요.","en":"Open the first puzzle and, without touching the screen, try things you can do with the device itself, like volume, brightness or charging."},"wow":{"ko":"화면 터치로는 풀 수 없고 센서, 볼륨, 충전, 빛 같은 기기 자체로 풀어요. 혼자 만든 이 게임이 iOS와 Vision Pro로 7년 간격 ADA를 두 번 받았어요.","en":"You can't solve it by touching the screen; you use sensors, volume, charging and light. This solo-made game won two ADAs seven years apart, on iOS and Vision Pro."}},{"do":{"ko":"막히면 공략을 찾지 말고 기기로 할 수 있는 일을 하나씩 시도해 보세요.","en":"When you get stuck, don't look up a solution; try everything the device can do, one at a time."},"wow":{"ko":"일부러 설명을 주지 않아 퍼즐마다 '어떻게 한 거지?' 하는 발견이 돼요. 튜토리얼 대신 단서로 가르쳐요.","en":"Instructions are deliberately withheld, so each puzzle becomes a 'how did they do that?' discovery that teaches through affordances."}},{"do":{"ko":"Vision Pro 버전이 있다면 레벨 선택 화면에 떠다니는 비눗방울을 건드려 보세요.","en":"If you have the Vision Pro version, touch the soapy bubbles floating on the level-select screen."},"wow":{"ko":"비눗방울이 레벨 선택 인터페이스이면서 반응해서 터지는 장난감이에요. 공간 캔버스 구석구석을 탐험하도록 다시 설계됐어요.","en":"The bubbles are the level-select interface and also pop in response to you. The game was rethought so you explore every corner of the spatial canvas."}}],"make":[{"ko":"화면 대신 기기 기울이기나 흔들기에만 반응하는 버튼 하나를 Core Motion으로 만들어 보세요.","en":"Use Core Motion to build one control that responds only to tilting or shaking the device, not the screen."},{"ko":"내 앱의 튜토리얼 문장 하나를 지우고 그 자리를 단서가 되는 시각 요소로 바꿔 보세요.","en":"Delete one tutorial sentence in your app and replace it with a visual clue."}],"ask":{"ko":"설명을 주지 않은 것이 왜 발견의 기쁨을 더 크게 만들까요?","en":"Why does withholding instructions make the joy of discovery bigger?"}},"Finding Hannah":{"time":15,"setup":{"ko":"무료로 시작할 수 있고, 전체 게임은 3.99달러 한 번 구입으로 열려요.","en":"Free to start; the full game unlocks with a single $3.99 purchase."},"missions":[{"do":{"ko":"첫 장면을 시작해 이야기 속 인물을 살펴보세요. 해나, 어머니, 할머니가 각각 어느 시대에 사는지 확인해 보세요.","en":"Start the first scene and look at who the story is about. Check which era Hannah, her mother and her grandmother each live in."},"wow":{"ko":"숨은그림찾기인데 주인공이 베를린의 세 세대 여성이에요. 여성 창업자 스튜디오가 여성을 위해 만든 이 게임은 2023 ADA 포용성 결선과 App Store 어워드 문화적 영향 부문에 올랐어요.","en":"It is a hidden-object game whose heroes are three generations of women in Berlin. Made for women by a women-led studio, it was a 2023 Inclusivity ADA finalist and won an App Store Award for Cultural Impact."}},{"do":{"ko":"해나에게 필요한 셀프케어 아이템을 합쳐 보세요. 합친 직후 화면에 무엇이 새로 열리는지 지켜보세요.","en":"Merge the self-care items Hannah needs. Watch what opens up on screen right after you combine them."},"wow":{"ko":"아이템 합치기가 점수가 아니라 이야기를 열어요. 해나가 스트레스를 다스릴 물건을 만들어야 새 장면으로 넘어가요.","en":"Merging does not add points; it opens the story. You reach new scenes by making the things Hannah needs to manage stress."}},{"do":{"ko":"장면 속 대사와 상황에서 월세나 일에 대한 이야기를 찾아보세요.","en":"Look for talk about rent or work in the dialogue and situations of each scene."},"wow":{"ko":"캐주얼 게임에서 보기 드문 직업 불만족, 월세 걱정, 권태 같은 어른의 고민이 입체적인 인물을 통해 나와요.","en":"Grown-up worries rarely seen in casual games, like job dissatisfaction, rent and ennui, come through multi-dimensional characters."}},{"do":{"ko":"시간을 신경 쓰지 말고 손그림 장면 하나를 천천히 뒤져 보세요.","en":"Search one hand-drawn scene slowly, without thinking about time."},"wow":{"ko":"재촉하는 장치 없이 내 속도로 찾을 수 있어요. 점수 마스터 도전은 선택이라 원할 때만 하면 돼요.","en":"Nothing rushes you, so you search at your own pace. Score-mastery challenges are optional and only there if you want them."}}],"make":[{"ko":"내 앱의 보상 하나를 골라, 점수 대신 이야기나 새 화면이 열리는 보상으로 바꾼 프로토타입을 만들어 보세요.","en":"Pick one reward in your app and prototype a version where it opens a story beat or a new screen instead of adding points."},{"ko":"내 앱의 예시 사용자를 흔히 다루지 않는 사람으로 바꾸고, 그 사람의 실제 고민 하나를 화면 문구에 넣어 보세요.","en":"Swap your app's example user for someone apps rarely feature, and put one of that person's real worries into the screen copy."}],"ask":{"ko":"익숙한 숨은그림찾기에 어른 여성의 이야기를 넣었을 때 왜 더 새롭게 느껴졌을까요?","en":"Why did a familiar hidden-object game feel new once it told grown-up women's stories?"}},"Automatoys":{"time":10,"setup":{"ko":"처음 세 레벨은 무료이고, 전체 게임은 1.99달러 한 번 구입으로 열려요.","en":"The first three levels are free; the full game unlocks with a single $1.99 purchase."},"missions":[{"do":{"ko":"무료인 첫 레벨을 끝까지 해 보세요. 동전을 넣은 뒤 공이 지나가는 장치를 하나씩 건드려 보세요.","en":"Play the first free level to the end. After the coin goes in, touch each contraption the ball passes through."},"wow":{"ko":"레벨이 12개뿐인 이 게임은 Steffan Glynn 한 사람이 기획과 프로그래밍을 맡은 첫 인디작이에요. 그런데도 2023 ADA 인터랙션 결선에 올랐어요.","en":"This 12-level game was Steffan Glynn's first indie release, designed and programmed by him alone, and it still made the 2023 Interaction ADA finalists."}},{"do":{"ko":"소리와 햅틱을 켠 채 레버와 톱니를 돌려 보세요. 손끝에 무엇이 느껴지는지 집중해 보세요.","en":"With sound and haptics on, turn the levers and gears. Pay attention to what you feel in your fingertips."},"wow":{"ko":"장난감 같은 재질, 효과음, 햅틱이 겹쳐서 화면 속 레버와 톱니가 진짜 물건처럼 느껴져요.","en":"Toy-like materials, satisfying sounds and haptic feedback combine so the levers and gears on screen feel like physical objects."}},{"do":{"ko":"일부러 타이밍을 틀려 공을 떨어뜨려 보세요. 그다음 기계가 움직이는 모습을 보고 다시 해 보세요.","en":"Miss the timing on purpose and drop the ball. Then watch how the machine moves and try again."},"wow":{"ko":"조작은 탭 하나뿐이고 나머지는 물리 시뮬레이션이 해요. 실패의 원인이 손재주가 아니라 기계를 이해하는 데 있다는 걸 바로 알게 돼요.","en":"Input is a single tap and the physics does the rest. You realize right away that failure is about understanding the machine, not dexterity."}}],"make":[{"ko":"버튼 하나를 골라 탭할 때 소리와 햅틱을 함께 넣고, 넣기 전과 후를 친구에게 눌러 보게 하세요.","en":"Pick one button, add a sound and a haptic to its tap, and have a friend press the before and after versions."},{"ko":"SpriteKit 물리로 공 하나와 탭하면 움직이는 장치 하나만 있는 퍼즐 화면을 만들어 보세요.","en":"Build a puzzle screen in SpriteKit physics with just one ball and one contraption that moves when tapped."}],"ask":{"ko":"조작은 탭 하나뿐인데 왜 손으로 기계를 만지는 느낌이 났을까요?","en":"With only one tap as input, why did it feel like handling a real machine?"}},"Riveo":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라 개발사가 공개한 트레일러나 스크린샷으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"트레일러나 스크린샷에서 키프레임, 마스크, 블렌드 모드가 쓰이는 장면을 찾아보세요. 그 화면이 휴대폰이라는 점을 떠올려 보세요.","en":"In the trailer or screenshots, find moments where keyframes, masks or blend modes are used. Remember that this is a phone screen."},"wow":{"ko":"데스크톱 편집기에 있을 법한 키프레임, 마스크, 블렌드 모드, 3D 텍스트 애니메이션을 작은 독립 팀이 아이폰에 넣었고, 4K 60fps로 내보낼 수 있었어요.","en":"A small independent team put desktop-class keyframes, masks, blend modes and 3D text animation on the iPhone, with export up to 4K at 60fps."}},{"do":{"ko":"텍스트, 오버레이, 효과가 겹친 편집 화면을 찾아 레이어가 어떻게 정리돼 있는지 보세요.","en":"Find an editing screen with text, overlays and effects stacked together, and see how the layers are organized."},"wow":{"ko":"데스크톱 타임라인을 줄인 게 아니라, 휴대폰에서 여러 겹의 편집을 다룰 수 있게 터치 중심으로 새로 설계했어요.","en":"Instead of shrinking a desktop timeline, it was designed touch-first so layered edits stay manageable on a phone."}},{"do":{"ko":"지금 미국 App Store에서 이 앱을 검색해 보세요.","en":"Search for the app on the US App Store today."},"wow":{"ko":"Apple이 비주얼 부문에서 인정한 야심 찬 앱인데도 2026년 기준 스토어에서 사라졌어요. 좋은 디자인만으로 앱이 살아남지 않는다는 걸 보여 줘요.","en":"Even an ambitious app Apple recognized for visuals is no longer listed as of 2026. It shows that good design alone does not keep an app alive."}}],"make":[{"ko":"내 앱의 복잡한 화면 하나를 골라, 휴대폰 한 화면에서 손가락으로 다룰 수 있는 접히는 레이어 목록으로 다시 그려 보세요.","en":"Pick one complex screen in your app and redraw it as a collapsible layer list you can handle with a finger on one phone screen."},{"ko":"SwiftUI로 사진 위에 텍스트 하나를 올리고 드래그와 핀치로 위치와 크기를 바꾸는 프로토타입을 만들어 보세요.","en":"Prototype in SwiftUI a text layer over a photo that you move and resize with drag and pinch."}],"ask":{"ko":"휴대폰에서 레이어 편집이 다루기 쉬워 보이게 만든 핵심은 무엇이었을까요?","en":"What was the key to making layered editing look manageable on a phone?"}},"Noted.":{"time":15,"setup":{"ko":"녹음해 볼 팟캐스트나 강의 영상, 또는 잠깐 대화해 줄 사람이 있으면 좋아요.","en":"Have a podcast or lecture to record, or someone to talk with for a few minutes."},"missions":[{"do":{"ko":"팟캐스트를 틀어 두고 녹음하면서 메모를 몇 줄 적어 보세요. 녹음이 끝나면 중간에 적은 메모 하나를 탭해 보세요.","en":"Record a podcast playing nearby and type a few notes as it goes. When it ends, tap a note you wrote in the middle."},"wow":{"ko":"재생이 그 메모를 적던 바로 그 순간으로 점프해요. 전부 받아 적지 않아도 돼서 녹음에 의존하는 학습장애 학생에게 특히 쓸모 있었어요.","en":"Playback jumps to the exact moment you wrote that note. You no longer have to transcribe everything, which matters most to students with learning differences."}},{"do":{"ko":"두 사람이 말하는 녹음을 하며 실시간 전사를 켜 보세요. 다음 녹음에서도 같은 사람이 말하게 해 보세요.","en":"Record two people talking with live transcription on. Then have the same person speak in a second recording."},"wow":{"ko":"말이 바로 글이 되고 화자가 구분돼요. 같은 사람을 다음 녹음에서도 기억해서 녹음이 검색할 수 있는 텍스트가 돼요.","en":"Speech becomes text as you go and speakers are told apart. It remembers the same person across recordings, so audio turns into searchable text."}},{"do":{"ko":"중간에 말이 끊기는 긴 녹음을 재생해 보세요.","en":"Play back a long recording that has pauses in it."},"wow":{"ko":"지능형 재생이 침묵 구간을 건너뛰고, AI 요약이 긴 강의나 회의를 짧게 줄여 줘요.","en":"Intelligent playback skips the silences, and AI summarization condenses long lectures or meetings."}},{"do":{"ko":"시스템 글자 크기를 크게 키우고 VoiceOver를 켠 채 메모를 열어 보세요.","en":"Turn the system text size way up, switch on VoiceOver and open a note."},"wow":{"ko":"텍스트를 200% 넘게 키워도, VoiceOver나 음성 제어로도 쓸 수 있어요. 포용성 결선에 오른 이유가 여기 있어요.","en":"It stays usable with text scaled past 200% and with VoiceOver or Voice Control. That is the angle behind its Inclusivity nomination."}}],"make":[{"ko":"AVAudioRecorder로 녹음하면서 메모를 추가할 때 현재 녹음 시간을 함께 저장하고, 메모를 탭하면 그 시간부터 재생되게 해 보세요.","en":"While recording with AVAudioRecorder, save the current time with each note, and make tapping a note play from that time."},{"ko":"내 앱의 긴 콘텐츠 하나에, 탭하면 해당 위치로 바로 가는 타임스탬프 목록을 붙여 보세요.","en":"Add a list of timestamps to one long piece of content in your app that jump straight to that spot when tapped."}],"ask":{"ko":"메모와 녹음 시간을 묶은 작은 연결 하나가 왜 받아 적는 부담을 그렇게 크게 줄였을까요?","en":"Why did one small link between a note and a moment in the audio take so much pressure off note-taking?"}},"Gibbon: Beyond the Trees":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"do":{"ko":"첫 정글에서 누른 채 매달렸다가 타이밍 맞춰 손을 떼 보세요. 계속 나아가며 배경이 어떻게 바뀌는지 지켜보세요.","en":"In the first jungle, hold to swing and release with timing. Keep going and watch how the backdrop changes."},"wow":{"ko":"원래 도피형 게임이었지만 팀은 이 유려한 움직임만 주는 건 잘못이라며 중심을 산림 파괴로 바꿨어요. 손그림 정글이 농장과 도시로 변하며 글 없이 그걸 말해요.","en":"It began as pure escapism, but the team felt giving only this fluid swinging was wrong and made deforestation the core. Painted jungle turning into plantations and cities says it without text."}},{"do":{"ko":"손을 떼고 날아가는 동안 공중제비를 연달아 이어 속도를 올려 보세요.","en":"While flying after a release, chain backflips to build speed."},"wow":{"ko":"누르면 알아서 흔들리고 떼는 타이밍만 고르면 돼요. 운동량으로 이어지는 움직임이 진짜 긴팔원숭이처럼 느껴져요.","en":"Holding swings you automatically and you only choose when to let go. Momentum carries through, so it feels like being a real gibbon."}},{"do":{"ko":"공중에서 다른 긴팔원숭이를 만나면 가까이 가 보세요.","en":"When you meet another gibbon mid-air, move close to it."},"wow":{"ko":"다른 긴팔원숭이와 만나면 도움 동작이 생겨서 혼자 하는 플랫포머가 가족과 협력의 표현이 돼요. 소셜 임팩트 수상의 뿌리예요.","en":"Meeting another gibbon unlocks assist moves, turning a solo platformer into an expression of family and cooperation, the root of its Social Impact award."}}],"make":[{"ko":"누르는 동안 자동으로 흔들리고 떼면 날아가는 진자 움직임 하나를 SpriteKit 물리로 만들어 보세요.","en":"Build one pendulum movement in SpriteKit physics that swings while held and flies when released."},{"ko":"내 앱의 배경 이미지 하나를 사용자의 진행에 따라 단계적으로 바뀌게 해서 글 없이 메시지를 전해 보세요.","en":"Make one background image in your app change in stages as the user progresses, delivering a message without text."}],"ask":{"ko":"움직임이 즐거울수록 망가지는 배경이 왜 더 아프게 다가왔을까요?","en":"Why did the ruined scenery hurt more precisely because the movement felt so good?"}},"Behind the Frame":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라 개발사가 공개한 트레일러나 스크린샷으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"트레일러에서 손그림 장면이 나올 때 영상을 멈추고 빛과 색을 살펴보세요.","en":"Pause the trailer on a hand-drawn scene and study the light and color."},"wow":{"ko":"아카츠키 대만 지사가 시험 삼아 꾸린 사내 스튜디오의 첫 오리지널 작품인데, 지브리풍 손그림만으로 NYX 어워드 비주얼 아트 금상을 받았어요.","en":"It was the first original game from a trial in-house studio at Akatsuki's Taiwan office, and its Ghibli-like hand-drawn art won NYX Gold for Best Visual Art."}},{"do":{"ko":"스크린샷 여러 장에서 같은 아파트 창밖 풍경을 찾아 서로 비교해 보세요.","en":"Find the same apartment view across several screenshots and compare them."},"wow":{"ko":"아파트 풍경 하나가 시간에 따라 바뀌면서 이야기를 끌고 가요. 그림이 서사의 대부분을 맡아요.","en":"A single apartment view changes over time and carries the story. The visuals do most of the storytelling."}},{"do":{"ko":"트레일러에서 대사나 자막이 거의 없는지 확인하며 길 건너 이웃의 모습을 따라가 보세요.","en":"In the trailer, notice how little dialogue there is and follow the neighbor across the street."},"wow":{"ko":"이야기는 거의 말없이, 창 너머 이웃과 완성해 가는 그림으로 펼쳐져요. 대사 대신 환경 단서에 기대요.","en":"The story unfolds almost wordlessly through the neighbor you watch and the paintings you finish. It relies on environmental clues, not dialogue."}}],"make":[{"ko":"내 앱 화면 하나에서 설명 문구를 지우고 그림이나 배경 변화만으로 상태를 전해 보세요.","en":"Remove the explanatory copy from one screen in your app and convey its state through art or background changes alone."},{"ko":"같은 배경 이미지를 시간대별로 세 장 바꿔 보여 주는 화면을 만들고, 사용자가 무엇을 읽어 내는지 물어보세요.","en":"Build a screen that shows the same background in three times of day, and ask someone what story they read from it."}],"ask":{"ko":"대사 없이도 이야기가 전해졌다면, 그 역할을 한 건 그림의 어떤 요소였을까요?","en":"If the story came through without dialogue, which part of the art did that work?"}},"Alba: A Wildlife Adventure":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"do":{"ko":"게임을 시작해 쓰레기 줍기처럼 섬의 자연을 지키는 일을 하나 해 보세요. 그리고 이 게임이 현실에서 약속한 일을 떠올려 보세요.","en":"Start the game and do one thing that protects the island, like picking up litter. Then think about what this game promised in the real world."},"wow":{"ko":"다운로드 1건마다 나무 1그루를 심겠다고 약속했고, 출시 약 1년 만인 2021년 12월 실제로 100만 그루를 심었어요. 게임 속 선행이 현실과 이어져요.","en":"It promised one tree for every download and hit one million trees planted in December 2021, about a year after launch. Kindness in the game connects to the real world."}},{"do":{"ko":"카메라를 꺼내 동물 하나를 찾아 찍고 도감에 기록해 보세요.","en":"Take out the camera, find an animal, photograph it and log it."},"wow":{"ko":"핵심 동작이 싸움이 아니라 사진 찍기예요. 관찰할수록 보상받는 조용하고 폭력 없는 루프예요.","en":"The core verb is photography, not fighting. It is a gentle, non-violent loop that rewards observation."}},{"do":{"ko":"다리를 고치거나 동물을 구한 뒤 마을 사람들의 반응을 살펴보세요.","en":"After repairing the bridge or rescuing an animal, watch how the townspeople react."},"wow":{"ko":"내 행동이 섬을 눈에 띄게 바꾸고 호텔 개발에 맞서 마을을 모아요. 아이 주인공이 환경 운동을 친근하게 만들어요.","en":"Your actions visibly change the island and rally the town against a hotel development. A child hero makes activism feel approachable."}}],"make":[{"ko":"내 앱의 주요 행동 하나가 현실의 작은 변화로 이어진다면 어떻게 보여 줄지 완료 화면 시안을 그려 보세요.","en":"Sketch a completion screen showing how one key action in your app could lead to a small real-world change."},{"ko":"카메라로 찍을 때마다 도감이 하나씩 채워지는 수집 화면 프로토타입을 만들어 보세요.","en":"Prototype a collection screen where each photo you take fills in one entry of a catalog."}],"ask":{"ko":"게임 속 작은 행동이 현실의 나무로 이어진다는 사실이 플레이 기분을 어떻게 바꿨나요?","en":"How did knowing that small acts in the game connected to real trees change how playing felt?"}},"Craft":{"time":15,"setup":null,"missions":[{"do":{"ko":"새 문서를 만들어 제목과 몇 줄만 적어 보세요. 따로 꾸미지 말고 그대로 보세요.","en":"Create a new document with a title and a few lines. Do not style anything; just look at it."},"wow":{"ko":"꾸미지 않아도 출판물처럼 보여요. 부다페스트의 작은 스타트업이 만든 이 앱은 2021년 ADA 결선과 Mac 올해의 앱을 함께 차지했어요.","en":"It looks publishable with no styling at all. This app from a small Budapest startup was both a 2021 ADA finalist and Mac App of the Year."}},{"do":{"ko":"문서 안의 블록 하나를 페이지로 바꾸고, 그 안에 또 페이지를 만들어 보세요.","en":"Turn one block in the document into a page, then make another page inside it."},"wow":{"ko":"모든 것이 블록이고 어떤 블록이든 페이지가 돼요. 폴더 없이도 문서 안에 문서를 넣어 구조가 생겨요.","en":"Everything is a block and any block can become a page. Nesting documents inside documents gives structure with no folders."}},{"do":{"ko":"방금 쓴 문서를 웹 페이지로 공유하고 그 링크를 브라우저에서 열어 보세요.","en":"Publish the document as a web page and open the link in a browser."},"wow":{"ko":"탭 한 번에 개인 메모가 공유 가능한 웹 페이지가 돼요. 메모와 공유 문서의 경계가 흐려져요.","en":"One tap turns a private note into a shareable web page, blurring the line between notes and shared documents."}}],"make":[{"ko":"내 앱의 목록 항목 하나를 탭하면 하위 항목을 담는 페이지로 바뀌는 중첩 구조를 SwiftUI로 만들어 보세요.","en":"Build a nested structure in SwiftUI where tapping a list item turns it into a page that holds sub-items."},{"ko":"기본 글꼴, 여백, 줄 간격만 다듬어 내 앱의 빈 화면이 꾸미지 않아도 완성돼 보이게 해 보세요.","en":"Tune only the default font, margins and line spacing so your app's empty screen looks finished without any styling."}],"ask":{"ko":"아무 설정도 안 했는데 문서가 예뻐 보였다면, 그건 어떤 기본값 덕분이었을까요?","en":"If the document looked good without any settings, which defaults made that happen?"}},"Beyond a Steel Sky":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"do":{"ko":"게임을 시작해 첫 장면의 그림체와 만화 같은 텍스트 상자를 살펴보세요.","en":"Start the game and study the art style and comic-book text boxes in the first scene."},"wow":{"ko":"1994년 고전의 후속작을 약 25년 만에 원작자 찰스 세실과 왓치맨의 데이브 기번스가 다시 만들었어요. 기번스의 아트 덕분에 3D인데도 그래픽 노블처럼 보여요.","en":"About 25 years after the 1994 classic, Charles Cecil and Watchmen's Dave Gibbons reunited for the sequel. Gibbons's art direction makes the 3D world read like a graphic novel."}},{"do":{"ko":"해킹할 수 있는 기계를 만나면 그 논리를 바꿔 보고 세상이 어떻게 달라지는지 보세요.","en":"When you find a machine you can hack, change its logic and watch how the world responds."},"wow":{"ko":"퍼즐이 도시 시스템 해킹이에요. 기계와 장치의 논리를 다시 연결하면 세상이 움직이는 방식이 바뀌어요.","en":"The puzzles are about hacking the city's systems. Rewire the logic of machines and devices and the world behaves differently."}},{"do":{"ko":"유니온 시티를 돌아다니며 주민과 대화하고 배경 구석구석을 살펴보세요.","en":"Walk around Union City, talk to residents and look into the corners of the scenery."},"wow":{"ko":"완벽한 유토피아처럼 보이는 도시의 균열이 환경 디테일과 대화 속에서 조금씩 드러나요.","en":"The cracks in a seemingly perfect utopia slowly show through environmental details and dialogue."}}],"make":[{"ko":"내 앱의 안내 문구 하나를 만화 텍스트 상자 스타일로 바꾸고 화면 분위기가 어떻게 달라지는지 보세요.","en":"Restyle one piece of guidance copy in your app as a comic text box and see how the mood changes."},{"ko":"스위치 몇 개의 연결을 바꾸면 결과가 달라지는 작은 논리 퍼즐 화면을 SwiftUI로 만들어 보세요.","en":"Build a small logic-puzzle screen in SwiftUI where rewiring a few switches changes the outcome."}],"ask":{"ko":"25년 만의 후속작이 옛것이 아니라 새롭게 느껴졌다면, 그건 무엇 때문이었을까요?","en":"If a sequel 25 years later felt fresh rather than dated, what made it so?"}},"StaffPad":{"time":20,"setup":{"ko":"iPad 전용 앱이고 77,000원 한 번 구입이 필요해요. Apple Pencil이 있으면 가장 좋아요.","en":"iPad only, with a one-time ₩77,000 purchase. An Apple Pencil is best."},"missions":[{"do":{"ko":"Apple Pencil로 오선지에 음표 몇 개를 손으로 적어 보세요. 그리고 재생을 눌러 보세요.","en":"Handwrite a few notes on the staff with Apple Pencil. Then press play."},"wow":{"ko":"손글씨 음표가 바로 인쇄 악보로 바뀌고 오케스트라 샘플이 연주해요. 영화 음악 작곡가가 녹음 현장에서 빨리 고치고 싶어서 직접 만들었어요.","en":"Your handwritten notes turn into engraved notation and an orchestra plays them. A film composer built it because he wanted faster edits during scoring sessions."}},{"do":{"ko":"음표 위에 스타카토 점이나 크레셴도 기호를 손으로 그려 보세요.","en":"Draw a staccato dot or a crescendo marking over your notes by hand."},"wow":{"ko":"아티큘레이션과 다이내믹까지 손글씨로 인식해요. 팔레트를 찾을 필요 없이 종이와 펜처럼 계속 써 나가요.","en":"Articulations and dynamics are recognized from handwriting too. No palette hunting; you keep writing as with pen and paper."}},{"do":{"ko":"펜으로 음표 하나를 세게, 또 하나를 살짝 눌러 지워 보세요.","en":"Erase one note pressing hard and another pressing lightly."},"wow":{"ko":"지우기가 펜 압력에 반응해요. 도구가 펜슬의 움직임에 맞춰 반응해서 종이 위 작업처럼 느껴져요.","en":"Erasing responds to pencil pressure. The tools adapt to the pencil, so it feels like working on paper."}}],"make":[{"ko":"PencilKit 캔버스에 쓴 글씨를 이미지로 만들어 Vision 텍스트 인식으로 읽고 결과를 바로 보여 주는 프로토타입을 만들어 보세요.","en":"Prototype a PencilKit canvas whose handwriting is rendered to an image, read with Vision text recognition and shown instantly."},{"ko":"내 앱의 입력 하나를 팔레트 선택 대신 손으로 쓰거나 그리는 방식으로 바꿔 보세요.","en":"Change one input in your app from picking in a palette to writing or drawing by hand."}],"ask":{"ko":"손으로 쓴 음표가 바로 악보와 소리로 돌아올 때, 작곡하는 흐름이 왜 덜 끊겼을까요?","en":"Why did composing feel less interrupted when handwritten notes came straight back as notation and sound?"}},"Blinkist":{"time":15,"setup":{"ko":"결제하지 않아도 돼요. 온보딩 끝의 무료 체험 결제 화면을 관찰한 뒤 닫아도 충분해요.","en":"No purchase needed; you can study the free-trial payment screen at the end of onboarding and close it."},"missions":[{"do":{"ko":"관심 있는 책의 블링크 하나를 열어 텍스트로 읽다가 오디오로 바꿔 들어 보세요.","en":"Open a Blink for a book you care about, read for a bit, then switch to audio."},"wow":{"ko":"책 한 권의 핵심이 약 15분 분량으로 줄어 있고, 읽던 자리에서 듣기로 이어져요. 출퇴근 같은 짧은 틈에 맞춘 단위예요.","en":"A whole book is distilled to about 15 minutes, and listening picks up where you were reading. It is sized for gaps like a commute."}},{"do":{"ko":"온보딩에서 관심 분야와 목표를 골라 끝까지 가 보세요. 마지막 화면에서 멈춰 보세요.","en":"Go through onboarding choosing interests and goals, and stop on the last screen."},"wow":{"ko":"개인화 추천을 약속한 흐름의 끝이 곧 무료 체험과 결제 화면이에요. 기대가 가장 높은 순간에 결제를 제안해요.","en":"The flow that promised personal picks ends on the free-trial payment screen, asking for payment when expectation peaks."}},{"do":{"ko":"그 결제 화면에서 건너뛰기 동선과 체험 기간 안내 문구를 찾아보세요.","en":"On that payment screen, look for the way to skip and the copy explaining the trial."},"wow":{"ko":"가치를 경험하기 전에 결제를 묻는 구조라서, 건너뛰기 동선과 안내 문구를 어디에 두었는지가 신뢰를 좌우해요.","en":"Because it asks for payment before you have felt the value, where the skip path and trial copy sit decides how much you trust it."}}],"make":[{"ko":"내 앱의 핵심 콘텐츠를 15분 안에 끝나는 단위 하나로 잘라 보고, 그 길이를 화면에 미리 표시해 보세요.","en":"Cut your app's core content into one unit that ends within 15 minutes, and show that length up front."},{"ko":"온보딩 마지막 화면을 결제 제안 버전과 바로 시작 버전으로 그려 친구에게 어느 쪽이 편한지 물어보세요.","en":"Sketch your last onboarding screen as a paywall version and a start-now version, and ask a friend which feels better."}],"ask":{"ko":"15분이라는 길이가 책을 읽는 부담을 왜 그렇게 낮춰 줬을까요?","en":"Why did a 15-minute length lower the barrier to reading a book so much?"}},"Widgetsmith":{"time":15,"setup":null,"missions":[{"do":{"ko":"소형 위젯을 만들어 글꼴과 색을 바꾼 뒤, 시간대별로 다른 위젯이 보이게 스케줄을 걸어 보세요.","en":"Make a small widget, change its font and color, then schedule a different widget for another time of day."},"wow":{"ko":"정해진 시간이 되면 홈 화면 위젯이 저절로 바뀌어요. 제한된 위젯 API 안에서 살아 있는 홈 화면을 만들었어요.","en":"At the set time, the widget on your Home Screen swaps by itself. It makes a living Home Screen within a limited widget API."}},{"do":{"ko":"투명 위젯 배경을 골라 내 배경화면 위에 놓아 보세요.","en":"Choose a transparent widget background and place it over your wallpaper."},"wow":{"ko":"위젯이 배경화면에 녹아든 것처럼 보여요. 이걸 위해 개발자가 31개 iPhone 모델의 위젯 위치를 직접 측정했어요.","en":"The widget seems to melt into the wallpaper. To get this right, the developer measured widget positions on 31 iPhone models."}}],"make":[{"ko":"WidgetKit 타임라인에 시간대별로 다른 항목 두 개를 넣어 아침과 저녁에 다른 위젯이 보이게 해 보세요.","en":"Put two entries for different times in a WidgetKit timeline so the widget differs in the morning and evening."},{"ko":"내 앱 위젯 하나에 글꼴과 색 두 가지만 사용자가 고를 수 있는 편집 화면을 만들어 보세요.","en":"Build an editor for one of your widgets that lets users choose just the font and the color."}],"ask":{"ko":"위젯이 시간에 따라 바뀌는 것만으로 홈 화면이 왜 살아 있다고 느껴졌을까요?","en":"Why did a widget that changes with the time make the Home Screen feel alive?"}},"Shazam":{"time":5,"setup":{"ko":"주변에서 음악이 나오고 있어야 해요.","en":"You need music playing nearby."},"missions":[{"do":{"ko":"음악을 틀어 둔 채로 앱을 열고 가운데 버튼을 탭해 보세요. 인식될 때까지 몇 초인지 세어 보세요.","en":"With music playing, open the app and tap the big center button. Count the seconds until it recognizes the song."},"wow":{"ko":"탭 한 번이면 짧은 샘플만으로 곡을 찾아요. 기다리는 동안 버튼이 파동처럼 퍼져서 몇 초가 불안이 아니라 기대가 돼요.","en":"One tap and a short sample are enough to find the song. The button ripples while it listens, so the wait feels like anticipation, not worry."}},{"do":{"ko":"이번엔 앱을 열지 말고 제어 센터의 음악 인식이나 액션 버튼으로 같은 곡을 찾아보세요.","en":"This time, without opening the app, find the same song from Music Recognition in Control Center or the Action button."},"wow":{"ko":"앱을 열지 않아도 시스템 곳곳에서 바로 인식이 시작돼요. 진입점 자체가 기능이 됐어요.","en":"Recognition starts from all over the system without opening the app. The entry points themselves became the feature."}},{"do":{"ko":"음악을 끈 조용한 곳에서 버튼을 눌러 일부러 실패해 보세요. 성공했을 때의 화면과 비교해 보세요.","en":"Turn the music off and tap in silence to fail on purpose. Compare it with the success screen."},"wow":{"ko":"성공하면 앨범 아트가 화면 가득 펼쳐지고, 실패하면 짧은 메시지로 다시 해 보게 해요. 대기, 성공, 실패가 한눈에 구분돼요.","en":"Success spreads the album art across the screen; failure shows a short nudge to try again. Waiting, success and failure are clearly distinct."}}],"make":[{"ko":"내 앱의 오래 걸리는 작업 하나에 버튼이 파동처럼 퍼지는 대기 애니메이션을 넣고, 넣기 전과 비교해 보세요.","en":"Add a rippling wait animation to one slow task in your app and compare it with the version without."},{"ko":"ShazamKit으로 버튼 하나를 누르면 주변 곡을 찾아 제목을 보여 주는 화면을 만들어 보세요.","en":"Use ShazamKit to build a screen where one button identifies the song nearby and shows its title."}],"ask":{"ko":"몇 초의 기다림이 지루하지 않았다면, 그건 화면의 어떤 부분 덕분이었을까요?","en":"If those few seconds of waiting did not feel dull, which part of the screen made that so?"}},"Photomator":{"time":10,"setup":{"ko":"어둡게 찍혀 노이즈가 많은 사진이나 해상도가 낮은 사진이 보관함에 있으면 좋아요.","en":"Have a noisy low-light photo or a low-resolution photo in your library."},"missions":[{"do":{"ko":"어둡게 찍혀 노이즈가 많은 사진을 열고 Denoise를 적용해 보세요. 적용 전후를 번갈아 비교해 보세요.","en":"Open a noisy low-light photo and apply Denoise. Flip between before and after."},"wow":{"ko":"머신러닝 보정이 버튼 하나에 숨어 있어요. 진행 상태를 보여 주고 비파괴로 적용해서 기다림과 되돌리기 걱정이 줄어요.","en":"Machine-learning correction hides behind one button. It shows progress and applies non-destructively, so waiting and undoing feel safe."}},{"do":{"ko":"해상도가 낮은 사진에 Super Resolution을 적용하고 크게 확대해 디테일을 보세요.","en":"Apply Super Resolution to a low-resolution photo and zoom in on the detail."},"wow":{"ko":"해상도를 키우는 무거운 ML 연산이 Core ML, Core Image, Metal로 기기 안에서 처리돼요.","en":"The heavy ML upscaling runs on the device itself through Core ML, Core Image and Metal."}},{"do":{"ko":"하늘이 있는 사진에서 하늘 자동 선택을 써 보세요.","en":"On a photo with sky in it, use automatic sky selection."},"wow":{"ko":"피사체, 하늘, 배경을 손으로 칠하지 않아도 자동으로 골라 줘요.","en":"It picks out the subject, sky or background automatically, with no brushing by hand."}},{"do":{"ko":"편집을 마친 뒤 사진 앱을 열어 같은 사진을 확인해 보세요.","en":"After editing, open the Photos app and check the same picture."},"wow":{"ko":"가져오기나 내보내기 없이 편집 결과가 사진 앱에 자동으로 반영돼요.","en":"Your edit is already in Photos, with no import or export step."}}],"make":[{"ko":"Core Image 노이즈 감소 필터 하나를 버튼에 연결하고, 원본과 결과를 탭으로 번갈아 보는 화면을 만들어 보세요.","en":"Wire a Core Image noise-reduction filter to a button and build a screen that toggles original and result on tap."},{"ko":"내 앱의 오래 걸리는 작업 하나에 진행 표시와 되돌리기 버튼을 붙여 보세요.","en":"Add a progress indicator and an undo button to one slow task in your app."}],"ask":{"ko":"무거운 ML 보정이 버튼 하나로 보일 때 오히려 더 믿음이 갔던 이유는 무엇일까요?","en":"Why did heavy ML correction feel more trustworthy when it looked like a single button?"}},"토스":{"time":10,"setup":{"ko":"실제 송금 흐름을 보려면 본인 계좌가 연결돼 있어야 해요. 소액으로 해 보세요.","en":"To see the real transfer flow you need your own account linked; try it with a small amount."},"missions":[{"do":{"ko":"소액 송금을 시작해 보세요. 화면이 바뀔 때마다 내가 정해야 하는 게 몇 개인지 세어 보세요.","en":"Start a small transfer. Count how many decisions each screen asks of you."},"wow":{"ko":"한 화면에 질문이 하나뿐이라 매번 결정 하나만 하면 돼요. 은행 앱들이 따라 한 흐름이에요.","en":"Each screen asks one question, so you make one decision at a time. Banking apps went on to copy this flow."}},{"do":{"ko":"송금 마지막 단계에서 공인인증서나 보안카드를 찾게 되는지 보세요.","en":"At the last step of the transfer, see whether you ever reach for a certificate or security card."},"wow":{"ko":"2015년부터 비밀번호만으로 송금하게 해서, 당시 금융 앱의 가장 큰 마찰이던 인증 절차를 없앴어요.","en":"Since 2015 it has let you send money with just a password, removing the certificate step that was the biggest friction in finance apps."}},{"do":{"ko":"대출이나 보험 같은 복잡한 상품 화면을 열어 문장을 소리 내어 읽어 보세요.","en":"Open a screen for a complex product like a loan or insurance and read the sentences aloud."},"wow":{"ko":"딱딱한 금융 용어 대신 대화하듯 쓴 문구라 복잡한 상품도 쉽게 읽혀요.","en":"The copy is conversational instead of stiff financial jargon, so even complex products read easily."}}],"make":[{"ko":"내 앱의 입력 폼 하나를 한 화면에 질문 하나씩으로 쪼갠 프로토타입을 만들고 완료 시간을 비교해 보세요.","en":"Prototype one form in your app split into one question per screen and compare completion times."},{"ko":"내 앱의 딱딱한 확인 문구 세 개를 대화체로 다시 써 보세요.","en":"Rewrite three stiff confirmation messages in your app in a conversational voice."}],"ask":{"ko":"화면은 여러 장인데도 송금이 쉽게 느껴졌다면, 그 이유는 무엇일까요?","en":"If the transfer felt easy despite spanning several screens, why was that?"}},"Metaballs":{"time":15,"setup":{"ko":"원래 앱은 Vision Pro용이에요. iPhone과 iPad에서는 별도의 Metaballs Mobile 판에서 탭과 드래그로 해 볼 수 있어요.","en":"The original is for Vision Pro; on iPhone and iPad, try the separate Metaballs Mobile edition with tap and drag."},"missions":[{"do":{"ko":"도형 두 개를 꺼내 손으로 밀어 서로 닿게 해 보세요. 그다음 방의 조명을 켜거나 꺼 보세요.","en":"Bring out two shapes and push them together by hand. Then switch the room lights on or off."},"wow":{"ko":"도형이 닿는 순간 실시간으로 하나의 덩어리로 녹아 붙어요. 재질이 실제 조명 변화에 반응해서 Apple 심사평은 이를 a marvel이라고 불렀어요.","en":"The moment they touch, they fuse into one smooth blob in real time. The material reacts to your real lighting, which Apple's jury called a marvel."}},{"do":{"ko":"붙은 덩어리를 손으로 잡아당겨 다시 떼어 내 보세요.","en":"Grab the fused blob and pull it apart again."},"wow":{"ko":"visionOS 26의 새 물체 조작 제스처로 만들어서 툴바 없이 찌르고 밀고 당겨 떼는 게 전부 손으로 돼요.","en":"Built on visionOS 26 object-manipulation gestures, poking, pushing and pulling apart all happen by hand with no toolbar."}},{"do":{"ko":"만든 모양을 밖으로 내보낼 수 있는지 확인해 보세요.","en":"Check whether you can export the shape you made."},"wow":{"ko":"장난감처럼 보이지만 유료 해금으로 USDZ로 내보내 데스크톱 3D 도구에서 쓸 수 있어요.","en":"It looks like a toy, but the paid unlock exports USDZ for desktop 3D tools, turning play into real modeling."}}],"make":[{"ko":"RealityKit으로 구 두 개를 띄우고 드래그로 옮길 수 있게 한 뒤, 가까워지면 하나로 합쳐지는 느낌을 흉내 내 보세요.","en":"Place two spheres in RealityKit that you can drag, and fake the feeling of them merging when they come close."},{"ko":"내 앱의 툴바 버튼 하나를 없애고 같은 기능을 직접 만지는 제스처로 바꿔 보세요.","en":"Remove one toolbar button from your app and replace it with a direct-touch gesture."}],"ask":{"ko":"툴바가 없는데도 무엇을 해야 할지 알았다면, 그건 무엇 덕분이었을까요?","en":"If you knew what to do with no toolbar, what made that possible?"}},"NBA: Live Games & Scores":{"time":20,"setup":{"ko":"멀티뷰와 테이블탑 모드는 Vision Pro에서 해 볼 수 있고, 생중계 경기가 있는 시간이어야 해요.","en":"Multiview and Tabletop mode need Vision Pro and a time when games are live."},"missions":[{"do":{"ko":"Vision Pro에서 생중계 경기 하나를 메인으로 열고 작은 창을 하나씩 더해 보세요. 이어서 테이블탑 모드를 켜 보세요.","en":"On Vision Pro, open a live game as the main view and add smaller windows one by one. Then turn on Tabletop mode."},"wow":{"ko":"메인 경기와 작은 창 4개로 5경기를 동시에 보고, 트래킹 데이터로 선수가 움직이는 3D 미니 코트가 중계 옆 테이블 위에 떠요.","en":"Five games run at once, one main plus four side windows, and a 3D mini court with players moving from tracking data sits on the table beside the broadcast."}},{"do":{"ko":"테이블탑 코트 주위를 돌며 다른 각도에서 플레이를 보세요. 중계 화면과 함께 움직이는지 확인해 보세요.","en":"Walk around the tabletop court and watch the play from another angle. Check that it moves in step with the broadcast."},"wow":{"ko":"어느 각도에서든 볼 수 있고, 팀은 3D 재현을 생중계와 맞춰 결과가 미리 새지 않게 하는 걸 핵심 문제로 다뤘어요.","en":"You can view the play from any angle, and the team treated syncing the 3D re-creation with the live video as a core problem so nothing gets spoiled."}},{"do":{"ko":"경기 기록을 열어 그 패널이 공간 어디에 놓이는지 보세요.","en":"Open the stats and notice where the panel sits in your space."},"wow":{"ko":"기록이 중계를 가리지 않고 옆에 벽 크기 패널로 놓여요. 화면을 덮는 대신 공간을 써요.","en":"Stats appear as wall-sized panels beside the game rather than covering it, using space instead of overlays."}}],"make":[{"ko":"visionOS 시뮬레이터에서 메인 창과 보조 창을 동시에 띄우는 앱을 만들어 보세요.","en":"Build an app in the visionOS simulator that opens a main window and a secondary window side by side."},{"ko":"내 앱에서 영상이나 지도 위를 덮던 정보 하나를 옆 패널로 옮겨 보세요.","en":"Move one piece of information that covers a video or map in your app into a side panel."}],"ask":{"ko":"다섯 경기를 동시에 틀어도 정신없지 않았다면, 그건 어떤 배치 덕분이었을까요?","en":"If five games at once did not feel chaotic, what about the layout made that possible?"}},"Primary: News in Depth":{"time":15,"setup":{"ko":"Vision Pro 전용 앱이에요. 무료이고 구독이나 인앱 구입이 없어요.","en":"Vision Pro only. It is free, with no subscriptions or in-app purchases."},"missions":[{"do":{"ko":"Vision Pro에서 기사 하나를 열고 공간 영상 속 현장을 천천히 둘러보세요.","en":"On Vision Pro, open a story and slowly look around the scene in the spatial video."},"wow":{"ko":"현장을 취재하던 기자가 iPhone으로 찍은 공간 영상이라 그 자리에 있는 듯해요. 모든 장면을 현장에서 실시간으로 찍고 검증한다는 AI 없음 원칙을 약속으로 내걸었어요.","en":"Field reporters shot it on iPhone as spatial video, so you feel present. The app promises no AI: every scene is filmed and verified on the ground in real time."}},{"do":{"ko":"영상을 보며 화면에 버튼이나 메뉴가 얼마나 보이는지 세어 보세요.","en":"While watching, count how many buttons or menus you can see."},"wow":{"ko":"UI를 일부러 최소로 줄여 이야기가 공간을 채워요. Apple은 선정성이나 낚시 없는 절제를 높이 샀어요.","en":"The UI is deliberately minimal so the story fills the space. Apple praised its restraint and lack of sensationalism or clickbait."}},{"do":{"ko":"영상에 깔리는 내레이션에 귀 기울여 보세요.","en":"Listen closely to the voice-over in the video."},"wow":{"ko":"공간 영상에 개인이 겪은 영향을 말하는 내레이션이 붙어서 헤드라인이 사람 크기의 이야기가 돼요.","en":"The spatial video comes with commentary on personal impact, turning headlines into human-scale stories."}}],"make":[{"ko":"내 앱의 콘텐츠 화면 하나에서 버튼과 장식을 절반으로 줄이고 콘텐츠가 얼마나 더 눈에 띄는지 비교해 보세요.","en":"Cut the buttons and decoration on one content screen in half and compare how much more the content stands out."},{"ko":"내 앱이 사용자에게 할 수 있는 신뢰 약속 하나를 한 문장으로 써서 첫 화면에 넣어 보세요.","en":"Write one trust promise your app can make to users in a single sentence and put it on the first screen."}],"ask":{"ko":"AI 없음이라는 약속이 영상을 볼 때 내 믿음을 어떻게 바꿨나요?","en":"How did the no-AI promise change how much you believed what you were watching?"}},"SILT":{"time":15,"setup":{"ko":"무료로 일부를 해 보고, 전체 게임은 한 번 구입으로 열려요.","en":"Free to play a portion; the full game unlocks with a one-time purchase."},"missions":[{"do":{"ko":"게임을 시작해 첫 심해 장면에서 멈추고 그림을 살펴보세요. 빛과 그림자만으로 어떻게 그렸는지 보세요.","en":"Start the game, pause on the first deep-sea scene and study it. Notice how it is drawn with light and shadow alone."},"wow":{"ko":"게임 전체가 아트 디렉터 Tom Mead의 개인 수채화에서 나왔고 제목도 그 그림에서 따왔어요. 그의 잉크 드로잉을 그대로 환경으로 옮기는 파이프라인을 직접 만들었어요.","en":"The whole game grew from art director Tom Mead's personal watercolours, even its title. The studio built a pipeline to turn his ink drawings directly into environments."}},{"do":{"ko":"처음 만나는 바다 생물에 빙의해 그 능력으로 막힌 길을 열어 보세요.","en":"Possess the first sea creature you meet and use its ability to open a blocked path."},"wow":{"ko":"잠수부가 바다 생물을 조종해요. 피라냐로 사슬을 끊는 식으로 생물 하나하나가 캐릭터이자 퍼즐 도구예요.","en":"The diver takes control of sea creatures, like piranhas biting through chains, so each creature is both a character and a puzzle tool."}},{"do":{"ko":"화면에서 HUD나 인벤토리, 길 안내를 찾아보세요.","en":"Look for a HUD, an inventory or any directions on screen."},"wow":{"ko":"HUD도 인벤토리도 명시적인 안내도 없어요. 필요한 정보가 전부 환경 안에 녹아 있어요.","en":"There is no HUD, no inventory and no explicit direction. Everything you need is folded into the environment."}},{"do":{"ko":"좁은 터널을 지나 넓은 곳으로 나갈 때 카메라를 지켜보세요.","en":"Watch the camera as you pass through a tight tunnel into open water."},"wow":{"ko":"좁은 곳에서는 카메라가 다가오고 넓은 곳에서는 물러나며 규모를 보여 줘요. 화면 구도가 이야기를 해요.","en":"The camera closes in through tight tunnels and pulls back to reveal scale, using framing as storytelling."}}],"make":[{"ko":"내 앱의 배경이나 아이콘 하나를 직접 손으로 그려 스캔해 넣고 분위기가 어떻게 바뀌는지 보세요.","en":"Hand-draw one background or icon for your app, scan it in and see how the mood changes."},{"ko":"화면의 안내 문구 하나를 지우고 빛이나 색 강조만으로 다음 행동을 알려 보세요.","en":"Delete one instruction on a screen and point to the next action with light or color emphasis alone."}],"ask":{"ko":"안내가 전혀 없는데도 길을 찾을 수 있었다면, 화면의 무엇이 길을 알려 줬을까요?","en":"If you found your way with no guidance at all, what on screen showed you the way?"}},"Art of Fauna":{"time":15,"setup":{"ko":"처음 10개 퍼즐은 무료이고, 나머지는 인앱 구입으로 열려요.","en":"The first 10 puzzles are free; the rest unlock with an in-app purchase."},"missions":[{"do":{"ko":"VoiceOver를 켜고 화면을 보지 않은 채, 카드 뒷면 설명의 순서를 맞춰 퍼즐 하나를 풀어 보세요.","en":"Turn on VoiceOver and, without looking, solve one puzzle by putting the text on the backs of the cards in order."},"wow":{"ko":"그림을 맞춰도, 뒷면 설명 순서를 맞춰도 풀려서 시각장애인도 VoiceOver로 끝까지 할 수 있어요. 본업이 따로 있는 그라츠의 1인 개발자가 사이드 프로젝트로 만들었어요.","en":"Puzzles solve by picture or by the text on the back, so blind players can finish with VoiceOver. A solo developer in Graz with a full-time job made it as a side project."}},{"do":{"ko":"설정에서 보기 불편한 동물을 숨기는 필터를 찾아 켜 보세요.","en":"In settings, find the filter that hides animals you would rather not see, and turn it on."},"wow":{"ko":"특정 동물을 숨길 수 있는 공포증 필터가 있어요. 다른 게임에서 보기 힘든 세심한 설정이에요.","en":"A phobia filter lets you hide specific animals, a rare and thoughtful setting."}},{"do":{"ko":"그림 퍼즐 하나를 맞춘 뒤 완성된 그림을 자세히 보세요.","en":"Finish one picture puzzle and look closely at the completed image."},"wow":{"ko":"18~19세기 실제 박물학 삽화를 써서 박물관 같은 차분한 분위기가 나요.","en":"It uses authentic 18th and 19th-century natural history illustrations, giving it a calm, museum-like feel."}}],"make":[{"ko":"내 앱의 시각적 선택 화면 하나를 VoiceOver만으로 해 보고, 텍스트 순서로도 쓸 수 있게 접근성 레이블을 붙여 보세요.","en":"Try one visual choice screen in your app with VoiceOver only, then add accessibility labels so it works through text order too."},{"ko":"내 앱에 사용자가 불편한 콘텐츠를 숨길 수 있는 토글 하나를 넣어 보세요.","en":"Add one toggle to your app that lets users hide content they find uncomfortable."}],"ask":{"ko":"별도 모드 없이 같은 퍼즐을 두 방식으로 풀게 한 설계가 왜 더 포용적이었을까요?","en":"Why was letting the same puzzle be solved two ways, with no separate mode, more inclusive?"}},"iA Writer":{"time":15,"setup":{"ko":"29,000원 한 번 구입이 필요해요.","en":"Requires a one-time ₩29,000 purchase."},"missions":[{"do":{"ko":"새 문서에 몇 문장을 쓰고 Focus Mode를 켜 보세요. 그대로 다음 문장을 이어서 써 보세요.","en":"Write a few sentences in a new document and turn on Focus Mode. Then keep writing the next sentence."},"wow":{"ko":"지금 쓰는 문장만 밝게 남고 나머지는 흐려져요. 2010년 아이패드에서 시작한 초기 집중 모드 앱으로 15년간 300만 카피 넘게 팔렸어요.","en":"Only the sentence you are writing stays bright; the rest dims. One of the first distraction-free editors, launched on iPad in 2010, it has sold over 3 million copies."}},{"do":{"ko":"AI 도구에서 복사한 문장을 붙여 넣고 내가 직접 쓴 문장과 비교해 보세요.","en":"Paste in a sentence copied from an AI tool and compare it with what you wrote yourself."},"wow":{"ko":"Authorship 기능이 AI 도구에서 붙여 넣은 텍스트와 직접 쓴 텍스트를 화면에서 구분해 보여 줘요.","en":"The Authorship feature visually marks text pasted from AI tools apart from text you wrote yourself."}},{"do":{"ko":"문서에서 오른쪽, 왼쪽으로 쓸어 보세요.","en":"Swipe right, then left, in a document."},"wow":{"ko":"오른쪽으로 쓸면 라이브러리, 왼쪽으로 쓸면 미리 보기예요. 버튼 없이 제스처로 오가요.","en":"Swipe right for your library, left for a preview. You move around with gestures, not buttons."}}],"make":[{"ko":"텍스트 편집기에서 커서가 있는 문단만 진하게 두고 나머지는 흐리게 하는 프로토타입을 만들어 보세요.","en":"Prototype a text editor that keeps only the paragraph with the cursor at full strength and dims the rest."},{"ko":"내 앱의 화면 전환 버튼 하나를 좌우 스와이프 제스처로 바꿔 보세요.","en":"Replace one navigation button in your app with a left or right swipe gesture."}],"ask":{"ko":"다른 문장이 흐려졌을 뿐인데 왜 글쓰기에 더 집중이 됐을까요?","en":"Other sentences only dimmed, so why did that make writing so much more focused?"}},"Vocabulary – Learn words daily":{"time":10,"setup":null,"missions":[{"do":{"ko":"앱을 열고 단어 카드 몇 장을 넘기며 그림과 글꼴을 살펴보세요.","en":"Open the app, swipe through a few word cards and look at the illustrations and type."},"wow":{"ko":"한 화면에 단어 하나와 뜻, 예문, 어원만 있어요. 2016년에 나온 앱이 9년 뒤 ADA 비주얼 결선에 올랐고 심사평은 조용히 모든 것을 제대로 해내는 앱이었어요.","en":"Each screen holds one word with its definition, example and etymology. Released in 2016, it became a Visuals finalist nine years later, praised for quietly doing everything right."}},{"do":{"ko":"카드를 넘길 때 손끝의 진동에 집중해 보세요.","en":"Pay attention to the vibration in your fingertip as you swipe cards."},"wow":{"ko":"은은한 햅틱이 스와이프를 받쳐 줘서 글자뿐인 앱에 촉감이 생겨요.","en":"Subtle haptics back up each swipe, adding touch to an app made of text."}},{"do":{"ko":"테마와 배경화면을 바꾸고 글자 크기도 바꿔 보세요.","en":"Change the theme and wallpaper, and adjust the text size."},"wow":{"ko":"같은 단어 카드가 테마마다 다른 물건처럼 보여 앱이 내 물건처럼 느껴져요.","en":"The same card looks like a different object with each theme, so the app starts to feel like yours."}},{"do":{"ko":"홈 화면이나 잠금 화면에 오늘의 단어 위젯을 추가해 보세요.","en":"Add a word-of-the-day widget to your Home Screen or Lock Screen."},"wow":{"ko":"앱을 열지 않아도 위젯과 알림, Apple Watch로 단어가 먼저 찾아와요.","en":"Without opening the app, words come to you through widgets, notifications and Apple Watch."}}],"make":[{"ko":"내 앱의 목록 화면 하나를 한 화면에 항목 하나만 보이는 카드 넘기기 화면으로 바꿔 보세요.","en":"Turn one list screen in your app into a card view that shows a single item per screen."},{"ko":"카드를 넘길 때 가벼운 햅틱을 넣고 넣기 전과 비교해 보세요.","en":"Add a light haptic to each card swipe and compare it with the version without."}],"ask":{"ko":"특별한 기능 없이도 조용히 다 잘한다는 느낌은 어디에서 왔을까요?","en":"Without any headline feature, where did the feeling of quietly doing everything right come from?"}},"oko":{"time":15,"setup":{"ko":"보행자 신호가 있는 실제 횡단보도에서 써 봐야 해요. 관찰은 제자리에서 하고, 건너는 판단은 직접 하세요.","en":"You need a real crosswalk with a pedestrian signal. Observe from the curb and make your own crossing decisions."},"missions":[{"do":{"ko":"비행기 모드로 바꾸고 횡단보도 앞 제자리에서 보행 신호에 카메라를 향해 보세요. 화면 대신 소리와 진동에 집중해 보세요.","en":"Switch to airplane mode and, standing still at a crosswalk, point the camera at the walk signal. Focus on sound and vibration, not the screen."},"wow":{"ko":"네트워크 없이도 기기 안의 AI가 신호를 읽어 알려 줘요. iOS 경험이 없던 세 친구가 1년도 안 돼 만들었고 횡단보도 100만 번 건너기를 도왔어요.","en":"On-device AI reads the signal with no network. Three friends with zero iOS experience shipped it in under a year, and it has helped with a million crossings."}},{"do":{"ko":"신호가 바뀌는 순간과 카운트다운 중에 피드백이 어떻게 달라지는지 비교해 보세요.","en":"Compare how the feedback changes when the signal switches and during the countdown."},"wow":{"ko":"건너도 됨, 건너지 마세요, 카운트다운을 구분해 서둘러야 할지까지 알려 줘요. 실제 음향 신호를 닮은 소리와 서로 다른 진동 패턴을 써요.","en":"It distinguishes Walk, Don't Walk and the countdown, even telling you to hurry, with sounds like real accessible signals and distinct haptic patterns."}},{"do":{"ko":"VoiceOver를 켜고 글자 크기를 가장 크게 키운 뒤 앱을 써 보세요.","en":"Turn on VoiceOver, set text size to the largest and use the app."},"wow":{"ko":"Apple 심사위원은 VoiceOver와 Dynamic Type 구현을 흠잡을 데 없다고 평했어요.","en":"Apple's jury called its VoiceOver and Dynamic Type implementation flawless."}}],"make":[{"ko":"Core ML 이미지 분류 모델 하나를 카메라에 연결하고, 결과마다 다른 햅틱 패턴이 나오게 해 보세요.","en":"Connect a Core ML image classifier to the camera and give each result its own haptic pattern."},{"ko":"내 앱의 상태 하나를 화면을 보지 않아도 알 수 있게 소리와 진동 패턴으로 표현해 보세요.","en":"Express one state in your app through sound and vibration so it can be understood without looking."}],"ask":{"ko":"화면을 보지 않고도 신호를 믿을 수 있었다면, 피드백의 어떤 점 덕분이었을까요?","en":"If you could trust the signal without looking, what about the feedback made that possible?"}},"Wavelength":{"time":20,"setup":{"ko":"2명 이상이 함께해야 해요. 같은 방이든 원격이든 괜찮아요.","en":"You need at least two players, in the same room or remote."},"missions":[{"do":{"ko":"친구와 같은 게임에 들어가, 한 사람이 다이얼을 돌릴 때 다른 사람 화면의 바늘도 함께 보세요.","en":"Join a game with a friend and, as one person turns the dial, watch the needle on the other person's screen."},"wow":{"ko":"모두의 화면에서 바늘이 실시간으로 움직여 보드게임의 토론이 그대로 살아나요. 킥스타터에서 30만 달러 넘게 모은 게임인데 앱에는 광고가 하나도 없어요.","en":"The needle moves live on everyone's screen, so the table debate survives. The board game raised over $300,000 on Kickstarter, and the app has zero ads."}},{"do":{"ko":"다이얼이 움직일 때 아바타의 반응을 지켜보고 이모지 반응도 보내 보세요.","en":"Watch the avatars react as the dial moves, and send an emoji reaction."},"wow":{"ko":"다이얼이 바뀌면 아바타가 반응해서 마주 앉아 떠드는 표정과 몸짓을 대신해요. 아바타 조합만 400만 가지가 넘어요.","en":"Avatars react as the dial changes, standing in for the faces and body language of in-person play, with over 4 million combinations."}},{"do":{"ko":"서로 다른 장소에 있는 친구와 원격으로 한 판 해 보세요.","en":"Play a round remotely with a friend somewhere else."},"wow":{"ko":"같은 방이든 세계 반대편이든 2명부터 10명 넘게 iPhone, iPad, Mac, Vision Pro에서 함께해요.","en":"In the same room or across the world, 2 to 10+ players join from iPhone, iPad, Mac and Vision Pro."}}],"make":[{"ko":"두 기기에서 슬라이더 값 하나가 실시간으로 함께 움직이는 프로토타입을 SharePlay로 만들어 보세요.","en":"Prototype with SharePlay a single slider whose value moves live on two devices."},{"ko":"내 앱의 공유 화면에 다른 사람의 반응이 작은 아바타로 보이는 시안을 그려 보세요.","en":"Sketch a shared screen in your app where other people's reactions appear as small avatars."}],"ask":{"ko":"바늘이 모두의 화면에서 함께 움직일 때 대화가 왜 더 뜨거워졌을까요?","en":"Why did the conversation heat up when the needle moved on everyone's screen together?"}},"Ahead: Emotions Coach":{"time":10,"setup":null,"missions":[{"do":{"ko":"온보딩에서 분노나 불안 같은 고민 하나를 고르고 첫 레슨을 끝까지 해 보세요. 걸린 시간을 재 보세요.","en":"In onboarding, choose a struggle like anger or anxiety and finish the first lesson. Time how long it takes."},"wow":{"ko":"감정 습관을 하루 5분 안쪽의 게임형 레슨으로 다뤄요. 2021년 베타 사용자 수천 명에서 시작해 개발사 발표 기준 200만 명이 쓰는 앱이 됐어요.","en":"It treats emotional habits in gamified lessons of five minutes or less, growing from a few thousand beta users in 2021 to 2 million people by the developer's count."}},{"do":{"ko":"감정 프로필을 찾아 열어 보세요.","en":"Find and open your emotional profile."},"wow":{"ko":"내가 왜 그렇게 반응하는지의 뿌리를 시각화해서, 막연한 자기 이해가 다시 볼 수 있는 결과물이 돼요.","en":"It visualizes the roots of how you react, turning vague self-knowledge into something concrete you can revisit."}},{"do":{"ko":"레슨을 마친 뒤 스트릭과 레벨 표시를 확인해 보세요.","en":"After a lesson, check your streak and level."},"wow":{"ko":"어학 앱의 스트릭, 레벨, 보상을 마음 건강에 가져왔어요. 일러스트와 가벼운 말투가 감정 공부의 부담을 낮춰요.","en":"It borrows streaks, levels and rewards from learning apps for mental health, and a playful illustrated tone lowers the stigma."}}],"make":[{"ko":"내 앱의 긴 기능 하나를 2분 안에 끝나는 단계로 쪼개고 진행 표시를 붙여 보세요.","en":"Split one long feature in your app into steps that end within two minutes, and add a progress indicator."},{"ko":"사용자의 답변 세 개로 간단한 프로필 그림을 만들어 보여 주는 화면 시안을 그려 보세요.","en":"Sketch a screen that turns three user answers into a simple visual profile."}],"ask":{"ko":"감정 공부가 게임처럼 짧아졌을 때 왜 덜 무겁게 느껴졌을까요?","en":"Why did emotional work feel lighter once it was short and game-like?"}},"Sky Guide":{"time":20,"setup":{"ko":"별이 보이는 맑은 밤에 야외에서 해 보면 가장 좋아요.","en":"Best done outdoors on a clear night when stars are visible."},"missions":[{"do":{"ko":"밤하늘 아래서 앱을 열고 iPhone을 머리 위로 들어 보세요. 아무것도 설정하지 말고 천천히 돌려 보세요.","en":"Under the night sky, open the app and hold your iPhone overhead. Change no settings; just turn slowly."},"wow":{"ko":"설정 없이 나침반과 모션 센서로 가리킨 별과 별자리, 행성을 바로 알아봐요. 2014년 ADA를 받은 앱이 10년 뒤 Vision Pro판으로 다시 결선에 올랐어요.","en":"With no setup, the compass and motion sensors identify the stars, constellations and planets you point at. It won an ADA in 2014 and was a finalist again in 2024 on Vision Pro."}},{"do":{"ko":"비행기 모드로 바꾸고 다시 하늘을 비춰 보세요.","en":"Switch to airplane mode and point at the sky again."},"wow":{"ko":"와이파이나 GPS 없이도 그대로 돼요. 별 보기 좋은 어두운 곳에서 꼭 필요한 기능이에요.","en":"It keeps working without Wi-Fi or GPS, which is essential at the dark sites where stargazing happens."}},{"do":{"ko":"AR 모드를 켜서 카메라 화면 위에 별자리 그림이 겹치는지 보세요.","en":"Turn on AR mode and see the constellation figures over the camera view."},"wow":{"ko":"실제 하늘 위에 별자리 그림이 겹쳐 보여요.","en":"Constellation figures are laid over the real sky."}},{"do":{"ko":"시간을 앞뒤로 돌려 하늘이 어떻게 움직이는지 보세요.","en":"Scrub time backward and forward and watch the sky move."},"wow":{"ko":"시간 이동으로 하늘을 과거나 미래의 위치로 돌려 볼 수 있어요.","en":"Time travel lets you scrub the sky to past or future positions."}}],"make":[{"ko":"CoreMotion으로 기기가 가리키는 방향을 읽어 화면에 방위와 각도를 보여 주는 프로토타입을 만들어 보세요.","en":"Prototype a screen that reads where the device points with CoreMotion and shows heading and angle."},{"ko":"내 앱의 기능 하나가 네트워크 없이도 동작하게 필요한 데이터를 앱 안에 넣어 보세요.","en":"Bundle the data one feature needs so it works without a network."}],"ask":{"ko":"하늘에 폰을 드는 것만으로 별 이름이 나왔을 때, 왜 설명서가 필요 없었을까요?","en":"When raising the phone was enough to name the stars, why was no manual needed?"}},"Duolingo":{"time":10,"setup":null,"missions":[{"do":{"ko":"레슨 하나를 끝내고 스트릭 화면을 열어 보세요. 스트릭을 지켜 주는 동결권이 어디서 보이는지도 찾아보세요.","en":"Finish one lesson and open your streak. Also look for where streak freezes show up."},"wow":{"ko":"끊기면 아까운 스트릭이 매일 돌아오게 만들어요. 2025년 말 기준 365일 이상 하루도 안 빠진 사용자가 약 1,500만 명이에요.","en":"A streak you would hate to lose brings you back daily. As of late 2025, about 15 million people were on streaks of 365 days or more."}},{"do":{"ko":"처음 설치했다면 계정을 만들기 전에 언어와 목표를 골라 첫 레슨을 해 보세요.","en":"On a fresh install, pick a language and goal and do the first lesson before creating an account."},"wow":{"ko":"가입 전에 첫 레슨부터 끝내게 해서 가입의 번거로움보다 가치를 먼저 느끼게 해요.","en":"You finish a lesson before signing up, so you feel the value before any sign-up friction."}},{"do":{"ko":"일부러 틀린 답을 내 보고 맞힌 답의 반응과 비교해 보세요.","en":"Give a wrong answer on purpose and compare the reaction with a right one."},"wow":{"ko":"답마다 애니메이션, 소리, 햅틱이 바로 따라와요. 몇 분짜리 레슨이라 틀려도 금방 다시 해요.","en":"Every answer gets instant animation, sound and haptics. Lessons last a few minutes, so a mistake is quickly retried."}}],"make":[{"ko":"내 앱에 연속 사용일 수 배지와, 하루를 놓쳐도 지켜 주는 동결 아이템 하나를 시안으로 그려 보세요.","en":"Sketch a consecutive-days badge for your app and a freeze item that protects it when a day is missed."},{"ko":"내 앱의 가입 화면을 핵심 기능을 한 번 써 본 뒤로 옮긴 흐름을 만들어 보세요.","en":"Build a flow that moves your sign-up screen to after the first use of your core feature."}],"ask":{"ko":"스트릭 숫자 하나가 왜 매일 앱을 다시 열게 만들까요?","en":"Why does a single streak number make people reopen the app every day?"}},"Kimono Cats":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라 개발사가 공개한 트레일러나 스크린샷으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"트레일러에서 고양이가 다트를 던지는 장면을 찾아 손가락 동작이 몇 가지인지 세어 보세요.","en":"In the trailer, find the cats throwing darts and count how many finger motions are involved."},"wow":{"ko":"조작은 위로 쓸어 다트를 던지는 동작 하나예요. 1983년부터 게임을 만든 ToeJam & Earl의 Greg Johnson이 아내와 함께 하려고 만들었어요.","en":"The control is a single upward swipe to throw a dart. Greg Johnson of ToeJam & Earl, making games since 1983, built it to play with his wife."}},{"do":{"ko":"스크린샷에서 다트 말고 다른 미니게임을 찾아보세요.","en":"Look through the screenshots for mini-games other than darts."},"wow":{"ko":"건지기, 수리검 던지기 같은 일본 마쓰리 미니게임이 각각 만족스러운 터치 동작 하나에 대응해요.","en":"Japanese matsuri mini-games like scooping and Shuriken Throw each map to one satisfying touch motion."}},{"do":{"ko":"트레일러나 스크린샷에서 두 고양이가 입 맞추는 장면이 나오면 배경을 지켜보세요.","en":"If the trailer or screenshots show two cats kissing, watch the background."},"wow":{"ko":"성별 구분 없이 캐릭터를 고르고, 고양이가 입 맞출 때 은은한 무지개가 떠요. 해석은 플레이어에게 맡겨요.","en":"Characters are chosen without gender, and a subtle rainbow appears when the cats kiss, leaving interpretation to players."}}],"make":[{"ko":"위로 쓸면 물체가 날아가는 제스처 하나만 있는 미니게임을 SpriteKit으로 만들어 보세요.","en":"Build a SpriteKit mini-game whose only control is swiping up to send an object flying."},{"ko":"내 앱의 핵심 기능을 손가락 동작 하나로 줄인다면 무엇일지 정해 프로토타입으로 만들어 보세요.","en":"Decide what your app's core feature would be as a single finger motion and prototype it."}],"ask":{"ko":"조작이 하나뿐인 게임이 왜 함께 하기 좋은 게임이 됐을까요?","en":"Why did a game with one control turn out so good for playing together?"}},"Diablo Immortal":{"time":20,"setup":null,"missions":[{"do":{"ko":"무료로 첫 전투를 해 본 뒤 상점을 열어 젬 같은 유료 상품이 어떻게 놓여 있는지 보세요.","en":"Play the first fight for free, then open the shop and see how paid items like gems are laid out."},"wow":{"ko":"첫 주 1,000만 다운로드, 8주 만에 매출 1억 달러를 넘겼어요. 동시에 캐릭터를 끝까지 키우는 데 최대 11만 달러가 든다는 분석과 PC판 유저 점수 0.2점이 나왔어요.","en":"It passed 10 million downloads in week one and $100 million in eight weeks, while maxing a character was estimated at up to $110,000 and the PC user score hit 0.2."}},{"do":{"ko":"가상 스틱으로 움직이면서 스킬 버튼을 끌어 조준해 보세요.","en":"Move with the virtual stick and drag a skill button to aim."},"wow":{"ko":"처음부터 모바일용으로 설계한 조작이라, 스킬 버튼을 끌어 조준하는 방식이 비평가들에게도 장점으로 꼽혔어요.","en":"The controls were designed for mobile from the start, and drag-to-aim skills were singled out by critics as a strength."}},{"do":{"ko":"전투 중 잠시 멈추고 배경과 효과를 살펴보세요.","en":"Pause mid-fight and study the scenery and effects."},"wow":{"ko":"NetEase의 Messiah 엔진으로 휴대폰에서 콘솔급 아이소메트릭 그래픽을 보여 줘요.","en":"NetEase's Messiah engine delivers console-grade isometric visuals on a phone."}}],"make":[{"ko":"내 앱 결제 화면 하나에 끝까지 쓰려면 총 얼마가 드는지 한 줄로 밝히는 문구를 넣어 보세요.","en":"Add one line to a purchase screen in your app that states the total cost to get everything."},{"ko":"화면 구석에 버튼 여러 개를 원형으로 배치하고 끌어서 방향을 정하는 조작을 SwiftUI로 만들어 보세요.","en":"Build in SwiftUI a radial cluster of buttons in a corner that you drag to set a direction."}],"ask":{"ko":"숫자로는 대성공인데 평가는 최악이었다면, 그 차이는 어디에서 생겼을까요?","en":"If the numbers were a huge success but reviews were the worst, where did that gap come from?"}},"tint.":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"do":{"ko":"색맹 모드를 켜고 색 대신 무늬와 소리만으로 퍼즐 하나를 풀어 보세요.","en":"Turn on color-blind mode and solve one puzzle using only patterns and sounds, not color."},"wow":{"ko":"색을 섞는 게 핵심인 퍼즐인데, 색마다 고유한 무늬와 음악이 붙어서 색을 못 봐도 풀 수 있어요.","en":"The whole puzzle is about mixing colors, yet every color has its own pattern and tune, so you can solve it without seeing color."}},{"do":{"ko":"길을 따라 수채 물감을 섞어 종이접기 조각의 색과 맞춰 보세요. 일부러 틀린 색도 만들어 보세요.","en":"Mix watercolors along the paths to match an origami piece, and make a wrong color on purpose."},"wow":{"ko":"색 이론 자체가 퍼즐이에요. 타이머도 카운트다운도 점수도 없어서 틀려도 조급해지지 않아요.","en":"Color theory itself is the puzzle. No timers, countdowns or points, so a mistake never feels rushed."}}],"make":[{"ko":"내 앱에서 색으로만 구분하던 상태 하나에 무늬나 아이콘을 함께 붙여 보세요.","en":"Add a pattern or icon to one state in your app that is currently told apart only by color."},{"ko":"색마다 다른 짧은 소리를 내는 버튼 세 개를 만들고, 눈을 감고도 구분되는지 시험해 보세요.","en":"Make three buttons that each play a different short sound for a color, and test whether you can tell them apart with eyes closed."}],"ask":{"ko":"색이 핵심인 게임을 색 없이도 풀게 만든 결정이 왜 게임을 더 풍부하게 했을까요?","en":"Why did making a color game solvable without color make it richer?"}},"Transit":{"time":10,"setup":{"ko":"대중교통이 다니는 곳에서 열어야 주변 노선의 실시간 정보를 볼 수 있어요.","en":"Open it somewhere with public transit to see real-time info for nearby lines."},"missions":[{"do":{"ko":"버스나 열차를 타기 전에 GO로 길 안내를 시작하고 그대로 타 보세요. 내 위치가 다른 승객에게 어떤 의미인지 떠올려 보세요.","en":"Start GO guidance before boarding a bus or train and ride with it on. Think about what your location means for other riders."},"wow":{"ko":"실시간 데이터가 없는 노선이라도 GO를 켠 승객 한 명만 타면 그 위치로 모두를 위한 실시간 도착 정보가 생겨요.","en":"Even on a route with no live feed, one rider using GO is enough to generate real-time arrivals for everyone."}},{"do":{"ko":"앱을 열고 아무것도 검색하지 말고 첫 화면만 보세요.","en":"Open the app and, without searching, just look at the first screen."},"wow":{"ko":"가까운 노선이 큰 색깔 카드로 실시간 출발 시간과 함께 바로 떠요. 가장 흔한 일에 검색이 필요 없어요.","en":"Nearby lines appear as large color-coded cards with live departures. The most common task needs no search."}},{"do":{"ko":"비행기 모드로 바꾸고 시간표와 경로를 찾아보세요.","en":"Switch to airplane mode and look up schedules and a trip."},"wow":{"ko":"지하나 데이터가 없는 곳에서도 오프라인 시간표와 경로 계획이 그대로 돼요.","en":"Offline schedules and trip planning keep working underground or without data."}}],"make":[{"ko":"내 앱의 첫 화면을 검색창 대신 사용자 근처 항목 카드로 시작하게 바꿔 보세요.","en":"Change your app's first screen to start with cards for things near the user instead of a search bar."},{"ko":"사용자가 앱을 쓰는 것만으로 다른 사용자에게 도움이 되는 데이터 하나를 정하고, 그걸 보여 줄 화면 시안을 그려 보세요.","en":"Pick one piece of data that simply using your app could contribute to others, and sketch the screen that shows it."}],"ask":{"ko":"승객 한 명이 모두의 실시간 정보가 된다는 설계는 왜 사람들을 움직였을까요?","en":"Why did the idea that one rider becomes everyone's live data motivate people?"}},"MD Clock":{"time":10,"setup":{"ko":"StandBy를 보려면 충전 중인 iPhone을 가로로 세워 둘 수 있어야 해요.","en":"To see StandBy, have your iPhone charging and propped up in landscape."},"missions":[{"do":{"ko":"시계 테마 하나를 골라 전체 화면으로 띄우고 숫자가 넘어가는 순간을 지켜보세요.","en":"Pick a clock theme, go full screen and watch the moment the digits change."},"wow":{"ko":"이미 다 해결된 시간 보기라는 기능 하나로, 테마와 애니메이션만 다듬어 2022 ADA 비주얼 결선에 올랐어요.","en":"With nothing but telling time, a long-solved function, it made the 2022 Visuals finalists by polishing themes and animation."}},{"do":{"ko":"충전 중인 iPhone을 가로로 세워 StandBy에서 시계를 띄워 보세요.","en":"Prop your charging iPhone in landscape and show the clock in StandBy."},"wow":{"ko":"시계가 책상이나 머리맡에 놓인 물건처럼 바뀌어요. 시스템의 새 기능을 따라가며 계속 다듬고 있어요.","en":"The clock becomes an object on your desk or nightstand. The app keeps pace with new platform features."}},{"do":{"ko":"테마를 몇 가지 바꿔 가며 방 분위기와 맞춰 보세요.","en":"Switch through a few themes and match one to your room."},"wow":{"ko":"24개가 넘는 테마로 같은 기능이 방과 기분에 맞춰 달라져요.","en":"With 24+ themes, the same function adapts to different rooms and moods."}}],"make":[{"ko":"SwiftUI로 숫자가 바뀔 때 넘어가는 애니메이션이 있는 전체 화면 시계를 만들어 보세요.","en":"Build a full-screen clock in SwiftUI with a flip animation when the digits change."},{"ko":"내 앱의 평범한 숫자 표시 하나에 전환 애니메이션을 넣고 넣기 전과 비교해 보세요.","en":"Add a transition animation to one plain number in your app and compare it with the version without."}],"ask":{"ko":"누구나 가진 시계 기능이 왜 이 앱에서는 다시 갖고 싶은 물건이 됐을까요?","en":"Why did a clock everyone already has become something you wanted in this app?"}},"Me: A Kid's Diary by Tinybop":{"time":15,"setup":{"ko":"6,600원 유료 앱이에요. 아이와 함께 해 보면 가장 좋아요.","en":"A paid app at ₩6,600. Best tried together with a child."},"missions":[{"do":{"ko":"아이와 함께 질문 하나를 골라 글 대신 그림이나 녹음으로 답해 보세요.","en":"With a child, pick one prompt and answer with a drawing or a voice recording instead of writing."},"wow":{"ko":"빈 일기장 대신 내가 동물이라면 이렇게 생겼을 거야 같은 질문을 던져요. 글을 못 쓰는 아이도 그림, 사진, 녹음으로 답할 수 있어요.","en":"Instead of a blank page it offers prompts like If I were an animal, I would look like this, and kids who cannot write answer with drawings, photos or recordings."}},{"do":{"ko":"나와 가족, 반려동물의 아바타를 만들어 보세요.","en":"Make avatars for yourself, family and pets."},"wow":{"ko":"아바타 덕분에 일기가 아이 자신의 세계와 관계에 대한 이야기가 돼요.","en":"Avatars make the diary about the child's own world and relationships."}},{"do":{"ko":"답을 몇 개 남긴 뒤 지금까지 만든 것이 모이는 곳을 찾아보세요.","en":"After a few answers, find where everything you have made is collected."},"wow":{"ko":"흩어진 기록이 한곳에 모여 아이가 어떤 사람인지 보여 주는 기록이 돼요.","en":"Scattered entries gather in one place and become a visual record of who the child is."}}],"make":[{"ko":"내 앱의 빈 입력 칸 하나를 구체적인 질문 하나로 바꾸고, 글이나 그림, 녹음 중 골라 답하게 해 보세요.","en":"Replace one empty input in your app with a specific prompt, and let users answer by text, drawing or recording."},{"ko":"사용자가 남긴 기록을 한 화면에 모아 보여 주는 갤러리 시안을 만들어 보세요.","en":"Sketch a gallery screen that gathers everything the user has created in one place."}],"ask":{"ko":"빈 페이지 대신 질문 하나가 왜 아이의 손을 먼저 움직였을까요?","en":"Why did a single prompt get a child moving where a blank page would not?"}},"Nova":{"time":10,"setup":{"ko":"앱스토어에서 내려간 Mac 전용 앱이라 개발사가 공개한 트레일러나 스크린샷으로 살펴봐야 해요.","en":"This Mac-only app has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"Panic이 공개한 영상이나 스크린샷에서 편집기 창 하나에 무엇이 함께 들어 있는지 세어 보세요.","en":"In Panic's own video or screenshots, count what is packed into a single editor window."},"wow":{"ko":"Electron 편집기가 대세일 때 Panic은 Coda를 접고 수년간 바닥부터 다시 쓴 완전 네이티브 macOS 전용 편집기를 냈어요. 편집, 디버깅, Git, 원격 파일이 한 창에 있어요.","en":"As Electron editors took over, Panic retired Coda and spent years rewriting a fully native, Mac-only editor. Editing, debugging, Git and remote files share one window."}},{"do":{"ko":"스크린샷에서 Git 커밋과 비교하는 화면을 찾아보세요.","en":"In the screenshots, look for the view that compares against Git commits."},"wow":{"ko":"Comparison View로 Git 커밋과의 차이를 보여 주고, Tree-sitter 파싱으로 문법 강조도 빠르고 정확해요.","en":"Comparison View shows diffs against Git commits, and Tree-sitter parsing makes syntax highlighting fast and accurate."}}],"make":[{"ko":"내 앱 화면 하나를 기본 Apple 컨트롤만으로 다시 만들어 보고 원래 화면과 반응 속도를 비교해 보세요.","en":"Rebuild one screen of your app with standard Apple controls only and compare how responsive it feels."},{"ko":"사용자가 가장 자주 오가는 두 화면을 한 창 안의 분할 화면으로 합친 시안을 그려 보세요.","en":"Sketch the two screens users switch between most as one split view in a single window."}],"ask":{"ko":"모두가 크로스플랫폼으로 갈 때 Mac 전용을 고집한 선택은 왜 매력으로 보였을까요?","en":"When everyone went cross-platform, why did insisting on Mac-only look appealing?"}},"Mission to Mars AR":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라 개발사가 공개한 트레일러나 스크린샷으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"트레일러나 스크린샷에서 로버가 실제 방 안에 놓인 장면을 찾아 주변 가구와 크기를 비교해 보세요.","en":"In the trailer or screenshots, find the rover placed in a real room and compare its size with the furniture."},"wow":{"ko":"퍼서비어런스가 화성에 착륙한 2021년 2월 18일에 맞춰 나와, 거실에서 로버를 실물 크기로 몰고 공포의 7분 착륙을 AR로 다시 볼 수 있었어요.","en":"Released around Perseverance's February 18, 2021 landing, it let you drive the rover at 1:1 scale in your living room and replay the Seven Minutes of Terror in AR."}},{"do":{"ko":"트레일러에서 AR 장면의 빛과 그림자가 실제 방과 어울리는지 살펴보세요.","en":"In the trailer, check whether the light and shadows of the AR scene fit the real room."},"wow":{"ko":"영상으로 보던 화성 탐사를 걸어 다니며 볼 수 있는 물체로 만들었어요. 비주얼 부문에서 인정받은 만큼 방에 맞춘 크기와 빛이 관찰 포인트예요.","en":"It turns a Mars mission into something physical you walk around. Recognized for visuals, its scale and lighting in a real room are what to watch."}}],"make":[{"ko":"RealityKit으로 실제 크기 물체 하나를 바닥에 놓는 AR 프로토타입을 만들고 그 주위를 걸어 보세요.","en":"Build a RealityKit AR prototype that places one life-size object on the floor, and walk around it."},{"ko":"내 앱의 설명 하나를 사용자가 걸어 다니며 볼 수 있는 AR 장면으로 바꾼다면 어떨지 시안을 그려 보세요.","en":"Sketch how one explanation in your app would work as an AR scene the user can walk around."}],"ask":{"ko":"화성 탐사를 영상으로 보는 것과 내 방에서 실물 크기로 보는 것은 무엇이 달랐을까요?","en":"What was different between watching a Mars mission on video and seeing it life-size in your room?"}},"Darkroom":{"time":15,"setup":{"ko":"편집해 볼 사진이 사진 보관함에 여러 장 있어야 해요.","en":"Have several photos in your Photos library to edit."},"missions":[{"do":{"ko":"앱을 열고 가져오기 없이 보관함의 사진 하나를 바로 편집해 보세요. 그리고 사진 앱에서 같은 사진을 확인해 보세요.","en":"Open the app and edit a library photo directly, with no import. Then check the same photo in Photos."},"wow":{"ko":"가져오기와 내보내기 없이 사진 보관함을 그대로 편집해요. 창업자는 시리아 난민 사태를 기록하며 수만 장을 다루다 기존 도구의 한계를 절감하고 이 앱을 키웠어요.","en":"It edits your Photos library directly, with no import or export. The founder grew it after wrangling tens of thousands of photos documenting the Syrian refugee crisis."}},{"do":{"ko":"편집한 사진을 다시 열어 이전 단계로 되돌려 보세요.","en":"Reopen an edited photo and step back to an earlier state."},"wow":{"ko":"비파괴 편집이라 전체 기록이 남고 언제든 되돌릴 수 있어요.","en":"Editing is non-destructive with full history, so you can always go back."}},{"do":{"ko":"사진 한 장의 보정을 복사해 다른 여러 장에 붙여 넣어 보세요.","en":"Copy the adjustments from one photo and paste them onto several others."},"wow":{"ko":"보정 복사와 일괄 편집으로 촬영 한 번 분량을 휴대폰에서 처리할 수 있어요.","en":"Copy-paste adjustments and batch editing make processing a whole shoot on a phone practical."}}],"make":[{"ko":"PhotoKit으로 보관함 사진 하나를 바로 불러와 필터 하나를 적용하는 화면을 만들어 보세요.","en":"Build a screen that loads a library photo directly with PhotoKit and applies one filter."},{"ko":"내 앱의 설정 하나를 복사해 여러 항목에 한 번에 붙여 넣는 기능을 시안으로 그려 보세요.","en":"Sketch a feature that copies one setting and pastes it onto many items at once."}],"ask":{"ko":"가져오기 단계 하나가 없어졌을 뿐인데 편집이 왜 훨씬 가볍게 느껴졌을까요?","en":"Only the import step disappeared, so why did editing feel so much lighter?"}},"Calm":{"time":20,"setup":{"ko":"잠자리에 들기 전에 이어폰이나 스피커와 함께 해 보세요.","en":"Try it at bedtime with earphones or a speaker."},"missions":[{"do":{"ko":"잠자리에 누워 Sleep Stories 하나를 고르고 타이머를 맞춰 들어 보세요.","en":"Lie down at bedtime, pick a Sleep Story, set the timer and listen."},"wow":{"ko":"어른을 위한 잠자리 동화라는 새 포맷이에요. 유명인 내레이션으로 잠들기 전 이야기 듣기라는 새 밤 루틴을 만들었어요.","en":"It is a new format: bedtime stories for adults. With celebrity narration, it created a new nightly routine of listening before sleep."}},{"do":{"ko":"앱을 처음 열 때 첫 3초 동안 무엇이 들리고 보이는지 집중해 보세요.","en":"When you first open the app, focus on what you hear and see in the first three seconds."},"wow":{"ko":"로그인이나 설명보다 먼저 빗소리와 자연 풍경, 심호흡하라는 한 줄이 나와요. 진정이라는 가치를 첫 3초에 감각으로 느끼게 해요.","en":"Before any login or explanation come rain sounds, nature scenes and a one-line cue to breathe. You feel calm in the first three seconds."}},{"do":{"ko":"짧은 호흡 운동과 여러 날짜 프로그램을 하나씩 열어 길이를 비교해 보세요.","en":"Open a short breathing exercise and a multi-day program and compare their lengths."},"wow":{"ko":"짧은 호흡부터 여러 날 이어지는 프로그램까지 길이가 다양해서 하루 중 언제든 쓸 수 있어요.","en":"From short breathing to multi-day programs, the range of lengths fits any moment of the day."}}],"make":[{"ko":"내 앱 첫 화면에 설명 문구 대신 핵심 가치를 3초 안에 느끼게 하는 소리나 움직임 하나를 넣어 보세요.","en":"Put one sound or motion on your app's first screen that conveys its core value within three seconds, instead of copy."},{"ko":"내 앱의 콘텐츠 하나에 끝나면 자동으로 멈추는 타이머를 붙여 보세요.","en":"Add a timer to one piece of content in your app that stops it automatically."}],"ask":{"ko":"이야기를 듣다 잠드는 경험이 왜 새로운 밤 습관이 될 수 있었을까요?","en":"Why could falling asleep to a story become a new nightly habit?"}},"Uber":{"time":15,"setup":{"ko":"실제로 차를 부르면 요금이 나오니 이동할 일이 있을 때 해 보세요.","en":"Calling a car costs money, so try it when you actually need a ride."},"missions":[{"do":{"ko":"차를 부른 뒤 휴대폰을 잠그고 잠금 화면과 Dynamic Island를 보세요. Dynamic Island를 길게 눌러 펼쳐도 보세요.","en":"After requesting a ride, lock your phone and look at the Lock Screen and Dynamic Island. Long-press the Dynamic Island to expand it."},"wow":{"ko":"앱을 열지 않아도 도착 예정 시간, 차량 정보, 번호판이 보여요. 축소 상태엔 핵심 숫자 하나, 펼치면 기사 정보까지 단계적으로 드러나요.","en":"Without opening the app you see the ETA, car details and plate. Compact shows one key number; expanded reveals driver details too."}},{"do":{"ko":"앱을 열고 목적지를 입력하기까지 몇 번 탭하는지 세어 보세요.","en":"Open the app and count how many taps it takes to enter a destination."},"wow":{"ko":"첫 입력이 어디로 가시나요 하나뿐이고 최근 장소와 저장한 장소를 제안해 가장 흔한 일을 한두 탭으로 줄였어요.","en":"The first input is just Where to?, with recent and saved places suggested, cutting the most common task to one or two taps."}}],"make":[{"ko":"ActivityKit으로 남은 시간 숫자 하나만 보여 주는 Live Activity를 만들어 보세요.","en":"Build a Live Activity with ActivityKit that shows just one number: the time remaining."},{"ko":"내 앱에서 사용자가 기다리는 구간 하나를 골라 잠금 화면에 무엇을 보여 줄지 시안을 그려 보세요.","en":"Pick one moment of waiting in your app and sketch what the Lock Screen should show."}],"ask":{"ko":"기다리는 동안 휴대폰을 덜 열어 보게 된 건 어떤 정보 덕분이었을까요?","en":"Which information let you check your phone less while waiting?"}},"Apple Music":{"time":15,"setup":{"ko":"가사와 Sing 기능을 써 볼 수 있게 가사가 있는 좋아하는 곡 몇 개를 골라 두고, 이어폰을 준비해 두세요.","en":"Pick a few favorite songs that have lyrics so you can try lyrics and Sing, and have earphones ready."},"missions":[{"do":{"ko":"가사가 있는 곡을 재생하고 가사 화면을 연 뒤, 아직 나오지 않은 뒷부분 가사 한 줄을 탭해 보세요.","en":"Play a song with lyrics, open the lyrics view and tap a line that has not been sung yet."},"wow":{"ko":"곡이 바로 그 구간으로 넘어가요. 현재 줄을 따라 흐르던 가사가 읽는 글이 아니라 곡 안을 이동하는 내비게이션이 돼요.","en":"The song jumps straight to that part. The scrolling lyrics stop being text to read and become the way you move through the song."}},{"do":{"ko":"지원되는 곡에서 Apple Music Sing을 켜고 보컬 볼륨을 끝까지 내려 보세요.","en":"On a supported song, turn on Apple Music Sing and pull the vocal volume all the way down."},"wow":{"ko":"원곡이 그대로 노래방 반주가 되고, 여러 사람의 파트 가사가 따로 보여요. 이미 있던 가사 화면을 넓혀 만든 기능이에요.","en":"The original track turns into a karaoke backing, and lyrics for multiple voices are shown separately. It grows out of the lyrics view that was already there."}},{"do":{"ko":"앨범 아트 색이 확 다른 곡 두세 개를 번갈아 재생하며 재생 화면을 지켜보세요.","en":"Switch between two or three songs with very different album art and watch the Now Playing screen."},"wow":{"ko":"앨범 아트에서 뽑은 색이 흐린 배경으로 깔려 곡마다 화면 분위기가 바뀌는데, 버튼과 글자는 늘 또렷하게 읽혀요.","en":"Colors pulled from the album art become a blurred background, so the mood changes with every song while the controls stay easy to read."}},{"do":{"ko":"미니 플레이어에서 전체 화면 플레이어로, 다시 가사와 대기열까지 차례로 올라가 보세요.","en":"Go up step by step from the mini player to the full player, then into lyrics and the queue."},"wow":{"ko":"블러의 두께와 시트 전환만으로 지금 어느 층에 있는지 바로 알 수 있어요. 설명 없이도 계층이 느껴져요.","en":"Blur thickness and sheet transitions alone tell you which layer you are on. You feel the hierarchy without any explanation."}}],"make":[{"ko":"이미지에서 대표 색을 뽑아 흐린 배경으로 깔고, 그 위 글자와 버튼의 대비를 확인하는 플레이어 화면을 만들어 보세요.","en":"Build a player screen that pulls a dominant color from an image as a blurred background, and check the contrast of text and buttons on top."},{"ko":"시간 정보가 붙은 텍스트 목록을 만들고, 현재 줄 강조와 줄을 탭하면 그 시간으로 이동하는 기능을 구현해 보세요.","en":"Make a list of timestamped lines that highlights the current line and seeks to that time when a line is tapped."}],"ask":{"ko":"가사를 탭하면 이동하게 한 것만으로 왜 가사 화면이 훨씬 자주 쓰는 화면이 됐을까요?","en":"Why did simply making lyrics tappable turn the lyrics view into a screen people use far more often?"}},"Draw Things":{"time":20,"setup":{"ko":"기본 생성은 무료지만 모델을 기기에 내려받아야 하니 저장 공간과 Wi-Fi를 확보해 두세요. Mac이나 iPad에서도 해 볼 수 있어요.","en":"Local generation is free, but models download to the device, so free up storage and use Wi-Fi. It also runs on Mac and iPad."},"missions":[{"do":{"ko":"모델을 내려받은 뒤 비행기 모드로 바꾸고, 프롬프트를 입력해 이미지를 생성해 보세요.","en":"After a model has downloaded, switch to Airplane Mode, type a prompt and generate an image."},"wow":{"ko":"인터넷이 끊겨도 그림이 나와요. Stable Diffusion, FLUX 같은 모델이 클라우드 없이 기기 안에서 돌아 프롬프트도 결과도 밖으로 안 나가요.","en":"The image still appears with no connection. Models like Stable Diffusion and FLUX run on the device, so neither your prompt nor the result leaves it."}},{"do":{"ko":"처음엔 프롬프트와 생성 버튼만 써 보고, 그다음 고급 설정을 펼쳐 보세요.","en":"First use only the prompt and the generate button, then expand the advanced settings."},"wow":{"ko":"단순해 보이던 화면 뒤에 샘플러, 스텝, LoRA, ControlNet 같은 설정이 숨어 있어요. 초보자 화면을 지키면서 전문가 도구를 다 담았어요.","en":"Behind the simple screen sit samplers, steps, LoRA and ControlNet. It keeps the beginner view clean while holding every pro tool."}},{"do":{"ko":"생성한 이미지에서 일부분만 골라 인페인팅으로 다시 그리게 해 보세요.","en":"Select just one part of a generated image and redraw it with inpainting."},"wow":{"ko":"전체를 새로 만들지 않고 고른 부분만 바뀌어요. 무한 캔버스, 이미지에서 비디오, 기기 내 LoRA 학습까지 한 앱에 들어 있어요.","en":"Only the selected area changes, not the whole picture. An infinite canvas, image to video and on-device LoRA training all live in the same app."}}],"make":[{"ko":"작은 Core ML 모델 하나를 앱에 넣고, 비행기 모드에서도 결과가 나오는지 확인하는 오프라인 데모를 만들어 보세요.","en":"Bundle a small Core ML model in an app and build an offline demo that still returns results in Airplane Mode."},{"ko":"입력창과 실행 버튼만 보이는 화면을 만들고, 고급 옵션은 접힌 영역에 숨겼다가 펼치게 해 보세요.","en":"Make a screen with only an input field and a run button, and tuck advanced options into a collapsed section that expands on demand."}],"ask":{"ko":"내 프롬프트가 기기 밖으로 나가지 않는다는 사실은 생성을 기다리는 시간을 어떻게 다르게 느끼게 할까요?","en":"How does knowing your prompt never leaves the device change the way the wait for an image feels?"}},"당근":{"time":15,"setup":{"ko":"동네 인증은 GPS로 실제 위치를 확인하니 위치 권한이 필요하고, 집 근처에서 하는 게 좋아요.","en":"Neighborhood verification checks your real location by GPS, so allow location access and do it near home."},"missions":[{"do":{"ko":"동네 인증을 시작해, 지금 서 있는 곳의 위치로 인증해 보세요.","en":"Start neighborhood verification and verify using the spot where you are standing."},"wow":{"ko":"주소를 적는 게 아니라 GPS로 정말 그 동네에 있는지 확인해요. 활동 범위를 좁히는 제약이 '가까운 이웃'이라는 신뢰로 바뀌어요.","en":"Instead of typing an address, it checks by GPS that you are really there. A limit on reach becomes trust that you are dealing with a near neighbor."}},{"do":{"ko":"중고거래 글 하나를 열고 판매자의 매너온도와 받은 후기를 확인해 보세요.","en":"Open a listing and check the seller's manner temperature and reviews."},"wow":{"ko":"처음 보는 사람의 신뢰도가 숫자 하나로 보여요. 거래 후 서로 남긴 후기가 쌓여 만들어진 숫자예요.","en":"A stranger's trustworthiness shows up as a single number, built from the reviews people leave each other after trades."}},{"do":{"ko":"중고거래 말고 동네생활, 알바, 동네 가게, 모임 같은 다른 서비스도 차례로 열어 보세요.","en":"Beyond secondhand trading, open the other services one by one, such as community posts, part-time jobs, local shops and groups."},"wow":{"ko":"전부 '내 동네'라는 같은 축 위에 있어요. 중고거래 앱이 이름까지 '당근'으로 바꾸며 지역 커뮤니티 플랫폼이 된 구조예요.","en":"Everything hangs on the same axis of your neighborhood. A secondhand app became a local community platform, and even renamed itself to just Danggeun."}}],"make":[{"ko":"CoreLocation으로 현재 위치가 정한 범위 안일 때만 글쓰기 버튼이 켜지는 화면을 만들어 보세요.","en":"Use CoreLocation to build a screen where the post button only turns on when you are inside a set area."},{"ko":"거래 후 남긴 평가를 숫자 하나로 합쳐 프로필에 보여 주는 신뢰 점수 카드를 만들어 보세요.","en":"Make a trust score card that rolls post-trade ratings into one number shown on a profile."}],"ask":{"ko":"서비스 범위를 일부러 좁힌 제약이 왜 오히려 낯선 사람 사이의 신뢰를 만들었을까요?","en":"Why did deliberately narrowing the service area end up creating trust between strangers?"}},"Is This Seat Taken?":{"time":15,"setup":{"ko":"9,900원 유료 게임이고, 광고나 인앱 결제는 없어요.","en":"A paid game at 9,900 won, with no ads or in-app purchases."},"missions":[{"do":{"ko":"첫 장면에서 설명을 찾지 말고, 승객 위에 뜨는 아이콘과 표정만 보고 자리를 배치해 보세요.","en":"In the first scene, do not look for instructions. Seat everyone using only the icons and faces above the passengers."},"wow":{"ko":"글자 하나 없이 '창가가 좋아', '시끄러운 사람은 싫어' 같은 취향이 읽혀요. 그래서 언어와 나이를 가리지 않아요.","en":"Without a single word, you can read wants like a window seat or no noisy neighbors. That is why it works across languages and ages."}},{"do":{"ko":"일부러 조건에 안 맞는 자리에 승객을 끌어다 놓아 보세요.","en":"Deliberately drag a passenger into a seat that breaks their preference."},"wow":{"ko":"캐릭터가 바로 장난스럽게 반응해서 조건이 맞는지 아닌지 즉시 알 수 있어요. 틀리는 순간도 재미있어요.","en":"The character reacts playfully right away, so you instantly know whether the rule is met. Even getting it wrong is fun."}},{"do":{"ko":"다음 장소로 넘어가 자리 규칙이 어떻게 달라지는지 지켜보세요.","en":"Move on to the next venue and watch how the seating rules change."},"wow":{"ko":"새 튜토리얼 없이 적은 규칙을 새로 조합하는 것만으로 난이도가 올라가요. 장소마다 자기만의 비틀기가 있어요.","en":"Difficulty rises just by recombining a small set of rules, with no new tutorial. Each venue brings its own twist."}}],"make":[{"ko":"캐릭터를 칸에 끌어다 놓으면 조건에 따라 웃거나 찡그리는 표정으로 바뀌는 드래그 앤 드롭 화면을 만들어 보세요.","en":"Build a drag and drop screen where a character smiles or frowns depending on whether its slot meets a rule."},{"ko":"규칙 세 개를 글 대신 아이콘으로만 표현한 퍼즐 한 판을 만들고, 친구가 설명 없이 풀 수 있는지 시험해 보세요.","en":"Make one puzzle whose three rules are shown only as icons, and see if a friend can solve it with no explanation."}],"ask":{"ko":"글 없이 표정만으로 규칙을 알려 준 게 왜 오히려 더 빨리 이해될까요?","en":"Why are rules shown only through faces understood faster than written ones?"}},"D-Day: The Camera Soldier":{"time":30,"setup":{"ko":"Apple Vision Pro 전용이고 6,600원 유료 앱이에요.","en":"Apple Vision Pro only, and a paid app at 6,600 won."},"missions":[{"do":{"ko":"원본 상륙 필름이 나오는 장면에서 가상 카메라 하우징 안쪽을 둘러보며 화면을 지켜보세요.","en":"When the original landing footage plays, look around the inside of the virtual camera housing as you watch."},"wow":{"ko":"리처드 테일러가 쓰던 카메라의 렌즈로 오마하 해변 상륙을 보는 셈이에요. 그는 총 대신 카메라를 들고 상륙한 촬영병이었어요.","en":"You are watching the Omaha Beach landing through Richard Taylor's own lens. He went ashore carrying a camera instead of a rifle."}},{"do":{"ko":"타임캡슐이 나오면 헬멧, 편지, 카메라 3D 스캔을 손가락으로 집어 옮기고 돌려 보세요.","en":"When a time capsule appears, pinch to grab, move and rotate the 3D scans of his helmet, letters and camera."},"wow":{"ko":"보기만 하던 다큐가 실물 같은 역사 유물을 손에 쥐는 경험으로 바뀌어요.","en":"A documentary you were only watching turns into handling photorealistic historical artifacts."}},{"do":{"ko":"장면이 바뀔 때마다 지금 보는 것이 기록 필름인지, 3D 영상인지, 재구성 장면인지 구분해 보세요.","en":"Each time the scene changes, try to tell whether you are seeing archival film, 3D video or a reconstruction."},"wow":{"ko":"기록 필름, 3D 영상, 몰입형 영상, 렌더링 재구성이 20분 한 타임라인에 섞여 순간마다 형식이 바뀌어요.","en":"Archival film, 3D video, immersive video and rendered reconstructions share one 20 minute timeline, switching format to fit each moment."}}],"make":[{"ko":"RealityKit으로 3D 물체 하나를 띄우고 핀치로 집어 돌려 볼 수 있게 만들어 보세요.","en":"Use RealityKit to place one 3D object that can be pinched, grabbed and rotated."},{"ko":"오래된 영상 하나를 카메라나 창틀 같은 3D 프레임 안에서 재생해, 누구의 시선인지 느껴지게 해 보세요.","en":"Play an old video inside a 3D frame such as a camera or window so the viewer feels whose eyes they are looking through."}],"ask":{"ko":"원본 필름을 그냥 크게 틀지 않고 그의 카메라 안에서 보게 한 선택이 왜 더 강하게 와닿을까요?","en":"Why does watching the footage inside his camera hit harder than simply showing it on a big screen?"}},"Katha Room":{"time":15,"setup":{"ko":"무료로 받을 수 있지만 구독형 앱이고 무료 체험이 있어요.","en":"Free to download, but it runs on a subscription with a free trial."},"missions":[{"do":{"ko":"이야기 목록을 천천히 넘기며 그림을 보고, 영어가 아닌 다른 언어로 된 이야기도 하나 찾아 들어 보세요.","en":"Scroll slowly through the stories looking at the artwork, then find and play one in a language other than English."},"wow":{"ko":"곤드 민화 양식으로 이야기마다 그림이 따로 있고, 영어, 칸나다어, 힌디어, 타밀어, 산스크리트어로 들려줘요.","en":"Every story has its own Gond style artwork, and stories are told in English, Kannada, Hindi, Tamil and Sanskrit."}},{"do":{"ko":"이야기를 하나 틀고 화면을 엎어 둔 채 끝까지 들어 보세요.","en":"Start a story, put the phone face down and listen to the end."},"wow":{"ko":"오디오 중심의 화면 없는 설계라 화면을 보지 않아도 이야기가 이어져요. 3세에서 7세 아이의 잠자리를 위한 선택이에요.","en":"It is audio first and screen free, so the story carries on without the screen. It is built for bedtime with kids aged 3 to 7."}},{"do":{"ko":"잠자리 타이머를 맞추거나 AirPlay로 스피커에 보내 보세요.","en":"Set the bedtime timer or send a story to a speaker with AirPlay."},"wow":{"ko":"작은 동화 앱인데 위젯, Spotlight 검색, 재생 목록, 잠자리 타이머, AirPlay까지 최신 iOS 기능을 고루 써요.","en":"A small story app that still uses widgets, Spotlight search, playlists, a bedtime timer and AirPlay."}}],"make":[{"ko":"목록의 항목마다 고유한 그림을 붙여, 글을 못 읽는 사람도 그림으로 고를 수 있는 화면을 만들어 보세요.","en":"Give each item in a list its own illustration so someone who cannot read can choose by picture."},{"ko":"오디오를 재생하고 정한 시간이 지나면 서서히 꺼지는 잠자리 타이머를 붙여 보세요.","en":"Add a bedtime timer that plays audio and fades it out after a set time."}],"ask":{"ko":"글을 못 읽는 아이에게 이야기마다 다른 그림을 준 것이 왜 중요할까요?","en":"Why does giving each story its own picture matter so much for children who cannot read yet?"}},"CapWords":{"time":10,"setup":{"ko":"사진으로 찍을 일상 물건 몇 개를 주변에 준비해 두세요.","en":"Have a few everyday objects nearby to photograph."},"missions":[{"do":{"ko":"주변 물건 하나를 찍고, 배경이 사라지며 물건만 남는 순간을 지켜보세요.","en":"Photograph an object near you and watch the moment the background falls away."},"wow":{"ko":"물건이 스티커처럼 오려져 단어와 발음이 붙은 카드가 돼요. 딸의 영어 질문에 답하던 아빠가 떠올린 아이디어예요.","en":"The object is cut out like a sticker and becomes a card with the word and pronunciation. The idea came from a dad answering his daughter's English questions."}},{"do":{"ko":"찍은 뒤 인식 결과가 나올 때까지 화면에서 눈을 떼지 마세요.","en":"After taking the photo, keep your eyes on the screen until the result appears."},"wow":{"ko":"스피너 대신 작은 애니메이션이 기다림을 채워요. 네트워크 지연이 스티커를 떼어 내는 순간처럼 느껴져요.","en":"Small animations fill the wait instead of a spinner, so network delay feels like peeling off a sticker."}},{"do":{"ko":"스티커를 몇 개 모은 뒤 컬렉션을 넘겨 보고 단어 발음을 들어 보세요.","en":"Collect a few stickers, then browse your collection and listen to the pronunciations."},"wow":{"ko":"내 주변 물건으로 만든 나만의 단어장이에요. 9개 언어를 지원하고, 아이와 어른 모두에게 맞아요.","en":"It is a word collection made from your own surroundings, available in nine languages and suited to kids and adults alike."}}],"make":[{"ko":"VisionKit의 피사체 들어올리기로 사진에서 물체만 오려 내고 라벨을 붙이는 화면을 만들어 보세요.","en":"Use VisionKit subject lifting to cut an object out of a photo and attach a label to it."},{"ko":"네트워크 요청을 기다리는 동안 스피너 대신 결과와 이어지는 짧은 애니메이션을 보여 주게 바꿔 보세요.","en":"Replace a spinner with a short animation that leads into the result while a network request runs."}],"ask":{"ko":"같은 단어라도 내가 직접 찍은 물건으로 배우면 왜 더 오래 기억에 남을까요?","en":"Why does a word stick longer when you learn it from an object you photographed yourself?"}},"puffies.":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"do":{"ko":"스티커를 시트에 붙이면서 기기를 살짝 기울여 보고, 붙는 순간 손끝의 진동에 집중해 보세요.","en":"Place a sticker while gently tilting the device, and focus on the vibration in your fingers as it lands."},"wow":{"ko":"기울이면 광택이 빛처럼 움직이고, 붙일 때마다 몇 달 다듬은 '뽁' 햅틱이 와요. 약 4,000개 스티커 외곽선을 전부 손으로 그렸어요.","en":"The gloss shifts like light as you tilt, and each placement gives a haptic blop tuned for months. Outlines for about 4,000 stickers were all hand drawn."}},{"do":{"ko":"일부러 다른 스티커 위에 겹쳐서 떨어뜨려 보세요.","en":"Deliberately drop a sticker on top of another one."},"wow":{"ko":"실패 화면 대신 스티커가 팩 가장자리로 쏙 돌아가요. 겹칠 때의 동작 하나를 위해 3개월을 쓰고 코드를 통째로 다시 짰어요.","en":"Instead of a fail screen, it zips back to the edge of the pack. The team spent three months and rewrote the codebase for this one behavior."}},{"do":{"ko":"접근성 옵션에서 스냅 거리나 손가락 오프셋을 바꾼 뒤 다시 붙여 보세요.","en":"Change the snap distance or finger offset in the accessibility options and place a sticker again."},"wow":{"ko":"접근성이 메뉴 구석이 아니라 핵심 조작 안에 들어 있어요. 손이 크거나 손 움직임이 불편해도 같은 손맛을 느껴요.","en":"Accessibility is built into the core mechanic, not tucked away. Players with larger hands or reduced motor control get the same feel."}}],"make":[{"ko":"물체를 놓을 때 햅틱을 주고, CoreMotion으로 기기 기울기에 따라 하이라이트가 움직이게 해 보세요.","en":"Add a haptic on drop and use CoreMotion to move a highlight as the device tilts."},{"ko":"잘못된 곳에 놓으면 에러 대신 원래 자리로 부드럽게 돌아가는 드래그 동작을 만들어 보세요.","en":"Build a drag where an invalid drop glides back to its starting spot instead of showing an error."}],"ask":{"ko":"실패가 없는 퍼즐인데 왜 계속 붙이고 싶어질까요?","en":"Why do you keep wanting to place stickers in a puzzle where you can never fail?"}},"Mela – Recipe Manager":{"time":15,"setup":{"ko":"레시피가 실린 블로그 하나와 종이 요리책이 있으면 좋아요.","en":"Have a recipe blog in mind and a printed cookbook nearby."},"missions":[{"do":{"ko":"종이 요리책 한 페이지를 카메라로 스캔해 레시피로 가져와 보세요.","en":"Scan a page of a printed cookbook with the camera and import it as a recipe."},"wow":{"ko":"기기 안 텍스트 인식으로 인쇄된 페이지가 앱 레시피가 돼요. Reeder를 만든 1인 개발자가 투자 없이 만들었고, 데이터는 하나도 안 모아요.","en":"On-device text recognition turns a printed page into a recipe. One developer, the maker of Reeder, built it without funding, and it collects no data."}},{"do":{"ko":"앱 안 브라우저로 광고가 많은 레시피 블로그 글을 열어 보세요.","en":"Open a cluttered recipe blog post in the in-app browser."},"wow":{"ko":"레시피가 감지되면 블로그 잡동사니를 걷어낸 깔끔한 화면으로 보여 주고, 한 번 탭으로 저장돼요.","en":"When a recipe is detected, Mela shows it in a clean native view without the blog clutter and saves it in one tap."}},{"do":{"ko":"레시피를 Cook Mode로 열고 조리대 너머 거리에서 화면을 보세요.","en":"Open a recipe in Cook Mode and look at it from across the counter."},"wow":{"ko":"큰 글자로 지금 단계만 밝게 남고 나머지는 어두워져요. 재료 체크와 타이머가 함께 있고 여러 레시피를 동시에 열 수 있어요.","en":"Large text keeps only the current step bright and dims the rest. Ingredient checkoffs and timers are there, and several recipes can be open at once."}},{"do":{"ko":"재료를 장보기 목록에 넣은 뒤 iPhone의 미리 알림 앱을 열어 보세요.","en":"Add ingredients to the grocery list, then open the Reminders app on your iPhone."},"wow":{"ko":"장보기 목록이 미리 알림 앱에 그대로 있어요. 시스템 앱을 다시 만들지 않아서 Mela를 안 쓰는 사람도 볼 수 있어요.","en":"The grocery list is right there in Reminders. Because it reuses system apps, people who do not use Mela can see it too."}}],"make":[{"ko":"EventKit으로 앱의 목록 항목을 미리 알림 앱에 바로 추가하는 버튼을 만들어 보세요.","en":"Use EventKit to make a button that adds list items straight into the Reminders app."},{"ko":"단계 목록에서 현재 단계만 크게 밝히고 나머지는 흐리게 하는 요리 화면을 만들어 보세요.","en":"Build a cooking view that enlarges and highlights the current step and dims the others."}],"ask":{"ko":"장보기 목록을 자체 화면 대신 미리 알림에 둔 선택이 왜 사용자를 더 편하게 할까요?","en":"Why does putting the grocery list in Reminders instead of a custom screen make life easier for users?"}},"CellWalk":{"time":15,"setup":null,"missions":[{"do":{"ko":"세포 전체에서 시작해 핀치로 계속 확대하다가, 구조를 잘라 안쪽으로 걸어 들어가 보세요.","en":"Start from the whole cell, keep pinching to zoom in, then cut into the structure and walk inside."},"wow":{"ko":"원자 2억 5천만 개짜리 세균 세포를 끊김 없이 분자 기계 수준까지 들어가요. 박사과정 때 시작해 두 명이 10년 넘게 만들었어요.","en":"You go seamlessly into a 250 million atom bacterial cell down to its molecular machines. Two people have built it for over a decade, starting in grad school."}},{"do":{"ko":"뉴런 모델이 있으면 열어서 같은 방식으로 확대하고 돌려 보세요.","en":"If the neuron model is available, open it and zoom and orbit the same way."},"wow":{"ko":"원자 36억 개로 된 뉴런도 iPhone, iPad, Vision Pro에서 렌더링돼요.","en":"Even a neuron made of 3.6 billion atoms renders on iPhone, iPad and Vision Pro."}},{"do":{"ko":"확대하는 동안 효소, 지질, 리보솜의 색과 DNA가 어떻게 강조되는지 지켜보세요.","en":"As you zoom, watch how enzymes, lipids and ribosomes are colored and how DNA is brought forward."},"wow":{"ko":"선명한 색을 칠하고 일부는 채도를 빼서 시선을 이끌어요. 3D 과학 데이터에 영화 같은 시각 위계를 준 거예요.","en":"Vivid colors with selective desaturation steer your eye, giving 3D science data a cinematic visual hierarchy."}},{"do":{"ko":"궁금한 요소를 탭해 설명을 열고, Concept Chains가 보이면 따라가 보세요.","en":"Tap an element you are curious about for its explanation, and follow Concept Chains if you see them."},"wow":{"ko":"Concept Chains는 기기 안 Apple Intelligence가 CellWalk 데이터에 근거해 학습자 수준에 맞게 설명을 맞춰 줘요.","en":"Concept Chains use on-device Apple Intelligence grounded in CellWalk's data to tailor explanations to your level."}}],"make":[{"ko":"RealityKit에서 큰 모델 하나를 핀치로 확대하면 단계마다 다른 세부 모델로 바뀌게 만들어 보세요.","en":"In RealityKit, make one large model swap to more detailed versions as you pinch to zoom."},{"ko":"3D 장면에서 선택한 대상만 색을 남기고 나머지는 채도를 빼는 강조 효과를 만들어 보세요.","en":"Build a focus effect in a 3D scene that keeps color only on the selected object and desaturates the rest."}],"ask":{"ko":"끊김 없는 확대가 세포와 원자의 크기 차이를 왜 숫자보다 더 잘 느끼게 할까요?","en":"Why does a seamless zoom convey the gap between a cell and an atom better than numbers do?"}},"Crayola Adventures":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요하고, 아이와 함께 해 보면 더 좋아요.","en":"Requires Apple Arcade, and it is best tried with a child."},"missions":[{"do":{"ko":"아이와 함께 이야기를 만든 뒤, 글을 직접 읽지 말고 AI 음성이 읽어 주는 걸 들어 보세요.","en":"Make a story together with a child, then do not read it yourself and let the AI voice read it aloud."},"wow":{"ko":"아이가 만든 이야기를 AI 음성이 실시간으로 읽어 줘요. 15개 넘는 언어로 되고, 글을 못 읽는 아이도 끝까지 혼자 놀 수 있어요.","en":"The AI voice reads the child's own story in real time, in over 15 languages, so a child who cannot read can play start to finish alone."}},{"do":{"ko":"캐릭터를 만들면서 피부색, 체형, 능력, 대명사 선택지를 하나씩 바꿔 보세요.","en":"While making a character, change the skin tone, body type, abilities and pronouns one at a time."},"wow":{"ko":"성별 구분이 없는 캐릭터 만들기라서 아이가 자기나 친구, 가족을 닮은 주인공을 만들 수 있어요.","en":"The creator is gender neutral, so a child can build a hero that looks like them, a friend or family."}},{"do":{"ko":"장식 만들기, 퍼즐, 동화책 읽기를 번갈아 해 보세요.","en":"Switch between making decorations, solving puzzles and reading storybooks."},"wow":{"ko":"부담 없는 활동이 섞여 있어서 나이가 다른 사람끼리도 같이 놀 수 있어요.","en":"The low pressure mix of activities lets people of different ages play together."}}],"make":[{"ko":"AVSpeechSynthesizer로 사용자가 입력한 문장을 바로 읽어 주는 버튼을 만들고, 언어를 바꿔 들어 보세요.","en":"Use AVSpeechSynthesizer to read back text the user typed, and try it in another language."},{"ko":"피부색과 체형을 고를 수 있는 간단한 아바타 만들기 화면을 만들어 보세요.","en":"Build a simple avatar creator with choices for skin tone and body type."}],"ask":{"ko":"튜토리얼만이 아니라 게임 전체를 읽어 주게 한 것이 왜 글을 못 읽는 아이에게 결정적일까요?","en":"Why is narrating the whole game, not just the tutorial, decisive for children who cannot read?"}},"Call of Duty: Warzone Mobile":{"time":10,"setup":{"ko":"앱스토어에서 내려가 직접 할 수 없어요. Activision의 공식 트레일러나 스크린샷으로 경험해 보세요.","en":"It has left the App Store, so experience it through Activision's own trailers and screenshots."},"missions":[{"do":{"ko":"공식 트레일러에서 버단스크 맵으로 낙하하는 장면을 찾아, 함께 떨어지는 인원을 세어 보세요.","en":"Find the drop into Verdansk in an official trailer and try counting how many players fall with you."},"wow":{"ko":"휴대폰에서 원조 맵 버단스크를 120명이 동시에 뛰었어요. PC와 콘솔보다 큰 로비였고, 사전 등록은 5,000만 건을 넘었어요.","en":"120 players ran the original Verdansk map at once on phones, a bigger lobby than on PC and console. Pre-registrations passed 50 million."}},{"do":{"ko":"트레일러나 스크린샷에서 컨트롤러로 하는 장면과 터치 조작 화면을 비교해 보세요.","en":"In trailers or screenshots, compare scenes played with a controller against the touch controls."},"wow":{"ko":"출시 때부터 컨트롤러와 터치를 모두 지원해, 같은 게임이 가볍게도 콘솔처럼도 돌아갔어요.","en":"Controller and touch were both supported from launch, so the same game worked casually or console style."}},{"do":{"ko":"트레일러에서 콘솔판과의 연동을 소개하는 부분을 찾아보세요.","en":"Look for the part of a trailer that talks about linking with the console games."},"wow":{"ko":"계급과 잠금 해제가 MWII, MWIII, Black Ops 6과 이어져서 콘솔과 PC에서 쌓은 것이 휴대폰으로 넘어왔어요.","en":"Rank and unlocks were shared with MWII, MWIII and Black Ops 6, so progress from console and PC carried over to the phone."}}],"make":[{"ko":"GameController 프레임워크로 같은 화면을 터치와 컨트롤러 둘 다로 조작하게 만들어 보세요.","en":"Use the GameController framework to make one screen playable by both touch and a controller."},{"ko":"iCloud로 진행 상황을 저장해, iPhone과 iPad에서 같은 기록이 이어지게 해 보세요.","en":"Save progress through iCloud so the same record carries over between iPhone and iPad."}],"ask":{"ko":"120명 로비라는 숫자 하나가 왜 휴대폰 게임에 대한 기대를 바꿨을까요?","en":"Why did a single number, a 120 player lobby, change what people expected from a phone game?"}},"Cityscapes: Sim Builder":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"do":{"ko":"공장 지역을 주거 지역 바로 옆에 붙이고 도로를 넉넉히 깔아 보세요.","en":"Put an industrial zone right next to housing and lay down plenty of roads."},"wow":{"ko":"산업과 교통이 오염을 만들고 거리도 따져서 도시가 바로 반응해요. SimCity 출신이 재난 대신 오염과 대중교통의 균형을 규칙으로 삼았어요.","en":"Industry and traffic create pollution and distance matters, so the city reacts. A former SimCity producer made balance, not disasters, the core rule."}},{"do":{"ko":"문제가 생기면 시민과 고문이 하는 말을 읽어 보세요.","en":"When something goes wrong, read what citizens and advisors say."},"wow":{"ko":"숫자 패널 대신 대화로 문제를 알리고 해결책까지 제안해요. 시뮬레이션 결과가 읽히는 이야기가 돼요.","en":"Instead of stat panels, they raise problems and suggest fixes in conversation. Simulation feedback becomes something you can read."}},{"do":{"ko":"주택, 일자리, 상점, 전력, 수도, 쓰레기 시설을 손가락으로 배치해 보세요.","en":"Place housing, jobs, shops, power, water and garbage with your finger."},"wow":{"ko":"고전 도시 건설의 요구를 다 다루면서도 터치 화면에 맞춘 배치라 어렵지 않아요.","en":"It covers every classic city need, yet the layout is made for touch and stays approachable."}}],"make":[{"ko":"격자 위에 공장과 집을 놓으면 거리에 따라 오염 수치가 바뀌는 작은 시뮬레이션을 만들어 보세요.","en":"Build a tiny grid simulation where pollution changes with the distance between factories and homes."},{"ko":"수치가 기준을 넘으면 그래프 대신 캐릭터가 말풍선으로 알려 주게 해 보세요.","en":"When a value passes a threshold, have a character say it in a speech bubble instead of a chart."}],"ask":{"ko":"재난 대신 오염과 교통의 균형을 핵심 규칙으로 삼은 게 왜 더 오래 고민하게 만들까요?","en":"Why does making pollution and transit the core rule, not disasters, keep you thinking longer?"}},"NBA":{"time":20,"setup":{"ko":"여러 경기 동시 보기와 3D 코트는 Apple Vision Pro에서, 몰입형 환경은 League Pass가 있을 때 볼 수 있어요.","en":"Multiview and the 3D court need Apple Vision Pro, and the immersive environments need League Pass."},"missions":[{"do":{"ko":"Vision Pro에서 경기 하나를 크게 띄우고, 다른 경기를 주변에 하나씩 더해 최대 5개까지 늘려 보세요.","en":"On Vision Pro, open one game large and add others around it one by one, up to five."},"wow":{"ko":"메인 경기는 거대한 화면에, 나머지는 둘레에 배치돼요. '모든 경기를 한꺼번에 보고 싶다'는 바람에 대한 공간적인 답이에요.","en":"The main game fills a giant screen while the rest sit around it, a spatial answer to wanting to watch every game at once."}},{"do":{"ko":"League Pass가 있다면 Court View를 켜고 거실 테이블 위를 바라보세요.","en":"If you have League Pass, turn on Court View and look at your living room table."},"wow":{"ko":"경기가 테이블 위 3D 미니어처 코트로 실시간 재현돼요. 중계가 화면 밖으로 나와 방 안에 놓여요.","en":"The game is recreated live as a 3D miniature court on your table. The broadcast steps out of the screen into the room."}},{"do":{"ko":"경기 중에 선수 기록 오버레이나 Strategy Stream 같은 다른 중계를 켜 보세요.","en":"During a game, turn on the live stat overlay or an alternate stream such as Strategy Stream."},"wow":{"ko":"한 경기가 여러 시청 모드가 돼요. Hoopervision 같은 다른 중계와 현지 언어 중계도 있어요.","en":"One game turns into several viewing modes, including streams like Hoopervision and local language broadcasts."}}],"make":[{"ko":"visionOS에서 큰 창 하나와 작은 창 여러 개를 둘레에 배치하는 멀티뷰 레이아웃을 만들어 보세요.","en":"In visionOS, build a multiview layout with one large window and several small ones arranged around it."},{"ko":"RealityKit으로 탁자 위에 작은 경기장 모델을 놓고 점 하나가 움직이게 해 보세요.","en":"Use RealityKit to place a small court model on a table and animate a single dot moving across it."}],"ask":{"ko":"경기를 더 큰 화면이 아니라 테이블 위 미니어처로 보여 준 것이 왜 새롭게 느껴질까요?","en":"Why does showing a game as a tabletop miniature feel newer than simply showing it bigger?"}},"Afterplace":{"time":20,"setup":{"ko":"11,000원 유료 게임이고 광고는 없어요. 컨트롤러가 있으면 함께 준비해 두세요.","en":"A paid game at 11,000 won with no ads. Have a controller ready if you own one."},"missions":[{"do":{"ko":"돌아다니며 그림, 음악, 효과음, 대사를 하나씩 눈과 귀로 확인해 보세요.","en":"Wander around and pay attention to the art, music, sound effects and writing one at a time."},"wow":{"ko":"이 모두를 한 사람이 만들었어요. 디자인부터 사운드까지 혼자 만든 오픈월드 RPG가 스튜디오 게임들을 제치고 2023 ADA를 받았어요.","en":"One person made all of it. An open world RPG built solo, from design to sound, beat studio games to a 2023 Apple Design Award."}},{"do":{"ko":"화면 아무 데나 터치해 움직이고 공격해 본 뒤, 두 엄지로도 해 보세요. 컨트롤러가 있으면 연결해 보세요.","en":"Touch anywhere to move and attack, then try two thumbs like a gamepad, and plug in a controller if you have one."},"wow":{"ko":"어떻게 쥐든 게임이 거기에 맞춰요. 휴대폰을 먼저 생각하고 만든 조작이에요.","en":"However you hold it, the game adapts. The controls were designed for the phone first."}},{"do":{"ko":"지도 표시를 찾지 말고 궁금한 곳으로 그냥 걸어가 보세요.","en":"Do not look for map markers. Just walk toward whatever looks interesting."},"wow":{"ko":"웨이포인트도 퀘스트 마커도 없어요. 비밀, 보물, 생물을 스스로 찾을 거라고 플레이어를 믿어요.","en":"There are no waypoints or quest markers. The game trusts you to find secrets, treasure and creatures yourself."}},{"do":{"ko":"자판기 같은 사물을 만나면 말을 걸어 보세요.","en":"If you come across something like a vending machine, talk to it."},"wow":{"ko":"옛 픽셀 RPG 모습인데 대사는 요즘 유머예요. 빈정대는 자판기가 있어요.","en":"It looks like a vintage pixel RPG, but the writing is modern and funny. There are sarcastic vending machines."}}],"make":[{"ko":"화면 어디를 눌러도 그 방향으로 캐릭터가 움직이는 터치 조작을 만들어 보세요.","en":"Build a touch control where pressing anywhere moves the character toward that point."},{"ko":"안내 표시 없이 눈에 띄는 지형 하나만으로 플레이어를 이끄는 작은 맵을 만들어 보세요.","en":"Make a small map that guides the player with one eye catching landmark instead of markers."}],"ask":{"ko":"퀘스트 마커를 없앤 결정이 왜 오히려 더 멀리 탐험하게 만들까요?","en":"Why does removing quest markers make players explore further, not less?"}},"Headspace":{"time":15,"setup":{"ko":"조용한 곳과 이어폰을 준비해 두세요.","en":"Find a quiet spot and have earphones ready."},"missions":[{"do":{"ko":"이어폰을 끼고 짧은 초보자 명상 세션 하나를 끝까지 따라 해 보세요.","en":"Put on earphones and follow one short beginner meditation session to the end."},"wow":{"ko":"전직 불교 승려가 2010년 런던에서 명상 이벤트와 CD로 시작한 회사가, 이 짧은 세션으로 다운로드 1억 500만 회 앱이 됐어요.","en":"A company that a former Buddhist monk began in London in 2010 with events and CDs grew, through sessions like this, to 105 million downloads."}},{"do":{"ko":"호흡 운동을 켜고 애니메이션이 커졌다 작아지는 속도에 맞춰 숨을 쉬어 보세요.","en":"Start a breathing exercise and breathe in time with the animation as it grows and shrinks."},"wow":{"ko":"움직임의 속도가 숨의 리듬에 맞춰져 있고 문장은 짧고 대화하듯 해요. 몸의 리듬에 모션 타이밍을 맞춘 좋은 예예요.","en":"The motion is paced to your breath, with short conversational copy. It is a great example of timing motion to a body rhythm."}},{"do":{"ko":"스트레스나 수면처럼 무거운 주제의 콘텐츠를 열어 일러스트를 보세요.","en":"Open content on a heavy topic like stress or sleep and look at the illustrations."},"wow":{"ko":"둥글고 친근한 캐릭터와 따뜻한 색 덕분에 정신 건강이라는 부담스러운 주제가 가볍게 다가와요.","en":"Round, friendly characters and a warm palette make a daunting topic like mental health feel approachable."}}],"make":[{"ko":"원이 4초 동안 커지고 4초 동안 작아지는 호흡 애니메이션을 만들고, 짧은 안내 문장을 붙여 보세요.","en":"Make a circle that grows for four seconds and shrinks for four, and pair it with short guiding lines."},{"ko":"무거운 주제의 빈 화면에 둥근 캐릭터 일러스트를 넣어 느낌이 어떻게 달라지는지 비교해 보세요.","en":"Add a round character illustration to an empty screen about a heavy topic and compare how it feels."}],"ask":{"ko":"숨에 맞춘 단순한 애니메이션이 왜 긴 설명보다 명상을 더 쉽게 시작하게 할까요?","en":"Why does a simple animation paced to the breath make it easier to start meditating than long instructions?"}},"SwingVision: A.I. Tennis App":{"time":30,"setup":{"ko":"테니스 코트와 iPhone이나 iPad를 세울 거치대가 필요해요. 판정과 자동 점수는 유료 플랜이고, Apple Watch가 있으면 손목으로 점수를 매길 수 있어요.","en":"You need a court and a stand for your iPhone or iPad. Line calls and scoring are on paid plans, and an Apple Watch lets you score from the wrist."},"missions":[{"do":{"ko":"코트 옆에 iPhone을 세우고 랠리를 한 뒤, 선 근처에 떨어진 공의 판정을 확인해 보세요.","en":"Set your iPhone up beside the court, play a rally, then check the call on a ball that landed near the line."},"wow":{"ko":"아이폰 한 대가 선 10cm 안쪽 공을 97% 맞혀요. 사람 눈은 약 90%예요. Tesla 오토파일럿의 3D 추적 기술이 테니스로 왔어요.","en":"One iPhone gets 97 percent of calls within 10 cm of the line right, versus about 90 for the human eye, using 3D tracking from Tesla Autopilot."}},{"do":{"ko":"라켓에 아무것도 달지 않고 찍은 뒤, 샷 속도와 깊이, 랠리 길이를 확인해 보세요.","en":"Record with nothing attached to your racket, then check shot speed, depth and rally length."},"wow":{"ko":"센서 없이 카메라 하나로 자동 추적하고, 분석은 Neural Engine으로 코트에 있는 휴대폰 안에서 돌아요.","en":"A single camera tracks everything with no sensors, and the analysis runs on the phone at the court through the Neural Engine."}},{"do":{"ko":"긴 경기를 찍은 뒤 하이라이트를 열어 보세요.","en":"Record a long match, then open the highlights."},"wow":{"ko":"긴 영상이 포인트와 샷 단위로 잘려 있어요. 아무도 두 시간짜리 영상을 다시 보지 않는다는 문제를 풀었어요.","en":"The long recording is already cut into points and shots, solving the problem that nobody rewatches two hours of video."}},{"do":{"ko":"Apple Watch가 있다면 경기 중 손목으로 점수를 매겨 보세요.","en":"If you have an Apple Watch, keep score from your wrist during play."},"wow":{"ko":"휴대폰을 만지러 가지 않고 손목에서 점수와 판정을 다뤄요.","en":"You handle scoring and calls from your wrist without walking over to the phone."}}],"make":[{"ko":"Vision 프레임워크로 영상 속 움직이는 공 하나를 추적해 궤적을 그려 보세요.","en":"Use the Vision framework to track one moving ball in a video and draw its path."},{"ko":"긴 영상을 움직임이 있는 구간만 잘라 짧은 하이라이트 목록으로 보여 주는 화면을 만들어 보세요.","en":"Build a screen that trims a long video to just the active parts and lists them as short highlights."}],"ask":{"ko":"사람 눈보다 정확하다는 숫자가 왜 이 앱을 믿게 만드는 가장 강한 이유가 될까요?","en":"Why is being more accurate than the human eye the strongest reason to trust this app?"}},"(Not Boring) Habits":{"time":10,"setup":null,"missions":[{"do":{"ko":"습관 하나를 만들고 체크인한 뒤, 손끝의 진동과 소리, 화면 속 풍경에 집중해 보세요.","en":"Create a habit and check in, focusing on the vibration, the sound and the landscape on screen."},"wow":{"ko":"습관 앱인데 3D, 애니메이션, 물리, 햅틱, 사운드로 게임처럼 반응해요. 체크할 때마다 3D 풍경 속 여정이 앞으로 나아가요.","en":"A habit app that responds like a game, with 3D, animation, physics, haptics and sound. Each check-in moves you further through a 3D landscape."}},{"do":{"ko":"진행 표시가 연속 일수로 세는지 반복 횟수로 세는지 확인하고, 하루 빠지면 어떻게 될지 생각해 보세요.","en":"Check whether progress counts days in a row or total reps, and think about what a missed day would do."},"wow":{"ko":"하루 빠지면 0이 되는 스트릭 대신 '60번 반복' 모델이에요. 하루를 놓쳐도 동기가 꺾이지 않아요.","en":"Instead of a streak that resets after one missed day, it uses a 60 reps model, so a missed day does not kill your motivation."}},{"do":{"ko":"'30분 중 10분'처럼 나눠서 채우는 목표를 만들고 하루에 여러 번 체크인한 뒤 위젯을 추가해 보세요.","en":"Make a goal you fill in parts, like 10 of 30 minutes, check in several times a day, then add a widget."},"wow":{"ko":"하루 여러 번 체크인과 단계형 목표를 지원하고, Grid, Climb, Streak 위젯으로 홈 화면에서도 보여요.","en":"Multiple daily check-ins and incremental goals are supported, and the Grid, Climb and Streak widgets put them on your Home Screen."}},{"do":{"ko":"아트 스킨 목록을 열어 다른 스킨으로 바꿔 보세요.","en":"Open the art skins and switch to a different one."},"wow":{"ko":"아티스트 협업 스킨과 손그림 배지가 꾸미기를 보상으로 만들고, 그것이 수익원도 돼요.","en":"Artist collaboration skins and hand drawn badges make customizing a reward, and a revenue stream too."}}],"make":[{"ko":"체크 버튼을 누르면 햅틱과 짧은 소리, 튀는 애니메이션이 함께 나오게 만들어 보세요.","en":"Make a check button that fires a haptic, a short sound and a bouncy animation together."},{"ko":"연속 일수 대신 누적 횟수로 진행률을 보여 주는 습관 카드를 만들어 보세요.","en":"Build a habit card that shows progress as total reps instead of days in a row."}],"ask":{"ko":"스트릭을 버리고 누적 횟수를 택한 게 왜 습관을 더 오래 이어 가게 할까요?","en":"Why does dropping streaks for total reps help people keep a habit longer?"}},"Vectornator: Vector Design":{"time":20,"setup":{"ko":"지금은 Linearity Curve라는 이름이고, iPad와 Apple Pencil이 있으면 가장 잘 느낄 수 있어요. 내보내기와 AI 기능은 Pro 구독이에요.","en":"It is now called Linearity Curve and is best on iPad with Apple Pencil. Export and AI features need a Pro subscription."},"missions":[{"do":{"ko":"Apple Pencil로 펜 도구를 골라 곡선을 그린 뒤, 노드를 끌어 모양을 다듬어 보세요.","en":"Pick the pen tool with Apple Pencil, draw a curve, then drag its nodes to refine the shape."},"wow":{"ko":"데스크톱급 베지어 펜과 노드 편집이 터치와 필압에 맞춰져 있어요. 이런 편집을 무료로 풀어 사용자 1,000만 명을 모았어요.","en":"Desktop class Bezier and node editing is tuned for touch and pressure. Offering it for free drew 10 million users."}},{"do":{"ko":"손그림 스케치 사진을 불러와 Auto Trace를 실행해 보세요.","en":"Import a photo of a hand drawn sketch and run Auto Trace."},"wow":{"ko":"스케치가 곧바로 벡터가 돼요. 한 번 탭으로 사진 배경을 지우는 기능도 있어요.","en":"The sketch becomes vectors instantly. There is also one tap background removal for photos."}},{"do":{"ko":"도형 두 개를 겹쳐 놓고 Shape Builder로 직접 합치거나 빼 보세요.","en":"Overlap two shapes and combine or subtract them directly with Shape Builder."},"wow":{"ko":"메뉴 명령이 아니라 손으로 직접 조작해서 불리언 연산을 해요.","en":"Boolean operations happen through direct manipulation, not menu commands."}}],"make":[{"ko":"SwiftUI Path로 점 세 개를 끌어 곡선 모양이 바뀌는 작은 베지어 편집기를 만들어 보세요.","en":"Build a tiny Bezier editor in SwiftUI where dragging three points reshapes a curve."},{"ko":"PencilKit에서 필압에 따라 선 굵기가 달라지는 캔버스를 만들어 손가락과 비교해 보세요.","en":"Make a PencilKit canvas where line width follows pressure, and compare it with drawing by finger."}],"ask":{"ko":"데스크톱 도구를 그대로 옮기지 않고 터치에 맞춰 다시 만든 것이 왜 중요했을까요?","en":"Why did it matter to rebuild desktop tools for touch rather than port them as they were?"}},"MARVEL Future Revolution":{"time":10,"setup":{"ko":"앱스토어에서 내려가 직접 할 수 없어요. Netmarble의 공식 트레일러나 스크린샷으로 경험해 보세요.","en":"It has left the App Store, so experience it through Netmarble's own trailers and screenshots."},"missions":[{"do":{"ko":"공식 트레일러에서 영웅이 넓은 지역을 날아다니는 장면을 찾아보세요.","en":"Find the scenes in an official trailer where heroes fly across wide areas."},"wow":{"ko":"마블 첫 모바일 오픈 월드 액션 RPG로, 스테이지 대신 이어진 넓은 지역을 날아다녔어요. 2022 ADA를 받고 2년 만에 문을 닫았어요.","en":"Marvel's first mobile open world action RPG let heroes fly across seamless zones instead of stages. It won a 2022 ADA and shut down two years after launch."}},{"do":{"ko":"트레일러의 컷신과 영웅 모델이 나오는 순간 멈춰 놓고 디테일을 보세요.","en":"Pause the trailer on cutscenes and hero close-ups and study the detail."},"wow":{"ko":"언리얼 엔진 4와 Metal로 iPhone과 iPad에서 콘솔 같은 화면을 냈어요. Apple도 정교한 캐릭터 모델을 짚었어요.","en":"Unreal Engine 4 and Metal delivered console-like visuals on iPhone and iPad, and Apple singled out the detailed character models."}},{"do":{"ko":"전투 장면에서 영웅마다 기술과 콤보가 어떻게 이어지는지 지켜보세요.","en":"Watch how skills and combos flow for each hero in the combat scenes."},"wow":{"ko":"캐릭터마다 다른 기술과 콤보 흐름이 모바일에서도 부드럽다는 평을 받았어요.","en":"Each character's skills and combo flow were praised as smooth even on mobile hardware."}}],"make":[{"ko":"SpriteKit이나 SceneKit으로 스테이지 전환 없이 넓은 맵을 자유롭게 움직이는 장면을 만들어 보세요.","en":"Use SpriteKit or SceneKit to build a scene where you move freely over a wide map with no stage breaks."},{"ko":"버튼 세 개를 순서대로 누르면 콤보 애니메이션이 이어지는 전투 입력을 만들어 보세요.","en":"Build a combat input where pressing three buttons in order chains into a combo animation."}],"ask":{"ko":"혁신상을 받은 게임이 2년 만에 사라졌다는 사실은 라이브 서비스 앱에 대해 무엇을 말해 줄까요?","en":"What does an award winning game disappearing after two years tell you about live service apps?"}},"Little Orpheus":{"time":10,"setup":{"ko":"앱스토어에서 내려가 직접 할 수 없어요. The Chinese Room의 공식 트레일러나 스크린샷으로 경험해 보세요.","en":"It has left the App Store, so experience it through The Chinese Room's own trailers and screenshots."},"missions":[{"do":{"ko":"트레일러에서 단순한 횡스크롤 이동 장면과 영화 같은 연출 장면을 함께 지켜보세요.","en":"In the trailer, watch the simple side-scrolling movement alongside the cinematic set pieces."},"wow":{"ko":"조작은 일부러 단순한데 화면은 콘솔급 영화 연출이에요. 소련 우주비행사의 허풍 같은 모험담으로 2021 ADA를 받았어요.","en":"The controls are deliberately simple, but the presentation is console grade cinema. A Soviet cosmonaut's tall tale won a 2021 ADA."}},{"do":{"ko":"트레일러에서 주인공이 심문관에게 이야기하는 목소리에 귀 기울여 보세요.","en":"Listen in the trailer for the hero telling his story to the interrogator."},"wow":{"ko":"모험 전체가 심문관 앞에서 늘어놓는 허풍이라, 믿기 어려운 내레이션이 웃음과 레벨을 이어 줘요.","en":"The whole adventure is a tall tale told to an interrogator, so the unreliable narration ties the comedy and the levels together."}},{"do":{"ko":"스크린샷 여러 장을 넘기며 장면마다 환경이 얼마나 다른지 보세요.","en":"Flip through several screenshots and see how different each environment is."},"wow":{"ko":"짧은 챕터마다 새 환경과 깜짝 장면이 있어요. Dear Esther를 만든 The Chinese Room의 손맛 있는 아트예요.","en":"Each short chapter brings a new environment and a surprise set piece, with hand crafted art from the makers of Dear Esther."}}],"make":[{"ko":"좌우 이동과 점프만 있는 화면에 카메라 줌과 배경 레이어 연출을 더해 분위기를 바꿔 보세요.","en":"Take a screen with only left, right and jump, and add camera zooms and layered backgrounds to change the mood."},{"ko":"레벨 시작마다 화자의 짧은 내레이션 한 줄을 띄워 이야기로 이어 보세요.","en":"Show one short line of narration from a storyteller at the start of each level to tie them into a story."}],"ask":{"ko":"조작을 단순하게 줄인 것이 왜 영화 같은 연출을 더 돋보이게 했을까요?","en":"Why did simplifying the controls make the cinematic moments stand out more?"}},"Sp!ng":{"time":10,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"do":{"ko":"화면을 누르고 있다가 원하는 순간에 손을 떼서 날아가 보세요. 몇 판을 연달아 해 보세요.","en":"Hold the screen to spin, release at the moment you choose to fling, and play several levels in a row."},"wow":{"ko":"조작은 '잡고 돌리고 놓기' 하나뿐인데, 이것만으로 1,400개가 넘는 레벨을 만들었어요.","en":"The only control is hold, spin and release, and that alone powers more than 1,400 levels."}},{"do":{"ko":"Zen이나 One Life 같은 다른 모드를 열어 같은 조작으로 해 보세요.","en":"Open another mode such as Zen or One Life and play with the same control."},"wow":{"ko":"똑같은 조작이 모드마다 다른 기분과 난이도가 돼요. Rush, Hyper, Play Perfect 모드도 있어요.","en":"The same input takes on a different mood and difficulty in each mode. There are also Rush, Hyper and Play Perfect."}},{"do":{"ko":"다른 테마의 레벨로 넘어가 음악이 어떻게 달라지는지 들어 보세요.","en":"Move on to levels in another theme and listen to how the music changes."},"wow":{"ko":"7개 테마마다 작곡가 Stafford Bawler의 음악이 따로 있어요.","en":"Each of the 7 themes has its own soundtrack by composer Stafford Bawler."}}],"make":[{"ko":"누르는 동안 점을 중심으로 돌고 손을 떼면 접선 방향으로 날아가는 오브젝트를 만들어 보세요.","en":"Make an object that orbits a point while you hold and flies off along the tangent when you let go."},{"ko":"같은 조작에 시간 제한과 목숨 하나 규칙만 바꿔 두 가지 모드를 만들어 보세요.","en":"Create two modes from the same control by changing only a time limit and a one life rule."}],"ask":{"ko":"입력이 하나뿐인데 왜 실력 차이가 크게 드러날까요?","en":"With only one input, why does skill show so clearly?"}},"(Not Boring) Weather":{"time":10,"setup":null,"missions":[{"do":{"ko":"날씨 화면에서 3D 장면, 숫자, 아이콘 등 보이는 곳을 아무 데나 눌러 보세요.","en":"On the weather screen, tap anything you see, from the 3D scene to the numbers and icons."},"wow":{"ko":"누르는 곳마다 반응해요. Paper 앱 수석 디자이너가 UI 전체를 게임 엔진으로 3D 렌더링했고, 원칙은 '죽은 화면은 없다'예요.","en":"Everything responds. The former lead designer of Paper rendered the whole UI in 3D with a game engine, under the rule that no screen is dead."}},{"do":{"ko":"소리를 켜고 화면을 만지며 효과음과 아주 미세한 진동에 집중해 보세요.","en":"Turn the sound on, touch the screen and focus on the sound effects and the faint vibrations."},"wow":{"ko":"고음질 효과음과 겨우 느껴질 만한 햅틱이 함께 와서 날씨를 손으로 만지는 느낌이 들어요.","en":"High fidelity sound and just noticeable haptics arrive together, so the weather feels like something you can touch."}},{"do":{"ko":"앱 아이콘이나 스킨을 다른 것으로 바꿔 보세요.","en":"Switch to a different app icon or skin."},"wow":{"ko":"아이콘만이 아니라 앱 전체 디자인이 바뀌어요. 꾸미기가 이 앱의 대표 특징이자 수익원이에요.","en":"The design of the whole app changes, not just the icon. Personalization is its signature and a revenue lever."}}],"make":[{"ko":"정적인 정보 카드 하나를 골라 탭하면 튀는 애니메이션과 가벼운 햅틱이 나오게 바꿔 보세요.","en":"Pick a static info card and make it bounce with a light haptic when tapped."},{"ko":"SceneKit으로 날씨에 따라 조명이 바뀌는 작은 3D 장면을 만들어 보세요.","en":"Use SceneKit to build a small 3D scene whose lighting changes with the weather."}],"ask":{"ko":"모든 것을 누를 수 있게 만든 원칙이 왜 날씨 확인을 하나의 놀이로 바꿀까요?","en":"Why does making everything tappable turn checking the weather into play?"}},"Sayonara Wild Hearts":{"time":10,"setup":{"ko":"앱스토어에서 내려가 직접 할 수 없어요. Simogo나 Annapurna의 공식 트레일러와 스크린샷으로 경험해 보세요.","en":"It has left the App Store, so experience it through Simogo's or Annapurna's own trailers and screenshots."},"missions":[{"do":{"ko":"공식 트레일러를 소리를 켜고 보며 화면 속 움직임이 비트에 맞는지 느껴 보세요.","en":"Watch an official trailer with the sound on and feel whether the movement lands on the beat."},"wow":{"ko":"레벨 하나가 오리지널 팝송 한 곡이고 달리고 피하는 동작이 비트에 맞춰져요. 작은 스튜디오가 약 4년 들인 '팝 앨범 비디오 게임'이에요.","en":"Each level is one original pop song, with riding and dodging synced to the beat. A small studio spent about four years on this pop album video game."}},{"do":{"ko":"트레일러에서 카메라 각도와 시점이 바뀌는 순간을 세어 보세요.","en":"Count how often the camera angle and perspective shift in the trailer."},"wow":{"ko":"네온 핑크와 보라 색 속에서 카메라와 시점이 쉬지 않고 바뀌어요. 음악이 이끄는 모션 디자인의 교과서예요.","en":"In neon pink and purple, the camera and perspective never stop moving. It is a textbook of music driven motion design."}},{"do":{"ko":"트레일러나 스크린샷에서 조작 안내가 얼마나 단순한지 살펴보세요.","en":"Look at how simple the control prompts are in the trailer or screenshots."},"wow":{"ko":"밀기와 탭만으로 하니 리듬과 볼거리에 집중하게 돼요. 여러 번 실패하면 구간을 건너뛰자고 제안해서 누구나 끝까지 볼 수 있어요.","en":"Just swipes and taps keep the focus on rhythm and spectacle. After repeated failures it offers a skip, so everyone can reach the end."}}],"make":[{"ko":"음악의 BPM에 맞춰 오브젝트가 튀거나 색이 바뀌는 화면을 만들어 보세요.","en":"Build a screen where objects pulse or change color in time with a song's BPM."},{"ko":"같은 구간을 세 번 실패하면 건너뛰기 버튼이 나타나는 규칙을 넣어 보세요.","en":"Add a rule that shows a skip button after the player fails the same section three times."}],"ask":{"ko":"게임을 '앨범'이라고 부른 것만으로 플레이하는 마음가짐이 어떻게 달라질까요?","en":"How does calling a game an album change the way you approach playing it?"}},"Strava":{"time":20,"setup":{"ko":"밖에서 짧게 걷거나 달릴 시간이 필요하고, Apple Watch가 있으면 휴대폰 없이도 해 볼 수 있어요.","en":"You need time outdoors for a short walk or run, and an Apple Watch lets you try it without the phone."},"missions":[{"do":{"ko":"짧게 달리거나 걸은 활동을 저장한 뒤, 지나온 구간의 순위를 확인해 보세요.","en":"Save a short run or walk, then check the leaderboard for a segment you passed."},"wow":{"ko":"같은 길을 지난 사람들과 기록이 비교돼요. 혼자 한 운동이 시간 차를 둔 경쟁이 돼요.","en":"Your time is compared with everyone who covered the same stretch. A solo workout becomes a race run at different times."}},{"do":{"ko":"저장한 활동이 피드에 어떻게 올라가는지 보고, 친구의 활동에 쿠도스를 눌러 보세요.","en":"See how your saved activity appears in the feed, and give kudos to a friend's activity."},"wow":{"ko":"운동 기록이 곧 게시물이 돼요. 기록 앱 위에 피드, 쿠도스, 클럽 같은 SNS 구조를 얹어 커뮤니티가 됐어요.","en":"A workout log becomes a post. Feeds, kudos and clubs on top of the records turned a tracker into a community."}},{"do":{"ko":"Apple Watch가 있다면 휴대폰을 두고 나가 세그먼트를 지나 보세요.","en":"If you have an Apple Watch, leave the phone behind and go through a segment."},"wow":{"ko":"휴대폰 없이 손목에서 세그먼트를 실시간으로 추적해요.","en":"Segments are tracked live on your wrist, with no phone."}},{"do":{"ko":"프라이버시 존과 활동 공개 범위 설정을 찾아 내 기록이 누구에게 보이는지 확인해 보세요.","en":"Find the privacy zone and activity visibility settings and check who can see your activities."},"wow":{"ko":"위치가 얼마나 드러날지 직접 정해요. 2018년 히트맵이 군사 기지 위치를 드러낸 뒤 이 설계의 중요성이 커졌어요.","en":"You decide how much of your location is exposed. The 2018 heatmap that revealed military bases showed why this design matters."}}],"make":[{"ko":"같은 구간 기록 몇 개를 저장하고 내 기록이 몇 등인지 보여 주는 순위 화면을 만들어 보세요.","en":"Store a few times for the same stretch and build a screen that shows where yours ranks."},{"ko":"위치 권한을 요청하기 전에 왜 필요한지 설명하는 화면을 하나 넣어 보세요.","en":"Add one screen that explains why you need location before the system permission prompt appears."}],"ask":{"ko":"모르는 사람과의 구간 순위가 왜 혼자 하는 운동을 계속하게 만들까요?","en":"Why does a segment ranking against strangers keep people working out on their own?"}},"Instagram":{"time":10,"setup":null,"missions":[{"do":{"ko":"스토리를 보다가 옆으로 반쯤만 넘기다 멈추고, 다시 되돌려 보세요.","en":"While watching stories, swipe sideways halfway, stop, then drag back."},"wow":{"ko":"3D 큐브 전환이 손가락을 그대로 따라와서 중간에 멈추고 되돌릴 수 있어요. 제스처와 애니메이션이 하나로 붙어 있어요.","en":"The 3D cube follows your finger exactly, so you can pause and reverse midway. Gesture and animation are one."}},{"do":{"ko":"피드 사진을 두 손가락으로 확대했다가 손을 떼 보세요.","en":"Pinch to zoom on a feed photo, then let go."},"wow":{"ko":"사진이 제자리로 튕겨 돌아가요. 더블탭 좋아요처럼 작은 제스처 피드백이 정교해요.","en":"The photo springs back into place. Small gesture feedback like this and double tap to like is finely made."}},{"do":{"ko":"스토리에서 탭, 길게 누르기, 아래로 스와이프를 차례로 해 보세요.","en":"In stories, try a tap, a long press and a swipe down in turn."},"wow":{"ko":"다음, 멈춤, 닫기로 이어지는 이 제스처 어휘가 업계 표준처럼 다른 앱에 복제됐어요.","en":"This vocabulary of next, pause and close was copied by other apps until it became an industry standard."}},{"do":{"ko":"사진을 골라 글을 쓴 뒤 공유를 누르고, 올라가는 데 걸리는 시간을 느껴 보세요.","en":"Pick a photo, write a caption, tap share and notice how long it takes to post."},"wow":{"ko":"업로드 전에 백그라운드 처리를 미리 시작하는 기법으로 체감 속도를 높인 것으로 잘 알려져 있어요.","en":"Instagram is known for starting background processing before you upload, which makes posting feel faster."}}],"make":[{"ko":"UIViewPropertyAnimator로 손가락을 따라가다 중간에 멈추고 되돌릴 수 있는 화면 전환을 만들어 보세요.","en":"Use UIViewPropertyAnimator to build a transition that follows the finger and can be paused and reversed."},{"ko":"이미지를 핀치로 확대하고 손을 떼면 스프링 애니메이션으로 돌아오게 만들어 보세요.","en":"Make an image you can pinch to zoom that springs back when released."}],"ask":{"ko":"손가락을 그대로 따라오는 전환이 왜 버튼으로 넘기는 것보다 더 자연스럽게 느껴질까요?","en":"Why does a transition that tracks your finger feel more natural than one triggered by a button?"}},"Notion":{"time":15,"setup":null,"missions":[{"do":{"ko":"빈 페이지에서 '/'를 입력하고 표나 보드 같은 데이터베이스 블록을 골라 보세요.","en":"On a blank page, type a slash and choose a database block such as a table or board."},"wow":{"ko":"빈 페이지가 바로 데이터베이스가 돼요. 문단도 이미지도 DB도 모두 블록이라 같은 방식으로 바뀌어요.","en":"The blank page becomes a database on the spot. Paragraphs, images and databases are all blocks, so they change the same way."}},{"do":{"ko":"같은 데이터베이스를 표, 보드, 캘린더, 갤러리 뷰로 차례로 바꿔 보세요.","en":"Switch the same database between table, board, calendar and gallery views."},"wow":{"ko":"데이터는 그대로인데 모습만 바뀌어요. 정보 구조와 표현을 떼어 놓은 설계예요.","en":"The data stays the same while only its look changes. Structure and presentation are kept apart."}},{"do":{"ko":"페이지 안에 페이지를 몇 단계 만들어 깊이 들어간 뒤, 상단 경로나 검색으로 돌아와 보세요.","en":"Nest pages several levels deep, then get back using the breadcrumb at the top or search."},"wow":{"ko":"끝없이 중첩해도 브레드크럼, 사이드바, 검색, 즐겨찾기로 바로 점프해서 길을 잃지 않아요.","en":"However deep you nest, breadcrumbs, the sidebar, search and favorites let you jump straight out, so you never get lost."}}],"make":[{"ko":"텍스트 입력 중 '/'를 치면 블록 종류 메뉴가 뜨는 작은 에디터를 만들어 보세요.","en":"Build a small editor that pops up a block type menu when you type a slash."},{"ko":"같은 배열 데이터를 목록과 격자 두 가지 뷰로 전환해 보여 주는 화면을 만들어 보세요.","en":"Make a screen that shows the same array of data as either a list or a grid."}],"ask":{"ko":"모든 것을 '블록' 하나로 통일한 것이 왜 빈 페이지를 덜 막막하게 만들까요?","en":"Why does making everything a block make a blank page feel less daunting?"}},"ChatGPT":{"time":10,"setup":null,"missions":[{"do":{"ko":"긴 답이 필요한 질문을 보내고, 답이 써지는 도중에 전송 버튼이 있던 자리를 눌러 보세요.","en":"Send a question that needs a long answer, and while it writes, tap where the send button was."},"wow":{"ko":"그 자리가 정지 버튼으로 바뀌어 있어 같은 위치에서 바로 멈춰요. 첫 글자부터 흘러나와 기다림도 짧게 느껴져요.","en":"That spot has become a stop button, so it halts right there. Text streams from the first word, so the wait feels short."}},{"do":{"ko":"음성 모드를 켜고 답하는 중간에 말을 끊고 끼어들어 보세요.","en":"Start voice mode and cut in while it is answering."},"wow":{"ko":"사람과 대화하듯 실시간으로 끼어들 수 있고, 음성 상태가 애니메이션으로 보여요.","en":"You can interrupt in real time like talking to a person, and the voice state is shown as an animation."}},{"do":{"ko":"답이 생성되는 도중에 화면을 위로 스크롤해 보세요.","en":"Scroll up while an answer is still being generated."},"wow":{"ko":"자동 스크롤이 멈춰서 읽던 곳을 놓치지 않아요. 복사와 재생성 버튼은 답이 다 끝난 뒤에야 나타나요.","en":"Auto scroll stops so you keep your place. Copy and regenerate only appear once the answer has finished."}}],"make":[{"ko":"텍스트를 한 글자씩 흘려 보여 주고, 그동안 전송 버튼을 정지 버튼으로 바꾸는 화면을 만들어 보세요.","en":"Build a screen that streams text character by character and swaps the send button for a stop button meanwhile."},{"ko":"사용자가 위로 스크롤하면 자동 스크롤을 멈추는 채팅 목록을 만들어 보세요.","en":"Make a chat list that stops auto scrolling once the user scrolls up."}],"ask":{"ko":"답을 한꺼번에가 아니라 흘려 보여 주는 것만으로 왜 기다림이 덜 지루할까요?","en":"Why does streaming the answer, rather than showing it all at once, make the wait feel less tedious?"}},"카카오톡":{"time":15,"setup":null,"missions":[{"do":{"ko":"친구 탭을 열어 2025년 9월 개편 이후 바뀐 모습을 살펴보세요.","en":"Open the Friends tab and look at how it changed after the September 2025 redesign."},"wow":{"ko":"친구 목록이 피드형으로 바뀌고 숏폼이 들어왔다가 거센 반발을 받았어요. 사용자의 머릿속 모델을 거스르는 IA 변경이 얼마나 위험한지 보여 줘요.","en":"The friends list became a feed with short videos and faced a fierce backlash. It shows how risky it is to change structure against users' mental models."}},{"do":{"ko":"채팅방 하나를 열어 송금이나 선물하기로 들어가는 길을 찾아보세요.","en":"Open a chat and find the way into sending money or gifts."},"wow":{"ko":"메신저 계정 하나에 카카오페이 송금, 카카오 T, 카카오 로그인이 묶여 있어요. 대화가 곧 결제 입구인 슈퍼앱이에요.","en":"Kakao Pay transfers, Kakao T and Kakao Login are tied to one messenger account. The chat itself is the doorway to payments."}},{"do":{"ko":"대화방에서 이모티콘을 보내고, 이모티콘 스토어나 구독 안내를 찾아보세요.","en":"Send an emoticon in a chat, then find the emoticon store or subscription offer."},"wow":{"ko":"대화 속 표현을 파는 한국형 수익 모델이에요. 2021년 1월에는 이모티콘 구독까지 생겼어요.","en":"It is a Korean business model that sells expression inside conversations, and in January 2021 it added an emoticon subscription."}}],"make":[{"ko":"채팅 화면의 입력창 옆에 송금이나 선물 같은 기능으로 들어가는 버튼을 붙인 프로토타입을 만들어 보세요.","en":"Prototype a chat screen with a button beside the input field that leads into a feature like payments or gifts."},{"ko":"친구 목록을 리스트와 피드 두 버전으로 만들어 주변 사람에게 어느 쪽이 편한지 물어보세요.","en":"Make a friends list in two versions, a plain list and a feed, and ask people around you which feels easier."}],"ask":{"ko":"친구 탭 개편이 기능을 더했는데도 왜 사용자에게는 무언가를 빼앗긴 것처럼 느껴졌을까요?","en":"Why did the Friends tab redesign feel like a loss to users even though it added features?"}},"Ball x Pit":{"time":20,"setup":null,"missions":[{"do":{"ko":"공을 내려오는 벽에 튕겨 보내며 첫 판을 끝까지 해 보세요.","en":"Play your first run to the end, flinging balls at the descending wall."},"wow":{"ko":"조작은 공 날리기 하나라 바로 읽혀요. 과금 가득한 'Punball'에 빠졌던 개발자가 과금 없는 버전을 만들려고 시작했고 200만 장이 팔렸어요.","en":"The only verb is flinging balls, so it reads instantly. A developer hooked on the pay heavy Punball set out to make a version without it, and sold 2 million copies."}},{"do":{"ko":"공 두 개를 합치거나 공 하나를 진화시킨 뒤 벽을 향해 날려 보세요.","en":"Fuse two balls or evolve one, then fling it at the wall."},"wow":{"ko":"두 효과를 합친 공이 연쇄 반응으로 화면을 가득 채워요. Apple이 짚은 '튕김으로 굴러가는 전투'가 이 순간이에요.","en":"A ball with both effects fills the screen with chain reactions. This is the ricochet-fueled combat Apple singled out."}},{"do":{"ko":"한 판이 끝나면 마을에 일꾼을 배치해 나무, 돌, 금을 모으고 건물을 지어 보세요.","en":"After a run, assign workers in the village to gather wood, stone and gold and construct a building."},"wow":{"ko":"건물이 새 캐릭터를 열거나 시작 능력치를 올려서, 짧은 한 판에도 장기 목표가 생겨요.","en":"Buildings unlock characters or raise starting stats, giving even a short run long term purpose."}}],"make":[{"ko":"SpriteKit 물리로 공을 날려 벽돌에 튕기게 하고, 두 공을 합치면 효과가 섞이게 만들어 보세요.","en":"Use SpriteKit physics to bounce balls off bricks, and make two merged balls combine their effects."},{"ko":"한 판이 끝날 때 모은 자원으로 다음 판 시작 능력치를 올리는 화면을 만들어 보세요.","en":"Build an end of run screen where gathered resources raise starting stats for the next run."}],"ask":{"ko":"과금을 걷어냈더니 같은 벽돌깨기 루프가 왜 더 오래 붙잡게 됐을까요?","en":"Why did the same brick breaker loop hold players longer once the monetization was stripped out?"}},"Detail: AI Video Editor":{"time":15,"setup":{"ko":"조용한 장소가 좋고, 대화 장면을 찍을 사람 한 명이 있으면 더 좋아요.","en":"Find a quiet spot, and ideally a second person to record a conversation with."},"missions":[{"do":{"ko":"두 사람이 대화하는 모습을 iPhone 한 대로 한 번에 찍고 Auto Edit을 실행해 보세요.","en":"Record two people talking in a single shot on one iPhone, then run Auto Edit."},"wow":{"ko":"한 컷이 말하는 사람에게 줌했다가 상대 반응으로 넘어가는 멀티 앵글 편집이 돼요. 침묵도 잘려서 혼자 찍은 영상이 2캠 촬영처럼 보여요.","en":"One shot becomes a multi angle edit that zooms on the speaker and cuts to the other's reaction. Silences are cut, so it looks like a two camera shoot."}},{"do":{"ko":"대충 쓴 메모나 개요를 넣어 텔레프롬프터 대본으로 바꾸고, 렌즈를 보며 읽어 보세요.","en":"Paste a rough note or outline, turn it into a teleprompter script and read it to the lens."},"wow":{"ko":"Foundation Models가 초안을 대본으로 바꾸고, 읽는 동안 화면에서 스크롤돼요.","en":"Foundation Models turn the draft into a script that scrolls on screen while you read."}},{"do":{"ko":"전면과 후면 카메라로 동시에 찍어 보세요.","en":"Record with the front and back cameras at the same time."},"wow":{"ko":"앞뒤 동시 녹화가 되고, 여러 iPhone과 iPad를 묶어 전환하는 스튜디오도 만들 수 있어요.","en":"Both cameras record together, and several iPhones and iPads can be linked into a switchable studio."}}],"make":[{"ko":"영상 하나에서 구간마다 확대 영역을 바꿔 가짜 멀티 앵글처럼 보이게 하는 편집을 만들어 보세요.","en":"Build an edit that changes the zoom area per section of one video so it looks like multiple angles."},{"ko":"텍스트를 일정 속도로 위로 흘려 보내는 간단한 텔레프롬프터 화면을 만들어 보세요.","en":"Make a simple teleprompter screen that scrolls text upward at a steady speed."}],"ask":{"ko":"카메라 한 대 영상이 컷 몇 번만으로 왜 훨씬 전문적으로 보일까요?","en":"Why does a one camera video look so much more professional after just a few cuts?"}},"Harvee":{"time":10,"setup":{"ko":"HRV, 안정 시 심박, 수면 데이터를 쓰기 때문에 Apple Watch가 필요해요.","en":"You need an Apple Watch, since it reads HRV, resting heart rate and sleep."},"missions":[{"do":{"ko":"Apple Watch 데이터가 들어온 뒤 홈 화면 가운데 있는 캐릭터의 모습을 확인해 보세요.","en":"Once your Apple Watch data has synced, look at the character in the middle of the home screen."},"wow":{"ko":"HRV, 심박, 수면, 활동이 차트 대신 작은 캐릭터 하나의 상태로 보여요. 회복 조언은 기기 안 모델이 만들어 데이터가 폰 밖으로 안 나가요.","en":"HRV, heart rate, sleep and activity show up as one small character's state, not charts. Advice comes from on-device models, so data stays on the phone."}},{"do":{"ko":"오늘의 스트레스와 회복 설명을 열어 끝까지 읽어 보세요.","en":"Open today's stress and recovery explanation and read it through."},"wow":{"ko":"따로 노는 차트 대신 하루 하나의 수치를 쉬운 말로 풀어 줘요.","en":"Instead of separate charts, it gives one daily reading explained in plain language."}},{"do":{"ko":"오늘 마신 카페인이나 물을 기록하고 7일 스트레스 히트맵을 보세요.","en":"Log today's caffeine or water and look at the 7 day stress heat map."},"wow":{"ko":"생활 습관 기록과 스트레스 결과를 나란히 보며 둘의 연결을 직접 찾게 돼요.","en":"Seeing lifestyle logs next to stress lets you find the connection yourself."}}],"make":[{"ko":"숫자 하나를 받아 범위에 따라 표정이 바뀌는 캐릭터 화면을 SwiftUI로 만들어 보세요.","en":"In SwiftUI, build a character whose expression changes with the range of a single number."},{"ko":"Foundation Models로 기기 안에서 숫자 몇 개를 쉬운 한 줄 조언으로 바꿔 보세요.","en":"Use Foundation Models on device to turn a few numbers into one line of plain advice."}],"ask":{"ko":"차트 대신 캐릭터 하나로 보여 준 것이 왜 건강 데이터를 매일 열어 보게 만들까요?","en":"Why does showing health data as one character, not charts, get people to open it every day?"}},"Lumy":{"time":10,"setup":{"ko":"7,500원 유료 앱이고, Apple Watch가 있으면 컴플리케이션도 확인할 수 있어요.","en":"A paid app at 7,500 won, and an Apple Watch lets you try the complications."},"missions":[{"do":{"ko":"앱을 열어 오늘의 골든아워와 블루 아워 시간을 확인하고, 화면 색이 어떤지 살펴보세요.","en":"Open the app, find today's golden hour and blue hour, and notice the colors on screen."},"wow":{"ko":"사진작가 아내와 골든아워를 찾으려 만든 개인 도구가 2024년 Apple Watch 올해의 앱이 됐어요. 색이 시간대에 따라 바뀌어 데이터가 빛처럼 느껴져요.","en":"A personal tool built to find golden hour with his photographer wife became 2024 Apple Watch App of the Year. Colors shift with the time, so data feels like light."}},{"do":{"ko":"타임 슬라이더를 끌어 하루를 처음부터 끝까지 훑어 보세요.","en":"Drag the time slider through the whole day."},"wow":{"ko":"하루 동안의 빛의 상태가 손끝을 따라 바뀌어요. 해와 달 계산은 모두 기기 안에서 해요.","en":"The day's light conditions change under your finger, and all sun and moon math runs on the device."}},{"do":{"ko":"모드를 사진에서 명상으로 바꿔 보세요.","en":"Switch the mode from Photography to Mindfulness."},"wow":{"ko":"정보 순서가 바뀌어요. 사진가에게는 골든아워와 블루 아워가, 새벽 명상가에게는 첫 빛이 먼저 보여요.","en":"The order of information changes. Photographers see golden and blue hour first, while dawn meditators see first light."}},{"do":{"ko":"위젯이나 Apple Watch 컴플리케이션을 추가해 보세요.","en":"Add a widget or an Apple Watch complication."},"wow":{"ko":"앱을 열지 않아도 다음 빛 이벤트가 잠금 화면이나 손목에 떠요.","en":"The next light event shows on your Lock Screen or wrist without opening the app."}}],"make":[{"ko":"현재 시각에 따라 배경 그라데이션 색이 바뀌는 화면을 만들고, 슬라이더로 시간을 움직여 보세요.","en":"Build a screen whose background gradient follows the time of day, and scrub the time with a slider."},{"ko":"사용자가 고른 모드에 따라 같은 정보 카드의 순서를 바꿔 보여 주게 해 보세요.","en":"Reorder the same information cards depending on the mode the user picks."}],"ask":{"ko":"숫자 대신 색으로 시간을 보여 준 것이 왜 해 뜨는 시각을 더 '느끼게' 할까요?","en":"Why does showing time through color make you feel sunrise more than a number does?"}},"Land of Livia":{"time":20,"setup":{"ko":"VoiceOver를 켜고 이어폰을 준비해 두세요.","en":"Turn on VoiceOver and have earphones ready."},"missions":[{"do":{"ko":"VoiceOver를 켠 채 눈을 감고, 메뉴를 지나 퀘스트 하나를 진행해 보세요.","en":"With VoiceOver on, close your eyes and get through the menus into a quest."},"wow":{"ko":"모든 메뉴와 퀘스트가 손으로 다듬은 VoiceOver로 돼요. 시각장애인 플레이어를 위해 처음부터 설계했고, 음악도 시각장애인 플레이어가 작곡했어요.","en":"Every menu and quest works through hand crafted VoiceOver. It was designed for blind players from the start, and a blind player composed the soundtrack."}},{"do":{"ko":"Siri나 단축어로 이동이나 인벤토리 관리 같은 동작을 실행해 보세요.","en":"Use Siri or Shortcuts to trigger an action such as navigation or inventory management."},"wow":{"ko":"App Intents 덕분에 여러 번 눌러야 할 복잡한 조작이 목소리나 버튼 하나로 끝나요.","en":"Thanks to App Intents, complex actions that would take many steps finish with your voice or a single button."}},{"do":{"ko":"모험을 보내 둔 뒤 앱을 닫았다가 나중에 다시 열어 보세요.","en":"Send off an adventure, close the app, and come back later."},"wow":{"ko":"자리를 비운 동안에도 모험이 진행돼요. 빠른 시각 반응이 필요 없는 구조예요.","en":"The adventure moves on while you are away. Nothing depends on fast visual reflexes."}}],"make":[{"ko":"만든 화면 하나에 VoiceOver 라벨과 힌트를 직접 써 넣고, 눈을 감고 써 보세요.","en":"Write VoiceOver labels and hints by hand for one of your screens, then use it with your eyes closed."},{"ko":"앱의 핵심 동작 하나를 App Intent로 만들어 Siri로 실행해 보세요.","en":"Expose one core action of your app as an App Intent and run it with Siri."}],"ask":{"ko":"VoiceOver를 처음부터 핵심 입력으로 설계한 것이 나중에 덧붙인 것과 어떻게 다르게 느껴질까요?","en":"How does designing VoiceOver in as a primary input from day one feel different from adding it later?"}},"DREDGE":{"time":20,"setup":{"ko":"컨트롤러가 있으면 터치와 비교해 볼 수 있어요.","en":"A controller lets you compare it with touch."},"missions":[{"do":{"ko":"낮에 평화롭게 낚시를 하다가, 일부러 해가 진 뒤에도 바다에 머물러 보세요.","en":"Fish peacefully in daylight, then deliberately stay out at sea after dark."},"wow":{"ko":"공포 게이지가 오르며 바다가 적대적으로 변해요. '러브크래프트식 낚시' 두 단어에서 시작한 4인 팀 데뷔작이 첫날 10만 장 팔렸어요.","en":"The panic meter climbs and the sea turns hostile. A four person debut born from the pitch Lovecraftian fishing sold 100,000 copies on day one."}},{"do":{"ko":"물고기를 잡을 때마다 화물칸 격자에 모양을 맞춰 끼워 넣어 보세요.","en":"Each time you catch a fish, fit it into the cargo grid by its shape."},"wow":{"ko":"테트리스 같은 화물칸이라 짐 정리 자체가 퍼즐이에요. 무엇을 싣고 무엇을 버릴지 매번 고민하게 돼요.","en":"The Tetris-like hold makes inventory a puzzle, so every trip forces a choice about what to keep."}},{"do":{"ko":"낚시 미니게임을 터치로 해 본 뒤, 컨트롤러로도 해 보세요.","en":"Play the fishing mini-games with touch, then with a controller."},"wow":{"ko":"짧고 다양한 미니게임이 터치와 컨트롤러 모두에 깔끔하게 맞아요.","en":"The short, varied mini-games map cleanly to both touch and controller."}}],"make":[{"ko":"모양이 다른 블록을 격자 가방에 끌어다 넣는 인벤토리 화면을 만들어 보세요.","en":"Build an inventory screen where differently shaped blocks are dragged into a grid bag."},{"ko":"시간이 지나면 화면이 어두워지고 긴장 게이지가 차오르는 낮과 밤 전환을 넣어 보세요.","en":"Add a day and night cycle where the screen darkens and a tension meter fills over time."}],"ask":{"ko":"전투 없이도 밤바다가 왜 그렇게 무섭게 느껴질까요?","en":"Why does the night sea feel so frightening even without combat?"}},"Infinity Nikki":{"time":30,"setup":{"ko":"무료 게임이지만 뽑기(가챠) 과금이 있어요.","en":"Free to play, but it uses gacha monetization."},"missions":[{"do":{"ko":"드레스를 입고 빛이 드는 곳에서 걷고 돌면서 옷자락과 반짝임을 지켜보세요.","en":"Wear a dress and walk and turn in the light while watching the fabric and sparkle."},"wow":{"ko":"천 시뮬레이션으로 드레스가 흔들리고 반짝여요. 옷 갈아입히기 게임을 언리얼 엔진 5 오픈월드로 만들며 1,000명 넘게 개발에 참여했어요.","en":"Fabric simulation makes the dress sway and sparkle. Over 1,000 developers built this dress-up game as an Unreal Engine 5 open world."}},{"do":{"ko":"이동 능력을 주는 옷을 찾아 입고, 전에는 못 가던 곳으로 가 보세요.","en":"Find and wear an outfit piece that grants a traversal ability, then reach a place you could not before."},"wow":{"ko":"무기 대신 옷을 모아요. 특정 옷이 이동 능력을 줘서 패션 자체가 성장 시스템이에요.","en":"You collect outfits instead of weapons. Certain pieces grant movement abilities, so fashion is the progression system."}},{"do":{"ko":"Stylist Duel이 열리면 도전해 보세요.","en":"Take on a Stylist Duel when one opens up."},"wow":{"ko":"옷 고르기 자체가 대결 규칙이 돼요.","en":"Choosing an outfit becomes the challenge itself."}}],"make":[{"ko":"아이템을 장착하면 새 동작이 열리는 간단한 캐릭터 화면을 만들어 보세요.","en":"Build a simple character screen where equipping an item unlocks a new move."},{"ko":"SceneKit에서 천 느낌의 물체에 조명을 바꿔 가며 재질이 어떻게 보이는지 비교해 보세요.","en":"In SceneKit, change the lighting on a cloth-like object and compare how the material looks."}],"ask":{"ko":"옷을 능력으로 바꾼 설계가 왜 꾸미기를 탐험의 동기로 만들까요?","en":"Why does turning clothing into abilities make dressing up a reason to explore?"}},"Complete Anatomy 2024":{"time":20,"setup":{"ko":"iPad나 Mac에서 해 보면 가장 잘 느낄 수 있어요.","en":"Best experienced on iPad or Mac."},"missions":[{"do":{"ko":"3D 인체 모델을 돌리며 구조를 하나씩 숨기거나 흐리게 해 안쪽으로 들어가 보세요.","en":"Rotate the 3D body and hide or fade structures one by one to work your way inside."},"wow":{"ko":"해부실을 터치 화면으로 옮긴 셈이에요. 아일랜드의 작은 회사가 만든 이 앱을 엘스비어가 약 4,470만 유로에 샀고 약 300만 명이 써요.","en":"It is a dissection lab on a touch screen. Elsevier bought this app from a small Irish company for about 44.7 million euros, and about 3 million people use it."}},{"do":{"ko":"실시간으로 뛰는 심장 모델을 열고 잘라 보세요.","en":"Open the beating heart model and dissect it."},"wow":{"ko":"심장이 뛰는 채로 해부할 수 있어요. 정지된 모델을 넘어선 경험이에요.","en":"You can dissect the heart while it beats, well beyond a static model."}},{"do":{"ko":"AR 모드로 인체 모델을 방 안에 띄워 보세요.","en":"Use AR mode to place the anatomy in your room."},"wow":{"ko":"해부 모델이 실제 공간에 놓여 주위를 걸으며 볼 수 있어요.","en":"The anatomy is projected into your physical space."}},{"do":{"ko":"모델의 피부색과 표현형을 바꿔 보세요.","en":"Change the model's skin tone and phenotype."},"wow":{"ko":"다양한 피부색과 표현형으로 실제 환자의 다양성을 보게 해요. 2024 ADA 포용성 부문 후보에 오른 이유예요.","en":"A wide range of skin tones and phenotypes reflects real patient diversity, the reason it was a 2024 ADA inclusivity finalist."}}],"make":[{"ko":"RealityKit에서 겹친 3D 모델의 바깥 층을 슬라이더로 투명하게 만들어 안쪽이 보이게 해 보세요.","en":"In RealityKit, use a slider to fade the outer layer of stacked 3D models so the inside shows."},{"ko":"아바타나 일러스트의 기본값을 여러 피부색 중에서 고를 수 있게 바꿔 보세요.","en":"Change an avatar or illustration so its default can be chosen from several skin tones."}],"ask":{"ko":"구조를 하나씩 걷어 내는 조작이 왜 책 속 해부도보다 더 오래 기억에 남을까요?","en":"Why does peeling away structures one by one stick in memory longer than an atlas page?"}},"Crouton":{"time":15,"setup":{"ko":"손글씨 레시피 카드나 요리책 한 페이지를 준비해 두세요.","en":"Have a handwritten recipe card or a cookbook page ready."},"missions":[{"do":{"ko":"손글씨 레시피 카드를 사진 한 장으로 찍어 가져와 보세요.","en":"Take one photo of a handwritten recipe card and import it."},"wow":{"ko":"직접 학습시킨 Core ML 모델이 재료와 분량을 나눠 줘요. 회사 다니며 Swift를 독학해 만든 앱인데, 첫 1년 사용자는 본인과 엄마뿐이었어요.","en":"Custom trained Core ML models split out ingredients and amounts. He taught himself Swift while working, and for the first year his only users were him and his mom."}},{"do":{"ko":"'대충 다진 양파'처럼 수식어가 붙은 재료가 있는 레시피를 가져와 장보기 목록을 보세요.","en":"Import a recipe with ingredients like roughly chopped onion, then look at the grocery list."},"wow":{"ko":"수식어를 떼고 '양파'만 뽑아 분량을 나누고, 카테고리별로 묶어 줘요.","en":"It strips the description down to onion, pulls out the quantity and groups items by category."}},{"do":{"ko":"단계 모드를 켜고 한 단계씩 넘겨 보세요.","en":"Turn on step mode and move through one step at a time."},"wow":{"ko":"지금 단계와 그 재료, 분량, 단위 변환, 타이머만 보여서 화면 대신 조리대를 보게 돼요.","en":"It shows only the current step with its ingredients, amounts, unit conversions and a timer, so you look at the counter, not the screen."}}],"make":[{"ko":"VisionKit 텍스트 인식으로 사진 속 글자를 읽어 줄 단위 목록으로 나눠 보여 주는 화면을 만들어 보세요.","en":"Use VisionKit text recognition to read a photo and split it into a list of lines."},{"ko":"레시피 단계 중 현재 단계와 그 재료만 보여 주는 단계 화면을 만들어 보세요.","en":"Build a step view that shows only the current recipe step and its ingredients."}],"ask":{"ko":"무엇을 뺄지 고민한 시간이 왜 이 앱의 조작을 더 매끄럽게 만들었을까요?","en":"Why did time spent deciding what to leave out make this app's interactions feel smoother?"}},"The Bear":{"time":15,"setup":{"ko":"첫 챕터는 무료이고, 나머지 4개 챕터는 한 번의 인앱 구매로 열려요.","en":"The first chapter is free; the other four unlock with a single in-app purchase."},"missions":[{"do":{"ko":"소리를 켜고 첫 장면에서 동굴 속 곰을 달래 꺼내 보세요. 곰이 움직이는 모습을 천천히 지켜보세요.","en":"Turn the sound on and coax the bear out of its cave in the first scene. Watch slowly how the bear moves."},"wow":{"ko":"움직임 하나하나가 손그림 애니메이션이에요. 갓 졸업한 세 명의 데뷔작이 이 그림으로 독일 게임 어워드 최우수 그래픽상을 받았어요.","en":"Every movement is hand-drawn animation. This debut by three fresh graduates won the German Computer Game Award for Best Graphic Design with it."}},{"do":{"ko":"일부러 빠르게 여러 번 탭해 보세요.","en":"Tap quickly and repeatedly on purpose."},"wow":{"ko":"급한 손짓에도 장면이 거칠어지지 않아요. 잠자리 동화의 차분함을 지키려고 상호작용을 부드럽게 설계했기 때문이에요.","en":"The scene never turns rough under hurried taps. The interactions were made gentle on purpose to protect the calm of a bedtime story."}},{"do":{"ko":"곰과 아이를 행성 너머로 이끌며 화면에 글이 얼마나 나오는지 세어 보세요.","en":"Guide the bear and the little one across the planets and count how much text appears on screen."},"wow":{"ko":"공감, 상실, 놓아주기 같은 감정이 설명 글 없이 은유적인 장면만으로 전해져요.","en":"Feelings like empathy, loss and letting go come through metaphorical scenes, not explanatory text."}}],"make":[{"ko":"내 앱에서 연타하기 쉬운 버튼 하나에 부드러운 이징 애니메이션을 넣어, 빠른 입력도 차분하게 받아 주게 만들어 보세요.","en":"Give one easily spam-tapped button in your app a soft easing animation so even fast input is received calmly."},{"ko":"손으로 그린 프레임 몇 장을 이어 붙인 짧은 애니메이션을 만들어 빈 화면이나 로딩 화면에 넣어 보세요.","en":"Make a short animation from a few hand-drawn frames and put it on an empty or loading screen."}],"ask":{"ko":"설명 글이 거의 없는데도 감정이 전해진 장면은 무엇 덕분이었나요?","en":"With almost no text, what made a scene carry its feeling?"}},"Synth Riders":{"time":20,"setup":{"ko":"Apple Vision Pro 전용이고 Apple Arcade 구독이 필요해요.","en":"It runs only on Apple Vision Pro and needs an Apple Arcade subscription."},"missions":[{"do":{"ko":"컨트롤러 없이 맨손으로 첫 곡을 시작해 색깔 노트를 터치하고 레일을 따라 손을 움직여 보세요.","en":"Start a first song with bare hands, no controllers: touch the colored notes and trace the rails with your hands."},"wow":{"ko":"Vision Pro 발매일에 나온 이 버전은 완전한 핸드 트래킹을 처음 도입해, 기본곡 73곡 전부를 맨손으로 플레이할 수 있어요.","en":"Released on Vision Pro launch day, this version introduced full hand tracking for the first time, so all 73 base songs play with bare hands."}},{"do":{"ko":"혼합 현실 모드로 바꿔 내 방에서 한 곡을 플레이해 보세요.","en":"Switch to mixed reality mode and play a song in your own room."},"wow":{"ko":"내 방이 레트로 퓨처리스틱 세계로 통하는 포털이 돼요.","en":"Your room becomes a portal into a retro-futuristic world."}},{"do":{"ko":"곡을 고르는 메뉴에서 음악이 흐르는 동안 주변 비주얼을 살펴보세요.","en":"In the song menu, watch the visuals around you while the music plays."},"wow":{"ko":"곡에 동기화된 오디오 반응형 비주얼이 게임플레이뿐 아니라 메뉴와 내비게이션까지 이어져요.","en":"Audio-reactive visuals synced to each song carry on beyond gameplay into menus and navigation."}}],"make":[{"ko":"정해진 BPM 타이머로 화면 배경의 밝기나 크기가 박자에 맞춰 변하게 해, 메뉴에서도 리듬이 느껴지게 해 보세요.","en":"Use a fixed BPM timer to pulse a background's brightness or scale on the beat, so even a menu feels rhythmic."},{"ko":"버튼을 누르는 대신 화면 위 선을 손가락으로 따라 그리면 성공하는 인터랙션 프로토타입을 만들어 보세요.","en":"Prototype an interaction where tracing a line with your finger, not pressing a button, counts as success."}],"ask":{"ko":"목표물을 치는 게임이 아니라 춤추는 느낌이 든 이유는 무엇이었나요?","en":"Why did it feel like dancing rather than hitting targets?"}},"CREME":{"time":5,"setup":{"ko":"App Store에서 내려가 직접 해 볼 수 없어요. 개발사가 공개한 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so you can only explore it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"개발사가 공개한 트레일러나 스크린숏에서 요리하는 장면을 찾아보세요.","en":"Find the cooking scenes in the developer's own trailer or screenshots."},"wow":{"ko":"Apple 심사위원단이 2023년 즐거움과 재미 부문 결선작으로 꼽은 요리 게임인데, 지금은 이런 자료로만 볼 수 있어요.","en":"Apple's jury picked this cooking game as a 2023 Delight and Fun finalist, yet now you can only see it through material like this."}},{"do":{"ko":"트레일러를 보다가 가장 유쾌하게 느껴지는 순간에서 멈춰 보세요.","en":"While watching the trailer, pause at the moment that feels most delightful."},"wow":{"ko":"그해 iPhone·iPad에서 가장 유쾌한 디자인 중 하나로 꼽혔지만 세부 설명은 공개되지 않아, 그 이유를 직접 찾아야 해요.","en":"It was named one of that year's most delightful iPhone and iPad designs, but no details were published, so you have to find why yourself."}}],"make":[{"ko":"내 앱 화면을 녹화해 15초 트레일러를 만들고, 무엇이 즐거운지 한 장면으로 보여 주는지 확인해 보세요.","en":"Screen-record your app into a 15-second trailer and check whether one scene shows what is fun."},{"ko":"내 앱의 평범한 동작 하나에 과정이 단계별로 보이는 짧은 애니메이션을 붙여, 기다림이 재미가 되게 해 보세요.","en":"Add a short step-by-step animation to one ordinary action in your app so waiting becomes fun."}],"ask":{"ko":"직접 해 볼 수 없는 앱에서 즐거움을 판단할 때 무엇을 근거로 삼았나요?","en":"When you could not play it, what did you rely on to judge whether it was fun?"}},"Endling":{"time":20,"setup":{"ko":"3,500원 유료 게임이에요.","en":"It is a paid game (₩3,500)."},"missions":[{"do":{"ko":"어미 여우가 되어 첫 밤에 새끼들을 위해 먹이를 찾으러 나가 보세요.","en":"As the mother fox, head out on the first night to find food for your cubs."},"wow":{"ko":"동물을 지켜보는 대신 직접 엄마가 되니 먹이 하나에도 무게가 실려요. 두 사람의 첫 게임이 BAFTA와 ADA를 받은 이유예요.","en":"Being the mother instead of watching an animal makes every scrap of food weigh on you. That is how a two-person debut won a BAFTA and an ADA."}},{"do":{"ko":"먹이를 찾다가 사람과 마주치면 잠시 멈춰서 주변을 살펴보세요.","en":"When you run into humans while foraging, stop for a moment and look around."},"wow":{"ko":"환경 메시지를 글로 설명하지 않고, 인간 캐릭터와의 조우와 레벨 디자인만으로 전해요.","en":"The environmental message is never spelled out; it comes through encounters with humans and the level design."}},{"do":{"ko":"한 구간을 지나며 조작에 쓰는 버튼이 몇 개인지 세어 보세요.","en":"Play through one stretch and count how many buttons the controls use."},"wow":{"ko":"조작을 일부러 단순하게 줄여 손이 아니라 이야기에 집중하게 돼요. Apple도 이 점을 짚었어요.","en":"The controls are deliberately simple, so you focus on the story rather than your hands. Apple pointed this out too."}}],"make":[{"ko":"내 앱의 핵심 화면 문구를 사용자가 관찰자가 아니라 주인공이 되는 1인칭으로 바꾼 버전을 만들어 보세요.","en":"Rewrite your app's key screen copy in first person so the user is the protagonist, not an observer."},{"ko":"내 앱의 기능 하나를 버튼 두세 개로만 조작하게 줄인 프로토타입을 만들어 보세요.","en":"Prototype one feature of your app reduced to just two or three controls."}],"ask":{"ko":"여우를 지켜보는 대신 직접 엄마 여우가 된 것이 감정을 어떻게 바꿨나요?","en":"How did being the mother fox, rather than watching one, change what you felt?"}},"MARVEL SNAP":{"time":15,"setup":null,"missions":[{"do":{"ko":"한 판을 시작해 끝날 때까지 시간을 재 보세요.","en":"Start a match and time it until it ends."},"wow":{"ko":"12장 덱, 3개 지역, 6턴으로 카드 게임을 압축했어요. 블리자드 명함 뒷면의 아이디어가 6분 이하 한 판으로 2,200만 다운로드를 넘겼어요.","en":"A 12-card deck, three locations and six turns compress a card game. An idea sketched on Blizzard business cards became sub-six-minute matches and 22 million downloads."}},{"do":{"ko":"손패가 좋을 때 스냅으로 판돈을 두 배로 올리고, 불리한 판에서는 일부러 후퇴해 보세요.","en":"Snap to double the stakes when your hand is good, and retreat on purpose when a match turns against you."},"wow":{"ko":"카드 실력만큼 블러핑이 중요해져요. 더블링 큐브처럼 판돈을 올리고, 지는 판은 손실을 줄여 빠질 수 있어요.","en":"Bluffing matters as much as cards. Like a doubling cube you raise the stakes, and you can cut your losses on a losing match."}},{"do":{"ko":"판이 시작되면 지역이 공개될 때마다 그 규칙을 읽어 보세요.","en":"Once a match starts, read each location's rule as it is revealed."},"wow":{"ko":"무작위로 열리는 지역마다 고유 규칙이 있어 같은 덱도 매 판 달라져요.","en":"Each randomly revealed location has its own rule, so the same deck plays differently every time."}},{"do":{"ko":"카드 하나를 업그레이드한 뒤 능력치가 바뀌었는지 확인해 보세요.","en":"Upgrade a card and check whether its stats changed."},"wow":{"ko":"능력치는 그대로이고 프레임, 3D 효과, 애니메이션만 바뀌어요. 페이투윈 없이 수집 욕구를 채워요.","en":"The stats stay the same; only the frame, 3D effects and animation change. It rewards collecting without pay-to-win."}}],"make":[{"ko":"내 앱에서 가장 긴 흐름을 6단계 안에 끝나도록 줄인 버전을 종이에 그려 보세요.","en":"Sketch on paper a version of your app's longest flow cut down to six steps or fewer."},{"ko":"내 앱의 보상 하나를 기능이 아닌 외형 변화(테두리, 애니메이션)로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype one reward in your app as a cosmetic change, like a frame or animation, instead of a feature."}],"ask":{"ko":"판돈을 올리는 버튼 하나가 카드 게임의 긴장을 어떻게 바꿨나요?","en":"How did one stake-raising button change the tension of a card game?"}},"Overboard!":{"time":30,"setup":{"ko":"9,900원 유료 게임이고 광고나 인앱 구매는 없어요.","en":"It is a paid game (₩9,900) with no ads or in-app purchases."},"missions":[{"do":{"ko":"첫 회차를 시작해 살인범 베로니카로서 아무 승객에게나 거짓말을 해 보세요.","en":"Start your first run and, as the murderer Veronica, lie to any passenger."},"wow":{"ko":"추리물을 뒤집어 내가 범인이에요. 4명이 100일 만에 만든 게임인데 NPC가 보고 들은 것을 기억해 거짓말에 결과가 따라요.","en":"The whodunit is flipped and you are the killer. Four people made it in 100 days, yet NPCs remember what they saw and heard, so lies have consequences."}},{"do":{"ko":"일부러 엉성한 알리바이를 대고 회차를 실패로 끝내 보세요.","en":"Give a sloppy alibi on purpose and let the run end in failure."},"wow":{"ko":"회차가 짧고 이후에만 드러나는 비밀이 있어서, 실패한 회차가 곧 다음 판의 정보가 돼요.","en":"Runs are short and some secrets only appear later, so a failed run becomes information for the next one."}},{"do":{"ko":"협박, 유혹, 약 타기 같은 선택지 중 평소라면 고르지 않을 것을 골라 보세요.","en":"Among options like blackmail, seduction and drugging, pick one you normally never would."},"wow":{"ko":"모든 대사와 행동이 선택지예요. inkle의 오픈소스 서사 언어 ink가 이 갈래들을 구동해요.","en":"Every line and action is a choice, driven by ink, inkle's open-source narrative scripting language."}}],"make":[{"ko":"inkle의 오픈소스 ink로 선택지 세 개짜리 짧은 대화를 써서 내 앱 프로토타입에 붙여 보세요.","en":"Write a short three-choice dialogue in inkle's open-source ink and attach it to a prototype of your app."},{"ko":"내 앱의 실패 화면에 다음 시도에 쓸 힌트 하나를 보여 주게 바꿔 보세요.","en":"Change your app's failure screen to show one hint for the next attempt."}],"ask":{"ko":"실패했는데도 바로 다시 하고 싶었던 이유는 무엇이었나요?","en":"Why did you want to try again right after failing?"}},"What Remains of Edith Finch":{"time":30,"setup":{"ko":"7,700원 유료 게임이고, 한두 번 앉아서 끝까지 할 수 있는 길이예요.","en":"It is a paid game (₩7,700), short enough to finish in one or two sittings."},"missions":[{"do":{"ko":"통조림 공장 장면에서 한 손으로 생선을 손질하면서 다른 손으로 상상 속 모험을 조종해 보세요.","en":"In the cannery scene, process fish with one hand while steering the imagined adventure with the other."},"wow":{"ko":"두 손이 서로 다른 일을 하면서 지루한 현실과 도피하는 마음이 조작 그 자체로 느껴져요.","en":"With each hand doing a different job, dull reality and the escaping mind are felt through the controls themselves."}},{"do":{"ko":"다음 친척의 이야기로 넘어갈 때마다 조작 방식이 어떻게 바뀌는지 비교해 보세요.","en":"Each time you move on to another relative's story, compare how the controls change."},"wow":{"ko":"에피소드마다 조작, 아트 스타일, 카메라를 새로 만들어서 이야기마다 다른 게임처럼 느껴져요.","en":"Each episode gets its own controls, art style and camera, so every story feels like a different game."}},{"do":{"ko":"내레이션 글자가 나타나면 걸어가며 글자 가까이 다가가 보세요.","en":"When narration text appears, walk up close to the words."},"wow":{"ko":"글자가 UI 위가 아니라 3D 공간 안에 떠서 장면에 반응해요. 읽는 일이 탐험의 일부가 돼요.","en":"The words float in 3D space, not on a UI overlay, and react to the scene. Reading becomes part of exploring."}}],"make":[{"ko":"반복 작업 하나를 화면 한쪽은 작업, 다른 쪽은 그 보상을 상상하게 하는 분할 화면 프로토타입으로 그려 보세요.","en":"Sketch a split-screen prototype of one repetitive task: the work on one side, the imagined reward on the other."},{"ko":"안내 문구를 고정 라벨 대신 화면 속 물체 옆에 붙여, 스크롤하면 물체와 함께 움직이게 만들어 보세요.","en":"Attach a guidance label next to an object on screen instead of a fixed label, so it moves with the object as you scroll."}],"ask":{"ko":"두 손으로 다른 일을 할 때 어떤 감정이 들었고, 그 감정은 왜 생겼나요?","en":"What did you feel when your two hands did different things, and why?"}},"Odio":{"time":10,"setup":{"ko":"머리 추적 공간 음향을 느끼려면 AirPods가 필요해요. 무료로 체험할 수 있어요.","en":"You need AirPods to feel the head-tracked Spatial Audio; it is free to try."},"missions":[{"do":{"ko":"AirPods를 끼고 원형 믹싱 화면에서 소리 레이어 하나를 손가락으로 끌어 다른 방향에 놓아 보세요.","en":"With AirPods in, drag one sound layer on the circular mixing screen and drop it in another direction."},"wow":{"ko":"옮긴 쪽에서 소리가 들려요. 한국인 디자인 학생의 졸업작품에서 출발해 2~3주 만에 나온 '소리를 손으로 옮기는' 데모가 뿌리예요.","en":"The sound now comes from where you put it. Its roots are a Korean design student's graduation project and a move-sound-by-hand demo built in two to three weeks."}},{"do":{"ko":"사운드스케이프를 틀어 둔 채 고개를 천천히 왼쪽, 오른쪽으로 돌려 보세요.","en":"With a soundscape playing, turn your head slowly left and right."},"wow":{"ko":"헤드 트래킹 덕분에 고개를 돌려도 소리가 공간에 고정돼요. 폭포가 정말 그 자리에 있는 것처럼 들려요.","en":"Head tracking keeps the sound fixed in space as you turn, so a waterfall sounds like it is really there."}},{"do":{"ko":"소리 레이어를 바꾸면서 화면 애니메이션을 함께 지켜보세요.","en":"Change the sound layers while watching the on-screen animation."},"wow":{"ko":"애니메이션이 소리와 완벽히 동기화돼요. Apple은 이를 '한층 증폭된 시청각 경험'이라 평했어요.","en":"The animation is perfectly synced with the sound, which Apple called a heightened audiovisual experience."}}],"make":[{"ko":"AVAudioEnvironmentNode로 소리 하나를 배치하고, 화면 위 점을 드래그하면 소리 위치가 바뀌게 만들어 보세요.","en":"Place one sound with AVAudioEnvironmentNode and let dragging a dot on screen move where it plays from."},{"ko":"내 앱의 슬라이더 하나를 원형 화면 위 위치로 값을 정하는 공간 제스처로 바꿔 보세요.","en":"Replace one slider in your app with a spatial gesture where position on a circle sets the value."}],"ask":{"ko":"슬라이더 대신 소리를 직접 옮기는 방식이 왜 더 직관적으로 느껴졌나요?","en":"Why did moving sounds directly feel more intuitive than a slider?"}},"Pok Pok Playroom":{"time":15,"setup":{"ko":"구독형 앱이고, 2세에서 8세 사이 아이와 함께 해 보면 더 좋아요.","en":"It is a subscription app, and it is best tried alongside a child aged 2 to 8."},"missions":[{"do":{"ko":"놀이방 하나를 열고 아무 물건이나 콕콕 눌러 보세요.","en":"Open any playroom and poke at whatever objects you see."},"wow":{"ko":"누를 때마다 은은한 햅틱과 딱 맞춘 효과음이 와요. 아기 볼을 콕콕 찌르던 소리에서 이름을 딴, 부모가 아들을 위해 만든 장난감다워요.","en":"Every poke brings soft haptics and perfectly matched sound. It suits a toy parents built for their son, named after the sound of poking a baby's cheek."}},{"do":{"ko":"비행기 모드로 바꾸고 다른 놀이방을 열어 보세요.","en":"Turn on Airplane Mode and open a different playroom."},"wow":{"ko":"16개가 넘는 놀이방이 모두 오프라인으로 작동해요.","en":"All of its more than 16 playrooms work offline."}},{"do":{"ko":"10분쯤 논 뒤 점수, 광고, 알림이 한 번이라도 나왔는지 떠올려 보세요.","en":"After playing for about ten minutes, recall whether a score, ad or notification ever appeared."},"wow":{"ko":"승패도 점수도 광고도 없어요. 끝없이 놀 수 있지만 보상을 쫓게 만들지 않아요.","en":"No winning, no scores, no ads. You can play endlessly without being pushed to chase rewards."}},{"do":{"ko":"화면 어디에 글자가 있는지 찾아보세요.","en":"Look for anywhere on screen that has text."},"wow":{"ko":"글자 없는 인터페이스라 읽지 못하는 2~8세 아이도, 어느 나라 아이도 놀 수 있어요.","en":"The interface has no words, so children aged 2 to 8 who cannot read, in any country, can play."}}],"make":[{"ko":"SwiftUI 버튼 하나에 sensoryFeedback 햅틱과 짧은 효과음을 함께 붙여, 누르는 순간이 실물처럼 느껴지게 해 보세요.","en":"Add sensoryFeedback haptics and a short sound to one SwiftUI button so pressing it feels physical."},{"ko":"내 앱의 한 화면에서 글자를 모두 지우고 그림과 움직임만으로 쓸 수 있는지 시험해 보세요.","en":"Remove all text from one screen of your app and test whether it works with images and motion alone."}],"ask":{"ko":"점수나 보상이 없는데도 계속 누르고 싶었던 이유는 무엇이었나요?","en":"With no score or reward, why did you keep wanting to tap?"}},"Be My Eyes":{"time":15,"setup":{"ko":"무료예요. 시각장애 사용자 흐름을 체험하려면 VoiceOver를 켤 준비를 해 두세요.","en":"It is free; be ready to turn on VoiceOver to try the blind user flow."},"missions":[{"do":{"ko":"봉사자로 가입해 언제든 도움 요청 전화를 받을 수 있는 상태가 되어 보세요.","en":"Sign up as a volunteer so you are ready to receive a call for help at any time."},"wow":{"ko":"시각장애 사용자 약 112만 명에 봉사자는 1,140만 명이 넘어요. 1명당 10명꼴이라 같은 언어, 맞는 시간대의 봉사자에게 연결돼요.","en":"About 1.12 million blind users are backed by over 11.4 million volunteers, ten per user, so calls reach someone with the same language and time zone."}},{"do":{"ko":"Be My AI로 책상 위 물건 사진을 찍고, 이어서 '이건 무슨 색이야?'처럼 후속 질문을 해 보세요.","en":"Take a photo of something on your desk with Be My AI, then ask a follow-up like what color is this."},"wow":{"ko":"사진 한 장으로 끝나지 않고 자연어로 계속 물을 수 있어요. AI가 답하지 못하면 사람 봉사자 연결을 제안해요.","en":"It does not stop at one photo; you can keep asking in plain language, and if the AI cannot answer it offers a human volunteer."}},{"do":{"ko":"VoiceOver를 켜고 앱의 첫 화면을 손가락으로 훑어 보세요.","en":"Turn on VoiceOver and sweep your finger across the app's first screen."},"wow":{"ko":"VoiceOver를 최우선으로 설계했어요. 시각장애 사용자에게는 봉사자에게 전화하는 큰 동작 하나만 내세워요.","en":"It is designed VoiceOver-first, and blind users are offered one big action: call a volunteer."}}],"make":[{"ko":"내 앱의 핵심 화면을 VoiceOver로 써 보고, 한 손가락으로 찾기 쉬운 큰 버튼 하나만 남긴 버전을 만들어 보세요.","en":"Use your app's key screen with VoiceOver, then build a version with only one large, easy-to-find button."},{"ko":"역할이 다른 두 사용자가 있다면, 각 역할에게 핵심 버튼 하나만 보여 주는 첫 화면 두 개를 그려 보세요.","en":"If your app has two kinds of users, sketch two first screens that each show one core button for that role."}],"ask":{"ko":"사용자보다 봉사자가 10배 많다는 사실이 앱 경험을 어떻게 바꿨을까요?","en":"How does having ten times more volunteers than users change the experience?"}},"League of Legends: Wild Rift":{"time":30,"setup":{"ko":"무료이지만 한 경기가 15~20분 걸리니 끊기지 않을 시간을 확보하세요.","en":"It is free, but a match takes 15 to 20 minutes, so set aside uninterrupted time."},"missions":[{"do":{"ko":"한 경기를 시작해 끝날 때까지 시간을 재 보세요.","en":"Start a match and time it to the end."},"wow":{"ko":"'롤은 폰으로 옮길 수 없다'던 라이엇이 Unity로 전부 다시 만들었어요. 작은 맵과 빠른 골드로 45분 경기를 15~20분으로 줄였어요.","en":"Riot, which once said LoL could not go mobile, rebuilt it in Unity. A smaller map and faster gold shrink a 45-minute match to 15 to 20."}},{"do":{"ko":"스킬 버튼을 누른 채 드래그해서 방향을 정하고 놓아 보세요.","en":"Press a skill button, drag to aim, then release."},"wow":{"ko":"마우스 클릭을 드래그 조준으로 바꿔 터치스크린에서도 스킬을 정확히 겨눌 수 있어요.","en":"Mouse clicks became drag-to-aim, so you can target skills precisely on a touchscreen."}},{"do":{"ko":"처음엔 겨누지 말고 공격 버튼만 눌러 보고, 그다음엔 직접 대상을 골라 보세요.","en":"First just press attack without aiming, then try picking the target yourself."},"wow":{"ko":"자동 타겟팅이 초보의 공격을 돕고, 숙련자는 여전히 수동으로 대상을 고를 수 있어요.","en":"Auto-targeting helps beginners land attacks, while experienced players can still choose targets manually."}},{"do":{"ko":"설정에서 카메라 관련 옵션을 바꾼 뒤 한 판 해 보세요.","en":"Change the camera options in settings, then play a match."},"wow":{"ko":"모바일 전용 카메라 설정으로 추적 방식을 조절해 작은 화면의 시야 한계를 보완해요.","en":"Mobile-only camera settings adjust how the camera follows you to make up for a small screen's view."}}],"make":[{"ko":"내 앱의 탭 두 번짜리 동작을 버튼을 누른 채 드래그해 방향까지 정하는 한 동작으로 합쳐 보세요.","en":"Merge a two-tap action in your app into one press-and-drag gesture that also sets direction."},{"ko":"내 앱의 가장 긴 작업을 절반 시간 안에 끝내려면 무엇을 줄일지 세 가지를 적어 보세요.","en":"Write down three things you would cut to finish your app's longest task in half the time."}],"ask":{"ko":"45분 게임을 20분 안으로 줄였는데도 롤처럼 느껴진 이유는 무엇이었나요?","en":"Why did it still feel like LoL after a 45-minute game was cut to under 20?"}},"Song of Bloom":{"time":20,"setup":{"ko":"3,300원 유료 게임이고, 충전 케이블을 가까이 두세요.","en":"It is a paid game (₩3,300); keep your charging cable nearby."},"missions":[{"do":{"ko":"장면을 몇 개 지나며 각 장면이 어떤 재료로 만들어졌는지 가까이 들여다보세요.","en":"Move through a few scenes and look closely at what each one is made of."},"wow":{"ko":"1인 개발자가 18개 장면을 점토 애니메이션, 뜨개질, 스케치, 조각 등 전부 다른 기법으로 손수 만들어서 장면마다 다른 작품 같아요.","en":"One developer handmade all 18 scenes in different techniques, from clay animation and knitting to sketches and sculpture, so each feels like a new artwork."}},{"do":{"ko":"막힌 퍼즐에서는 화면 밖, 기기 자체로 할 수 있는 행동을 떠올려 보세요. 충전 케이블을 꽂아 보는 것도 방법이에요.","en":"When a puzzle stumps you, think of what you can do with the device itself, off screen. Plugging in the charging cable is one idea."},"wow":{"ko":"풀이가 제4의 벽을 넘어 기기를 써요. Apple도 일부 퍼즐이 충전 케이블을 꽂는 것 같은 행동을 요구한다고 말했어요.","en":"Solutions break the fourth wall and use the device. Apple noted some puzzles ask for things like plugging in a charging cable."}},{"do":{"ko":"한 퍼즐에서 막히면 다른 갈래의 장면으로 넘어가 보세요.","en":"When you get stuck, move on to a scene on another branch."},"wow":{"ko":"도전 과제가 가지처럼 뻗은 비선형 구조라 한 곳에서 막혀도 다른 곳으로 진행할 수 있어요.","en":"Challenges branch out non-linearly, so being stuck in one place never stops you elsewhere."}},{"do":{"ko":"화면이 깨지거나 이상해 보이는 순간이 오면 멈추고 살펴보세요.","en":"When the screen looks broken or strange, stop and look closely."},"wow":{"ko":"개발자가 자기 코딩 오류를 일부러 디자인 재료로 써서 만든 글리치 질감이에요.","en":"That glitchy texture is the developer's own coding errors, used on purpose as design material."}}],"make":[{"ko":"UIDevice 배터리 상태 알림으로 충전 케이블을 꽂는 순간 화면이 바뀌는 숨은 인터랙션을 만들어 보세요.","en":"Use UIDevice battery state notifications to build a hidden interaction where plugging in the cable changes the screen."},{"ko":"내 앱 화면 하나의 배경을 직접 그리거나 만든 손작업 재료를 찍은 사진으로 바꿔 보세요.","en":"Replace one screen's background with a photo of something you drew or crafted by hand."}],"ask":{"ko":"케이블을 꽂는 게 답이라는 걸 알았을 때 왜 놀라웠나요?","en":"Why was it surprising to learn that plugging in a cable was the answer?"}},"Sleep Cycle":{"time":10,"setup":{"ko":"밤새 머리맡에 둘 폰이 필요하고, 첫 결과는 다음 날 아침에 볼 수 있어요.","en":"You need to leave your phone by your bed overnight, and the first results arrive the next morning."},"missions":[{"do":{"ko":"손목에 아무것도 차지 말고, 폰을 머리맡에 둔 채 수면 추적을 켜고 하룻밤 자 보세요.","en":"Wear nothing on your wrist, put your phone by your bed with tracking on, and sleep one night."},"wow":{"ko":"웨어러블 없이 폰 마이크의 특허받은 소리 분석이나 가속도계만으로 밤새 수면 데이터를 모아요.","en":"With no wearable, it collects sleep data all night using only patented sound analysis through the phone's mic, or the accelerometer."}},{"do":{"ko":"스마트 알람을 켜고 기상 시간을 정한 뒤, 다음 날 실제로 알람이 울린 시각을 확인해 보세요.","en":"Turn on the smart alarm with a wake-up time, then check the next day when it actually rang."},"wow":{"ko":"정한 시간 전 일정 구간 안에서 가장 얕은 수면 단계에 깨워 줘요. 앱의 핵심 가치가 알람 하나에 담겨 있어요.","en":"It wakes you during your lightest sleep within a window before your set time. The app's core value lives in one alarm."}},{"do":{"ko":"아침에 결과 화면에서 밤사이 감지된 소리 기록을 찾아보세요.","en":"In the morning, look for the record of sounds detected overnight."},"wow":{"ko":"코골이나 기침 같은 야간 소리를 감지해 기록해요. 일부 기능은 프리미엄 구독으로 열려요.","en":"It detects and logs night sounds like snoring and coughing; some of these features need Premium."}}],"make":[{"ko":"AVAudioRecorder 미터링으로 주변 소리 크기를 1분마다 기록해 그래프로 보여 주는 프로토타입을 만들어 보세요.","en":"Prototype logging ambient loudness every minute with AVAudioRecorder metering and showing it as a graph."},{"ko":"내 앱 알림 하나를 정해진 시각이 아니라 일정 구간 안에서 가장 알맞은 순간에 보내는 규칙으로 바꿔 보세요.","en":"Change one notification in your app to fire at the best moment within a window, not at a fixed time."}],"ask":{"ko":"아무것도 차지 않았는데 수면 기록이 나왔을 때 그 결과를 믿게 만든 것은 무엇이었나요?","en":"When a sleep record appeared without any wearable, what made you trust it?"}},"Obsidian":{"time":15,"setup":null,"missions":[{"do":{"ko":"노트를 하나 쓴 뒤 파일 앱에서 볼트 폴더를 찾아 열어 보세요.","en":"Write a note, then find and open the vault folder in the Files app."},"wow":{"ko":"노트가 평범한 마크다운 파일로 그대로 있어요. 앱이 사라져도 데이터가 남는 'file over app' 구조예요.","en":"Your note sits there as a plain Markdown file. It is file over app: the data outlives the app."}},{"do":{"ko":"비행기 모드로 바꾸고 노트를 열어 고쳐 보세요.","en":"Turn on Airplane Mode, then open and edit a note."},"wow":{"ko":"로컬 퍼스트라 오프라인에서도 그대로 빨라요.","en":"It is local-first, so it stays fast offline."}},{"do":{"ko":"노트 두 개를 [[위키링크]]로 서로 이은 뒤 그래프 뷰를 열어 보세요.","en":"Link two notes to each other with [[wikilinks]], then open the graph view."},"wow":{"ko":"폴더 계층 대신 노트들이 점과 선의 네트워크로 나타나요.","en":"Instead of a folder hierarchy, your notes appear as a network of dots and lines."}}],"make":[{"ko":"내 앱 데이터를 사람이 읽을 수 있는 마크다운 파일로 저장하고, 파일 앱에서 보이게 설정해 보세요.","en":"Save your app's data as human-readable Markdown files and make them visible in the Files app."},{"ko":"텍스트 속 [[이름]]을 찾아 다른 항목으로 이동하는 링크로 바꿔 주는 작은 파서를 만들어 보세요.","en":"Build a tiny parser that turns [[name]] in text into a link to another item."}],"ask":{"ko":"노트가 내 파일로 남아 있다는 걸 봤을 때 앱을 대하는 마음이 어떻게 달라졌나요?","en":"Seeing your notes as your own files, how did your feeling about the app change?"}},"Claude":{"time":15,"setup":null,"missions":[{"do":{"ko":"간단한 계산기처럼 작은 인터랙티브 결과물을 만들어 달라고 요청해 보세요.","en":"Ask it to make a small interactive result, such as a simple calculator."},"wow":{"ko":"결과물이 대화와 분리된 아티팩트 창에 미리 보여서 채팅 스크롤 속에 묻히지 않아요.","en":"The result previews in a separate artifact window, so it does not get buried in the chat scroll."}},{"do":{"ko":"카메라로 종이 문서를 찍어 올리고 요약해 달라고 해 보세요.","en":"Photograph a paper document with the camera and ask for a summary."},"wow":{"ko":"타이핑 없이 사진이나 파일만으로 분석이 시작돼요. 모바일 입력이 키보드에 묶이지 않아요.","en":"Analysis starts from a photo or file with no typing. Mobile input is not limited to the keyboard."}},{"do":{"ko":"긴 설명을 요청하고 답이 스트리밍되는 동안 위아래로 훑어보세요.","en":"Ask for a long explanation and skim up and down while it streams."},"wow":{"ko":"제목, 목록, 코드 블록 위계로 그려져 작은 화면에서도 긴 답을 훑어 읽을 수 있어요.","en":"It renders with headings, lists and code blocks, so a long answer stays skimmable on a small screen."}},{"do":{"ko":"폰에서 대화를 시작한 뒤 웹이나 데스크톱에서 같은 대화를 열어 보세요.","en":"Start a conversation on your phone, then open it on the web or desktop."},"wow":{"ko":"대화가 동기화되어 폰에서 시작한 작업을 다른 기기에서 바로 이어 가요.","en":"Conversations sync, so work started on the phone continues on another device."}}],"make":[{"ko":"내 앱의 긴 결과물 하나를 본문 스크롤과 분리된 시트로 띄워 따로 볼 수 있게 만들어 보세요.","en":"Show one long output in your app in a sheet separate from the main scroll."},{"ko":"긴 텍스트 응답을 제목, 목록, 본문 스타일로 나눠 렌더링하고 통짜 텍스트와 훑어보기 쉬운지 비교해 보세요.","en":"Render a long text response as headings, lists and body, and compare how skimmable it is against plain text."}],"ask":{"ko":"결과물이 대화와 따로 떠 있을 때 무엇이 더 편해졌나요?","en":"What got easier when the result floated apart from the conversation?"}},"배달의민족":{"time":10,"setup":{"ko":"무료예요. 주문하지 않고 둘러보기만 해도 충분해요.","en":"It is free, and browsing without ordering is enough."},"missions":[{"do":{"ko":"앱 곳곳의 배너와 문구를 보며, 로고를 손으로 가린 채 배민인지 알아볼 수 있는지 해 보세요.","en":"Look at banners and copy around the app and see if you can tell it is Baemin with the logo covered."},"wow":{"ko":"앱 UI와 프로모션 전반에 자체 서체를 일관되게 써서, 로고 없이 글자체만 봐도 배민임을 알아봐요.","en":"Its own typefaces run through the UI and promotions, so the lettering alone, without a logo, says Baemin."}},{"do":{"ko":"프로모션 배너와 푸시 알림 문구를 소리 내 읽어 보세요.","en":"Read the promotion banners and push notification copy out loud."},"wow":{"ko":"B급 유머와 말장난 카피 덕분에 기능적인 주문 앱에서 캐릭터 있는 목소리가 들려요.","en":"Tongue-in-cheek humor and puns give a functional ordering app a voice with character."}},{"do":{"ko":"앱에서 본 서체의 이름을 확인하고, 무료로 받아 내 기기에 설치할 수 있는지 알아보세요.","en":"Find the name of a typeface you saw in the app and check whether you can download it free for your device."},"wow":{"ko":"한나체부터 을지로체까지 10종 넘는 전용 서체를 무료로 배포해요. 서체가 브랜드 자산이자 사회 기여가 됐어요.","en":"It gives away more than ten custom typefaces, from Hanna to Euljiro. The fonts are both a brand asset and a public good."}}],"make":[{"ko":"무료 배포된 배민 서체 하나를 내 앱 프로토타입의 제목에만 적용해 브랜드 인상이 어떻게 바뀌는지 비교해 보세요.","en":"Apply one of Baemin's free typefaces to just the titles of your prototype and compare how the brand feel changes."},{"ko":"내 앱의 딱딱한 버튼 문구나 알림 하나를 말장난이 들어간 문장으로 다시 써 보세요.","en":"Rewrite one stiff button label or notification in your app as a line with a pun."}],"ask":{"ko":"로고 없이도 배민이라고 알아본 순간, 무엇이 단서였나요?","en":"When you recognized Baemin without a logo, what was the clue?"}},"PowerWash Simulator":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"do":{"ko":"스크래치 모드로 바꾸고 손가락으로 화면 위 때를 직접 문질러 보세요.","en":"Switch to Scratch Mode and rub the grime off the screen with your finger."},"wow":{"ko":"1,700만 명이 한 원작은 노즐을 조준하는 게임인데, Apple Arcade판은 손끝으로 때를 직접 닦는 방식을 새로 만들었어요.","en":"The original, played by 17 million, is about aiming a nozzle; the Apple Arcade version invented wiping grime away with your fingertip."}},{"do":{"ko":"부품 하나를 끝까지 닦아 보세요.","en":"Clean one part all the way."},"wow":{"ko":"때가 즉시 사라지고 완료율이 실시간으로 오르다가, 부품이 끝나는 순간 '딩' 소리가 나요. 제한 시간도 실패도 없어요.","en":"Grime vanishes instantly, the completion rate climbs live, and a ding sounds when the part is done. No timer, no failure."}},{"do":{"ko":"거의 다 닦았는데 마지막 얼룩이 안 보일 때 스마트 작업 진행 목록을 열어 보세요.","en":"When you are nearly done but cannot spot the last dirt, open the smart job progress list."},"wow":{"ko":"남은 얼룩 위치를 알려 줘요. 마지막 1%를 찾아 헤매는 장르의 고질적 답답함을 Arcade판이 풀었어요.","en":"It shows where the remaining dirt is, fixing the genre's old frustration of hunting for the last 1 percent."}}],"make":[{"ko":"SwiftUI Canvas에 때 이미지를 깔고, 손가락으로 문지른 부분이 지워지며 완료율이 오르는 프로토타입을 만들어 보세요.","en":"Lay a grime image on a SwiftUI Canvas and prototype rubbing it away with a finger as a completion percentage rises."},{"ko":"내 앱의 작업 하나가 끝나는 순간에 짧은 효과음과 햅틱을 붙여 보세요.","en":"Add a short sound and haptic at the moment a task in your app is finished."}],"ask":{"ko":"그저 닦는 일인데 왜 계속 하고 싶었나요?","en":"It is just cleaning, so why did you want to keep going?"}},"Blue Prince":{"time":30,"setup":{"ko":"Mac 전용이고 32,000원 유료 게임이에요. 종이와 펜을 곁에 두면 좋아요.","en":"It runs only on Mac and costs ₩32,000; keep paper and a pen nearby."},"missions":[{"do":{"ko":"첫 문을 열고 나오는 평면도 3장 중 하나를 골라 방을 놓아 보세요.","en":"Open the first door and pick one of the three floor plans to place a room."},"wow":{"ko":"탐험하면서 저택 구조를 직접 지어요. 1인 개발자가 6개월짜리 프로토타입에 약 8년을 쏟은 메커니즘이에요.","en":"You build the mansion's layout as you explore. A solo developer spent about eight years on what began as a six-month prototype."}},{"do":{"ko":"걸음 수가 다 떨어질 때까지 하루를 보낸 뒤 다음 날을 시작해 보세요.","en":"Spend a day until your steps run out, then start the next day."},"wow":{"ko":"밤이 지나면 집이 초기화돼요. 남는 건 단서와 코드, 방이 어떻게 작동하는지에 대한 지식이에요.","en":"After the night the house resets. What stays is knowledge: clues, codes and how the rooms work."}},{"do":{"ko":"종이와 펜을 들고 편지, 그림, 방 이름에서 눈에 띄는 것을 적어 보세요.","en":"With paper and pen, write down anything that stands out in letters, paintings and room names."},"wow":{"ko":"단서가 곳곳에 흩어져 있어 저절로 노트를 쓰게 돼요. 46번 방이 목표지만 엔딩 뒤에도 메타 퍼즐이 이어져요.","en":"Clues are scattered everywhere, so you start taking notes. Room 46 is the goal, but meta puzzles continue after the ending."}}],"make":[{"ko":"내 앱의 화면 하나에서 다음 단계를 무작위 선택지 3개 중 고르게 하는 프로토타입을 만들어 보세요.","en":"Prototype a screen where the next step is chosen from three random options."},{"ko":"사용자가 실패해도 다음 시도에 남는 지식이나 기록 하나를 정해 화면에 보여 줘 보세요.","en":"Pick one piece of knowledge or record that survives a user's failure and show it on screen."}],"ask":{"ko":"집이 초기화되는데도 다음 날이 기다려진 이유는 무엇이었나요?","en":"The house resets, so why did you look forward to the next day?"}},"Consume Me":{"time":20,"setup":{"ko":"17,000원 유료 게임이고, 섭식 장애를 다루니 내 마음 상태를 살피며 해 보세요.","en":"It is a paid game (₩17,000) about eating disorders, so check in with how you feel as you play."},"missions":[{"do":{"ko":"칼로리 한도가 있는 접시 미니게임에서 음식을 테트리스처럼 끼워 맞춰 보세요.","en":"In the plate minigame with a calorie limit, fit the food together like Tetris."},"wow":{"ko":"개발자가 고교 시절 실제로 칼로리를 세던 경험이에요. 맞춰 넣는 손놀림이 음식을 통제하려는 불안을 그대로 느끼게 해요.","en":"It comes from the developer counting calories in high school. The fitting motion makes you feel the anxious urge to control food."}},{"do":{"ko":"하루 일정을 짤 때 숙제, 다이어트, 수면, 인간관계 중 하나를 일부러 포기해 보세요.","en":"When planning the day, deliberately give up one of homework, dieting, sleep or relationships."},"wow":{"ko":"에너지와 기분, 돈이 그 선택의 대가로 흔들려요. 주인공이 치르는 선택의 대가를 그대로 느껴요.","en":"Energy, mood and money shift as the price of that choice, so you feel the cost the protagonist pays."}},{"do":{"ko":"운동이나 화장 미니게임을 손가락으로 직접 해 보세요.","en":"Play the exercise or makeup minigame with your finger."},"wow":{"ko":"무거운 주제를 블랙 유머와 투박한 손그림으로 풀어 부담 없이 다가와요. 마우스 조작이 터치로 자연스럽게 옮겨졌어요.","en":"Dark humor and rough hand-drawn art make a heavy subject approachable, and the mouse controls moved naturally to touch."}}],"make":[{"ko":"내 앱의 숫자 목표 하나를 막대그래프 대신 칸에 블록을 끼워 넣는 작은 퍼즐로 표현해 보세요.","en":"Show one numeric goal in your app as a small puzzle of fitting blocks into a space instead of a bar."},{"ko":"하루를 몇 칸으로 나눠 활동을 배치하면 에너지 수치가 바뀌는 한 화면짜리 프로토타입을 만들어 보세요.","en":"Build a one-screen prototype where placing activities into slots of a day changes an energy value."}],"ask":{"ko":"재미있는 퍼즐인데 마음이 불편해진 순간이 있었다면, 그건 왜였나요?","en":"If a fun puzzle ever made you uneasy, why?"}},"Denim – Playlist Cover Maker":{"time":10,"setup":null,"missions":[{"do":{"ko":"커버를 하나 만들면서 화면을 스크롤하고 사진을 넣어 크롭해 보세요.","en":"Make a cover, scrolling through the screens and adding and cropping a photo."},"wow":{"ko":"커버 앱이 ADA 결선에 오른 이유가 손끝에 와요. 심사위원이 꼽은 부드러운 스크롤 전환, 메시 그래디언트, 지능형 크롭과 깊이 효과예요.","en":"You feel why a cover app made the ADA finals: the smooth scroll transitions, mesh gradients, intelligent cropping and depth effects the jury named."}},{"do":{"ko":"스타일을 고르고 제목만 입력한 뒤 결과를 보세요.","en":"Pick a style, type just a title, and look at the result."},"wow":{"ko":"빈 캔버스 없이 스타일 선택, 제목 입력, 미세 조정의 짧은 흐름만으로 앨범 재킷 같은 커버가 나와요.","en":"With no blank canvas, a short flow of style, title and fine-tuning produces a cover that looks like album art."}},{"do":{"ko":"쓰는 음악 서비스를 연결하고 실제 플레이리스트에 새 커버를 적용해 보세요.","en":"Connect the music service you use and apply the new cover to a real playlist."},"wow":{"ko":"Spotify, YouTube Music과 직접 연결되고 Apple Music도 지원해서, 앱 안에서 바로 적용돼요.","en":"It connects directly to Spotify and YouTube Music and supports Apple Music, so the cover is applied from inside the app."}}],"make":[{"ko":"SwiftUI MeshGradient로 3x3 점 배경을 만들고, 점 하나를 드래그하면 색이 흐르게 해 보세요.","en":"Build a 3x3 SwiftUI MeshGradient background and let dragging one point make the colors flow."},{"ko":"내 앱의 생성 기능 하나를 빈 화면 대신 스타일 선택, 제목 입력, 조정의 3단계로 바꿔 보세요.","en":"Turn one creation feature in your app from a blank screen into three steps: style, title, adjust."}],"ask":{"ko":"디자이너가 아닌데도 완성도 높은 결과가 나온 건 어떤 단계 덕분이었나요?","en":"Which step let a non-designer get a polished result?"}},"Play":{"time":10,"setup":{"ko":"App Store에서 내려가 직접 해 볼 수 없어요. 개발사가 공개한 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so you can only explore it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"개발사 트레일러나 스크린숏에서 프로토타입이 코드로 내보내지는 장면을 찾아보세요.","en":"In the developer's trailer or screenshots, find where a prototype is exported as code."},"wow":{"ko":"iPhone에서 만든 프로토타입이 실제 SwiftUI 코드가 되어 Xcode로 넘어가요. 디자인과 개발 사이 번역이 사라져요.","en":"A prototype made on iPhone becomes real SwiftUI code that moves into Xcode, removing the translation between design and development."}},{"do":{"ko":"트레일러에서 Mac과 iPhone 화면이 함께 보이는 장면이 있는지 찾아보세요.","en":"Look for any moment in the trailer where Mac and iPhone screens appear together."},"wow":{"ko":"Mac에서 고친 인터랙션이 실시간으로 동기화되어 곧바로 실제 기기에서 만져 볼 수 있었어요.","en":"Interactions edited on the Mac synced live, so you could touch them on a real device right away."}},{"do":{"ko":"스크린숏에서 화면 요소가 어떤 단위로 나뉘어 있는지 살펴보세요.","en":"In the screenshots, look at how the screen elements are broken into units."},"wow":{"ko":"정적인 벡터 목업이 아니라 스택, 모디파이어, 상태 같은 실제 SwiftUI 구조를 코드 없이 시각적으로 다뤘어요.","en":"It was not static vector mockups but real SwiftUI structure, stacks, modifiers and state, handled visually without code."}}],"make":[{"ko":"SwiftUI 프리뷰에서 버튼 하나의 상태를 바꿔 가며 실제 기기에서 바로 확인하는 작은 프로토타입을 만들어 보세요.","en":"Build a small SwiftUI prototype where you toggle one button's state in the preview and check it on a real device."},{"ko":"다음 디자인 시안을 정적 이미지 대신 SwiftUI 화면 하나로 만들어 개발에 그대로 넘겨 보세요.","en":"Make your next design mock as one SwiftUI screen instead of a static image and hand it straight to development."}],"ask":{"ko":"디자인이 곧 코드라는 점이 팀의 어떤 대화를 없애 줄까요?","en":"Which team conversations disappear when the design is already code?"}},"Skate City: New York":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"do":{"ko":"프로 스케이트 모드를 열고 한 번 길게 달려 보세요.","en":"Open Pro Skate mode and take one long run."},"wow":{"ko":"센트럴파크, 맨해튼, 브루클린을 재현한 뉴욕이 절차 생성으로 끝없이 이어져요. 고정된 루프가 아니라 반복되는 느낌이 적어요.","en":"A New York modeled on Central Park, Manhattan and Brooklyn goes on endlessly through procedural generation, not a fixed loop."}},{"do":{"ko":"화면 아래쪽 절반에서 왼쪽, 오른쪽 여러 방향으로 스와이프해 보세요.","en":"Swipe in different directions, left and right, on the lower half of the screen."},"wow":{"ko":"버튼 하나 없이 8방향 스와이프만으로 올리 계열과 놀리 계열 트릭이 나와요.","en":"With no buttons at all, eight-direction swipes produce ollie and nollie tricks."}},{"do":{"ko":"트릭을 하고 착지할 때 손에 전해지는 진동에 집중해 보세요.","en":"Focus on the vibration in your hands as you land a trick."},"wow":{"ko":"햅틱이 보드 접지와 착지에 맞춰 조율돼 있어요. 리뷰어들은 예상보다 훨씬 몰입감 있다고 평했어요.","en":"The haptics are tuned to the board's grip and landings, which reviewers called far more immersive than expected."}}],"make":[{"ko":"화면을 8방향 스와이프로 나눠 방향마다 다른 동작이 나오는 제스처 프로토타입을 만들어 보세요.","en":"Prototype a gesture area where each of eight swipe directions triggers a different action."},{"ko":"Core Haptics로 착지처럼 짧고 강한 진동 패턴을 만들어 내 앱의 완료 순간에 붙여 보세요.","en":"Build a short, strong landing-like pattern with Core Haptics and add it to a completion moment in your app."}],"ask":{"ko":"버튼이 하나도 없는데 조작이 깊게 느껴진 이유는 무엇이었나요?","en":"With no buttons at all, why did the controls feel deep?"}},"Control Ultimate Edition":{"time":30,"setup":{"ko":"A17 Pro 이상이나 M 시리즈 칩의 iPhone·iPad, 또는 Apple 실리콘 Mac이 필요하고 가격은 4.99달러예요.","en":"You need an iPhone or iPad with A17 Pro or an M-series chip, or an Apple silicon Mac; it costs $4.99."},"missions":[{"do":{"ko":"M3 이상 Mac이라면 그래픽 설정에서 레이 트레이싱을 켜고 올디스트 하우스를 둘러보세요.","en":"On an M3 or later Mac, turn on ray tracing in the graphics settings and look around the Oldest House."},"wow":{"ko":"Remedy의 Northlight 엔진으로 만든 콘솔 AAA 게임이 Mac에서 하드웨어 레이 트레이싱까지 켜고 돌아가요.","en":"A console AAA game built on Remedy's Northlight engine runs on a Mac with hardware ray tracing on."}},{"do":{"ko":"염동력으로 주변 물건을 집어 던져 벽과 기둥을 부숴 보세요.","en":"Use telekinesis to hurl nearby objects and smash walls and pillars."},"wow":{"ko":"촘촘한 파티클과 파괴 효과가 쏟아져요. Metal 성능을 보여 주는 장면이자 Apple이 인정한 물리 기반 전투예요.","en":"Dense particles and destruction pour out, a showcase of Metal and the physics-based combat Apple recognized."}},{"do":{"ko":"한 번 산 계정으로 Mac과 iPhone, iPad에서 각각 게임을 받아 보세요.","en":"With the account you bought it on, download the game on Mac, iPhone and iPad."},"wow":{"ko":"유니버설 구매라 한 번 사면 모든 기기에서 플레이하고 확장팩 둘도 들어 있어요. 터치 UI도 새로 만들었어요.","en":"It is a universal purchase, so one buy plays everywhere with both expansions included, and the touch UI was rebuilt."}}],"make":[{"ko":"SpriteKit으로 물체를 끌어 던지면 부딪혀 흩어지는 작은 물리 장면을 만들어 보세요.","en":"Build a small SpriteKit physics scene where objects you drag and throw collide and scatter."},{"ko":"내 앱이 iPhone, iPad, Mac 유니버설 구매가 된다면 기기마다 바꿔야 할 조작을 하나씩 적어 보세요.","en":"If your app became a universal purchase on iPhone, iPad and Mac, write down one control to change per device."}],"ask":{"ko":"폰이나 Mac에서 콘솔 게임이 돌아가는 걸 봤을 때 무엇이 가장 '진짜'처럼 느껴졌나요?","en":"Seeing a console game run on a phone or Mac, what felt most real?"}},"Tiimo":{"time":15,"setup":{"ko":"구독형 부분 유료 앱이고, Apple Watch가 있으면 손목에서도 확인해 볼 수 있어요.","en":"It is a freemium subscription app; an Apple Watch lets you try it on your wrist too."},"missions":[{"do":{"ko":"오늘 할 일 몇 개를 넣고 비주얼 타임라인을 열어 보세요.","en":"Add a few tasks for today and open the visual timeline."},"wow":{"ko":"하루가 색과 아이콘이 붙은 블록과 카운트다운으로 보여요. ADHD 청소년 연구에서 시작해 2025 iPhone 올해의 앱이 된 플래너의 핵심 화면이에요.","en":"Your day shows as colored, iconed blocks with countdowns, the core of a planner that grew from ADHD research into 2025 iPhone App of the Year."}},{"do":{"ko":"AI 코플래너에 머릿속 생각을 정리하지 않은 그대로 말하거나 입력해 보세요.","en":"Speak or type your thoughts into the AI co-planner exactly as they are, unsorted."},"wow":{"ko":"흐트러진 생각이 소요 시간이 붙은 계획으로 바뀌어요. 가장 어려운 '시작하기'를 덜어 줘요.","en":"Scattered thoughts turn into a plan with durations, easing the hardest step: getting started."}},{"do":{"ko":"할 일 하나를 시작한 뒤 앱을 닫고 잠금 화면이나 Apple Watch를 보세요.","en":"Start a task, close the app, and look at the Lock Screen or your Apple Watch."},"wow":{"ko":"Live Activity, 위젯, Watch로 앱을 열지 않아도 지금 할 일과 남은 시간이 계속 보여요.","en":"Through Live Activities, widgets and the Watch, the current task and time left stay visible without opening the app."}}],"make":[{"ko":"ActivityKit으로 남은 시간을 줄어드는 막대로 보여 주는 Live Activity 하나를 만들어 보세요.","en":"Build a Live Activity with ActivityKit that shows time left as a shrinking bar."},{"ko":"내 앱의 목록 화면 하나를 시간 길이만큼 높이가 다른 색 블록 타임라인으로 바꿔 보세요.","en":"Turn one list screen in your app into a timeline of colored blocks sized by duration."}],"ask":{"ko":"시간을 글자 대신 색 블록으로 봤을 때 무엇이 달라졌나요?","en":"What changed when you saw time as colored blocks instead of text?"}},"Rytmos":{"time":15,"setup":{"ko":"소리를 켜거나 헤드폰을 끼고 해 보세요.","en":"Play with sound on or headphones in."},"missions":[{"do":{"ko":"퍼즐 하나를 푼 뒤, 같은 퍼즐을 다른 경로로 다시 풀어 보세요.","en":"Solve a puzzle, then solve the same one again by a different path."},"wow":{"ko":"풀이 경로가 곧 악보라 다르게 풀면 다른 음악이 나와요. 글래스턴베리 무대에 섰던 밴드 출신 뮤지션들의 설계예요.","en":"The path is the score, so a different solution plays different music, designed by musicians from bands that played Glastonbury."}},{"do":{"ko":"소리를 켜고 경로 선을 하나씩 완성해 보세요.","en":"With sound on, complete the path lines one at a time."},"wow":{"ko":"선이 완성될 때마다 악기 트랙이 하나씩 더해져 풀이가 노래로 쌓여요.","en":"Each finished line adds an instrument track, so the solution builds into a song."}},{"do":{"ko":"레벨을 깬 뒤 열리는 잼 모드에서 악기를 마음대로 눌러 보세요.","en":"After clearing a level, play the instruments freely in the jam mode that unlocks."},"wow":{"ko":"퍼즐 규칙 없이 그 행성의 음악 전통에서 온 악기를 자유롭게 연주하게 해, 호기심에 보상을 줘요.","en":"With no puzzle rules, you play instruments from that planet's musical tradition, a reward for curiosity."}}],"make":[{"ko":"격자 위에 손가락으로 선을 그을 때 지나는 칸마다 다른 음이 나는 프로토타입을 AVAudioEngine으로 만들어 보세요.","en":"Build an AVAudioEngine prototype where each grid cell your finger passes through plays a different note."},{"ko":"내 앱의 진행 표시 하나를 단계가 끝날 때마다 소리 층이 더해지는 방식으로 바꿔 보세요.","en":"Change one progress indicator so each finished step adds a layer of sound."}],"ask":{"ko":"다른 경로가 다른 음악이 된다는 걸 알았을 때 플레이가 어떻게 달라졌나요?","en":"Once you knew a different path made different music, how did you play differently?"}},"Lies of P":{"time":30,"setup":{"ko":"Mac 전용이고 64,900원 유료 게임이에요.","en":"It runs only on Mac and costs ₩64,900."},"missions":[{"do":{"ko":"도시 크라트의 거리를 걸으며 조명과 텍스처를 가까이 들여다보세요.","en":"Walk the streets of the city of Krat and look closely at the lighting and textures."},"wow":{"ko":"게임스컴 2022 3관왕으로 한국 콘솔 게임 최초 기록을 세운 작품답게, 벨 에포크풍 폐허의 질감과 조명이 Apple 비주얼상의 이유가 됐어요.","en":"Fitting for the first Korean console game to win three Gamescom 2022 awards, its Belle Epoque ruins' textures and light earned Apple's visuals award."}},{"do":{"ko":"무기의 날과 손잡이를 바꿔 조립해 보세요.","en":"Swap and assemble a weapon's blade and handle."},"wow":{"ko":"날과 손잡이를 조합하는 시스템이 피노키오라는 주제를 게임 메커니즘과 연결해요.","en":"Combining blades and handles ties the Pinocchio theme to the game's mechanics."}},{"do":{"ko":"대화에서 거짓말 선택지가 나오면 일부러 거짓말을 골라 보세요.","en":"When a lie option appears in dialogue, choose to lie on purpose."},"wow":{"ko":"거짓말 대화 선택이 피노키오 이야기를 게임 규칙으로 만들어요.","en":"The lying dialogue choice turns the Pinocchio story into a game rule."}},{"do":{"ko":"그래픽 설정에서 MetalFX 업스케일링과 볼류메트릭 포그를 켜고 끄며 비교해 보세요.","en":"In the graphics settings, toggle MetalFX upscaling and volumetric fog and compare."},"wow":{"ko":"Mac에서 네이티브로 돌아가는 콘솔급 소울라이크라, 화질과 프레임 사이를 직접 조절할 수 있어요.","en":"It is a console-grade soulslike running natively on Mac, and you choose your own balance of image quality and frame rate."}}],"make":[{"ko":"내 앱의 아이템 하나를 두 부품을 조합해 만드는 방식으로 바꾼 프로토타입을 그려 보세요.","en":"Sketch a prototype where one item in your app is built by combining two parts."},{"ko":"내 앱의 대표 화면 하나에 시대 분위기를 정하고, 색과 서체를 그 시대에 맞춰 바꿔 보세요.","en":"Pick a historical era for one key screen in your app and change its colors and type to match."}],"ask":{"ko":"뻔한 스팀펑크 대신 벨 에포크를 고른 것이 분위기에 어떤 차이를 만들었나요?","en":"What did choosing Belle Epoque over familiar steampunk do to the mood?"}},"Loóna: Cozy Puzzle Games":{"time":15,"setup":{"ko":"Apple Vision Pro 전용이에요. 무료로 퍼즐 1개를 해 볼 수 있고, 더 하려면 월 구독이 필요해요.","en":"It runs only on Apple Vision Pro; one puzzle is free and more require a monthly subscription."},"missions":[{"do":{"ko":"내 공간에 떠 있는 디오라마 퍼즐을 마지막 조각까지 맞춰 보세요.","en":"Assemble the diorama puzzle floating in your space down to the last piece."},"wow":{"ko":"완성된 순간 장면이 움직이며 살아나요. MSQRD를 만든 네 명이 자기 앱을 RealityKit으로 처음부터 다시 만들어 발매일에 냈어요.","en":"The moment it is complete, the scene comes alive. The four MSQRD founders rebuilt their app from scratch in RealityKit for launch day."}},{"do":{"ko":"동반 캐릭터 루모에게 포옹이나 제스처를 해 보세요.","en":"Give the companion character Lumo a hug or a gesture."},"wow":{"ko":"AI 동반 캐릭터 루모가 내 몸짓에 반응해요.","en":"Lumo, the AI companion, responds to your gestures."}},{"do":{"ko":"조용한 곳에서 고개를 돌려 가며 주변 소리를 들어 보세요.","en":"In a quiet place, turn your head and listen to the sounds around you."},"wow":{"ko":"1,000개 넘는 공간 음향이 깔려 있고 제한 시간도 실패도 없어, 도전보다 차분함이 남아요.","en":"Over 1,000 spatial sounds and no timers or failure leave calm rather than challenge."}}],"make":[{"ko":"Reality Composer Pro로 조각 세 개를 모으면 애니메이션이 재생되는 작은 장면을 만들어 보세요.","en":"In Reality Composer Pro, build a small scene where collecting three pieces plays an animation."},{"ko":"내 앱의 완료 순간을 정지 화면 대신 짧게 움직이는 장면으로 바꿔 보세요.","en":"Replace your app's completion moment with a short moving scene instead of a still screen."}],"ask":{"ko":"퍼즐이 완성된 뒤 장면이 살아날 때 왜 보상처럼 느껴졌나요?","en":"Why did the scene coming alive feel like a reward?"}},"Chantlings":{"time":10,"setup":{"ko":"4,400원 유료 앱이고, 소리 내 노래할 수 있는 조용한 곳이 필요해요.","en":"It is a paid app (₩4,400), and you need a quiet place where you can sing out loud."},"missions":[{"do":{"ko":"화면을 만지지 말고 '아' 소리로 길게 노래하면서 음을 올렸다 내려 보세요.","en":"Without touching the screen, sing a long \"ah\" and slide the pitch up and down."},"wow":{"ko":"숲속 생물들이 내 음정과 리듬, 모음 모양까지 따라 하며 화음을 넣어요. 그 애니메이션은 녹화가 아니라 실시간으로 생성돼요.","en":"The forest creatures follow your pitch, rhythm and vowel shape in harmony, and their animation is generated live, not prerecorded."}},{"do":{"ko":"노래에 자신 없는 사람에게 한 소절만 불러 보게 해 보세요.","en":"Ask someone who is shy about singing to sing just one line."},"wow":{"ko":"화음 엔진이 대선율을 즉흥으로 만들어 줘서, 노래를 배운 적 없는 사람도 음악적으로 들려요.","en":"The harmony engine improvises countermelodies, so even someone who never studied singing sounds musical."}},{"do":{"ko":"블루투스 스피커나 AirPlay로 소리를 내보낸 채 불러 보세요.","en":"Sing with the sound going out to a Bluetooth speaker or AirPlay."},"wow":{"ko":"실시간 마이크 앱에서 까다로운 하울링과 지연을 처리해요.","en":"It handles feedback and latency, the hard part of any live-mic music app."}}],"make":[{"ko":"AVAudioEngine 입력 탭으로 마이크 음량을 읽어, 소리가 클수록 캐릭터 입이 크게 벌어지는 프로토타입을 만들어 보세요.","en":"Read mic level with an AVAudioEngine input tap and prototype a character whose mouth opens wider as you get louder."},{"ko":"내 앱 버튼 하나를 소리를 내면 눌리는 음성 트리거로 바꿔 보세요.","en":"Replace one button in your app with a voice trigger that fires when you make a sound."}],"ask":{"ko":"내 목소리가 합창이 됐을 때 노래하는 부담이 왜 줄었나요?","en":"Why did singing feel less scary once your voice became a choir?"}},"Sago Mini First Words":{"time":15,"setup":{"ko":"만 5세 이하 아이와 함께 해 보면 좋고, 따라 말하기를 위해 마이크를 쓸 수 있어야 해요.","en":"It is best tried with a child aged five or under, and the microphone needs to be available for speaking practice."},"missions":[{"do":{"ko":"다른 아이가 단어를 말하는 영상을 본 뒤, 아이와 함께 그 단어를 소리 내 따라 해 보세요.","en":"Watch the video of another child saying a word, then say it out loud together with your child."},"wow":{"ko":"언어치료 기법인 또래 비디오 모델링을 그대로 옮겼어요. 앱이 따라 말하는 소리를 듣고 학습 단계를 조정해요.","en":"It brings the speech therapy technique of peer video modeling straight into an app, listening to the repeated word to adjust the level."}},{"do":{"ko":"몇 단어를 지나며 같은 단어가 다른 상황에서 다시 나오는지 살펴보세요.","en":"Go through several words and watch whether the same word comes back in a different situation."},"wow":{"ko":"단어를 여러 사회적 상황과 맥락에서 연습하게 해 어휘와 사회·정서 능력을 함께 길러요.","en":"Words are practiced across social situations and contexts, building vocabulary and social-emotional skills together."}},{"do":{"ko":"화면에서 글자를 읽어야만 하는 곳이 있는지 찾아보세요.","en":"Look for anywhere on screen that requires reading."},"wow":{"ko":"읽기 없이 큰 터치 영역과 친근한 캐릭터만으로 만 5세 이하 아이가 쓸 수 있어요.","en":"No reading is needed; large touch targets and friendly characters let children five and under use it."}}],"make":[{"ko":"내 앱의 안내 화면 하나를 설명 글 대신 다른 사람이 직접 해 보이는 짧은 영상으로 바꿔 보세요.","en":"Replace one instruction screen in your app with a short video of someone demonstrating it."},{"ko":"Speech 프레임워크로 단어 하나를 말하면 인식되어 다음 화면으로 넘어가는 프로토타입을 만들어 보세요.","en":"Use the Speech framework to prototype saying one word to move to the next screen."}],"ask":{"ko":"다른 아이의 영상을 보고 따라 하는 방식이 왜 아이에게 잘 통할까요?","en":"Why does copying a video of another child work so well for kids?"}},"Camo Studio":{"time":10,"setup":{"ko":"App Store에서 내려가 직접 해 볼 수 없어요. 개발사가 공개한 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so you can only explore it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"개발사 트레일러나 스크린숏에서 iPhone이 컴퓨터의 웹캠으로 쓰이는 장면을 찾아보세요.","en":"In the developer's trailer or screenshots, find the iPhone being used as a computer webcam."},"wow":{"ko":"2020년에 이미 아이폰을 웹캠으로 썼어요. 2년 뒤 Apple이 같은 기능을 Continuity Camera로 OS에 넣었고, 개발사는 2026년 Apple을 고소했어요.","en":"It turned the iPhone into a webcam in 2020; two years later Apple built the same into the OS as Continuity Camera, and in 2026 the developer sued Apple."}},{"do":{"ko":"스튜디오 제어판 스크린숏에서 조절 항목이 몇 개인지 세어 보세요.","en":"In screenshots of the studio control panel, count how many settings there are."},"wow":{"ko":"렌즈, 노출, 화이트밸런스, 인물 흐림, LUT까지 화상회의 앱이 숨겨 둔 카메라 설정을 꺼내 줘요.","en":"Lens, exposure, white balance, portrait blur and LUTs: it exposes camera settings video call apps hide."}},{"do":{"ko":"장면과 오버레이 화면을 보며 어떤 앱에서 쓰이는지 확인해 보세요.","en":"Look at the scenes and overlays and check which apps they are used in."},"wow":{"ko":"한 번 만든 레이아웃을 Zoom, Teams, FaceTime, OBS 등 40개 넘는 앱에서 그대로 써요.","en":"A layout set up once works in more than 40 apps, including Zoom, Teams, FaceTime and OBS."}}],"make":[{"ko":"AVCaptureDevice로 노출과 화이트밸런스를 슬라이더로 조절하는 카메라 프리뷰를 만들어 보세요.","en":"Build a camera preview with sliders for exposure and white balance using AVCaptureDevice."},{"ko":"Apple 기본 기능이 내 앱 기능을 대신하게 된다면 그 위에 얹을 수 있는 한 겹을 적어 보세요.","en":"If an Apple built-in feature replaced yours, write down one layer you could add on top of it."}],"ask":{"ko":"Apple이 같은 기능을 OS에 넣은 뒤에도 남을 수 있는 가치는 무엇일까요?","en":"What value can survive after Apple builds the same feature into the OS?"}},"Chineasy":{"time":10,"setup":null,"missions":[{"do":{"ko":"첫 레슨에서 火나 山 같은 한자를 그림과 함께 익힌 뒤, 그림 없이 다시 떠올려 보세요.","en":"Learn characters like 火 or 山 with their pictures in a first lesson, then recall them without the pictures."},"wow":{"ko":"한자가 모닥불, 산봉우리 그림으로 기억에 남아요. 조회수 600만 회를 넘긴 ShaoLan의 TED 강연에서 시작한 방법이에요.","en":"The characters stick as a campfire and mountain peaks. The method began with ShaoLan's TED talk, viewed over 6 million times."}},{"do":{"ko":"기본 한자 몇 개를 익힌 뒤, 그것들이 합쳐진 한자가 나오면 뜻을 먼저 맞혀 보세요.","en":"After learning a few basic characters, guess the meaning of a character built from them before it is shown."},"wow":{"ko":"부품을 알면 복합 한자와 단어의 뜻이 조립되듯 보여요.","en":"Once you know the parts, compound characters and words read like assemblies."}}],"make":[{"ko":"내 앱의 어려운 용어 세 개를 각각 모양을 닮은 그림과 짝지은 학습 카드로 만들어 보세요.","en":"Turn three hard terms in your app into learning cards, each paired with a picture that resembles it."},{"ko":"작은 요소 두 개를 끌어다 합치면 새 요소가 나오는 조합 화면 프로토타입을 만들어 보세요.","en":"Prototype a screen where dragging two small pieces together creates a new one."}],"ask":{"ko":"그림이 사라진 뒤에도 한자를 기억할 수 있었던 이유는 무엇이었나요?","en":"Why could you still remember the character after the picture was gone?"}},"Rebel Girls":{"time":15,"setup":{"ko":"이야기를 들으려면 소리가 필요하고, 아이와 함께 들으면 더 좋아요.","en":"You need sound for the stories, and listening with a child is even better."},"missions":[{"do":{"ko":"이야기 하나를 골라 소리를 켜고 끝까지 들어 보세요.","en":"Pick a story, turn the sound on, and listen to the end."},"wow":{"ko":"책 속 300단어 소개글이 성우 낭독과 사운드 디자인을 입은 약 2,000단어 오디오 드라마가 됐어요. 첫 코드부터 출시까지 5개월 걸렸어요.","en":"A 300-word book profile became a roughly 2,000-word audio drama with voice actors and sound design, five months from first code to launch."}},{"do":{"ko":"재생 화면의 버튼과 아이콘을 가까이 들여다보세요.","en":"Look closely at the buttons and icons on the player screen."},"wow":{"ko":"버튼과 아이콘까지 손으로 그려 UI 전체가 책처럼 느껴져요. 이야기마다 50여 개국 일러스트레이터의 그림이 붙어요.","en":"Even the buttons and icons are hand-drawn, so the whole UI feels like a book, with art from illustrators in about 50 countries."}},{"do":{"ko":"이야기를 오프라인으로 저장한 뒤 비행기 모드에서 재생해 보세요.","en":"Save a story for offline use, then play it in Airplane Mode."},"wow":{"ko":"구독 없이 무료이고, 여행용 오프라인 다운로드를 지원해요.","en":"It is free with no subscription and supports offline downloads for travel."}}],"make":[{"ko":"내 앱 버튼 아이콘 하나를 손으로 그려 스캔한 이미지로 바꾸고 인상이 어떻게 달라지는지 비교해 보세요.","en":"Replace one button icon with a hand-drawn, scanned image and compare how the feel changes."},{"ko":"내 앱의 짧은 안내 글 하나를 효과음을 곁들인 30초 음성으로 녹음해 재생해 보세요.","en":"Record one short piece of guidance text in your app as 30 seconds of voice with sound effects and play it."}],"ask":{"ko":"같은 이야기를 읽을 때와 들을 때 무엇이 달랐나요?","en":"What was different between reading and hearing the same story?"}},"Focus Noodles":{"time":10,"setup":{"ko":"6,600원 유료 앱이에요.","en":"It is a paid app (₩6,600)."},"missions":[{"do":{"ko":"짧은 세션을 정하고 폰을 화면이 아래로 가게 엎어 두세요. 중간에 한 번 집어 들어 보세요.","en":"Set a short session and lay the phone face down. Pick it up once partway through."},"wow":{"ko":"엎으면 라면이 익기 시작하고, 들면 진동과 플래시, 소리가 울려요. 알림이 아니라 몸으로 지키는 약속이 돼요.","en":"Face down, the noodles start cooking; pick it up and it buzzes, flashes and sounds. It becomes a promise kept with your body, not a notification."}},{"do":{"ko":"세션 길이를 5분과 60분으로 바꿔 가며 완성되는 라면을 비교해 보세요.","en":"Compare the finished noodles at a 5-minute and a 60-minute session length."},"wow":{"ko":"5분이면 컵라면, 60분이면 문어가 올라간 고급 라면이 완성돼요.","en":"Five minutes makes cup noodles; sixty makes a deluxe bowl topped with an octopus."}},{"do":{"ko":"세션을 끝까지 마친 뒤 받은 동화 카드를 열어 보세요.","en":"Finish a session and open the fairy-tale card you receive."},"wow":{"ko":"무엇이 나올지 모르는 수집 카드가 작은 보상이 되어 다시 돌아오고 싶어져요.","en":"A collectible card you cannot predict is a small reward that makes you want to come back."}}],"make":[{"ko":"CMMotionManager로 폰이 엎어졌는지 감지해 타이머를 시작하고, 들면 멈추는 프로토타입을 만들어 보세요.","en":"Use CMMotionManager to start a timer when the phone is face down and stop it when lifted."},{"ko":"내 앱 타이머 하나를 진행률 숫자 대신 시간에 따라 익어 가는 음식 같은 은유 그림으로 바꿔 보세요.","en":"Replace one timer's percentage with a metaphor image, like food that cooks over time."}],"ask":{"ko":"폰을 엎어 두는 동작 하나가 왜 집중을 더 잘 지키게 했나요?","en":"Why did the simple act of turning the phone over protect your focus?"}},"Poolsuite FM":{"time":10,"setup":null,"missions":[{"do":{"ko":"채널 하나를 틀어 두고 앱의 창, 토글, 효과음을 이것저것 만져 보세요.","en":"Put a channel on and play with the app's windows, toggles and sound effects."},"wow":{"ko":"장난감 같은 레트로 무드예요. 광고 없는 무료 라디오인데 이 무드 하나로 선크림 브랜드를 만들고 NFT 2,500개를 40분 만에 팔았어요.","en":"It is a toy-like retro mood. An ad-free radio app built a sunscreen brand on it and sold out 2,500 NFTs in 40 minutes."}},{"do":{"ko":"검색하지 말고 채널만 바꿔 가며 분위기를 골라 보세요.","en":"Without searching, pick a mood just by switching channels."},"wow":{"ko":"알고리즘 대신 사람이 고른 채널이라 무엇을 들을지 고민할 필요가 없어요.","en":"The channels are hand-picked, not algorithmic, so there is no choosing fatigue."}}],"make":[{"ko":"내 앱 설정 화면 하나를 픽셀아트 창과 토글, 클릭 효과음이 있는 레트로 버전으로 만들어 보세요.","en":"Make a retro version of one settings screen with pixel-art windows, toggles and click sounds."},{"ko":"내 앱의 선택 화면을 검색 대신 분위기 채널 서너 개로 바꾼 프로토타입을 그려 보세요.","en":"Sketch a prototype that replaces search on a selection screen with three or four mood channels."}],"ask":{"ko":"기능보다 분위기가 먼저 느껴졌던 순간은 언제였나요?","en":"When did you feel the mood before the features?"}},"Brief":{"time":10,"setup":{"ko":"App Store에서 내려가 직접 해 볼 수 없어요. 개발사가 공개한 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so you can only explore it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"개발사 트레일러나 스크린숏에서 하루 기사 목록이 어디서 끝나는지 찾아보세요.","en":"In the developer's trailer or screenshots, find where the day's list of stories ends."},"wow":{"ko":"무한 스크롤 대신 하루 몇 개 기사로 끝나고, 모두가 같은 기사를 같은 순서로 봐요. 구글 iOS 개발자 두 명이 만든 설계예요.","en":"Instead of infinite scroll it ends after a few stories, and everyone sees the same stories in the same order, a design by two former Google iOS engineers."}},{"do":{"ko":"기사 화면 스크린숏에서 내용이 어떤 칸으로 나뉘어 있는지 보세요.","en":"In screenshots of a story, look at how the content is split into sections."},"wow":{"ko":"핵심 사실, 타임라인 맥락, 인용으로 압축돼서 다 읽고 나면 상황을 파악했다는 느낌으로 끝나요.","en":"It is condensed into key facts, timeline context and quotes, so you finish feeling caught up."}},{"do":{"ko":"스크린숏에서 관점(Perspectives) 섹션을 찾아 양쪽 목소리가 어떻게 놓였는지 보세요.","en":"Find the Perspectives section in the screenshots and see how the two sides are laid out."},"wow":{"ko":"논쟁적인 기사에 대해 좌우 진영의 주요 목소리를 나란히 보여 줘요.","en":"For contested stories, it sets the main voices from left and right side by side."}}],"make":[{"ko":"내 앱 피드 맨 끝에 '오늘은 여기까지'라는 끝 화면을 넣은 버전을 만들어 보세요.","en":"Build a version of your app's feed with an end screen that says that is all for today."},{"ko":"긴 글 하나를 핵심 사실, 타임라인, 인용 세 칸으로 나눈 카드 화면을 만들어 보세요.","en":"Make a card screen that splits one long article into key facts, timeline and quotes."}],"ask":{"ko":"피드에 끝이 있다는 것이 읽는 사람에게 어떤 안도감을 줄까요?","en":"What kind of relief does a feed with an ending give the reader?"}},"NaadSadhana":{"time":15,"setup":{"ko":"소리 내 노래할 수 있는 곳이 필요하고, 헤드폰이 있으면 더 좋아요.","en":"You need a place where you can sing out loud, ideally with headphones."},"missions":[{"do":{"ko":"헤드폰을 끼고 반주 없이 아무 선율이나 즉흥으로 불러 보세요.","en":"With headphones on, improvise any melody with no accompaniment."},"wow":{"ko":"앱이 노래를 듣고 Core ML로 27개 악기 반주를 실시간으로 만들어요. 고전 성악가이자 전직 엔지니어 한 사람이 혼자 만들었어요.","en":"The app listens and generates 27-instrument accompaniment live with Core ML, built alone by a classical vocalist and former engineer."}},{"do":{"ko":"노래하면서 일부러 음을 조금 틀리게 내 보세요.","en":"While singing, go slightly off pitch on purpose."},"wow":{"ko":"온디바이스 AI가 음정 정확도를 즉시 알려 줘요.","en":"On-device AI tells you your pitch accuracy instantly."}},{"do":{"ko":"디지털 탄푸라를 켜고 라가 하나를 골라 불러 보세요.","en":"Turn on the digital tanpura, pick a raga and sing."},"wow":{"ko":"라가와 음계 411개, 탈과 그루브 127개를 담아 인도 고전음악을 깊이 지원해요.","en":"With 411 ragas and scales and 127 talas and grooves, it supports Indian classical music in depth."}}],"make":[{"ko":"AVAudioEngine 입력으로 목소리 높이를 읽어 음정이 맞으면 초록, 틀리면 빨강으로 보여 주는 프로토타입을 만들어 보세요.","en":"Read vocal pitch from AVAudioEngine input and prototype a display that turns green on pitch and red off pitch."},{"ko":"내 앱의 연습 기능 하나에 사용자가 시작하면 배경 반주가 따라붙는 버전을 만들어 보세요.","en":"Build a version of one practice feature where a backing track joins in when the user starts."}],"ask":{"ko":"반주가 내 노래를 따라온다고 느꼈을 때 연습이 왜 공연처럼 느껴졌나요?","en":"When the accompaniment followed you, why did practice start to feel like a performance?"}},"Where Cards Fall":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"do":{"ko":"두 손가락을 벌려 카드 집을 세우고, 다시 오므려 무너뜨려 보세요.","en":"Spread two fingers to build a house of cards, then pinch to collapse it."},"wow":{"ko":"벌리면 서고 오므리면 무너져요. USC 학생 시절 프로토타입을 10년 붙든 이 제스처가 쉽게 무너지는 물건을 퍼즐 도구로 바꿔요.","en":"Spread and it stands, pinch and it falls. This gesture, nursed for a decade from a USC student prototype, turns something fragile into a puzzle tool."}},{"do":{"ko":"세운 카드 집을 계단이나 다리처럼 써서 다음 장소로 건너가 보세요.","en":"Use the house of cards you built as stairs or a bridge to reach the next spot."},"wow":{"ko":"카드 집이 계단, 다리, 발판이 돼요.","en":"The house of cards becomes stairs, bridges and platforms."}},{"do":{"ko":"레벨을 하나 끝낸 뒤 장면에서 무엇이 다시 세워졌는지 보세요.","en":"After finishing a level, look at what has been rebuilt in the scene."},"wow":{"ko":"대사 없이, 퍼즐을 풀수록 주인공의 기억이 다시 세워져요.","en":"Without dialogue, each solved puzzle rebuilds a memory of the protagonist."}}],"make":[{"ko":"SwiftUI MagnifyGesture로 두 손가락을 벌리면 카드 탑이 높아지고 오므리면 무너지는 프로토타입을 만들어 보세요.","en":"Use SwiftUI's MagnifyGesture to prototype a card tower that grows as you spread and collapses as you pinch."},{"ko":"내 앱에서 쉽게 사라지는 것 하나를 골라 그것을 도구로 쓰는 인터랙션을 종이에 그려 보세요.","en":"Pick something fleeting in your app and sketch an interaction that uses it as a tool."}],"ask":{"ko":"핀치 제스처가 카드 집을 세우는 데 왜 그렇게 잘 맞았나요?","en":"Why did the pinch gesture fit building a house of cards so well?"}},"Ulysses":{"time":15,"setup":{"ko":"구독형 앱이고, Mac이나 iPad가 있으면 동기화까지 확인해 볼 수 있어요.","en":"It is a subscription app; a Mac or iPad lets you test syncing too."},"missions":[{"do":{"ko":"새 글을 쓴 뒤 저장 버튼이나 파일 이름을 정하는 곳을 찾아보세요.","en":"Write a new piece, then look for a save button or a place to name the file."},"wow":{"ko":"파일을 관리할 필요 없이 모든 글이 라이브러리 한곳에 모여요. 그룹, 필터, 키워드로 정리하고 글만 쓰게 해요.","en":"There is no file to manage; every text gathers in one library, organized by groups, filters and keywords, so you just write."}},{"do":{"ko":"iPhone에서 쓰던 글을 Mac이나 iPad에서 열어 이어 써 보세요.","en":"Open a piece you started on iPhone on a Mac or iPad and keep writing."},"wow":{"ko":"iCloud 동기화로 기기를 오가며 긴 원고를 자연스럽게 이어 써요.","en":"iCloud sync lets you carry a long manuscript across devices seamlessly."}},{"do":{"ko":"구독 결제 화면의 문구를 읽으며 구독 이유를 어떻게 설명하는지 살펴보세요.","en":"Read the subscription screen copy and see how it explains why it charges a subscription."},"wow":{"ko":"구독 명분을 지속적인 업데이트와 지원을 위한 반복 수익이라고 설명해요. 2017년 전환 때는 기존 사용자에게 평생 50% 할인을 줬어요.","en":"It frames the subscription as recurring revenue for ongoing updates and support. At the 2017 switch, existing users got 50 percent off for life."}}],"make":[{"ko":"내 앱 저장 흐름에서 파일 이름 입력을 없애고 자동으로 라이브러리에 모이게 만든 프로토타입을 만들어 보세요.","en":"Prototype a save flow with no file naming, where everything gathers in a library automatically."},{"ko":"내 앱 가격 정책이 바뀐다고 가정하고, 기존 사용자에게 줄 혜택과 공지 문구를 세 문장으로 써 보세요.","en":"Imagine your app's pricing changes and write a three-sentence notice with the benefit for existing users."}],"ask":{"ko":"저장이나 파일을 신경 쓰지 않아도 됐을 때 글쓰기가 어떻게 달라졌나요?","en":"How did writing change when you never had to think about saving or files?"}},"Clear Todos":{"time":10,"setup":null,"missions":[{"do":{"ko":"화면을 아래로 당겨 새 항목을 만들고, 오른쪽으로 밀어 완료하고, 왼쪽으로 밀어 지워 보세요.","en":"Pull the screen down to add an item, swipe one right to complete it and swipe one left to delete it."},"wow":{"ko":"버튼이 거의 없는데 당기고 미는 손짓만으로 추가, 완료, 삭제가 다 돼요. 제스처마다 소리와 햅틱이 붙어 할 일을 지우는 손맛이 나요.","en":"There are almost no buttons, yet pulling and swiping handle add, complete and delete. Every gesture has its own sound and haptic, so clearing a task feels physical."}},{"do":{"ko":"항목 두 개 사이에 두 손가락을 대고 벌려 보세요.","en":"Put two fingers between two items and spread them apart."},"wow":{"ko":"목록이 벌어지며 그 사이에 새 항목이 끼워져요. 메뉴의 삽입 명령 대신 손가락 동작이 곧 명령이에요.","en":"The list opens up and a new item slots in between. The finger motion itself is the insert command, no menu needed."}},{"do":{"ko":"항목을 여러 개 만든 뒤 맨 위와 맨 아래 항목의 색을 비교해 보세요.","en":"Make several items, then compare the color of the top one with the bottom one."},"wow":{"ko":"위쪽 항목일수록 색이 진해서 글자 하나 없이 색만으로 우선순위가 읽혀요.","en":"Higher items are darker, so you read priority from color alone without a single label."}}],"make":[{"ko":"목록 화면 하나에 오른쪽 스와이프 완료를 넣고, 완료되는 순간 짧은 소리와 햅틱을 붙여 보세요.","en":"Add swipe-right-to-complete to one list screen and attach a short sound and haptic at the moment it completes."},{"ko":"두 행 사이에서 핀치를 벌리면 빈 행이 생기는 삽입 제스처를 프로토타입으로 만들어 보세요.","en":"Prototype an insert gesture where spreading a pinch between two rows opens an empty row."}],"ask":{"ko":"버튼이 거의 없는데도 어떻게 손이 먼저 쓰는 법을 알게 됐을까요?","en":"With almost no buttons, how did your hands figure out how to use it so quickly?"}},"Airtable":{"time":15,"setup":{"ko":"무료 계정이 필요하고, 데스크톱과 비교해 보려면 컴퓨터가 있으면 좋아요.","en":"You need a free account, and a computer helps if you want to compare with desktop."},"missions":[{"do":{"ko":"표 하나를 열고 뷰를 그리드에서 칸반, 캘린더, 갤러리로 차례로 바꿔 보세요.","en":"Open a table and switch its view from grid to kanban, calendar and gallery in turn."},"wow":{"ko":"같은 데이터가 표에서 카드 보드, 달력, 사진첩으로 바로 바뀌어요. 다시 입력한 건 하나도 없어요.","en":"The same data turns from a table into a card board, a calendar and a photo wall instantly, and you re-entered nothing."}},{"do":{"ko":"새 필드를 만들고 타입을 첨부, 체크박스, 링크 레코드로 바꿔 보세요.","en":"Create a new field and change its type to attachment, checkbox and linked record."},"wow":{"ko":"스프레드시트처럼 보이지만 칸마다 타입이 있어서 다른 표의 레코드까지 연결돼요. 코드 없이 관계형 데이터베이스를 만지는 셈이에요.","en":"It looks like a spreadsheet, but every field has a type and can link to records in another table. You are handling a relational database with no code."}},{"do":{"ko":"레코드 한 줄을 탭해 카드로 펼친 뒤, 같은 베이스를 컴퓨터에서도 열어 비교해 보세요.","en":"Tap a record to expand it into a card, then open the same base on a computer and compare."},"wow":{"ko":"모바일은 스키마 편집과 자동화 설정을 덜어 내고 조회, 입력, 간단한 편집에 집중해요. 무엇을 뺐는지가 그대로 설계로 보여요.","en":"Mobile drops schema editing and automation setup and focuses on viewing, entering and light editing. What was removed is the design."}}],"make":[{"ko":"데이터 배열 하나를 리스트, 카드, 캘린더 세 가지 뷰로 토글하는 SwiftUI 화면을 만들어 보세요.","en":"Build a SwiftUI screen that toggles one data array between list, card and calendar views."},{"ko":"리스트 행을 탭하면 모든 필드가 담긴 카드로 펼쳐지는 전환을 프로토타입으로 만들어 보세요.","en":"Prototype a transition where tapping a list row expands it into a card holding every field."}],"ask":{"ko":"같은 데이터를 다른 모양으로 보는 것만으로 왜 이해가 달라질까요?","en":"Why does seeing the same data in a different shape change how well you understand it?"}},"Perplexity":{"time":10,"setup":null,"missions":[{"do":{"ko":"최근 뉴스에 대해 질문한 뒤 답변 문장 속 번호 각주 하나를 탭해 보세요.","en":"Ask about a recent news story, then tap one of the numbered footnotes inside the answer."},"wow":{"ko":"답의 문장마다 출처 번호가 붙어 있고 상단에 출처 카드가 있어요. AI 답변을 그 자리에서 바로 검증할 수 있어요.","en":"Sentences carry source numbers and source cards sit on top, so you can check the AI's answer right where you read it."}},{"do":{"ko":"답변 아래 제안된 관련 질문 하나를 탭해 두세 번 더 파고들어 보세요.","en":"Tap one of the suggested related questions under the answer and keep digging two or three more times."},"wow":{"ko":"검색어를 다시 떠올리지 않아도 다음 질문이 미리 준비돼 있어서 검색이 대화가 돼요.","en":"The next question is already waiting, so you never have to think up a new query and search turns into a conversation."}},{"do":{"ko":"음성 입력으로 궁금한 걸 말로 물어보세요.","en":"Ask something out loud using voice input."},"wow":{"ko":"말 한마디가 출처 달린 요약 답변으로 돌아와요. 링크를 하나씩 눌러 보던 단계가 사라져요.","en":"One spoken question comes back as a sourced summary, and the step of opening links one by one is gone."}}],"make":[{"ko":"답변 텍스트에 [1] 같은 각주 번호를 넣고 위에 출처 카드를 늘어놓은 목업 화면을 만들어 보세요.","en":"Mock up an answer screen with footnote numbers like [1] in the text and source cards lined up above it."},{"ko":"결과 화면 아래에 다음에 물어볼 만한 질문 칩 세 개를 붙여 보세요.","en":"Add three chips with likely follow-up questions under a result screen."}],"ask":{"ko":"작은 출처 번호 하나가 왜 답변을 더 믿게 만들까요?","en":"Why does one small source number make you trust an answer more?"}},"GoodNotes":{"time":20,"setup":{"ko":"iPad와 Apple Pencil이 있으면 가장 좋고, 수백 페이지짜리 PDF 하나를 준비해 두세요.","en":"An iPad with Apple Pencil works best, and have a PDF of a few hundred pages ready."},"missions":[{"do":{"ko":"Apple Pencil로 빠르게 글씨를 휘갈겨 쓰면서 펜 끝과 잉크 사이의 간격을 지켜보세요.","en":"Scribble quickly with Apple Pencil and watch the gap between the pen tip and the ink."},"wow":{"ko":"필기감에 맞춰 만든 잉크 엔진이라 잉크가 펜을 바로 따라와요. 이 손맛이 iPad 디지털 플래너 문화를 만들었어요.","en":"The ink engine is tuned for writing feel, so ink keeps right up with the pen. That feel is what started the iPad digital planner culture."}},{"do":{"ko":"손글씨로 단어 몇 개를 쓴 다음 그 단어를 검색해 보세요.","en":"Handwrite a few words, then search for one of them."},"wow":{"ko":"손으로 쓴 글씨가 검색에 걸려요. 손글씨 노트가 찾을 수 있는 데이터가 돼요.","en":"Your handwriting shows up in search results. A handwritten notebook becomes searchable data."}},{"do":{"ko":"수백 페이지짜리 PDF를 가져와 곧바로 뒤쪽 페이지로 넘어가 보세요.","en":"Import a PDF of a few hundred pages and jump straight to a page near the end."},"wow":{"ko":"전체를 다 받기 전에 필요한 페이지부터 불러와요. 동기화 진행률과 부분 로딩이 대용량 교재를 버티게 해요.","en":"It loads the pages you need before the whole file arrives. Sync progress and partial loading are what make huge textbooks usable."}}],"make":[{"ko":"PencilKit 캔버스를 한 화면에 붙이고 기본 설정과 잉크 종류를 바꿔 가며 필기 지연을 비교해 보세요.","en":"Drop a PencilKit canvas into a screen and compare writing latency across default settings and ink types."},{"ko":"큰 PDF를 열 때 보이는 페이지만 먼저 렌더링하고 나머지는 나중에 불러오는 뷰어를 만들어 보세요.","en":"Build a PDF viewer that renders the visible pages first and loads the rest later."}],"ask":{"ko":"디지털 펜이 종이 같다고 느껴지는 기준은 무엇이었나요?","en":"What made the digital pen feel like paper to you?"}},"네이버 지도":{"time":15,"setup":{"ko":"한국 안에서 실제로 갈 장소 하나를 정하고 시작하세요.","en":"Pick a real place in Korea you might go to before starting."},"missions":[{"do":{"ko":"가려는 장소까지 대중교통 길찾기를 하고 버스 도착 정보와 환승 안내를 자세히 보세요.","en":"Get transit directions to your place and look closely at the bus arrival info and transfer guidance."},"wow":{"ko":"버스 실시간 도착, 지하철 빠른 환승 칸, 막차 정보까지 나와요. 해외 지도 앱과 가장 크게 차이 나는 부분이에요.","en":"You get live bus arrivals, the best subway car for a quick transfer and last-train info. This is where it differs most from foreign map apps."}},{"do":{"ko":"가게 하나를 검색해 상세 화면을 끝까지 내려 보세요.","en":"Search for a shop and scroll its detail screen all the way down."},"wow":{"ko":"블로그 리뷰, 방문자 리뷰, 메뉴에 예약, 주문, 결제까지 이어져요. 지도가 사실상 동네 커머스 앱이에요.","en":"Blog reviews, visitor reviews and the menu flow into booking, ordering and payment. The map is really a local commerce app."}},{"do":{"ko":"거리뷰나 실내 지도로 그 장소 주변과 건물 안을 미리 둘러보세요.","en":"Use street view or the indoor map to look around the place and inside the building beforehand."},"wow":{"ko":"국내 데이터가 많아서 가기 전에 골목과 건물 안까지 볼 수 있어요. 현지 데이터가 곧 UX 경쟁력이에요.","en":"Rich local data lets you see the alleys and even indoors before you go. Local data is the UX advantage."}}],"make":[{"ko":"장소 카드에서 리뷰를 거쳐 예약 버튼까지 탭 두 번 안에 닿는 동선을 프로토타입으로 만들어 보세요.","en":"Prototype a flow from a place card through reviews to a booking button in two taps or fewer."},{"ko":"길찾기 결과 화면에 막차 시간처럼 현지 사람만 아는 정보 한 줄을 넣어 보세요.","en":"Add one line of local-only info, like the last train time, to a directions result screen."}],"ask":{"ko":"지도 앱이 예약과 주문까지 맡아도 어색하지 않은 이유는 뭘까요?","en":"Why does it not feel strange for a map app to handle booking and ordering too?"}},"Guitar Wiz":{"time":20,"setup":{"ko":"기타가 있으면 좋고, VoiceOver를 켜고 끄는 법을 미리 알아 두세요. Apple Watch가 있으면 함께 준비하세요.","en":"A guitar helps, and know how to toggle VoiceOver. Have an Apple Watch ready if you own one."},"missions":[{"do":{"ko":"VoiceOver를 켜고 눈을 감은 채 튜너로 기타 줄 하나를 맞춰 보세요.","en":"Turn on VoiceOver, close your eyes and tune one guitar string with the tuner."},"wow":{"ko":"줄이 높은지 낮은지를 음성으로 알려 줘서 화면을 보지 않고도 조율이 끝나요. 인도 벵갈루루의 1인 개발자가 만든 앱이에요.","en":"It tells you by voice whether the string is sharp or flat, so you finish tuning without looking. One developer in Bengaluru built it."}},{"do":{"ko":"Apple Watch에서 iPhone 없이 튜너를 켜고 줄을 퉁겨 보세요.","en":"Open the tuner on Apple Watch without your iPhone and pluck a string."},"wow":{"ko":"시계 혼자서 튜너가 돌아가요. 개발자가 완성까지 수년이 걸렸다고 한 기능이에요.","en":"The watch runs the tuner on its own. The developer says this part took years to get right."}},{"do":{"ko":"메트로놈을 켜고 소리 대신 손에 오는 진동으로 박자를 따라가 보세요.","en":"Start the metronome and follow the beat through vibration instead of sound."},"wow":{"ko":"박자가 진동으로 전해져 화면도 소리도 없이 템포를 탈 수 있어요.","en":"The beat arrives as vibration, so you can keep tempo with no screen and no sound."}},{"do":{"ko":"VoiceOver를 켠 채 코드 레슨을 열고 지판 다이어그램에 초점을 옮겨 보세요.","en":"With VoiceOver on, open a chord lesson and move focus onto the fretboard diagram."},"wow":{"ko":"손가락 위치를 읽어 주고, 지판 다이어그램 같은 커스텀 컨트롤에도 의미 있는 레이블이 붙어 있어요.","en":"It reads out finger placement, and even custom controls like the fretboard diagram carry meaningful labels."}}],"make":[{"ko":"커스텀 게이지 하나에 숫자 대신 조금 높음, 맞음 같은 accessibilityValue를 붙이고 VoiceOver로 들어 보세요.","en":"Give a custom gauge an accessibilityValue like slightly sharp or in tune instead of a number, and listen with VoiceOver."},{"ko":"상태가 맞음으로 바뀌는 순간 햅틱을 한 번 주어, 화면을 보지 않고도 알 수 있게 만들어 보세요.","en":"Fire one haptic when the state changes to correct, so it can be felt without looking."}],"ask":{"ko":"화면 없이 조율이 되려면 어떤 정보를 말과 진동으로 바꿔야 했을까요?","en":"To tune without a screen, what information had to be turned into speech and vibration?"}},"Pickle Pro":{"time":20,"setup":{"ko":"Vision Pro 전용 유료 게임이에요. 공을 휘두를 공간이 필요하고, PS VR2 Sense 컨트롤러나 Vision Pro를 가진 친구가 있으면 더 좋아요.","en":"A paid game for Vision Pro only. You need room to swing, and PS VR2 Sense controllers or a friend with a Vision Pro make it better."},"missions":[{"do":{"ko":"PS VR2 Sense 컨트롤러를 연결하고 실제로 패들을 휘둘러 공을 받아 쳐 보세요.","en":"Connect PS VR2 Sense controllers and actually swing the paddle to return the ball."},"wow":{"ko":"손 제스처 흉내가 아니라 진짜 컨트롤러가 추적돼 정밀하게 쳐져요. Sense 컨트롤러 지원을 처음 발표한 Vision Pro 게임이에요.","en":"A real tracked controller replaces hand-gesture guessing, so your shots land precisely. It was the first announced Vision Pro game with Sense support."}},{"do":{"ko":"같은 방에 Vision Pro를 가진 친구가 있다면 SharePlay로 함께 경기를 열어 보세요.","en":"If a friend with a Vision Pro is in the same room, start a match together through SharePlay."},"wow":{"ko":"두 사람이 바닥에 고정된 코트 하나를 같이 보며 마주 보고 쳐요. 가상 경기장이 아니라 내 거실이에요.","en":"You both see one court anchored to the floor and play face to face, in your own living room rather than a virtual arena."}},{"do":{"ko":"AI 상대를 초급으로 한 판, 프로 수준으로 한 판 해 보세요.","en":"Play one match against a beginner AI and one against a pro-level AI."},"wow":{"ko":"AI 상대는 전작 Racket Club의 수천 시간 플레이 데이터로 학습했어요. 물리 엔진도 그 게임과 같아요.","en":"The AI learned from thousands of hours of gameplay from the earlier Racket Club, and it shares that game's physics engine."}}],"make":[{"ko":"RealityKit으로 바닥에 고정되는 평면 하나를 놓고 그 위에 공 하나가 튀게 만들어 보세요.","en":"Use RealityKit to anchor a plane to the floor and bounce a ball on it."},{"ko":"손 제스처 입력과 게임 컨트롤러 입력을 같은 동작에 연결하고 정밀도를 비교해 보세요.","en":"Map both hand-gesture input and game-controller input to the same action and compare the precision."}],"ask":{"ko":"손 대신 실제 컨트롤러를 쥐었을 때 무엇이 가장 달라졌나요?","en":"What changed most when you held a real controller instead of using your hands?"}},"despelote":{"time":30,"setup":{"ko":"Mac 전용 유료 게임이에요. 헤드폰을 쓰면 위치 기반 대화를 훨씬 잘 들을 수 있어요.","en":"A paid game for Mac only. Headphones make the positional dialogue much easier to hear."},"missions":[{"do":{"ko":"헤드폰을 쓰고 공을 몰며 이야기하는 사람들 쪽으로 천천히 다가가 보세요.","en":"Wear headphones and slowly dribble toward people who are talking."},"wow":{"ko":"가까이 갈수록 대화가 또렷해져요. 키토 현지에서 주민들과 대본 없이 녹음한 진짜 대화라 엿듣기가 곧 탐험이에요.","en":"The talk gets clearer as you get closer. It is real unscripted conversation recorded with locals in Quito, so eavesdropping is how you explore."}},{"do":{"ko":"공 차기 말고 할 수 있는 다른 행동을 찾아보세요.","en":"Try to find anything you can do other than kicking the ball."},"wow":{"ko":"할 수 있는 건 공 차기 하나뿐이에요. 목표도 실패도 없어서 2001년 키토의 여덟 살 아이 시선에 그대로 머물게 돼요.","en":"Kicking is the only thing you can do. With no goals or failure, you simply stay in the eyes of an eight-year-old in Quito in 2001."}},{"do":{"ko":"잠시 멈추고 배경과 인물이 어떻게 그려졌는지 비교해 보세요.","en":"Stop for a moment and compare how the backgrounds and the people are drawn."},"wow":{"ko":"실제 키토 거리 사진에 거친 입자와 파스텔을 입히고 흑백 손그림 인물을 올려서, 화면 전체가 기억 속 장면처럼 보여요.","en":"Real photos of Quito streets get grain and pastel tints with black-and-white hand-drawn people on top, so the whole screen looks like a memory."}}],"make":[{"ko":"플레이어와 소리 나는 지점의 거리에 따라 볼륨이 줄어드는 장면 하나를 SpriteKit으로 만들어 보세요.","en":"Build one SpriteKit scene where volume fades with the distance between the player and a sound source."},{"ko":"실제 사진에 입자와 색조 필터를 씌우고 흑백 선화를 올려 기억 같은 화면을 만들어 보세요.","en":"Put a grain and tint filter on a real photo and lay black-and-white line art over it to make a memory-like frame."}],"ask":{"ko":"대본 없는 실제 대화가 왜 더 기억처럼 들렸을까요?","en":"Why did the unscripted real conversations sound more like memories?"}},"Balatro":{"time":30,"setup":{"ko":"광고와 인앱 구매가 없는 유료 앱이고, Apple Arcade에서는 Balatro+로도 할 수 있어요.","en":"A paid app with no ads or in-app purchases, also available as Balatro+ on Apple Arcade."},"missions":[{"do":{"ko":"첫 판에서 족보를 하나 내고, 점수가 올라가는 동안 칩과 배수 숫자를 끝까지 지켜보세요.","en":"Play a poker hand in your first round and watch the chips and mult numbers until the score settles."},"wow":{"ko":"카드 한 장마다 칩 × 배수가 소리와 화면 흔들림과 함께 올라가요. 1인 개발자가 취미로 시작해 500만 장을 판 게임의 핵심 쾌감이에요.","en":"Chips times mult climbs card by card with sound and screen shake. This is the core thrill of a solo hobby project that sold 5 million copies."}},{"do":{"ko":"조커를 두 장 이상 모은 뒤 앞에서 냈던 족보를 다시 내 보세요.","en":"Collect two or more Jokers, then play the same hand you played before."},"wow":{"ko":"배수가 겹겹이 쌓여 같은 족보의 점수가 크게 뛰어요. 누구나 아는 포커 규칙 위에 끝없는 빌드가 생겨요.","en":"The multipliers stack and the same hand scores far higher. Endless builds grow on top of poker rules everyone already knows."}},{"do":{"ko":"손에 든 카드를 손가락으로 끌어 순서를 바꾸고 골라 보세요.","en":"Drag the cards in your hand with your finger to reorder and select them."},"wow":{"ko":"마우스 호버 대신 드래그와 큰 탭 영역으로 다시 설계해서 세로 화면에서도 편해요. CRT 필터 픽셀도 작은 화면에서 잘 읽혀요.","en":"It was redesigned around dragging and large tap targets instead of hover, so portrait play is comfortable, and the CRT pixel art stays readable."}}],"make":[{"ko":"점수 숫자가 한 번에 바뀌지 않고 단계별로 올라가며 화면이 살짝 흔들리는 연출을 만들어 보세요.","en":"Make a score that climbs step by step instead of jumping, with a slight screen shake at each step."},{"ko":"누구나 아는 간단한 규칙 하나에 배수를 곱하는 변형 카드 하나를 더한 미니 게임을 만들어 보세요.","en":"Make a mini game that adds one multiplier card to a simple rule everyone knows."}],"ask":{"ko":"계산 과정을 보여 주는 것이 왜 최종 숫자만 보여 주는 것보다 짜릿할까요?","en":"Why is showing the calculation more thrilling than showing only the final number?"}},"Moises":{"time":15,"setup":{"ko":"이어폰이나 헤드폰과 기기에 있는 좋아하는 노래 파일 하나를 준비하세요. 악기가 있으면 더 좋아요.","en":"Have earphones and a favorite song file on your device. An instrument makes it better."},"missions":[{"do":{"ko":"좋아하는 노래를 넣고 분리가 끝나면 드럼 슬라이더만 끝까지 내린 채 재생해 보세요.","en":"Load a favorite song, and once it is split, pull only the drum slider all the way down and play it."},"wow":{"ko":"녹음된 곡에서 드럼만 사라지고 나머지는 그대로예요. 드럼을 빼고 직접 쳐 보고 싶던 개발자의 아이디어가 7,000만 명의 서비스가 됐어요.","en":"Only the drums vanish from a finished recording. One developer's wish to play drums along to songs became a 70-million-user service."}},{"do":{"ko":"같은 곡의 키를 올려 보고, 이번엔 템포만 느리게 바꿔 보세요.","en":"Raise the key of the same song, then slow down only the tempo."},"wow":{"ko":"목소리가 변조되지 않은 채 키가 바뀌고, 키는 그대로인 채 느려져요.","en":"The key changes without chipmunk vocals, and it slows down without changing key."}},{"do":{"ko":"코드 표시를 켜 둔 채 곡을 재생해 보세요.","en":"Play the song with the chord display on."},"wow":{"ko":"코드가 재생에 맞춰 흘러가고 키도 자동으로 잡혀요. 채보하지 않아도 곡이 바로 합주 차트가 돼요.","en":"Chords scroll in time with playback and the key is detected for you. With no transcription, the song becomes a play-along chart."}},{"do":{"ko":"메트로놈과 카운트인을 켜고 곡에 맞춰 들어가 보세요.","en":"Turn on the metronome and count-in and come in with the song."},"wow":{"ko":"고정 BPM이 아니라 곡에서 감지한 비트를 따라 움직여요.","en":"It follows the beat detected in the song rather than a fixed BPM."}}],"make":[{"ko":"AVAudioEngine으로 미리 나눈 트랙 두 개를 재생하고 트랙마다 볼륨 슬라이더를 붙여 보세요.","en":"Play two pre-split tracks with AVAudioEngine and give each one its own volume slider."},{"ko":"AVAudioUnitTimePitch로 피치와 속도를 따로 바꾸는 슬라이더 두 개를 만들어 보세요.","en":"Use AVAudioUnitTimePitch to build two sliders that change pitch and speed independently."}],"ask":{"ko":"내 파트만 빼고 듣는 경험이 왜 연습 방식을 바꿀까요?","en":"Why does hearing a song without your own part change how you practice?"}},"Watch Duty: Wildfire Maps":{"time":10,"setup":{"ko":"미국 App Store 계정이 필요할 수 있어요. 미국 지역 하나를 정해 알림을 켜 보세요.","en":"You may need a US App Store account. Pick a US area to turn alerts on for."},"missions":[{"do":{"ko":"미국 카운티 하나의 알림을 켜고, 진행 중인 화재 하나의 업데이트 타임라인을 열어 보세요.","en":"Turn on alerts for one US county and open the update timeline for an active fire."},"wow":{"ko":"업데이트마다 시각이 찍힌 사람이 검증한 글이에요. 정규직 15명과 무전을 듣는 자원봉사자 약 200명이 LA 산불 때 1,400만 명에게 이걸 전했어요.","en":"Each update is timestamped and human-verified. About 15 staff and 200 scanner-listening volunteers delivered this to 14 million people during the LA fires."}},{"do":{"ko":"지도에서 레이어를 하나씩 켜며 겹쳐 보세요.","en":"Turn the map layers on one at a time and stack them."},"wow":{"ko":"화재 경계선, 대피 구역, 위성 열 감지, 대기질, 바람, 소방 항공기까지 지도 하나에 겹쳐요. 기관 사이트를 오갈 필요가 없어요.","en":"Fire perimeters, evacuation zones, satellite heat, air quality, wind and firefighting aircraft all stack on one map, no agency sites needed."}},{"do":{"ko":"산불 말고 홍수 정보도 찾아보세요.","en":"Look for flood information as well as wildfires."},"wow":{"ko":"2026년에 홍수로 영역을 넓혀 같은 검증된 리포터 모델을 두 번째 재난에도 쓰고 있어요.","en":"In 2026 it expanded to floods, reusing the same verified-reporter model for a second kind of disaster."}}],"make":[{"ko":"시각과 작성자가 붙은 짧은 업데이트 카드가 위에서부터 쌓이는 타임라인 화면을 만들어 보세요.","en":"Build a timeline screen where short updates with a timestamp and author stack from the top."},{"ko":"MapKit 지도 위에 영역 오버레이 두 개를 겹치고 각각 켜고 끄는 토글을 붙여 보세요.","en":"Overlay two area layers on a MapKit map and add a toggle for each."}],"ask":{"ko":"사람이 확인했다는 사실이 왜 자동 경보보다 더 믿음을 줄까요?","en":"Why does knowing a person checked it build more trust than an automated alert?"}},"Bears Gratitude":{"time":10,"setup":null,"missions":[{"do":{"ko":"앱을 처음 열고 몇 초 안에 첫 기록을 써 보세요.","en":"Open the app for the first time and write your first entry within a few seconds."},"wow":{"ko":"로그인 화면 없이 곧장 곰 그림 속으로 들어가요. 사용자 100명을 목표로 했던 부부가 봉쇄 기간에 그린 곰 그림 수백 장에서 시작한 앱이에요.","en":"No sign-in, you land straight among the bears. A couple hoping for 100 users started it from hundreds of bears drawn during lockdown."}},{"do":{"ko":"프롬프트 카드를 옆으로 넘기다 마음에 드는 1인칭 문구 하나를 골라 써 보세요.","en":"Swipe through the prompt cards, pick a first-person prompt you like and write to it."},"wow":{"ko":"빈 페이지 대신 My Good Day 같은 작고 구체적인 계기가 주어져서 쓸 말이 바로 떠올라요.","en":"Instead of a blank page you get a small, specific nudge like My Good Day, so words come right away."}},{"do":{"ko":"기록하고 모으고 되돌아보는 화면을 차례로 지나며 그림을 살펴보세요.","en":"Move through writing, collecting and looking back, and pay attention to the drawings."},"wow":{"ko":"와이어프레임이 아니라 그림에 맞춰 순서대로 설계해서 입력 폼이 아니라 그림책을 넘기는 느낌이에요.","en":"It was designed around the drawings, in order, not from wireframes, so it feels like paging through a picture book rather than a form."}}],"make":[{"ko":"내 앱의 첫 화면에서 로그인을 빼고 바로 첫 입력을 할 수 있게 바꾼 프로토타입을 만들어 보세요.","en":"Prototype your app's first screen with sign-in removed so the first input happens right away."},{"ko":"빈 입력창 대신 1인칭 문구가 적힌 카드를 옆으로 넘겨 고르는 입력 화면을 만들어 보세요.","en":"Replace an empty text field with swipeable cards that carry first-person prompts."}],"ask":{"ko":"로그인 화면 하나가 없다는 것만으로 왜 첫 기록이 쉬워졌을까요?","en":"Why did removing just the sign-in screen make the first entry so easy?"}},"Unpacking":{"time":20,"setup":{"ko":"유료 게임이에요. 효과음을 느끼려면 소리를 켜거나 이어폰을 쓰세요.","en":"A paid game. Turn sound on or use earphones to feel the sound effects."},"missions":[{"do":{"ko":"소리를 켜고 같은 물건을 서로 다른 표면 위에 차례로 놓아 보세요.","en":"With sound on, place the same item on several different surfaces in turn."},"wow":{"ko":"놓는 표면마다 소리가 달라요. 짐 푸는 게임에 효과음만 1만 4천 개 넘게 녹음했어요.","en":"It sounds different on every surface. This game about unpacking boxes has over 14,000 recorded sound effects."}},{"do":{"ko":"방 정리를 마칠 때 일부러 물건 하나를 어색한 자리에 둬 보세요.","en":"When you finish a room, deliberately leave one item somewhere it does not belong."},"wow":{"ko":"게임 오버가 아니라 그 물건만 빨갛게 표시돼요. 타이머도 점수도 없어서 끝까지 차분해요.","en":"There is no game over, just that one item highlighted in red. With no timer or score, it stays calm."}},{"do":{"ko":"첫 이사를 마치고 다음 집에서 상자를 열어 보세요.","en":"Finish the first move and open boxes in the next home."},"wow":{"ko":"대사 한 줄 없이 챙기고 잃고 숨기는 물건만으로 한 사람의 삶이 읽혀요.","en":"Without a single line of dialogue, you read a person's life from what she keeps, loses and hides."}}],"make":[{"ko":"드래그한 물건을 놓는 표면 종류에 따라 다른 소리와 햅틱이 나는 화면을 만들어 보세요.","en":"Build a screen where dropping a dragged item plays a different sound and haptic for each surface type."},{"ko":"실패 메시지 대신 잘못된 항목만 빨갛게 표시하는 확인 방식을 내 앱 폼에 적용해 보세요.","en":"Apply a check to a form in your app that highlights only the wrong item in red instead of showing an error message."}],"ask":{"ko":"대사 없이 물건만으로 이야기가 전해진 건 왜일까요?","en":"Why could the story come through with objects alone and no words?"}},"Arc Search":{"time":10,"setup":null,"missions":[{"do":{"ko":"궁금한 걸 검색창에 입력하고 Browse for Me를 눌러 보세요.","en":"Type a question into the search bar and tap Browse for Me."},"wow":{"ko":"링크 목록 대신 웹페이지 6개 이상을 대신 읽고, 인용과 링크와 영상이 담긴 새 페이지를 만들어 줘요.","en":"Instead of links, it reads six or more pages for you and builds a new page with quotes, links and video."}},{"do":{"ko":"아무 웹페이지나 열고 화면을 핀치해 보세요.","en":"Open any web page and pinch the screen."},"wow":{"ko":"페이지가 요약돼요. 튜토리얼 없이 제스처와 맥락으로 기능을 배워요.","en":"The page gets summarized. You learn features through gestures in context, not a tutorial."}},{"do":{"ko":"휴대폰을 귀에 대고 질문을 말해 보세요.","en":"Hold the phone to your ear and say a question."},"wow":{"ko":"Call Arc로 전화하듯 음성 질문을 할 수 있어요. 휴대폰을 드는 동작이 곧 기능이에요.","en":"Call Arc lets you ask by voice like a phone call. Raising the phone is the feature."}},{"do":{"ko":"앱을 새로 연 뒤 색이 다른 웹사이트 몇 곳을 차례로 열어 보세요.","en":"Open the app fresh, then visit a few websites with different colors."},"wow":{"ko":"열자마자 키보드가 올라와 있고, 툴바가 사이트 색에 맞춰 바뀌어 브라우저가 페이지의 일부처럼 보여요.","en":"The keyboard is already up when it opens, and the toolbar tints to each site so the browser feels like part of the page."}}],"make":[{"ko":"검색 결과 목록 대신 요약 문단과 출처 링크 세 개가 담긴 카드 한 장을 보여 주는 화면을 만들어 보세요.","en":"Build a screen that shows one card with a summary paragraph and three source links instead of a results list."},{"ko":"콘텐츠 화면에 핀치 제스처를 걸어 요약 시트가 올라오게 연결해 보세요.","en":"Attach a pinch gesture to a content screen that brings up a summary sheet."}],"ask":{"ko":"링크를 누르지 않아도 되는 검색이 왜 편하면서도 낯설게 느껴질까요?","en":"Why does search without clicking links feel both easy and strange?"}},"Sunlitt":{"time":15,"setup":{"ko":"창가나 야외에서 하면 AR 모드를 제대로 느낄 수 있어요.","en":"Use it by a window or outdoors to really feel the AR mode."},"missions":[{"do":{"ko":"창가나 발코니에서 AR 모드를 켜고 카메라를 하늘로 향한 채 날짜를 여름과 겨울로 바꿔 보세요.","en":"By a window or balcony, turn on AR mode, point the camera at the sky and switch the date between summer and winter."},"wow":{"ko":"고른 날짜의 해 궤적이 카메라 화면에 겹쳐요. 나폴리 골목에서 볕 드는 집을 찾던 Academy 동기들이 만든 이유가 바로 이거예요.","en":"The sun's path for that date overlays the camera view. This is exactly why Academy classmates hunting for a sunny flat in Naples built it."}},{"do":{"ko":"3D 해시계 Monolitt와 그림자 지도를 열고 내가 사는 도시를 찾아보세요.","en":"Open the Monolitt 3D sundial and the shadow map and find your own city."},"wow":{"ko":"도시 건물이 드리우는 그림자까지 실시간으로 보여요.","en":"It shows real-time shadows, including those cast by city buildings."}},{"do":{"ko":"위젯이나 라이브 액티비티를 켜고 일출이나 일몰 무렵 잠금 화면과 Dynamic Island를 보세요.","en":"Add a widget or Live Activity and check the Lock Screen and Dynamic Island around sunrise or sunset."},"wow":{"ko":"앱을 열지 않아도 해의 움직임이 시스템 곳곳에 보이고 햅틱까지 태양 움직임에 맞춰져 있어요.","en":"The sun's movement shows up across the system without opening the app, and even the haptics follow it."}},{"do":{"ko":"iPad, Mac, Apple Watch 중 가진 기기에서도 열어 비교해 보세요.","en":"Open it on whichever iPad, Mac or Apple Watch you have and compare."},"wow":{"ko":"6명 팀이 코드를 거의 100% 공유해 다섯 플랫폼에 냈어요. 기기마다 같은 앱처럼 느껴지는지 보세요.","en":"A six-person team shipped five platforms sharing almost 100% of the code. See whether it feels like one app everywhere."}}],"make":[{"ko":"ARKit 화면에 하늘을 가로지르는 곡선 하나를 고정해 그려 보세요.","en":"Draw one fixed arc across the sky in an ARKit view."},{"ko":"현재 시각에 따라 배경 그라데이션 색이 바뀌는 SwiftUI 화면을 만들어 보세요.","en":"Build a SwiftUI screen whose background gradient changes with the current time of day."}],"ask":{"ko":"숫자 대신 내 창문 위에 궤적을 그려 주는 게 왜 결정을 쉽게 만들까요?","en":"Why does drawing the path over your own window make the decision easier than numbers?"}},"Universe — Website Builder":{"time":20,"setup":{"ko":"무료 플랜으로 시작할 수 있어요. VoiceOver와 큰 글씨 설정을 바꾸는 법을 알아 두세요.","en":"You can start on the free plan. Know how to change VoiceOver and large text settings."},"missions":[{"do":{"ko":"컴퓨터 없이 iPhone에서 블록을 탭하고 끌고 핀치해 첫 페이지를 만들고 무료 플랜으로 공개해 보세요.","en":"With no computer, tap, drag and pinch blocks on iPhone to make a first page and publish it on the free plan."},"wow":{"ko":"HTML이나 CSS 없이 휴대폰만으로 진짜 웹사이트가 생겨요. 이렇게 만든 사이트가 100만 개를 넘었어요.","en":"A real website appears from just a phone, no HTML or CSS. More than a million sites have been made this way."}},{"do":{"ko":"VoiceOver를 켜거나 글자 크기를 가장 크게 키운 채 블록을 편집해 보세요.","en":"Edit blocks with VoiceOver on or with text size turned all the way up."},"wow":{"ko":"시각 디자인 도구인데도 스크린 리더와 큰 글씨로 쓸 수 있어요. Apple이 콕 집어 칭찬한 부분이에요.","en":"It is a visual design tool, yet it works with a screen reader and large text. Apple singled this out."}},{"do":{"ko":"휴대폰에서 만든 사이트를 iPad나 Mac 또는 웹에서 열어 이어서 고쳐 보세요.","en":"Open the site you made on the phone on an iPad, Mac or the web and keep editing."},"wow":{"ko":"같은 블록 시스템이라 작은 화면에서 시작한 사이트를 큰 화면에서 그대로 마무리할 수 있어요.","en":"It is the same block system, so a site started on a small screen continues as is on a big one."}}],"make":[{"ko":"정사각형 그리드 위 블록을 드래그로 옮기고 핀치로 크기를 바꾸는 편집기를 만들어 보세요.","en":"Build an editor where blocks on a square grid move by drag and resize by pinch."},{"ko":"그 편집기의 블록마다 위치와 크기를 읽어 주는 VoiceOver 레이블과 동작을 붙여 보세요.","en":"Give each block in that editor VoiceOver labels and actions that announce its position and size."}],"ask":{"ko":"웹 레이아웃을 정사각형 블록으로 줄인 것이 왜 휴대폰에서 통했을까요?","en":"Why did shrinking web layout down to square blocks work on a phone?"}},"Pocket Card Jockey: Ride On!":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"do":{"ko":"첫 경주에서 솔리테어 카드를 최대한 빨리 연달아 없애 보세요.","en":"In your first race, clear the solitaire cards as fast and as many in a row as you can."},"wow":{"ko":"카드를 없앨수록 말의 에너지가 쌓여 더 잘 달려요. 포켓몬을 만든 게임프리크가 솔리테어와 경마를 이렇게 붙였어요.","en":"The more cards you clear, the more energy your horse builds. Pokémon studio GAME FREAK fused solitaire and racing this way."}},{"do":{"ko":"솔리테어 사이 구간에서 말을 안쪽 코스나 경쟁마 근처로 끌어다 놓아 보세요.","en":"Between solitaire rounds, drag your horse to the inside track or next to a rival."},"wow":{"ko":"짧은 전략 판단이 카드 플레이 사이에 끼어들어 경주에 리듬이 생겨요.","en":"Quick strategic choices cut in between card rounds and give the race a rhythm."}},{"do":{"ko":"한 판은 일부러 카드를 많이 남긴 채 끝내 보세요.","en":"End one round on purpose with lots of cards left."},"wow":{"ko":"판 결과에 따라 말의 기분과 스태미나가 달라져요. 카드 실수가 그대로 경주에 남아요.","en":"The round result changes your horse's mood and stamina, so card mistakes carry straight into the race."}}],"make":[{"ko":"퍼즐을 풀 때마다 다른 화면의 게이지가 차오르는 두 장르 연결 프로토타입을 만들어 보세요.","en":"Prototype two genres linked so that solving a puzzle fills a gauge in another view."},{"ko":"퍼즐 결과를 성공과 실패가 아니라 다음 단계의 상태값 두세 개로 넘겨 보세요.","en":"Pass a puzzle's result on as two or three state values for the next stage instead of win or lose."}],"ask":{"ko":"전혀 다른 두 장르가 왜 어색하지 않게 붙었을까요?","en":"Why did two completely different genres fit together so naturally?"}},"Hindsight":{"time":30,"setup":{"ko":"유료 게임이에요. 소리를 켜고 조용한 시간에 하세요.","en":"A paid game. Play with sound on during a quiet moment."},"missions":[{"do":{"ko":"어머니 집에서 찻잔이나 사진 같은 물건 하나를 탭해 보세요.","en":"In your mother's house, tap an object such as a teacup or a photo."},"wow":{"ko":"카메라가 그 물건 속으로 들어가 다른 시절의 기억으로 넘어가요. 화면 전환 자체가 이야기를 해요.","en":"The camera dives into the object and lands in a memory from another time. The transition itself tells the story."}},{"do":{"ko":"새 장면에서 확대하고 둘러보며 다음 물건을 찾아보세요.","en":"In the new scene, zoom and look around to find the next object."},"wow":{"ko":"장면이 매치컷과 시점 전환으로 이어져서, 찾는 동작이 곧 다음 기억으로 가는 길이에요.","en":"Scenes join through match cuts and perspective shifts, so searching is itself the way to the next memory."}}],"make":[{"ko":"이미지를 탭하면 그 지점으로 확대되면서 다음 화면으로 이어지는 전환을 SwiftUI로 만들어 보세요.","en":"Build a SwiftUI transition where tapping an image zooms into that spot and flows into the next screen."},{"ko":"두 장면에서 모양이 비슷한 물체를 같은 위치에 두고 크로스페이드하는 매치컷을 만들어 보세요.","en":"Make a match cut that crossfades two scenes with similarly shaped objects in the same position."}],"ask":{"ko":"버튼 대신 물건 속으로 들어가는 전환이 왜 감정을 더 크게 만들까요?","en":"Why does diving into an object, instead of pressing a button, make the feeling stronger?"}},"Rise: Energy & Sleep Tracker":{"time":15,"setup":{"ko":"7일 무료 체험 뒤 구독하는 앱이에요. 건강 앱 데이터 접근을 허용하면 첫날부터 볼 수 있어요.","en":"A subscription app after a 7-day trial. Allow Health data access to see results from day one."},"missions":[{"do":{"ko":"웨어러블 없이 건강 앱 접근만 허용하고 첫 화면의 수면 부채 숫자를 보세요.","en":"Without any wearable, just allow Health access and look at the sleep debt number on the first screen."},"wow":{"ko":"첫날부터 iPhone만으로 수면 부채가 계산돼요. NFL과 NBA 팀이 먼저 쓰던 수면 코칭이 출발점이에요.","en":"From day one it calculates sleep debt with only an iPhone. It grew out of sleep coaching that NFL and NBA teams used first."}},{"do":{"ko":"오늘의 에너지 곡선을 열고 오후 처짐 시간과 최고조 시간을 찾아보세요.","en":"Open today's energy curve and find your afternoon dip and your peak."},"wow":{"ko":"데이터가 언제 집중 업무를 할지에 대한 답으로 바뀌어요.","en":"The data turns into an answer to when you should do focused work."}},{"do":{"ko":"습관 알림을 켜 둔 채 하루를 보내 보세요.","en":"Turn on habit reminders and go through a day."},"wow":{"ko":"카페인을 끊을 시간, 빛을 쬘 시간 같은 습관이 정해진 시각에 알림으로 와요. 기록에 그치지 않고 행동을 시켜요.","en":"Habits like when to stop caffeine or get light arrive at set times. It nudges actions instead of only recording."}}],"make":[{"ko":"수면 점수 대신 필요한 수면과 실제 수면의 차이를 시간 하나로 보여 주는 화면을 만들어 보세요.","en":"Build a screen that shows the gap between needed and actual sleep as one number of hours instead of a score."},{"ko":"Swift Charts로 하루 에너지 곡선과 지금 위치를 표시한 타임라인을 그려 보세요.","en":"Draw a daily energy curve with a marker for now using Swift Charts."}],"ask":{"ko":"점수 대신 부채라는 말이 왜 행동을 바꾸게 할까요?","en":"Why does calling it debt instead of a score push you to act?"}},"Moncage":{"time":20,"setup":{"ko":"유료 게임이에요.","en":"A paid game."},"missions":[{"do":{"ko":"큐브를 천천히 돌리며 두 면의 파이프나 다리가 하나로 이어지는 각도를 찾아보세요.","en":"Rotate the cube slowly and look for the angle where a pipe or bridge on two faces joins into one."},"wow":{"ko":"두 면의 물체가 한 그림으로 이어지는 순간, 그 착시가 곧 퍼즐의 답이에요. 게임 전체가 큐브 하나예요.","en":"The moment objects on two faces become one picture, that illusion is the solution. The whole game is one cube."}},{"do":{"ko":"퍼즐을 풀고 나서 열리는 사진을 들여다보세요.","en":"After solving a puzzle, look closely at the photo that unlocks."},"wow":{"ko":"대사 없이 그 사진들로 이야기가 진행돼요. 진행과 서사가 같은 보상이에요.","en":"The story moves through those photos without words. Progress and narrative are the same reward."}},{"do":{"ko":"큐브를 한 바퀴 돌리며 면마다 어떤 장소가 있는지 비교해 보세요.","en":"Turn the cube all the way around and compare the place on each face."},"wow":{"ko":"등대, 공장, 무너진 마을처럼 면마다 다른 수작업 장면이 있고, 그 대비가 주제를 전해요.","en":"Each face is a different handcrafted scene, like a lighthouse, a factory or a ruined town, and the contrast carries the theme."}}],"make":[{"ko":"SceneKit으로 서로 떨어진 막대 두 개가 특정 카메라 각도에서만 하나로 이어져 보이는 장면을 만들어 보세요.","en":"Use SceneKit to make two separate rods that only look connected from one camera angle."},{"ko":"그 각도에 가까워지면 햅틱이 약하게 오고 맞으면 강하게 오는 피드백을 붙여 보세요.","en":"Add feedback that gives a light haptic near that angle and a strong one when it lines up."}],"ask":{"ko":"정답을 보는 각도로 만든 것이 왜 아하 순간을 크게 만들까요?","en":"Why does making the answer a viewing angle make the aha moment bigger?"}},"Active Arcade":{"time":15,"setup":{"ko":"몸을 움직일 공간과 기기를 세워 둘 곳이 필요해요. 함께할 사람이나 TV가 있으면 더 좋아요.","en":"You need room to move and a place to stand the device. A second person or a TV makes it better."},"missions":[{"do":{"ko":"기기를 세워 두고 한 발 물러선 뒤 게임 하나를 시작해 몸을 움직여 보세요.","en":"Stand the device up, step back and start a game, then move your body."},"wow":{"ko":"웨어러블도 센서도 없이 카메라 하나가 전신을 따라와 몸이 컨트롤러가 돼요. 광고도 인앱 결제도 없는 무료예요.","en":"With no wearable or sensor, one camera follows your whole body and you become the controller. It is free with no ads or IAP."}},{"do":{"ko":"두더지 잡기나 Bunny Hop처럼 규칙을 이미 아는 게임을 골라 해 보세요.","en":"Pick a game whose rules you already know, like Whack-a-Mole or Bunny Hop."},"wow":{"ko":"규칙을 따로 배울 필요가 없어서 운동한다는 느낌보다 노는 느낌이 먼저 와요.","en":"There are no rules to learn, so it feels like play before it feels like exercise."}},{"do":{"ko":"가족이나 친구와 2인 모드를 하거나 AirPlay로 TV에 띄워 보세요.","en":"Play a two-player mode with family or friends, or AirPlay it to a TV."},"wow":{"ko":"휴대폰 하나가 거실용 모션 콘솔이 돼요.","en":"A single phone becomes a living-room motion console."}}],"make":[{"ko":"Vision 프레임워크의 몸 자세 인식으로 손목 위치에 점을 찍는 카메라 화면을 만들어 보세요.","en":"Build a camera screen that puts a dot on your wrists using body pose detection in the Vision framework."},{"ko":"그 손목 점이 화면의 목표 원에 닿으면 점수가 오르는 한 판짜리 게임으로 바꿔 보세요.","en":"Turn it into a one-round game where your wrist dot scores by touching a target circle."}],"ask":{"ko":"운동이라는 말을 지웠을 때 왜 더 오래 움직이게 될까요?","en":"Why do you keep moving longer once the word exercise disappears?"}},"Townscaper":{"time":15,"setup":{"ko":"유료 게임이에요.","en":"A paid game."},"missions":[{"do":{"ko":"물 위 한 곳을 여러 번 탭해 블록을 높이 쌓고, 옆에도 몇 개 붙여 보세요.","en":"Tap one spot on the water several times to stack blocks high, then add a few beside it."},"wow":{"ko":"블록 덩어리가 저절로 아치, 계단, 첨탑으로 바뀌어요. 목표도 점수도 없는 이 장난감이 스팀에서만 38만 장 팔렸어요.","en":"Block clusters turn into arches, stairs and spires on their own. This toy with no goals sold 380,000 copies on Steam alone."}},{"do":{"ko":"블록을 몇 개 쌓다가 다시 탭해 지우고, 새 블록의 색을 바꿔 보세요.","en":"Stack a few blocks, tap some again to remove them and change the color of new blocks."},"wow":{"ko":"탭하면 생기고 다시 탭하면 사라지는 게 규칙의 전부예요. 자원도 실패도 없이 어디에 지을지만 정해요.","en":"Tap to add and tap again to remove is the whole rule set. No resources, no failure, only where to build."}},{"do":{"ko":"마을을 넓게 만든 뒤 바닥의 그리드 모양을 살펴보세요.","en":"Build a wide town, then look at the shape of the grid underneath."},"wow":{"ko":"정사각형이 아니라 비틀린 사각형 그리드라서 단순한 탭만으로도 손으로 지은 듯한 마을이 돼요.","en":"The grid is made of distorted quads, not squares, so simple taps make a town that looks hand built."}}],"make":[{"ko":"이웃 칸이 채워졌는지에 따라 타일 모양을 바꾸는 간단한 자동 타일 규칙을 만들어 보세요.","en":"Make a simple auto-tile rule that changes a tile's shape based on which neighbors are filled."},{"ko":"탭하면 추가, 다시 탭하면 삭제만 있는 그리드에 그 규칙을 붙여 탭할 때마다 모양이 바뀌게 해 보세요.","en":"Attach that rule to a grid where tapping only adds or removes, so every tap reshapes it."}],"ask":{"ko":"직접 설계하지 않았는데도 내가 지었다고 느끼는 이유는 뭘까요?","en":"Why does it feel like you built it, even though you designed none of it?"}},"RakugakiAR":{"time":15,"setup":{"ko":"유료 앱이에요. 종이와 펜, 그리고 생물이 돌아다닐 바닥 공간을 준비하세요.","en":"A paid app. Have paper, a pen and some floor space for the creature to roam."},"missions":[{"do":{"ko":"종이에 아무 생물이나 그리고 카메라로 스캔한 뒤 바닥을 비춰 보세요.","en":"Draw any creature on paper, scan it with the camera and point at the floor."},"wow":{"ko":"내 낙서가 3D 생물이 되어 방을 걸어 다녀요. 이 장면 영상이 퍼져 5일 만에 46만 다운로드를 넘겼어요.","en":"Your doodle becomes a 3D creature walking around the room. Clips of this pushed it past 460,000 downloads in five days."}},{"do":{"ko":"생물에게 먹이를 주고 손가락으로 쿡 찔러 보세요.","en":"Feed the creature and poke it with your finger."},"wow":{"ko":"우스꽝스러운 동작으로 반응해서 내가 그린 그림이 살아 있는 것처럼 느껴져요.","en":"It reacts with goofy movements, so your own drawing feels alive."}},{"do":{"ko":"생물이 노는 모습을 녹화해 보세요.","en":"Record a video of the creature playing."},"wow":{"ko":"녹화가 놀이의 마지막 단계로 들어 있어서 웃긴 결과를 바로 나누고 싶어져요.","en":"Recording is built in as the last step of play, so you want to share the silly result right away."}}],"make":[{"ko":"사진으로 찍은 그림을 RealityKit 평면에 텍스처로 입혀 바닥 위에 세워 보세요.","en":"Put a photographed drawing onto a RealityKit plane as a texture and stand it on the floor."},{"ko":"그 평면을 탭하면 통통 튀거나 흔들리는 반응 애니메이션 하나를 붙여 보세요.","en":"Add one reaction animation where tapping that plane makes it bounce or wobble."}],"ask":{"ko":"내가 그린 그림이라는 사실이 왜 반응을 더 웃기고 사랑스럽게 만들까요?","en":"Why does the fact that you drew it make its reactions funnier and more lovable?"}},"If Found...":{"time":20,"setup":{"ko":"유료 게임이에요.","en":"A paid game."},"missions":[{"do":{"ko":"첫 페이지의 그림을 손가락으로 천천히 문질러 지워 보세요.","en":"Slowly rub out the drawing on the first page with your finger."},"wow":{"ko":"지운 자리 아래에서 다음 페이지가 드러나며 이야기가 진행돼요. 게임 전체가 지우기 하나로 흘러가요.","en":"The next page shows through where you erase and the story moves on. The whole game runs on erasing."}},{"do":{"ko":"일기 페이지를 지울 때 무엇을 지우고 있는지 생각하며 끝까지 문질러 보세요.","en":"When you reach a diary page, rub it all out while thinking about what you are erasing."},"wow":{"ko":"지우는 행위가 과거를 지우고 다시 쓰려는 주인공의 몸부림과 겹쳐요. 손가락이 감정을 대신해요.","en":"Erasing mirrors the protagonist trying to erase and rewrite her past. Your finger carries the feeling."}}],"make":[{"ko":"위 이미지를 문지른 자리만 투명해져 아래 이미지가 드러나는 지우개 화면을 만들어 보세요.","en":"Build an eraser screen where rubbing makes the top image transparent and reveals the one underneath."},{"ko":"지운 면적이 일정 비율을 넘으면 다음 장면으로 넘어가게 진행 조건을 붙여 보세요.","en":"Add a rule that moves to the next scene once a set share of the area has been erased."}],"ask":{"ko":"버튼 대신 지우는 동작으로 이야기를 넘기니 무엇이 달라졌나요?","en":"What changed when erasing, not a button, moved the story forward?"}},"Blind Drive":{"time":15,"setup":{"ko":"유료 게임이에요. 바이노럴 오디오라 헤드폰이나 이어폰이 꼭 필요해요.","en":"A paid game. Headphones or earphones are a must for the binaural audio."},"missions":[{"do":{"ko":"헤드폰을 쓰고 화면을 보지 않은 채 첫 레벨을 달려 보세요.","en":"Put on headphones and drive the first level without looking at the screen."},"wow":{"ko":"화면에는 점수와 생명뿐이고 차가 오는 방향은 바이노럴 3D 소리로만 알 수 있어요. 귀로 피하는 운전이에요.","en":"The screen shows only score and lives, and binaural 3D audio is your only clue to where cars come from. You dodge by ear."}},{"do":{"ko":"버튼 두 개로 좌우를 피하다가, 지원 기기라면 일부러 한 번 부딪혀 보세요.","en":"Dodge left and right with the two buttons, and on a supported device crash once on purpose."},"wow":{"ko":"입력은 두 개뿐이라 실력은 듣는 능력에 달려 있고, 충돌과 위험은 섬세한 햅틱으로도 전해져요.","en":"With only two inputs, skill is all listening, and crashes and danger also come through fine-grained haptics."}},{"do":{"ko":"VoiceOver를 켜고 메뉴부터 플레이까지 해 보세요.","en":"Turn on VoiceOver and go from the menu into play."},"wow":{"ko":"스크린 리더를 완전히 지원해서 시각장애인도 처음부터 끝까지 플레이할 수 있어요. 나중에 덧붙인 접근성이 아니에요.","en":"Full screen-reader support means blind players can play start to finish. Accessibility was not an afterthought."}}],"make":[{"ko":"AVAudioEnvironmentNode로 소리가 왼쪽이나 오른쪽에서 다가오는 장면을 만들어 보세요.","en":"Use AVAudioEnvironmentNode to make a sound approach from the left or right."},{"ko":"화면 없이 버튼 두 개로 그 소리를 피하는 10초짜리 미니 게임을 만들어 보세요.","en":"Make a 10-second mini game where you dodge that sound with two buttons and no screen."}],"ask":{"ko":"화면을 지웠는데도 긴장감이 오히려 커진 이유는 뭘까요?","en":"Why did removing the screen make the tension greater instead of smaller?"}},"Sky: Children of the Light":{"time":30,"setup":{"ko":"다른 플레이어를 만나야 하니 인터넷 연결이 필요해요.","en":"You need an internet connection to meet other players."},"missions":[{"do":{"ko":"다른 플레이어가 여럿 모인 곳을 찾아가고, 게임 내 콘서트나 이벤트가 열리면 들어가 보세요.","en":"Find a spot where many players gather, and join an in-game concert or event if one is on."},"wow":{"ko":"7년간 자체 엔진으로 만든 이 세계에서 2023년 오로라 콘서트 때 한 서버에 10,061명이 모여 기네스 기록을 세웠어요.","en":"In this world built over seven years on a custom engine, 10,061 players packed one server for the 2023 Aurora concert, a Guinness record."}},{"do":{"ko":"모르는 플레이어에게 몸짓을 보내고 손을 잡아 함께 날아 보세요.","en":"Send a gesture to a stranger, hold hands and fly together."},"wow":{"ko":"채팅 없이 몸짓과 손잡기로 통해요. 손을 잡으면 비행력이 센 쪽이 상대를 이끌어 줘요.","en":"You connect through gestures and holding hands with no chat. Holding hands lets the stronger flyer lead the other."}},{"do":{"ko":"혼자서는 열리지 않는 문 앞에서 다른 플레이어를 기다려 보세요.","en":"Wait at a gate that will not open alone for other players to arrive."},"wow":{"ko":"여러 명이 있어야 열리는 문이 있어서 낯선 사람을 돕는 게 부가 기능이 아니라 핵심 루프예요.","en":"Some gates need several players, so helping strangers is the core loop rather than a side feature."}},{"do":{"ko":"날개빛을 몇 개 모은 뒤 다시 날아 보세요.","en":"Collect some winged light and fly again."},"wow":{"ko":"망토 에너지가 늘어나 더 멀리 날아요. 탐험 자체가 성장이에요.","en":"Your cape energy grows and you fly farther. Exploring is itself progression."}}],"make":[{"ko":"채팅 없이 미리 정한 몸짓 세 개로만 소통하는 2인 프로토타입 화면을 만들어 보세요.","en":"Build a two-person prototype where players can only communicate through three preset gestures."},{"ko":"두 사람이 동시에 버튼을 눌러야만 열리는 문 하나를 만들어 협력 순간을 시험해 보세요.","en":"Make one door that opens only when two people press at the same time, and test that moment of cooperation."}],"ask":{"ko":"말이 통하지 않는데도 낯선 사람이 왜 친구처럼 느껴졌을까요?","en":"Why did a stranger feel like a friend even though you could not talk?"}},"Things 3":{"time":15,"setup":{"ko":"iPhone판은 유료 일회성 구매이고 무료 체험은 Mac에만 있어요.","en":"The iPhone version is a paid one-time purchase, and the free trial is Mac only."},"missions":[{"do":{"ko":"오른쪽 아래 Magic Plus 버튼을 탭하지 말고 끌어서 목록 중간에 놓아 보세요.","en":"Instead of tapping the Magic Plus button at the bottom right, drag it into the middle of a list."},"wow":{"ko":"놓은 자리에 바로 할 일이나 헤딩이 들어가요. 버튼 하나가 추가와 위치 지정을 한 번에 해요.","en":"A to-do or heading appears exactly where you drop it. One button handles adding and placing at once."}},{"do":{"ko":"Siri나 단축어로 할 일을 하나 추가하거나 Mail to Things로 메일을 보내 보세요.","en":"Add a to-do with Siri or Shortcuts, or send an email with Mail to Things."},"wow":{"ko":"앱을 열지 않아도 할 일이 들어와요. Apple 플랫폼 전용으로 깊게 맞춘 통합이에요.","en":"To-dos arrive without opening the app. It is integration tuned deeply for Apple platforms only."}},{"do":{"ko":"할 일 몇 개를 Today, Upcoming, Someday로 나눠 보내고 사이드바를 보세요.","en":"Send a few to-dos to Today, Upcoming and Someday, then look at the sidebar."},"wow":{"ko":"Inbox에서 Logbook까지 GTD 흐름이 고정된 사이드바로 보여서 기능이 많아도 구조는 단순해요.","en":"The GTD flow from Inbox to Logbook is a fixed sidebar, so the structure stays simple despite many features."}}],"make":[{"ko":"플로팅 추가 버튼을 끌어서 놓은 위치에 새 행이 생기게 만드는 리스트를 만들어 보세요.","en":"Build a list where dragging a floating add button creates a new row where you drop it."},{"ko":"내 앱의 가장 흔한 동작 하나를 App Intents로 노출해 Siri와 단축어에서 실행해 보세요.","en":"Expose your app's most common action through App Intents and run it from Siri and Shortcuts."}],"ask":{"ko":"추가 버튼을 끌 수 있다는 걸 알았을 때 왜 놀라웠을까요?","en":"Why was it surprising to find out the add button could be dragged?"}},"Seeing AI":{"time":15,"setup":{"ko":"글자가 있는 문서, 바코드가 있는 제품, 지폐를 옆에 두고 VoiceOver를 켤 줄 알아 두세요.","en":"Keep a printed document, a product with a barcode and a bank note nearby, and know how to turn on VoiceOver."},"missions":[{"do":{"ko":"짧은 텍스트 채널을 고르고 셔터를 누르지 않은 채 카메라를 글자에 대 보세요.","en":"Choose the Short Text channel and point the camera at some text without pressing the shutter."},"wow":{"ko":"찍기도 전에 글자가 잡히는 즉시 소리 내어 읽기 시작해요. 기다림을 없앤 지연 시간 설계예요.","en":"It starts reading aloud the moment text comes into view, before any photo. The latency was designed away."}},{"do":{"ko":"문서 채널에서 일부러 페이지 한쪽 끝이 잘리게 카메라를 대 보세요.","en":"In the Document channel, aim the camera so one edge of the page is cut off on purpose."},"wow":{"ko":"왼쪽 가장자리가 보이지 않는다는 식으로 음성으로 알려 줘서, 화면을 못 봐도 구도를 맞출 수 있어요.","en":"It tells you by voice that an edge is missing, so you can frame the page without seeing the screen."}},{"do":{"ko":"눈을 감고 제품 채널로 상품의 바코드를 찾아보세요.","en":"Close your eyes and find a product's barcode with the Product channel."},"wow":{"ko":"바코드에 가까워질수록 신호음이 빨라져서 소리만으로 위치를 찾아요.","en":"The beeps speed up as you get closer, so you find the barcode by sound alone."}},{"do":{"ko":"스캔한 문서나 영수증에 그 안의 내용을 질문해 보세요.","en":"Ask a question about what is in a scanned document or receipt."},"wow":{"ko":"생성형 AI가 문서 내용에 답하고 사진도 더 자세히 설명해요. 시각장애인 커뮤니티와 함께 설계한 무료 앱이에요.","en":"Generative AI answers about the document and describes photos in more detail. It is free and designed with the blind community."}}],"make":[{"ko":"카메라 화면에서 Vision 텍스트 인식이 글자를 잡는 즉시 AVSpeechSynthesizer로 읽게 만들어 보세요.","en":"Make a camera screen that reads text aloud with AVSpeechSynthesizer the instant Vision text recognition finds it."},{"ko":"목표에 가까워질수록 신호음 간격이 짧아지는 오디오 피드백을 만들어 보세요.","en":"Build audio feedback where the beep interval shortens as you approach a target."}],"ask":{"ko":"화면을 보지 못하는 사람에게 기다림을 없애는 것이 왜 그렇게 중요했을까요?","en":"Why did removing the wait matter so much for people who cannot see the screen?"}},"Spotify":{"time":10,"setup":null,"missions":[{"do":{"ko":"곡을 하나 틀고 하단 미니 플레이어를 위로 밀어 올려 보세요.","en":"Play a song and swipe the mini player at the bottom upward."},"wow":{"ko":"앨범 아트가 그대로 커지며 전체 화면으로 이어져요. 같은 요소가 커지니 내가 어디 있는지 잃지 않아요.","en":"The album art itself grows into the full screen. Because the same element expands, you never lose your place."}},{"do":{"ko":"미니 플레이어를 좌우로 스와이프해 보세요.","en":"Swipe the mini player left and right."},"wow":{"ko":"전체 화면을 열지 않고도 이전 곡과 다음 곡으로 넘어가요. 가장 자주 하는 동작이 손끝에 있어요.","en":"You skip back and forward without opening the full screen. The most frequent action sits under your thumb."}},{"do":{"ko":"분위기가 다른 곡 몇 개를 넘기며 Now Playing 배경을 지켜보세요.","en":"Skip through a few songs with different moods and watch the Now Playing background."},"wow":{"ko":"Canvas 루프 영상과 앨범 아트에서 뽑은 배경색이 곡마다 화면 분위기를 바꿔요.","en":"Canvas loops and a background color taken from the album art change the mood for every song."}},{"do":{"ko":"Now Playing 화면을 아래로 계속 스크롤해 보세요.","en":"Keep scrolling down on the Now Playing screen."},"wow":{"ko":"가사, 아티스트 정보, 크레딧, 다음 곡이 카드로 이어져 한 화면 안에서 정보가 깊어져요.","en":"Lyrics, artist info, credits and the queue follow as cards, so information deepens within one screen."}}],"make":[{"ko":"matchedGeometryEffect로 미니 플레이어의 앨범 아트가 전체 화면으로 커지는 전환을 만들어 보세요.","en":"Use matchedGeometryEffect to make a mini player's album art grow into a full screen."},{"ko":"이미지의 평균 색을 뽑아 화면 배경 그라데이션으로 쓰는 코드를 붙여 보세요.","en":"Add code that takes an image's average color and uses it as the screen's background gradient."}],"ask":{"ko":"같은 앨범 아트가 커지는 전환이 왜 길을 잃지 않게 해 줄까요?","en":"Why does the same album art growing keep you from getting lost?"}},"Linear":{"time":15,"setup":{"ko":"Linear 워크스페이스가 필요해요. 데스크톱이나 웹과 비교해 보면 더 좋아요.","en":"You need a Linear workspace. Comparing with desktop or web helps."},"missions":[{"do":{"ko":"이슈 하나를 열고 상태를 여러 번 빠르게 바꿔 보세요.","en":"Open an issue and change its status several times quickly."},"wow":{"ko":"서버 응답을 기다리지 않고 바로 반영돼요. 데이터를 먼저 기기에 동기화하는 로컬 퍼스트 구조에서 나오는 속도예요.","en":"Each change shows instantly without waiting for the server. The speed comes from a local-first sync engine."}},{"do":{"ko":"데스크톱이나 웹에서 Cmd+K를 누르고 하고 싶은 기능 이름을 입력해 보세요.","en":"On desktop or web, press Cmd+K and type the name of what you want to do."},"wow":{"ko":"어떤 기능이든 이름만으로 실행돼요. 메뉴를 찾아다니는 비용 자체를 없앴어요.","en":"Any feature runs from its name alone. The cost of hunting through menus is gone."}},{"do":{"ko":"모바일 앱에서 받은편지함 알림을 처리하고 이슈 하나를 빠르게 만들어 보세요.","en":"In the mobile app, clear some inbox notifications and quickly create an issue."},"wow":{"ko":"데스크톱을 그대로 옮기지 않고 이동 중에 하는 일만 남겼는데도 같은 속도감이 느껴져요.","en":"It does not copy the desktop, keeping only on-the-go tasks, yet the same sense of speed carries over."}}],"make":[{"ko":"버튼을 누르면 서버 응답 전에 화면부터 바꾸고 실패할 때만 되돌리는 낙관적 업데이트를 만들어 보세요.","en":"Build an optimistic update that changes the screen before the server responds and rolls back only on failure."},{"ko":"내 앱 기능 이름을 검색해 바로 실행하는 커맨드 메뉴를 하나 만들어 보세요.","en":"Make a command menu that searches your app's feature names and runs them directly."}],"ask":{"ko":"빠르다는 느낌은 애니메이션보다 구조에서 나온다는 말을 어디서 실감했나요?","en":"Where did you feel that speed comes from architecture rather than animation?"}},"Photomath":{"time":10,"setup":{"ko":"종이에 인쇄되거나 손으로 쓴 수학 문제 몇 개를 준비하세요.","en":"Have a few printed or handwritten math problems on paper."},"missions":[{"do":{"ko":"손으로 쓴 수식 하나에 카메라를 대 보세요.","en":"Point the camera at an equation you wrote by hand."},"wow":{"ko":"인쇄체뿐 아니라 손글씨 수식도 알아보고 바로 풀이를 보여 줘요.","en":"It reads handwritten math as well as print and shows a solution right away."}},{"do":{"ko":"인식이 틀린 부분이 있으면 다시 찍지 말고 수학 키보드로 고쳐 보세요.","en":"If part of it was misread, fix it with the math keyboard instead of retaking the photo."},"wow":{"ko":"OCR이 틀려도 처음부터 다시 찍을 필요 없이 고친 식으로 이어서 풀이를 받아요.","en":"Even when OCR misreads, you keep going from the corrected expression without starting over."}},{"do":{"ko":"풀이 단계 하나를 탭해 보세요.","en":"Tap one of the solution steps."},"wow":{"ko":"답만 주지 않고 왜 이렇게 되는지 설명이 펼쳐져요. 정답 앱이 아니라 학습 앱이에요.","en":"It does not stop at the answer but explains why the step works. It is a learning app, not an answer app."}},{"do":{"ko":"문제가 여러 개 있는 종이에 대고 인식 프레임을 줄여 하나만 골라 보세요.","en":"Aim at a page with several problems and shrink the recognition frame to pick just one."},"wow":{"ko":"인식 범위를 사용자가 직접 조절할 수 있어서 실패를 사용자 탓으로 돌리지 않아요.","en":"You adjust the recognition area yourself, so failure is never blamed on you."}}],"make":[{"ko":"Vision 텍스트 인식 결과를 바로 고칠 수 있는 입력창과 함께 보여 주는 화면을 만들어 보세요.","en":"Build a screen that shows Vision text recognition results next to a field where you can fix them."},{"ko":"결과 화면을 단계 목록으로 만들고 단계를 탭하면 설명이 펼쳐지게 해 보세요.","en":"Turn a result into a list of steps where tapping a step expands its explanation."}],"ask":{"ko":"인식이 틀려도 고칠 수 있다는 것이 왜 앱을 더 믿게 만들까요?","en":"Why does being able to fix a misreading make you trust the app more?"}},"Working Copy":{"time":20,"setup":{"ko":"클론해 볼 Git 저장소 주소와 다른 텍스트 에디터 앱 하나가 있으면 좋아요. 푸시는 일회성 Pro 구매가 필요해요.","en":"Have a Git repository URL to clone and another text editor app. Pushing needs a one-time Pro purchase."},"missions":[{"do":{"ko":"저장소를 클론한 뒤 다른 에디터 앱에서 파일 앱을 통해 그 저장소의 파일을 열고 고쳐 보세요.","en":"Clone a repository, then open and edit one of its files from another editor app through the Files app."},"wow":{"ko":"다른 앱이 Working Copy 안의 파일을 직접 열고 저장해요. 샌드박스를 우회하지 않고 File Provider를 정석대로 쓴 통합이에요.","en":"Another app opens and saves files inside Working Copy directly, using File Provider the proper way instead of hacking the sandbox."}},{"do":{"ko":"단축어 앱에서 Working Copy 액션을 찾아 커밋이나 풀을 넣은 단축어를 만들어 보세요.","en":"Find Working Copy actions in the Shortcuts app and build a shortcut that commits or pulls."},"wow":{"ko":"앱이 다른 앱과 자동화가 부르는 Git 엔진이 돼요.","en":"The app becomes a Git engine that other apps and automations can call."}},{"do":{"ko":"저장소 안의 HTML 파일을 미리보기로 열어 보세요.","en":"Open an HTML file in the repository in the preview."},"wow":{"ko":"자바스크립트 콘솔이 있는 미리보기라 iPad에서 정적 사이트를 고치고 바로 확인할 수 있어요.","en":"The preview has a JavaScript console, so you can edit and check a static site right on the iPad."}}],"make":[{"ko":"내 앱의 문서 폴더를 파일 앱에 보이게 설정하고 다른 앱에서 그 파일을 열어 보세요.","en":"Make your app's documents folder visible in the Files app and open a file from another app."},{"ko":"App Intents로 내 앱의 핵심 동작 하나를 단축어 액션으로 내보내 보세요.","en":"Expose one core action of your app as a Shortcuts action with App Intents."}],"ask":{"ko":"앱이 직접 다 하지 않고 다른 앱에 길을 열어 준 것이 왜 더 강력했을까요?","en":"Why was opening a path for other apps more powerful than doing everything itself?"}},"쿠팡":{"time":10,"setup":{"ko":"한국 계정이 필요해요. 실제 결제는 하지 않아도 돼요.","en":"You need a Korean account. You do not have to actually pay."},"missions":[{"do":{"ko":"자주 사는 물건 하나를 검색하고 목록에서 가격보다 먼저 도착 예정일을 보세요.","en":"Search for something you buy often and look at the arrival date in the list before the price."},"wow":{"ko":"목록부터 내일 도착 보장 같은 구체적인 날짜가 보여요. 이 약속은 직접 운영하는 물류센터와 배송 인력에서 나와요.","en":"Specific dates like guaranteed arrival tomorrow show right in the list. That promise comes from its own warehouses and delivery staff."}},{"do":{"ko":"상품을 장바구니에 담고 결제 직전 화면까지만 가 보세요.","en":"Put an item in the cart and go only as far as the screen right before payment."},"wow":{"ko":"배송지와 결제 수단이 미리 골라져 있어서 비밀번호 한 번이면 끝나는 구조예요.","en":"The address and payment method are already selected, so a single password would finish it."}},{"do":{"ko":"같은 계정으로 쿠팡이츠나 쿠팡플레이에도 들어가 보세요.","en":"Sign in to Coupang Eats or Coupang Play with the same account."},"wow":{"ko":"한 계정과 결제 정보로 묶여 있어서 쇼핑 밖으로도 앱을 쓰게 만들어요.","en":"One account and payment profile ties them together, pulling you in beyond shopping."}}],"make":[{"ko":"상품 목록 셀에 가격 옆이 아니라 위에 도착 날짜 배지를 단 화면을 만들어 비교해 보세요.","en":"Build a product list cell with the arrival date badge above the price instead of beside it, and compare."},{"ko":"저장된 주소와 결제 수단이 기본 선택된 한 화면짜리 결제 흐름을 프로토타입으로 만들어 보세요.","en":"Prototype a one-screen checkout with a saved address and payment method preselected."}],"ask":{"ko":"가격보다 도착 날짜를 먼저 보여 주는 것이 왜 구매 결정을 빠르게 할까요?","en":"Why does showing the arrival date before the price speed up the decision to buy?"}},"Hearing Buddy":{"time":15,"setup":{"ko":"여러 사람이 대화하는 자리가 있으면 가장 좋고, 친구의 iPhone이나 iPad가 있으면 캡션 공유도 해 볼 수 있어요.","en":"A group conversation works best, and a friend's iPhone or iPad lets you try caption sharing."},"missions":[{"do":{"ko":"여러 사람이 빠르게 대화하는 자리에서 실시간 자막을 켜 보세요.","en":"Turn on live captions where several people are talking quickly."},"wow":{"ko":"오가는 말이 기기 안에서 바로 자막이 돼요. 대화가 서버로 나가지 않아 분당 과금이 없고 그래서 무제한 무료예요.","en":"The back-and-forth becomes captions right on the device. Nothing goes to a server, so there is no per-minute cost and it stays free."}},{"do":{"ko":"캡션 공유 모드를 켜고 친구의 iPhone이나 iPad에서 같은 자막을 열어 보세요.","en":"Turn on shared captions and open the same transcript on a friend's iPhone or iPad."},"wow":{"ko":"아이폰 한 대가 방 전체의 대화를 받아 적고, 주변 사람들이 각자 화면에서 같은 자막을 봐요.","en":"One iPhone captions the whole room, and people nearby follow the same transcript on their own screens."}},{"do":{"ko":"자막 언어를 한국어로 바꾸고 한국어로 말해 보세요.","en":"Switch the caption language to Korean and speak Korean."},"wow":{"ko":"한국어, 일본어, 광둥어를 포함해 18개 언어와 지역 옵션을 지원해요.","en":"It supports 18 language and regional options, including Korean, Japanese and Cantonese."}}],"make":[{"ko":"Apple 온디바이스 음성 인식으로 마이크 입력을 실시간 텍스트로 띄우는 한 화면을 만들어 보세요.","en":"Build one screen that shows microphone input as live text using Apple's on-device speech recognition."},{"ko":"그 텍스트를 같은 방의 다른 기기에 보내 함께 보는 공유 화면을 프로토타입으로 만들어 보세요.","en":"Prototype a shared view that sends that text to another device in the same room."}],"ask":{"ko":"대화가 기기 밖으로 나가지 않는다는 것이 왜 무료와 신뢰를 동시에 가능하게 했을까요?","en":"How did keeping speech on the device make it both free and trustworthy?"}},"TR-49":{"time":30,"setup":{"ko":"유료 게임이에요. 풀 보이스라 소리를 켜거나 이어폰을 쓰세요.","en":"A paid game. It is fully voiced, so turn sound on or use earphones."},"missions":[{"do":{"ko":"첫 단서 조각에서 저자 이니셜과 연도를 찾아 네 글자 코드를 직접 입력해 보세요.","en":"Find an author's initials and a year in the first clue fragments and type the four-character code yourself."},"wow":{"ko":"맞는 코드를 넣으면 보관된 책이 열려요. 입력 방식이 곧 퍼즐이에요. 세 명이 9개월 만에 만들어 3시간 만에 손익분기점을 넘겼어요.","en":"The right code opens an archived book, so input is the puzzle. Three people made it in nine months and it broke even in three hours."}},{"do":{"ko":"한 기록에서 얻은 단서로 다른 기록을 열며 원하는 순서대로 오가 보세요.","en":"Use clues from one record to open another and move between them in any order you like."},"wow":{"ko":"약 50개 기록이 비선형으로 이어져서 내가 찾은 조각 순서대로 애비와 리엄의 이야기가 드러나요.","en":"About 50 records connect nonlinearly, so the story of Abbi and Liam emerges in the order you uncover it."}},{"do":{"ko":"소리를 켜고 기록이 열릴 때 들리는 목소리에 귀 기울여 보세요.","en":"With sound on, listen to the voices when a record opens."},"wow":{"ko":"풀 보이스 연기라서 그림보다 목소리로 장면이 그려지는 오디오 드라마처럼 느껴져요.","en":"Full voice acting makes it play like an audio drama, with scenes painted by voices more than art."}}],"make":[{"ko":"문자 두 개와 숫자 두 개를 입력하면 규칙에 맞을 때만 내용이 열리는 화면을 만들어 보세요.","en":"Build a screen where entering two letters and two numbers opens content only when it matches a rule."},{"ko":"열린 내용 안에 다음 코드의 단서를 숨겨 세 단계짜리 추리 흐름을 만들어 보세요.","en":"Hide the clue to the next code inside each unlocked entry to make a three-step deduction chain."}],"ask":{"ko":"직접 추론한 코드가 맞았을 때의 쾌감은 힌트 버튼과 무엇이 달랐나요?","en":"How did getting a code you deduced yourself feel different from using a hint button?"}},"Spilled!":{"time":20,"setup":{"ko":"처음 몇 구역은 무료이고, 전체는 한 번의 인앱 구매로 열려요.","en":"The first few areas are free, and one in-app purchase unlocks the full game."},"missions":[{"do":{"ko":"배를 몰아 기름띠 위를 지나간 뒤 지나온 길을 돌아보세요.","en":"Steer the boat through an oil slick, then look back at where you came from."},"wow":{"ko":"지나간 자리에 깨끗한 물이 남아요. 보트에서 자란 1인 개발자가 엄마와 태양광 보트로 개조한 배 위에서 만든 게임이에요.","en":"Clean water stays in your wake. A solo developer who grew up on boats made it aboard a boat she and her mother refitted with solar."}},{"do":{"ko":"도구를 바꿔 자석으로 가라앉은 드럼통을 낚고 호스로 불을 끄거나 강둑의 기름을 씻어 보세요.","en":"Switch tools to fish up sunken drums with the magnet and use the hose on fires or oily riverbanks."},"wow":{"ko":"도구마다 동작이 달라서 단순한 청소 설정이 계속 새로워요.","en":"Each tool has its own action, so a simple clean-up premise keeps feeling fresh."}},{"do":{"ko":"서두르지 말고 한 구역을 천천히 청소해 보세요.","en":"Take your time and clean one area slowly."},"wow":{"ko":"실패 조건이 없어서 서두를 이유가 없고, 환경 메시지가 글이 아니라 깨끗해지는 화면으로 전해져요.","en":"There is no fail state, so no reason to rush, and the environmental message comes through the cleaner screen, not text."}}],"make":[{"ko":"캐릭터가 지나간 자리만 색이 바뀌는 마스크 레이어를 SpriteKit으로 만들어 보세요.","en":"Use SpriteKit to make a mask layer that changes color only where the character has passed."},{"ko":"내 앱의 진행 상황을 숫자 대신 화면이 점점 깨끗해지는 시각 변화로 보여 줘 보세요.","en":"Show progress in your app as the screen gradually getting cleaner instead of a number."}],"ask":{"ko":"깨끗해진 물이 눈에 보이는 것만으로 왜 계속하고 싶어질까요?","en":"Why does simply seeing clean water make you want to keep going?"}},"Thank Goodness You're Here!":{"time":30,"setup":{"ko":"Mac 전용 유료 게임이에요.","en":"A paid game for Mac only."},"missions":[{"do":{"ko":"눈에 보이는 사물과 사람을 아무거나 때려 보세요.","en":"Slap any object or person you can see."},"wow":{"ko":"때리기 하나로 거의 모든 상호작용이 되고 모든 사물이 개그가 돼요. 반슬리의 어릴 적 친구 둘이 목소리 연기까지 직접 했어요.","en":"One slap handles almost every interaction and turns every object into a joke. Two childhood friends from Barnsley even voiced most of it."}},{"do":{"ko":"마을을 돌아다니며 측면 시점과 탑뷰가 바뀌는 순간을 지켜보세요.","en":"Walk around town and watch for the moment the view switches between side-on and top-down."},"wow":{"ko":"손그림 카툰이 시점을 바꿔 가며 장면마다 콩트처럼 연출돼요.","en":"The hand-drawn cartoon switches views so each scene is staged like a comedy sketch."}},{"do":{"ko":"첫 퀘스트를 따라가며 같은 농담이 다시 나오는지 살펴보세요.","en":"Follow the first quest and watch whether the same joke comes back."},"wow":{"ko":"반복 개그가 점점 커지고 퀘스트가 황당하게 번지면서 웃음이 시스템과 템포에서 나와요.","en":"Running gags escalate and quests spiral into absurdity, so the laughs come from systems and pacing."}}],"make":[{"ko":"버튼 하나만 있는 장면을 만들고 그 버튼이 사물마다 다른 반응을 일으키게 해 보세요.","en":"Make a scene with a single button that triggers a different reaction on each object."},{"ko":"같은 반응이 세 번째에 더 크게 터지는 반복 개그 규칙 하나를 넣어 보세요.","en":"Add a running-gag rule where the same reaction plays bigger on the third time."}],"ask":{"ko":"할 수 있는 동작이 하나뿐인데 왜 지루하지 않았을까요?","en":"With only one action available, why did it never get boring?"}},"Capybara AI Meeting Translator":{"time":15,"setup":{"ko":"Apple Intelligence를 지원하는 기기와 외국어 대화나 영상 하나를 준비하세요.","en":"Have a device that supports Apple Intelligence and a foreign-language conversation or video."},"missions":[{"do":{"ko":"외국어 영상이나 대화를 틀어 둔 채 녹음을 시작하고 화면을 지켜보세요.","en":"Start recording with a foreign-language video or conversation playing and watch the screen."},"wow":{"ko":"받아 적은 원문 바로 아래에 번역이 문장별로 붙고, 그동안 카피바라 한 마리가 물속에 느긋하게 앉아 있어요.","en":"Translations attach line by line right under the transcript, while a relaxed capybara sits in the water on screen."}},{"do":{"ko":"녹음을 끝내고 자동 요약이 나오면 연필 아이콘으로 한 줄을 고쳐 보세요.","en":"Stop recording, and when the summary appears, edit a line with the pencil icon."},"wow":{"ko":"제목과 글머리표로 정리된 요약을 바로 고칠 수 있어서 AI 결과가 고정된 산출물이 아니라 출발점이에요.","en":"The summary with headings and bullets can be edited on the spot, so the AI result is a starting point, not a locked output."}},{"do":{"ko":"Siri에게 이 노트 요약해줘라고 말해 보세요.","en":"Say Summarize this note to Siri."},"wow":{"ko":"App Intents로 연결돼 있어서 앱을 뒤지지 않아도 노트 요약과 검색이 말로 돼요.","en":"It is wired through App Intents, so summarizing and searching notes work by voice without digging through the app."}}],"make":[{"ko":"Translation 프레임워크로 입력한 문장 바로 아래에 번역이 붙는 두 줄짜리 셀을 만들어 보세요.","en":"Use the Translation framework to build a two-line cell with the translation right under each sentence."},{"ko":"긴 작업이 도는 동안 화면 구석에서 천천히 움직이는 마스코트 애니메이션 하나를 넣어 보세요.","en":"Add one mascot animation that moves slowly in a corner while a long task runs."}],"ask":{"ko":"느긋한 카피바라 한 마리가 왜 회의의 긴장을 줄여 줄까요?","en":"Why does one relaxed capybara make a meeting feel less tense?"}},"Ground News":{"time":15,"setup":null,"missions":[{"do":{"ko":"오늘 가장 큰 뉴스 하나를 열고, 편향 분포 막대에서 진보·중도·보수 매체가 각각 얼마나 다뤘는지 확인해 보세요.","en":"Open today's biggest story and check on the Bias Distribution bar how much left, center and right outlets each covered it."},"wow":{"ko":"같은 사건인데 한쪽은 많이 보도하고 다른 쪽은 거의 침묵하는 게 막대 하나로 드러나요. 매일 5만 개 이상 매체의 기사 약 6만 건을 모아 만든 그림이에요.","en":"For the same event, one side covers it heavily while the other is nearly silent, and a single bar shows it. It is built from about 60,000 articles a day from 50,000+ sources."}},{"do":{"ko":"Blindspot 피드를 열고, 평소 내가 보던 매체에서는 본 적 없는 기사가 있는지 찾아보세요.","en":"Open the Blindspot feed and look for stories you have never seen in the outlets you usually read."},"wow":{"ko":"한쪽 진영에서만 주로 다룬 기사가 모여 있어요. 같은 사건을 다른 어휘로 쓴 기사들도 자연어 처리로 한데 묶어 내요.","en":"It collects stories covered mostly by one side, and natural-language processing groups articles that describe the same event in different words."}},{"do":{"ko":"기사를 보도한 매체 하나를 골라, 그 매체를 누가 소유하고 있는지 정보를 찾아보세요.","en":"Pick one outlet that covered a story and look up who owns it."},"wow":{"ko":"무엇을 보도했는지뿐 아니라 누가 소유한 매체인지도 보여 줘요. 2,276개 이상 매체에 소유 구조 정보가 붙어 있어요.","en":"It shows not just what was reported but who owns the outlet; ownership data is attached to 2,276+ outlets."}}],"make":[{"ko":"같은 주제의 항목을 출처 성향별로 세 색으로 나눠, 한 줄짜리 비율 막대로 보여 주는 SwiftUI 뷰를 만들어 보세요.","en":"Build a SwiftUI view that splits items on one topic into three colors by source lean and shows them as a single ratio bar."},{"ko":"목록에서 한쪽 출처에만 몰린 항목만 골라내는 필터를 하나 추가해, 사용자가 놓친 것을 따로 보여 주세요.","en":"Add a filter that pulls out items covered by only one kind of source, so users see what they missed."}],"ask":{"ko":"숫자 표 대신 색 막대 하나로 보여 준 것이 왜 누가 침묵하는지를 더 빨리 느끼게 했을까요?","en":"Why does one colored bar, rather than a table of numbers, make you feel faster who is staying silent?"}},"NYT Games":{"time":15,"setup":{"ko":"주요 게임은 무료로 바로 할 수 있고, 아카이브와 전체 크로스워드는 구독이 필요해요.","en":"The headline games are free; archives and the full crossword need a subscription."},"missions":[{"do":{"ko":"오늘의 워들을 끝까지 풀고, 다 푼 뒤에 한 판 더 할 수 있는지 확인해 보세요.","en":"Finish today's Wordle, then see whether you can play another round."},"wow":{"ko":"하루 한 판뿐인데 2025년 한 해 이 앱에서 풀린 퍼즐이 112억 개, 그중 워들만 42억 번이에요. 덜 주는 것이 매일 돌아오게 만들어요.","en":"There is only one puzzle a day, yet players solved 11.2 billion puzzles in the app in 2025, 4.2 billion of them Wordle. Giving less brings people back daily."}},{"do":{"ko":"결과 공유 버튼을 눌러, 친구에게 보내질 내용을 확인해 보세요.","en":"Tap share on your result and look at what would be sent to a friend."},"wow":{"ko":"정답은 하나도 없이 어떻게 풀었는지만 이모지 격자로 담겨요. 스포일러 없이 자랑할 수 있어 풀이 하나하나가 홍보가 돼요.","en":"It is an emoji grid of how you played with no answer in it. You can brag without spoilers, so every solve becomes marketing."}},{"do":{"ko":"워들을 마친 뒤 허브로 돌아가, 바로 옆에 있는 커넥션스나 스펠링 비를 하나 열어 보세요.","en":"After Wordle, go back to the hub and open Connections or Spelling Bee right next to it."},"wow":{"ko":"2023년 Crosswords 앱이 NYT Games로 바뀌며 허브 중심으로 다시 설계됐어요. 워들 하러 온 사람이 옆 게임을 자연스럽게 발견해요.","en":"In 2023 the Crosswords app became NYT Games and was redesigned around a hub, so someone who came for Wordle naturally finds the game next to it."}}],"make":[{"ko":"콘텐츠가 하루에 하나만 열리고, 다 쓰면 내일 다시 오라고 알려 주는 잠금 화면을 만들어 보세요.","en":"Build a screen that unlocks one piece of content per day and, once it is used, tells people to come back tomorrow."},{"ko":"결과를 정답 없이 이모지 격자 텍스트로 바꿔 공유 시트로 보내는 함수를 짜 보세요.","en":"Write a function that turns a result into an emoji grid with no answer and sends it to the share sheet."}],"ask":{"ko":"하루 한 판이라는 제한이 왜 더 많이, 더 오래 하게 만들었을까요?","en":"Why does a limit of one puzzle a day make people play more, and for longer?"}},"quadline":{"time":15,"setup":{"ko":"￦3,300 유료 앱이에요.","en":"It is a paid app at 3,300 won."},"missions":[{"do":{"ko":"설명을 찾지 말고 첫 레벨을 바로 시작해, 처음 보는 기호를 일단 탭해 보세요.","en":"Do not look for instructions; start the first level and just tap the symbol you have never seen."},"wow":{"ko":"글자 한 줄, 튜토리얼 하나 없는데 규칙을 알게 돼요. 키이우의 1인 개발자가 175개 넘는 레벨을 기호와 움직임만으로 가르치게 만들었어요.","en":"There is not a line of text or a tutorial, yet you learn the rule. A solo developer in Kyiv made 175+ levels teach through symbols and motion alone."}},{"do":{"ko":"새 기호가 처음 나오는 레벨에서, 원형 화살표나 화살촉이 무엇을 하는지 직접 눌러 확인해 보세요.","en":"When a new symbol first appears, tap it to find out what a circular arrow or a chevron does."},"wow":{"ko":"원형 화살표는 회전, 화살촉은 컨베이어처럼 밀기예요. 10가지 핵심 메커닉 모두 기호 자체가 설명서 역할을 해요.","en":"Circular arrows rotate and chevrons push like conveyor belts. For all 10 core mechanics, the symbol itself is the manual."}},{"do":{"ko":"기기의 라이트·다크 모드를 바꿔 보고, 색에 기대지 않고도 퍼즐을 읽을 수 있는지 확인해 보세요.","en":"Switch between light and dark mode and check whether you can read the puzzle without relying on color."},"wow":{"ko":"흑백 도형으로만 만들어져 어떤 퍼즐 정보도 색에 의존하지 않아요. 색각 이상이 있어도 똑같이 풀 수 있어요.","en":"It is built from black-and-white shapes, so no puzzle information depends on hue, and colorblind players solve it the same way."}},{"do":{"ko":"일부러 어려운 레벨에서 한참 멈춰 서 보고, 막혔을 때 해답을 찾아보세요.","en":"Stall on a hard level on purpose, and when you are stuck, look for the solution."},"wow":{"ko":"내장된 해답이 있어 영영 막히지 않고, 타이머나 압박도 없어요. 한 번 탭하는 조작이라 손이 불편해도 할 수 있어요.","en":"Built-in solutions mean you never stay stuck, and there are no timers or pressure. One-tap controls keep it playable with limited dexterity."}}],"make":[{"ko":"온보딩 문장을 모두 지우고, 첫 화면에서 기호 하나가 스스로 움직여 규칙을 보여 주는 프로토타입을 만들어 보세요.","en":"Delete all onboarding text and build a prototype where one symbol moves on its own on the first screen to show the rule."},{"ko":"내 앱 화면을 흑백으로 캡처해, 색으로만 전달하는 정보를 찾아 모양으로 바꿔 보세요.","en":"Capture your app's screens in grayscale, find information carried only by color, and change it to shape."}],"ask":{"ko":"글자를 모두 빼자 왜 오히려 규칙이 더 빨리 이해됐을까요?","en":"Why did removing every word make the rules easier to grasp?"}},"Little Nightmares":{"time":20,"setup":{"ko":"￦4,400 유료 게임이고, MFi 게임 컨트롤러가 있으면 함께 준비해 보세요.","en":"It is a paid game at 4,400 won; have an MFi game controller ready if you own one."},"missions":[{"do":{"ko":"첫 장면을 터치로 기어가고 숨고 달아나며 해 보고, 컨트롤러가 있으면 연결해 같은 구간을 다시 해 보세요.","en":"Play the opening by touch, crawling, hiding and fleeing; if you have a controller, connect it and replay the same stretch."},"wow":{"ko":"콘솔·PC에서 200만 장 넘게 팔린 공포 플랫포머를 프랑스 이식 전문 스튜디오 Playdigious가 터치용으로 다시 짰어요. 두 조작을 비교해 보면 그 차이가 느껴져요.","en":"French port specialist Playdigious rebuilt a horror platformer that sold over 2 million copies on console and PC for touch. Comparing the two control styles shows the work."}},{"do":{"ko":"처음 거대한 어른이 나타나면 싸울 방법을 찾지 말고, 숨을 곳부터 찾아보세요.","en":"When the first giant adult appears, do not look for a way to fight; look for somewhere to hide."},"wow":{"ko":"주인공 식스는 일부러 약하게 만들어져 맞서 싸울 수 없어요. 잠입이 아니라 숨바꼭질이라 긴장은 숨고 기어가고 도망치는 데서 나와요.","en":"Six is deliberately vulnerable and cannot fight back. It is hide and seek, not stealth, so tension comes from hiding, crawling and fleeing."}},{"do":{"ko":"옆에서 비추는 장면마다 화면 앞쪽과 뒤쪽 깊이에 무엇이 있는지 살펴보세요.","en":"In each side-view scene, look at what sits in the foreground and the background."},"wow":{"ko":"2.5D 디오라마 구도라 거대하고 기괴한 어른들이 앞뒤에서 어른거려요. 대사 한 줄 없이 크기와 위협이 전해져요.","en":"The 2.5D diorama lets giant, grotesque adults loom in front and behind, conveying scale and threat without a line of dialogue."}}],"make":[{"ko":"공격 버튼 없이 숨기만 할 수 있는 짧은 장면을 만들어, 무력함이 긴장을 만드는지 시험해 보세요.","en":"Build a short scene where the player can only hide, with no attack button, and test whether helplessness creates tension."},{"ko":"같은 동작을 제스처와 화면 버튼 두 방식으로 구현해, 친구에게 둘 다 해 보게 하세요.","en":"Implement the same action with a gesture and with on-screen buttons, and have a friend try both."}],"ask":{"ko":"주인공에게 싸울 힘을 주지 않은 것이 왜 공포를 더 키웠을까요?","en":"Why does denying the hero any way to fight make the horror stronger?"}},"Meditate":{"time":10,"setup":{"ko":"Apple Watch가 있으면 손목 햅틱으로 명상하는 것까지 해 볼 수 있어요.","en":"If you have an Apple Watch, you can also try meditating with wrist haptics."},"missions":[{"do":{"ko":"짧은 명상 세션 하나를 끝까지 마치고, 끝난 뒤 만다라가 어떻게 변하는지 지켜보세요.","en":"Finish one short meditation session and watch how the mandala changes afterward."},"wow":{"ko":"배지나 숫자 대신 SwiftUI로 그린 나만의 만다라가 세션마다 피어나요. 인도 푸네의 인디 앱이 이 아이디어 하나로 2024 ADA Visuals 결선에 올랐어요.","en":"Instead of badges or numbers, your own SwiftUI mandala blooms with each session. An indie app from Pune reached the 2024 ADA Visuals finalists on this one idea."}},{"do":{"ko":"어제 명상하고 기록을 깜빡했다고 치고, 지난 날짜로 세션을 추가해 보세요.","en":"Pretend you meditated yesterday and forgot to log it, then add a session for that past date."},"wow":{"ko":"최대 7일 전까지 소급해 기록할 수 있어요. 진행 원, 인터벌 종소리와 햅틱, 배경 음악 같은 타이머 기본기도 꼼꼼해요.","en":"You can log up to 7 days back, and the timer basics are careful too: a progress circle, interval bells and haptics, and ambient music."}},{"do":{"ko":"Apple Watch가 있으면 휴대폰을 꺼내지 말고 손목에서만 명상을 시작해 보세요.","en":"If you have an Apple Watch, leave the phone in your pocket and start a session from your wrist."},"wow":{"ko":"완전히 독립된 Watch 앱이라 휴대폰 없이 손목 햅틱만으로 명상할 수 있어요.","en":"It is a fully independent Watch app, so you can meditate with wrist haptics and no phone."}}],"make":[{"ko":"완료 횟수에 따라 꽃잎 수가 늘어나는 SwiftUI 도형을 만들어, 숫자 카운터 대신 보여 주세요.","en":"Build a SwiftUI shape whose petals grow with each completion and show it instead of a number counter."},{"ko":"연속 기록이 이어지면 도형이 더 풍성해지는 상태를 하나 추가해 보세요.","en":"Add a state where the shape grows fuller while the streak continues."}],"ask":{"ko":"숫자 대신 자라는 그림을 보상으로 준 것이 왜 다시 명상하고 싶게 만들었을까요?","en":"Why does a growing picture, rather than a number, make you want to meditate again?"}},"stitch.":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"do":{"ko":"첫 후프를 골라 숫자 칸을 빈틈없이 채워 보고, 채울 때마다 화면을 가까이 들여다보세요.","en":"Pick your first Hoop, fill the numbered areas with no gaps, and look closely at the screen as you stitch."},"wow":{"ko":"숫자 퍼즐인데 자체 자수 엔진이 실제 실 질감을 그려요. 색각 이상·저시력·멀미용 옵션까지 넣어 2023 Inclusivity ADA를 받고 Innovation 결선에도 올랐어요.","en":"It is a number puzzle, but an in-house engine renders real thread texture. With options for color blindness, low vision and motion sensitivity it won the 2023 Inclusivity ADA and was an Innovation finalist."}},{"do":{"ko":"설정에서 Number Outlines와 Big Numbers를 켜고, Reduce Motion으로 애니메이션을 꺼 보세요.","en":"In settings, turn on Number Outlines and Big Numbers, and use Reduce Motion to turn off animations."},"wow":{"ko":"대비, 저시력, 움직임 민감을 각각 겨냥한 옵션이에요. 같은 퍼즐이 다른 눈과 몸에 맞게 바뀌어요.","en":"Each option targets contrast, low vision or motion sensitivity, so the same puzzle adapts to different eyes and bodies."}},{"do":{"ko":"다 완성한 후프를 Free Stitch 모드로 열어, 색을 마음대로 바꿔 보세요.","en":"Open a finished Hoop in Free Stitch mode and recolor it however you like."},"wow":{"ko":"끝난 작품을 다시 칠하며 놀 수 있어요. 실패가 없는 차분한 분위기가 퍼즐이 끝난 뒤에도 이어져요.","en":"You can keep playing by recoloring finished work, so the calm, no-fail mood continues after the puzzle ends."}}],"make":[{"ko":"숫자 격자를 채울 때 칸마다 실 질감 이미지를 입히는 셀을 만들어, 같은 퍼즐이 어떻게 달라 보이는지 비교해 보세요.","en":"Build a grid cell that paints a thread-texture image when filled, and compare how the same puzzle looks."},{"ko":"게임 설정에 큰 숫자, 윤곽선, 모션 줄이기 세 가지 토글을 먼저 만들어 보세요.","en":"Start your game's settings with three toggles: big numbers, outlines and reduce motion."}],"ask":{"ko":"같은 숫자 퍼즐인데 자수라는 옷을 입히자 왜 더 차분하게 느껴졌을까요?","en":"Why does the same number puzzle feel calmer once it is dressed as embroidery?"}},"Knotwords":{"time":15,"setup":null,"missions":[{"do":{"ko":"무료 데일리 미니를 열어 단서가 하나도 없다는 걸 확인한 뒤, 한 구역의 글자부터 배치해 보세요.","en":"Open the free Daily Mini, notice there are no clues at all, and start by placing the letters of one region."},"wow":{"ko":"단서 없는 크로스워드인데 퍼즐마다 정답이 딱 하나예요. 워들 열풍 전에 Good Sudoku를 만들다 나온 아이디어라 상식이 아니라 추론으로 풀어요.","en":"It is a crossword with no clues and exactly one solution per puzzle. The idea came from building Good Sudoku, before Wordle, so you solve by deduction, not trivia."}},{"do":{"ko":"막힐 것 같을 때 찍지 말고, 모든 가로세로 줄이 단어가 돼야 한다는 조건만으로 남은 칸을 좁혀 보세요.","en":"When you feel stuck, do not guess; narrow the remaining cells using only the rule that every row and column must be a word."},"wow":{"ko":"풀어 갈수록 퍼즐 구조가 유일한 해답 쪽으로 이끌어요. 추측 대신 스도쿠 같은 확신이 생겨요.","en":"As you go, the structure steers you toward the unique solution, giving sudoku-style certainty instead of guesswork."}}],"make":[{"ko":"작은 격자에 구역별 글자 묶음을 주고 모든 줄이 단어가 되게 하는 퍼즐을 종이로 먼저 만들어 보세요.","en":"On paper, make a small grid with a set of letters per region where every line must spell a word."},{"ko":"만든 퍼즐에 해답이 하나뿐인지 확인하는 간단한 검사 스크립트를 짜 보세요.","en":"Write a small script that checks whether your puzzle has exactly one solution."}],"ask":{"ko":"단서를 없애자 왜 크로스워드가 상식 시험이 아니라 논리 퍼즐이 됐을까요?","en":"Why did removing the clues turn a crossword from a trivia test into a logic puzzle?"}},"Beecarbonize":{"time":20,"setup":null,"missions":[{"do":{"ko":"첫 판에서 산업 쪽만 계속 키우고 배출량은 일부러 내버려 둬 보세요.","en":"In your first game, keep growing industry and deliberately ignore emissions."},"wow":{"ko":"기후 연구에 기반한 카드 120장이 시스템처럼 움직여 배출이 높아지면 홍수와 폭염이 닥쳐요. 이 실시간 전략 게임이 광고도 결제도 없이 완전 무료예요.","en":"Its 120 cards grounded in climate research act as a system, so high emissions bring floods and heatwaves. And this real-time strategy game is completely free, with no ads or microtransactions."}},{"do":{"ko":"원자력 카드가 보이면 써 보고, 이후 무슨 일이 생기는지 지켜보세요.","en":"When a nuclear power card shows up, use it and watch what follows."},"wow":{"ko":"원자력은 사고 위험을 높여요. 좋아 보이는 선택에도 대가가 붙는 구조라 정답 하나를 외울 수 없어요.","en":"Nuclear power raises the risk of incidents. Even good-looking choices carry costs, so there is no single answer to memorize."}},{"do":{"ko":"재해 이벤트가 뜨면 일시정지를 누르고 천천히 대응 방법을 골라 보세요.","en":"When a disaster event appears, pause and choose your response slowly."},"wow":{"ko":"재해에는 타이머가 붙지만, 일시정지와 속도 조절로 내 속도에 맞춰 생각할 수 있어요.","en":"Disasters come with timers, but pause and speed controls let you think at your own pace."}},{"do":{"ko":"한 번 이긴 뒤, 다른 승리 카드를 목표로 새 판을 해 보세요.","en":"After one win, start a new game aiming for a different winning card."},"wow":{"ko":"승리 카드가 여섯 장이라 지속 가능한 미래가 여러 모습이에요. 정답이 하나가 아니에요.","en":"There are six winning cards, each a different sustainable future, so there is no single correct answer."}}],"make":[{"ko":"자원 두 개와 배출 수치 하나만 있는 카드 게임을 만들고, 배출이 기준을 넘으면 재해가 터지게 해 보세요.","en":"Make a card game with two resources and one emissions value, and trigger a disaster when emissions cross a threshold."},{"ko":"승리 조건을 두 가지 이상 두어 서로 다른 전략이 모두 이길 수 있게 설계해 보세요.","en":"Design two or more win conditions so different strategies can all succeed."}],"ask":{"ko":"기후 문제를 설명 대신 실패하는 경험으로 보여 준 것이 왜 더 와닿았을까요?","en":"Why does showing climate change through failing, rather than explaining it, hit harder?"}},"Procreate":{"time":20,"setup":{"ko":"iPad 전용 앱이고 ￦22,000 한 번 구매예요. Apple Pencil이 있으면 더 좋아요.","en":"It is iPad only and a one-time purchase of 22,000 won; an Apple Pencil helps."},"missions":[{"do":{"ko":"새 캔버스에서 브러시 하나로 선을 빠르게, 또 느리게 그어 보세요. Apple Pencil이 있으면 힘도 달리 줘 보세요.","en":"On a new canvas, draw lines fast and slow with one brush; with an Apple Pencil, vary the pressure too."},"wow":{"ko":"자체 그래픽 엔진 Valkyrie가 그리는 선이에요. 호바트의 회사가 한 번 구매로 판 이 앱은 2018년 iPad 판매 1위였고 스타워즈 콘셉트 아트에도 쓰였어요.","en":"Those strokes come from Valkyrie, its own graphics engine. Sold as a one-time purchase by a company in Hobart, it was the best-selling iPad app of 2018 and used for Star Wars concept art."}},{"do":{"ko":"선을 몇 개 그은 뒤 두 손가락으로 탭하고, 이어서 세 손가락으로 탭해 보세요.","en":"Draw a few lines, then tap with two fingers, then with three."},"wow":{"ko":"두 손가락 탭은 실행 취소, 세 손가락 탭은 다시 실행이에요. 버튼 대신 제스처라 그림이 화면을 가득 채워요.","en":"Two-finger tap undoes and three-finger tap redoes. Gestures replace buttons, so the artwork fills the display."}},{"do":{"ko":"접근성 설정에서 떨림 보정 같은 옵션을 찾아 켜고, 일부러 손을 떨며 선을 그어 보세요.","en":"Find an option like tremor filtering in the accessibility settings, turn it on, and draw while shaking your hand on purpose."},"wow":{"ko":"떨림·움직임 필터, 보조 터치 메뉴, 소리 피드백, 색각 설정을 전문가 기능처럼 다뤄요.","en":"Tremor and motion filtering, an assistive touch menu, audio feedback and color-blindness settings are treated as pro features."}}],"make":[{"ko":"캔버스 앱 프로토타입에서 실행 취소 버튼을 지우고 두 손가락 탭 제스처로 바꿔 보세요.","en":"In a canvas prototype, remove the undo button and replace it with a two-finger tap."},{"ko":"PencilKit으로 필압에 따라 선 굵기가 바뀌는 그리기 화면을 만들어 보세요.","en":"Build a PencilKit drawing screen where line width follows pressure."}],"ask":{"ko":"버튼을 화면에서 지우고 제스처로 옮긴 것이 왜 전문가에게 더 빠르게 느껴졌을까요?","en":"Why does moving buttons off the screen and into gestures feel faster to professionals?"}},"Please, Touch The Artwork":{"time":15,"setup":{"ko":"￦6,600 유료 게임이에요.","en":"It is a paid game at 6,600 won."},"missions":[{"do":{"ko":"첫 몬드리안풍 격자 퍼즐을 손가락으로 선을 그으며 풀어 보세요.","en":"Solve the first Mondrian-style grid puzzle by drawing lines with your finger."},"wow":{"ko":"한 개발자가 어느 밤 몬드리안 그림 생성기를 코딩하다 퍼즐을 붙인 게 시작이에요. Divinity와 Hitman을 만들던 사람이 나머지를 혼자 만들었어요.","en":"It began one late night when a developer coded a Mondrian painting generator and added a puzzle. Someone who had worked on Divinity and Hitman built the rest solo."}},{"do":{"ko":"앙소르 그림 속 숨은 그림 찾기 장면이 나오면, 작품 구석구석을 직접 탭해 보세요.","en":"When you reach the hidden-object scenes inside Ensor paintings, tap every corner of the artwork."},"wow":{"ko":"숨은 물건을 찾다 보면 그림을 평소보다 훨씬 자세히 보게 돼요. 퍼즐이 그림 보는 법을 가르쳐요.","en":"Searching for hidden objects makes you look at the painting far more closely than usual. The puzzle teaches you how to look."}},{"do":{"ko":"키스 해링에서 영감을 받은 선 그리기 퍼즐이 나오면, 화면에 게임 UI가 얼마나 적은지 살펴보세요.","en":"When the Keith Haring-inspired line puzzles arrive, notice how little game UI is on screen."},"wow":{"ko":"UI를 최소로 줄여 작품 전체가 보여요. 게임 HUD가 아니라 명화가 주인공이에요.","en":"Minimal chrome keeps the whole artwork visible, so the painting, not a game HUD, is the hero."}}],"make":[{"ko":"명화 하나를 격자로 단순화해, 선을 그어 칸을 나누는 퍼즐을 한 단계 만들어 보세요.","en":"Simplify a painting into a grid and build one puzzle level where you draw lines to divide it."},{"ko":"게임 화면에서 버튼과 점수 표시를 모두 숨기고 터치만 남긴 버전을 만들어 비교해 보세요.","en":"Make a version of a game screen with every button and score hidden, leaving only touch, and compare."}],"ask":{"ko":"그림을 감상 대상이 아니라 만지는 퍼즐로 바꾸자 왜 더 오래 들여다보게 됐을까요?","en":"Why does turning a painting into something you touch make you look at it longer?"}},"Empathy":{"time":15,"setup":{"ko":"미국 스토어 기준 앱이라 지역에 따라 내려받지 못할 수도 있어요.","en":"It is a US App Store app, so it may not be available in your region."},"missions":[{"do":{"ko":"가족 상황을 가상으로 정해 개인 케어 플랜을 만들고, 할 일 목록을 끝까지 내려 보세요.","en":"Imagine a family situation, create a personal care plan, and scroll to the end of its task list."},"wow":{"ko":"회사 추산으로 가족 한 명이 사별 뒤 장례, 계정 해지, 유산 정리에 약 570시간을 써요. 대부분 앱이 피하는 이 일을 단계별 할 일로 바꿔요.","en":"By the company's estimate a family member spends about 570 hours on funerals, account closures and estates after a death. It turns that avoided problem into step-by-step tasks."}},{"do":{"ko":"계정이나 구독 해지 같은 할 일 하나를 골라, 케어 매니저에게 맡길 수 있는지 찾아보세요.","en":"Pick a task like closing an account or subscription and see whether a care manager can take it."},"wow":{"ko":"사람의 도움이 제품 안에 있어요. 케어 매니저가 안내하고 계정, 멤버십, 구독 해지 같은 일을 대신 처리해요.","en":"Human help is built in: care managers guide you and handle tasks like closing accounts, memberships and subscriptions."}},{"do":{"ko":"가족과 함께 쓰는 기능에서 할 일 하나를 다른 가족에게 맡긴다고 생각하며 살펴보세요.","en":"Explore the family collaboration feature as if you were handing one task to another relative."},"wow":{"ko":"최대 5명이 정보를 나누고 할 일을 나눠 맡아, 슬픔에 잠긴 한 사람에게 짐이 몰리지 않아요.","en":"Up to five people share information and split tasks, so the burden does not fall on one grieving relative."}},{"do":{"ko":"할 일 목록 말고 하루 치유 연습을 찾아, 일기나 호흡 연습을 하나 해 보세요.","en":"Step away from the task list, find the daily healing practice, and try one journal entry or breathing exercise."},"wow":{"ko":"행정 절차 바로 옆에 슬픔 돌봄이 있어요. 일기, 명상, 호흡 연습과 상속·세금 가이드를 한 앱에 함께 둬요.","en":"Grief care sits right beside the logistics: journaling, meditation and breathing next to guides on probate and taxes."}}],"make":[{"ko":"막막한 큰 일을 질문 몇 개로 받아 단계별 체크리스트로 쪼개 주는 화면을 만들어 보세요.","en":"Build a screen that takes an overwhelming job, asks a few questions, and breaks it into a step-by-step checklist."},{"ko":"체크리스트 항목마다 다른 사람에게 맡기기 버튼을 붙여, 혼자 다 하지 않아도 된다는 느낌을 주세요.","en":"Add a hand-off button to each checklist item so people feel they do not have to do it all alone."}],"ask":{"ko":"같은 할 일 목록인데 왜 이 앱의 톤과 순서는 사별한 사람을 덜 지치게 할까요?","en":"It is still a to-do list, so why do its tone and order tire a grieving person less?"}},"HoloVista":{"time":20,"setup":{"ko":"￦4,400 유료 게임이고, 휴대폰을 들고 몸을 돌릴 공간이 있으면 좋아요.","en":"It is a paid game at 4,400 won; you'll want room to turn around with your phone."},"missions":[{"do":{"ko":"휴대폰을 들고 몸을 돌려 방을 둘러본 뒤, 설정에서 모션 대체 조작으로 바꿔 같은 방을 다시 둘러보세요.","en":"Turn your body with the phone to look around a room, then switch to the motion-control alternative in settings and look again."},"wow":{"ko":"휴대폰을 움직이는 게 핵심인 게임인데 움직이지 않고도 할 수 있어요. 글자 크기·대비·소리·효과 강도까지 조절돼 2021 ADA Inclusivity를 받았어요.","en":"The game is built on moving your phone, yet you can play without moving. Text size, contrast, sound and effect intensity adjust too, which won it the 2021 Inclusivity ADA."}},{"do":{"ko":"방에서 사진을 찍어 게임 속 소셜 피드에 올리고, 캐릭터들의 반응을 확인해 보세요.","en":"Take a photo in a room, post it to the in-game social feed, and see how the characters react."},"wow":{"ko":"찍은 사진이 그대로 이야기가 돼요. 소셜 미디어와 진정성에 대한 비판을 설명이 아니라 메커닉으로 전해요.","en":"Your photos become the story. Its critique of social media and authenticity is delivered through the mechanic, not explained."}}],"make":[{"ko":"자이로로 시점을 돌리는 장면에, 드래그로 시점을 돌리는 대체 조작을 함께 넣어 보세요.","en":"In a scene where the gyroscope turns the view, add an alternative that turns it by dragging."},{"ko":"찍은 사진이 가짜 피드에 올라가고 댓글이 달리는 흐름을 프로토타입으로 만들어 보세요.","en":"Prototype a flow where a photo you take goes to a fake feed and gets comments."}],"ask":{"ko":"몸을 움직이는 게임에 움직이지 않는 방법을 넣었는데 왜 경험이 줄지 않았을까요?","en":"Why did adding a way to play without moving not shrink the experience of a game about moving?"}},"Wonderbox":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라, 개발사의 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"개발사 트레일러에서 아이들이 만든 모험을 다른 사람이 플레이하는 장면을 찾아보세요.","en":"In the developer's trailer, look for scenes of people playing adventures that other players built."},"wow":{"ko":"아이들이 모험을 만들고 서로의 작품을 하는 Apple Arcade 게임이었어요. 2023년 Epic Games가 이 게임을 만든 브라질 스튜디오를 통째로 인수했어요.","en":"It was an Apple Arcade game where kids built adventures and played each other's creations, and in 2023 Epic Games bought the whole Brazilian studio behind it."}},{"do":{"ko":"트레일러나 스크린숏에서 한 작품 안에 액션, 플랫폼, 퍼즐이 섞인 장면을 찾아보세요.","en":"In the trailer or screenshots, look for one creation that mixes action, platforming and puzzles."},"wow":{"ko":"모험 하나에 아케이드 액션, 플랫포밍, 퍼즐이 함께 들어가요. 그런데도 8세 이상 아이가 만들 수 있게 도구를 쉽게 설계했어요.","en":"A single adventure mixes arcade action, platforming and puzzles, yet the tools were made simple enough for kids aged 8 and up."}}],"make":[{"ko":"작은 게임에 만들기 모드를 붙여, 블록 몇 개만 놓으면 바로 플레이해 볼 수 있게 해 보세요.","en":"Add a make mode to a small game so placing a few blocks lets you play right away."},{"ko":"만든 레벨을 문자열로 내보내 친구가 불러와 플레이할 수 있게 해 보세요.","en":"Export a level as a string so a friend can import and play it."}],"ask":{"ko":"플레이하는 사람을 만드는 사람으로 바꾼 것이 왜 큰 회사가 스튜디오를 통째로 살 만큼 가치 있었을까요?","en":"Why was turning players into makers valuable enough for a big company to buy the whole studio?"}},"Klima":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라, 개발사의 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"개발사 트레일러나 스크린숏에서 생활 습관 질문 몇 개로 탄소 발자국이 계산되는 장면을 찾아보세요.","en":"In the developer's trailer or screenshots, find where a few lifestyle questions produce a carbon footprint."},"wow":{"ko":"몇 가지 질문으로 탄소 발자국을 계산해 그만큼을 월 구독으로 상쇄하게 했어요. 이 방식으로 18개국에 공개 출시하며 580만 달러를 이미 모았어요.","en":"A few questions sized your footprint and turned it into a monthly offset subscription; it launched publicly in 18 countries with $5.8M already raised."}},{"do":{"ko":"스크린숏에서 나무 심기, 태양광, 깨끗한 조리 화덕 중 무엇을 후원할지 고르는 화면을 찾아보세요.","en":"In the screenshots, find where you choose between tree planting, solar installations and clean cookstoves."},"wow":{"ko":"추상적인 숫자가 내가 고른 구체적인 프로젝트가 돼요. Gold Standard나 VCS 인증 프로젝트만 써서 그린워싱 무관용 약속을 뒷받침했어요.","en":"An abstract number becomes a concrete project you chose, and only Gold Standard or VCS certified projects back the zero-greenwashing promise."}}],"make":[{"ko":"질문 세 개로 점수를 계산하고, 그 점수를 바로 월 금액으로 보여 주는 화면을 만들어 보세요.","en":"Build a screen that scores three questions and immediately shows the score as a monthly amount."},{"ko":"결과 화면에서 돈이 어디로 가는지 세 가지 선택지 중 고르게 해 보세요.","en":"On the result screen, let people pick where the money goes from three choices."}],"ask":{"ko":"탄소 숫자를 월 구독료로 바꾼 것이 왜 행동을 더 쉽게 만들었을까요?","en":"Why did turning a carbon number into a monthly fee make acting on it easier?"}},"Museum Alive":{"time":15,"setup":{"ko":"￦4,400 유료 앱이고, AR을 쓰니 바닥이 넓은 방에서 해 보세요.","en":"It is a paid app at 4,400 won and uses AR, so try it in a room with open floor space."},"missions":[{"do":{"ko":"바닥이 넓은 곳에 화석을 하나 놓고, 데이비드 애튼버러의 내레이션이 나오는 동안 지켜보세요.","en":"Place a fossil on open floor and watch while David Attenborough narrates."},"wow":{"ko":"거실 바닥의 화석이 되살아나요. 눈이 다섯인 오파비니아, 검치호 스밀로돈 같은 멸종 동물이 사진 측량으로 담은 서식지와 함께 움직여요.","en":"The fossil on your floor comes back to life: extinct creatures like five-eyed Opabinia and sabre-toothed Smilodon move in photogrammetry-captured habitats."}},{"do":{"ko":"되살아난 동물 주위를 걸어 돌며 인터랙티브 핫스팟을 탭해 보세요.","en":"Walk around the revived creature and tap its interactive hotspots."},"wow":{"ko":"생물마다 애튼버러 영상, 정보 자료, 이미지와 서식지·생태계 핫스팟이 붙어요. BAFTA를 받은 2014년 다큐가 손안의 박물관이 돼요.","en":"Each creature comes with Attenborough videos, info packs, images and habitat hotspots, turning a BAFTA-winning 2014 documentary into a museum in your hand."}}],"make":[{"ko":"ARKit으로 바닥 평면을 찾아 3D 모델을 실제 크기로 놓는 데모를 만들어 보세요.","en":"Build an ARKit demo that finds the floor and places a 3D model at real scale."},{"ko":"놓인 모델을 탭하면 짧은 내레이션 오디오가 재생되게 해 보세요.","en":"Make tapping the placed model play a short narration clip."}],"ask":{"ko":"화면 속 박물관이 아니라 내 거실에 놓았다는 것이 왜 더 놀랍게 느껴졌을까요?","en":"Why is it more astonishing when the creature is in your living room rather than in a museum on screen?"}},"Noom":{"time":20,"setup":{"ko":"설문형 온보딩을 끝까지 하려면 시간이 걸리고, 마지막에 결제 화면이 나와요.","en":"The survey-style onboarding takes a while to finish and ends at a payment screen."},"missions":[{"do":{"ko":"설문형 온보딩을 진행하면서, 질문 사이에 끼어드는 요약 화면을 눈여겨보세요.","en":"Go through the survey-style onboarding and watch for the summary screens between questions."},"wow":{"ko":"내가 입력한 답을 반영한 중간 요약과 설명이 나와요. 정보를 빼앗기는 게 아니라 나를 이해해 가는 과정처럼 느껴져요.","en":"Summaries and explanations reflecting your answers appear, so it feels like being understood rather than having data collected."}},{"do":{"ko":"질문이 많아 지칠 때쯤 화면 위쪽 진행 표시를 보세요.","en":"When the questions start to wear you out, look at the progress indicator at the top."},"wow":{"ko":"긴 설문을 짧은 화면 단위로 쪼개고 얼마나 남았는지 계속 보여 줘요. 질문이 많아도 끝까지 가게 돼요.","en":"The long survey is split into short screens and keeps showing how much is left, so you finish despite the number of questions."}},{"do":{"ko":"마지막까지 가서 개인화된 목표 달성 예측을 본 뒤, 바로 다음 화면이 무엇인지 확인해 보세요.","en":"Reach the end, look at the personalized goal prediction, and see what screen comes right after."},"wow":{"ko":"예측 바로 뒤에 결제가 나와요. 긴 설문이 사실은 구독 전환 퍼널의 핵심이에요.","en":"Payment comes right after the prediction. The long survey is the core of the subscription funnel."}}],"make":[{"ko":"설문 세 문항마다 답을 반영한 요약 화면 하나를 끼워 넣는 온보딩 프로토타입을 만들어 보세요.","en":"Prototype an onboarding that inserts a summary of the answers after every three questions."},{"ko":"설문 마지막에 입력값으로 계산한 간단한 예측 그래프를 보여 주는 화면을 만들어 보세요.","en":"Build a final screen that shows a simple prediction graph calculated from the answers."}],"ask":{"ko":"질문을 더 많이 했는데도 왜 사용자는 끝까지 가고 싶어졌을까요?","en":"Why did asking more questions make people want to reach the end?"}},"Otter.ai":{"time":15,"setup":{"ko":"함께 대화할 사람이 한 명 있으면 화자 구분까지 확인할 수 있어요.","en":"Having a second person to talk with lets you see speaker separation too."},"missions":[{"do":{"ko":"녹음을 시작하고 다른 사람과 번갈아 말하면서, 화면의 전사문을 지켜보세요.","en":"Start recording, take turns speaking with someone, and watch the transcript on screen."},"wow":{"ko":"말하는 동안 글이 실시간으로 이어지고 화자별로 자동으로 나뉘어요. 대화를 자막처럼 따라갈 수 있어요.","en":"The text flows in real time as you talk and splits by speaker automatically, so you can follow the conversation like captions."}},{"do":{"ko":"녹음이 끝나면 전사문의 단어 하나를 탭하고, 잘못 알아들은 부분을 그 자리에서 고쳐 보세요.","en":"After recording, tap a word in the transcript and fix a misheard part right there."},"wow":{"ko":"단어를 탭하면 그 구간 오디오가 재생돼요. 듣고 고치는 흐름이 한 화면에서 끝나요.","en":"Tapping a word plays that moment of audio, so listening and fixing happen on one screen."}},{"do":{"ko":"조금 긴 대화를 녹음한 뒤, AI 요약에서 결정 사항과 할 일이 어떻게 뽑혔는지 보세요.","en":"Record a longer conversation, then see how the AI summary pulls out decisions and action items."},"wow":{"ko":"긴 전사문을 다 읽지 않아도 결정 사항과 액션 아이템이 자동으로 정리돼요.","en":"Decisions and action items are pulled out automatically, so you get the gist without reading the whole transcript."}}],"make":[{"ko":"음성 인식 결과를 단어별 타임스탬프와 함께 저장하고, 단어를 탭하면 그 시점부터 재생되게 해 보세요.","en":"Store speech recognition results with per-word timestamps and play from that moment when a word is tapped."},{"ko":"녹음 버튼을 누르면 먼저 상대의 동의를 묻는 화면이 뜨는 흐름을 만들어 보세요.","en":"Build a flow where pressing record first shows a screen asking for the other person's consent."}],"ask":{"ko":"글자와 소리를 단어 단위로 묶은 것이 왜 고치는 일을 이렇게 쉽게 만들었을까요?","en":"Why did linking text and audio word by word make correcting so easy?"}},"Pinterest":{"time":10,"setup":null,"missions":[{"do":{"ko":"홈 피드를 빠르게 내리면서, 이미지가 뜨기 직전 빈 칸이 어떤 색인지 보세요.","en":"Scroll the home feed fast and notice the color of each cell just before its image loads."},"wow":{"ko":"빈 회색 상자 대신 그 이미지의 대표 색으로 칸이 먼저 채워져요. 레이아웃이 먼저 잡혀 로딩이 기다림처럼 느껴지지 않아요.","en":"Instead of a gray box, each cell is filled with the image's dominant color, so the layout settles first and loading does not feel like waiting."}},{"do":{"ko":"핀 하나를 탭하고, 그리드 속 이미지가 어떻게 상세 화면으로 넘어가는지 천천히 보세요.","en":"Tap a pin and watch closely how the grid image turns into the detail screen."},"wow":{"ko":"그리드의 이미지가 그대로 커지며 상세 화면이 돼요. 화면이 바뀌어도 방금 본 이미지를 놓치지 않아요.","en":"The grid image itself grows into the detail view, so you never lose the picture you just saw."}},{"do":{"ko":"상세 화면에서 아래로 계속 내려 보세요.","en":"On the detail screen, keep scrolling down."},"wow":{"ko":"바로 비슷한 핀 그리드가 이어져요. 이미지 하나를 보는 순간이 곧 다음 탐색의 시작이 돼요.","en":"A grid of similar pins follows right away, so looking at one image becomes the start of the next search."}},{"do":{"ko":"Pinterest Lens로 사진을 찍고, 그중 일부 영역만 골라 보세요.","en":"Take a photo with Pinterest Lens and select just one part of it."},"wow":{"ko":"고른 부분과 비슷한 핀을 찾아 줘요. 검색어를 몰라도 탐색이 이어져요.","en":"It finds pins similar to that part, so exploring continues even when you have no words to search."}}],"make":[{"ko":"이미지 URL과 대표 색 값을 함께 받아, 로딩 전 셀을 그 색으로 채우는 그리드를 만들어 보세요.","en":"Build a grid that receives a dominant color with each image URL and fills the cell with it before loading."},{"ko":"SwiftUI matchedGeometryEffect로 그리드 셀이 상세 화면으로 커지는 전환을 만들어 보세요.","en":"Use SwiftUI matchedGeometryEffect to make a grid cell grow into a detail screen."}],"ask":{"ko":"로딩 칸을 대표 색으로 채운 것이 왜 실제보다 빨리 뜨는 것처럼 느껴졌을까요?","en":"Why does filling loading cells with the dominant color make images feel faster than they are?"}},"Figma":{"time":15,"setup":{"ko":"확인할 Figma 파일이나 프로토타입 링크가 하나 있어야 해요.","en":"You need a Figma file or prototype link to look at."},"missions":[{"do":{"ko":"프로토타입 링크를 모바일 앱에서 풀스크린으로 실행하고, 버튼을 직접 누르고 스크롤해 보세요.","en":"Run a prototype link full screen in the mobile app, and press buttons and scroll with your own fingers."},"wow":{"ko":"데스크톱 미리보기로는 알기 어려운 터치 영역과 스크롤 감각이 실제 기기에서 바로 드러나요.","en":"Touch targets and scroll feel, hard to judge in a desktop preview, show up immediately on a real device."}},{"do":{"ko":"파일을 열어 편집 도구를 찾아보고, 대신 무엇이 남아 있는지 확인해 보세요.","en":"Open a file, look for the editing tools, and see what is there instead."},"wow":{"ko":"편집을 억지로 옮기지 않고 보기, 프로토타입 실행, 댓글에 집중했어요. 작은 화면에서 할 일을 일부러 좁혔어요.","en":"Rather than force editing onto the phone, it focuses on viewing, running prototypes and commenting, deliberately narrowing the job for a small screen."}},{"do":{"ko":"데스크톱에서 파일을 고친 뒤, 모바일 앱에서 같은 파일을 열어 보세요.","en":"Change a file on the desktop, then open the same file in the mobile app."},"wow":{"ko":"파일이 클라우드에 하나로 있어서 모바일에서 여는 게 곧 최신 버전을 여는 거예요.","en":"The file exists once in the cloud, so opening it on mobile is opening the latest version."}}],"make":[{"ko":"내 앱 화면 목업을 Figma 프로토타입으로 연결해, 휴대폰에서 풀스크린으로 눌러 보세요.","en":"Link your app mockups into a Figma prototype and tap through it full screen on your phone."},{"ko":"내 앱의 모바일 버전에서 꼭 필요한 동작 세 가지만 남기고 나머지를 지운 화면을 그려 보세요.","en":"Sketch a mobile version of your app that keeps only three essential actions and removes the rest."}],"ask":{"ko":"편집 기능을 빼고 보기와 댓글만 남긴 것이 왜 모바일에서 더 쓸모 있게 만들었을까요?","en":"Why did removing editing and keeping only viewing and comments make the mobile app more useful?"}},"Google":{"time":10,"setup":null,"missions":[{"do":{"ko":"Google 앱의 렌즈를 열고 외국어 메뉴판이나 표지판에 카메라를 댄 뒤 번역 모드로 바꿔 보세요.","en":"Open Lens in the Google app, point it at a foreign-language menu or sign, and switch to translate."},"wow":{"ko":"번역문이 원문 자리에 그대로 덮여요. 메뉴판 레이아웃은 그대로인 채 내 언어로 읽혀요.","en":"The translation is laid right over the original text, so the menu keeps its layout and reads in your language."}},{"do":{"ko":"셔터를 누르지 말고, 카메라를 책이나 바코드에 대고 가만히 있어 보세요.","en":"Do not press the shutter; just hold the camera over a book or a barcode."},"wow":{"ko":"누르기 전부터 인식된 텍스트, 물체, 바코드가 실시간으로 하이라이트돼요. 무엇을 할 수 있는지 먼저 알려 줘요.","en":"Text, objects and barcodes are highlighted live before you press anything, telling you what you can do first."}},{"do":{"ko":"물건 사진을 찍은 뒤, 궁금한 점을 글로 덧붙여 검색해 보세요.","en":"Take a photo of an object, then add a question in words and search."},"wow":{"ko":"사진과 글을 함께 써서 묻는 멀티서치예요. 이미지와 언어를 한 번에 섞어 검색해요.","en":"This is multisearch: you ask with a photo and words together, mixing image and language in one query."}}],"make":[{"ko":"Vision 프레임워크로 카메라 프리뷰에서 텍스트를 찾아, 그 위에 하이라이트 상자를 그려 보세요.","en":"Use the Vision framework to find text in a camera preview and draw highlight boxes over it."},{"ko":"인식한 텍스트 자리에 다른 문자열을 같은 크기로 덮어씌우는 오버레이를 만들어 보세요.","en":"Build an overlay that covers recognized text with another string at the same size."}],"ask":{"ko":"번역을 따로 보여 주지 않고 원문 자리에 덮은 것이 왜 더 마법처럼 느껴졌을까요?","en":"Why does laying the translation over the original feel more magical than showing it separately?"}},"Scriptable":{"time":30,"setup":{"ko":"무료 앱이고, JavaScript를 조금 알면 더 쉽게 해 볼 수 있어요.","en":"It is free, and a little JavaScript knowledge makes it easier."},"missions":[{"do":{"ko":"ListWidget으로 글자 한 줄을 띄우는 스크립트를 쓰고, 홈 화면에 Scriptable 위젯을 추가해 연결해 보세요.","en":"Write a script that shows one line of text with ListWidget, add a Scriptable widget to the Home Screen, and link it."},"wow":{"ko":"내가 쓴 JavaScript 몇 줄이 홈 화면 위젯이 돼요. Apple이 열어 두지 않은 위젯 커스터마이징을 스크립트로 열었어요.","en":"A few lines of your own JavaScript become a Home Screen widget, opening up widget customization Apple never exposed."}},{"do":{"ko":"같은 스크립트를 Siri 단축어에서 실행되게 연결해 보세요.","en":"Hook the same script up so it runs from a Siri Shortcut."},"wow":{"ko":"스크립트를 단축어, 공유 시트, x-callback-url에서 실행할 수 있어 다른 앱과 자동화 흐름으로 이어져요.","en":"Scripts run from Shortcuts, the share sheet and x-callback-url, so they chain into automations with other apps."}},{"do":{"ko":"비행기 모드를 켜고 앱 안의 API 문서를 열어 보세요.","en":"Turn on Airplane Mode and open the API documentation inside the app."},"wow":{"ko":"모든 API 문서가 앱 안에 오프라인으로 들어 있어요. 스크립트도 파일 앱에 일반 JS 파일로 저장돼요.","en":"All the API docs are inside the app and work offline, and scripts are saved as plain JS files in the Files app."}}],"make":[{"ko":"Scriptable로 오늘 날짜와 남은 할 일 수를 보여 주는 위젯을 직접 만들어 보세요.","en":"Use Scriptable to build a widget showing today's date and how many tasks are left."},{"ko":"내 앱의 기능 하나를 URL 스킴으로 열어 두고, 단축어에서 호출해 보세요.","en":"Expose one feature of your app through a URL scheme and call it from Shortcuts."}],"ask":{"ko":"위젯을 앱 기능이 아니라 사용자가 코딩하는 플랫폼으로 연 것이 왜 강력했을까요?","en":"Why was opening widgets as a platform users code, rather than a fixed app feature, so powerful?"}},"리멤버":{"time":15,"setup":{"ko":"받아 둔 종이 명함이 한 장 있어야 해요.","en":"You need at least one paper business card."},"missions":[{"do":{"ko":"종이 명함 한 장을 촬영하고, 정보가 바로 채워지는지 기다리는 상태가 나오는지 지켜보세요.","en":"Photograph a paper business card and watch whether the details fill in instantly or a waiting state appears."},"wow":{"ko":"OCR에만 맡기지 않고 약 1,000명의 타이피스트가 직접 입력하는 방식으로 시작했어요. 촬영 직후와 입력 완료 후를 나눠 보여 주는 대기 화면도 그래서 생겼어요.","en":"Instead of relying on OCR alone, it started with about 1,000 typists entering cards by hand, which is why it separates the just-photographed and completed states."}},{"do":{"ko":"저장한 명함 중 오래된 것을 열어, 정보가 바뀌었거나 승진·이직 알림이 왔는지 확인해 보세요.","en":"Open an older saved card and check whether its details changed or a promotion or job-change alert arrived."},"wow":{"ko":"상대가 회사나 직책을 바꾸면 명함 정보가 갱신되는 살아있는 명함이에요. 한 번 저장한 데이터가 계속 가치를 가져요.","en":"It is a living card that updates when the person changes company or title, so data saved once keeps its value."}}],"make":[{"ko":"사진을 올린 뒤 처리 중과 완료 상태를 다르게 보여 주는 카드 UI를 만들어 보세요.","en":"Build a card UI that shows a processing state and a done state differently after a photo is uploaded."},{"ko":"저장된 데이터가 바뀌면 사용자에게 알려 주는 살아있는 기록 흐름을 하나 설계해 보세요.","en":"Design a living-record flow that notifies the user when saved data changes."}],"ask":{"ko":"기계 대신 사람이 입력해 느려졌는데도 왜 사용자는 더 믿게 됐을까요?","en":"Having people type the cards made it slower, so why did users trust it more?"}},"Structured":{"time":10,"setup":null,"missions":[{"do":{"ko":"오늘 할 일과 캘린더 일정을 넣고, 하루 전체가 세로 타임라인 하나로 펼쳐지는 걸 보세요.","en":"Add today's tasks and calendar events and watch the whole day lay out as one vertical timeline."},"wow":{"ko":"할 일과 일정이 시간 순 색 블록으로 놓여 빈 시간과 과부하가 한눈에 보여요. 이 독일 플래너는 1,500만 다운로드에 하루 60만 개 넘는 작업이 만들어져요.","en":"Tasks and events sit in time order as colored blocks, so gaps and overloads are visible at once. This German planner has 15 million downloads and 600,000+ tasks created daily."}},{"do":{"ko":"새 할 일을 추가하면서 앱이 제안하거나 미리 채워 주는 내용을 확인해 보세요.","en":"Add a new task and look at what the app suggests or fills in for you."},"wow":{"ko":"Apple 온디바이스 Foundation Models로 할 일을 제안하고 미리 채워요. 계획을 시작하는 부담이 줄어 ADHD 커뮤니티가 특히 좋아해요.","en":"It uses Apple's on-device Foundation Models to suggest and pre-fill tasks, lowering the effort of starting, which the ADHD community praises."}},{"do":{"ko":"잠금 화면에 Structured 위젯을 추가하고, 앱을 열지 않은 채 다음 할 일을 확인해 보세요.","en":"Add a Structured widget to the Lock Screen and check what is next without opening the app."},"wow":{"ko":"타임라인이 위젯과 알림으로 압축돼서 지금과 다음 할 일을 앱 밖에서 바로 봐요.","en":"The timeline is compressed into widgets and notifications, so you see now and next outside the app."}}],"make":[{"ko":"할 일 배열을 시간 순 세로 블록으로 그리고, 블록 사이 빈 시간을 따로 표시하는 SwiftUI 뷰를 만들어 보세요.","en":"Build a SwiftUI view that draws tasks as vertical blocks in time order and marks the free gaps between them."},{"ko":"다음 할 일 하나만 보여 주는 잠금 화면 위젯을 WidgetKit으로 만들어 보세요.","en":"Build a WidgetKit Lock Screen widget that shows only the next task."}],"ask":{"ko":"목록 대신 시간 축 위에 놓은 것이 왜 빈 시간과 과부하를 바로 보이게 했을까요?","en":"Why does placing tasks on a time axis, instead of a list, make gaps and overloads obvious?"}},"Moonlitt: Moon Phase Tracker":{"time":10,"setup":{"ko":"밖이나 창가에서 해 보면 실제 달 방향과 비교할 수 있어요.","en":"Try it outdoors or by a window so you can compare with the real moon."},"missions":[{"do":{"ko":"앱을 열자마자 아무것도 누르지 말고, 화살표가 가리키는 쪽을 실제 하늘과 비교해 보세요.","en":"Open the app, touch nothing, and compare where the arrow points with the real sky."},"wow":{"ko":"화면 전체가 나침반이 돼 지금 선 자리에서 달이 있는 방향을 가리켜요. 탭 한 번 없이 답이 나와요.","en":"The whole screen becomes a compass pointing to the moon from where you stand, an answer with zero taps."}},{"do":{"ko":"시간 슬라이더를 앞뒤로 천천히, 또 빠르게 끌어 보세요.","en":"Drag the time slider back and forth, slowly and then quickly."},"wow":{"ko":"달이 궤적을 따라 미끄러지고 손에 햅틱이 전해져요. 팀은 이 슬라이더의 반응과 햅틱만 몇 달 동안 다듬었어요.","en":"The moon glides along its path as haptics tick in your hand. The team spent months tuning just this slider's response and haptics."}},{"do":{"ko":"다가오는 보름달이나 월식 일정을 찾아 설명을 읽어 보세요.","en":"Find an upcoming full moon or eclipse and read its description."},"wow":{"ko":"Apple Intelligence가 달 이벤트를 쉬운 말로 요약하고, 보름달의 전통 이름이나 중추절 같은 문화 맥락도 덧붙여요.","en":"Apple Intelligence summarizes lunar events in plain language and adds cultural context such as traditional full moon names and the Mid-Autumn Festival."}}],"make":[{"ko":"CoreLocation의 나침반 방향으로 특정 방위를 가리키는 화살표를 첫 화면에 띄워 보세요.","en":"Use CoreLocation heading to show an arrow pointing to a fixed bearing on the first screen."},{"ko":"슬라이더 값이 바뀔 때마다 sensoryFeedback 햅틱을 주고, 간격을 바꿔 가며 손맛을 비교해 보세요.","en":"Fire a sensoryFeedback haptic as a slider value changes, and compare the feel at different step sizes."}],"ask":{"ko":"앱을 열자마자 답을 보여 준 것이 왜 메뉴 하나 없이도 충분했을까요?","en":"Why was showing the answer the moment the app opens enough, with no menu at all?"}},"Caradise":{"time":15,"setup":{"ko":"Apple Vision Pro 전용 앱이고, 무료 스타터 팩 세 대로 시작할 수 있어요.","en":"It is Apple Vision Pro only, and you can start with a free starter pack of three cars."},"missions":[{"do":{"ko":"무료 스타터 팩의 차 한 대를 방에 실제 크기로 놓고, 문을 탭해 열고 실내로 들어가 보세요.","en":"Place a car from the free Starter Pack at true scale, tap a door to open it, and step inside."},"wow":{"ko":"문이 열리고 실내에 들어가고 엔진이 공간 음향으로 울려요. 이 디테일을 개발자 한 명이 만들었고 Apple은 visionOS에서 보기 드물다고 했어요.","en":"Doors open, you step inside, and the engine roars in Spatial Audio. One developer built it, and Apple called its detail rarely seen on visionOS."}},{"do":{"ko":"엔진을 켠 뒤 차 주위를 천천히 돌며 소리와 배기 연기, 보닛에 비친 빛을 살펴보세요.","en":"Start the engine, then walk slowly around the car and watch the sound, the exhaust and the light on the hood."},"wow":{"ko":"엔진 소리는 공간 음향, 배기는 실시간 파티클이고 실제 방의 빛이 보닛에 비쳐요. 차가 공간 속 나에게 반응해요.","en":"The engine is Spatial Audio, the exhaust is real-time particles, and your room's light reflects off the hood, so the car reacts to you in space."}},{"do":{"ko":"AI 컨시어지에게 목소리로 차 색을 바꿔 달라고 말해 보세요.","en":"Ask the AI Concierge out loud to change the car's paint color."},"wow":{"ko":"자연어 음성 명령으로 차를 다시 꾸밀 수 있어요. 타이핑이 불편한 기기에서 말이 곧 입력이 돼요.","en":"Natural-language voice commands restyle the car, so on a device where typing is awkward, speech becomes the input."}}],"make":[{"ko":"RealityKit으로 3D 모델 하나를 놓고, 탭하면 문 부분만 회전해 열리게 만들어 보세요.","en":"Place a 3D model with RealityKit and make tapping rotate just the door open."},{"ko":"모델에 공간 오디오 소스를 붙여, 다가가면 소리가 커지게 해 보세요.","en":"Attach a spatial audio source to the model so it gets louder as you approach."}],"ask":{"ko":"모형을 보는 대신 문을 열고 앉게 한 것이 왜 박물관보다 더 생생했을까요?","en":"Why does opening the door and sitting inside feel more vivid than looking at a model in a museum?"}},"Prince of Persia: The Lost Crown":{"time":20,"setup":{"ko":"초반부는 무료로 체험할 수 있고, 전체를 하려면 구매가 필요해요.","en":"The opening is a free trial; the full game requires a purchase."},"missions":[{"do":{"ko":"무료 체험 구간에서 전투가 시작되면 자동 패리와 전투 중 시간 느리게를 켜고 다시 싸워 보세요.","en":"When combat starts in the free trial, turn on auto-parry and combat slow-down and fight again."},"wow":{"ko":"콘솔판을 하나도 덜어내지 않은 채 폰으로 왔는데, 모바일에만 있는 자동 패리, 자동 포션, 시간 느리게 옵션이 새로 생겼어요.","en":"The full console game arrived with nothing cut, plus mobile-only auto-parry, auto-potion and slow-time options."}},{"do":{"ko":"화면 버튼의 위치, 모양, 크기를 내 손에 맞게 바꿔 보세요.","en":"Change the position, shape and size of the on-screen buttons to fit your hands."},"wow":{"ko":"터치용으로 다시 만든 인터페이스라 화면 버튼을 완전히 재배치할 수 있어요.","en":"The interface was rebuilt for touch, so every on-screen button can be fully remapped."}},{"do":{"ko":"아직 갈 수 없는 곳을 발견하면 Memory Shard로 그 장면을 지도에 꽂아 두세요.","en":"When you find a spot you cannot reach yet, pin it to the map with a Memory Shard."},"wow":{"ko":"그 장면 스크린숏이 지도에 남아요. 나중에 돌아올 곳을 기억하게 해 주는 메트로배니아다운 장치예요.","en":"A screenshot of the spot stays on the map, a very Metroidvania way to remember where to return."}},{"do":{"ko":"비행기 모드로 바꾸고 이어서 플레이해 보세요.","en":"Switch to Airplane Mode and keep playing."},"wow":{"ko":"오프라인으로 그대로 돌아가고, 최신 기기에서는 60fps로 움직여요.","en":"It keeps running offline, and on recent devices it moves at 60 fps."}}],"make":[{"ko":"액션 프로토타입에 자동 회피 토글을 넣고, 같은 구간을 켜고 끄며 난이도를 비교해 보세요.","en":"Add an auto-dodge toggle to an action prototype and compare the same section with it on and off."},{"ko":"화면 버튼을 드래그해 옮기고 크기를 바꿀 수 있는 편집 모드를 만들어 보세요.","en":"Build an edit mode where on-screen buttons can be dragged and resized."}],"ask":{"ko":"어려움을 없애지 않고 선택지로 남겨 둔 보조 기능이 왜 더 많은 사람을 끝까지 가게 할까요?","en":"Why do assists offered as options, without removing the challenge, carry more people to the end?"}},"PBJ — The Musical":{"time":20,"setup":{"ko":"￦6,600 유료 게임이고, 소리를 켜고 해야 해요.","en":"It is a paid game at 6,600 won; play with sound on."},"missions":[{"do":{"ko":"첫 스테이지에서 종이 인형을 끌어 움직이며, 가장자리를 가까이 들여다보세요.","en":"In the first stage, drag a paper figure around and look closely at its edges."},"wow":{"ko":"모든 그림이 디지털 전에 실물로 존재했어요. 어린이용 안전 가위로 일부러 삐뚤게 오린 가장자리이고, 비주얼에만 약 2년이 걸렸어요.","en":"Every asset existed physically before going digital. Those edges were cut imperfectly with children's safety scissors, and the visuals took about two years."}},{"do":{"ko":"일부러 천천히 진행하다가 빨리 진행해 보며, 음악이 어떻게 따라오는지 들어 보세요.","en":"Play deliberately slowly, then quickly, and listen to how the music follows you."},"wow":{"ko":"Lorraine Bowen의 악보에 연주만 나오는 버퍼 구간이 있어 내 속도에 맞춰 늘어나요. 노래는 대부분 아이들이 불러요.","en":"Lorraine Bowen's score has instrumental buffer sections that stretch to your pace, and most of the singing is by children."}},{"do":{"ko":"인형을 밀고 당길 때 그림의 움직임과 손에 오는 반응 속도를 비교해 보세요.","en":"As you push and pull figures, compare how the art moves with how fast it responds to your touch."},"wow":{"ko":"가장자리는 10~12fps 정도로 움직여 손으로 만든 느낌이지만, 게임 자체는 60fps 이상이라 반응은 빨라요.","en":"Edges animate at about 10 to 12 fps for a handmade feel, while gameplay runs at 60+ fps so it stays responsive."}}],"make":[{"ko":"종이를 실제로 잘라 찍은 사진 몇 장으로 스톱모션 느낌의 짧은 애니메이션을 만들어 보세요.","en":"Cut real paper, photograph a few pieces, and make a short stop-motion style animation."},{"ko":"배경 음악에 반복 가능한 구간을 두고, 플레이어가 다음 단계에 갈 때까지 그 구간을 반복해 보세요.","en":"Give background music a loopable section and repeat it until the player reaches the next step."}],"ask":{"ko":"모든 것을 손으로 잘라 만든 불완전함이 왜 더 따뜻하게 느껴졌을까요?","en":"Why does the imperfection of everything being cut by hand feel warmer?"}},"Opal":{"time":15,"setup":null,"missions":[{"do":{"ko":"자주 여는 앱 하나를 골라 지금 바로 집중 세션으로 막고, 그 앱을 열어 보세요.","en":"Pick an app you open often, block it with a focus session right now, and then try to open it."},"wow":{"ko":"iOS 16 Screen Time API로 만든 첫 앱 중 하나라 시스템 수준에서 막혀요. 직원 11명이 연 매출 1,000만 달러를 냈고 사용자 약 3분의 2가 학생이에요.","en":"As one of the first apps built on iOS 16's Screen Time API, it blocks at the system level. Eleven people took it to $10M ARR, and about two-thirds of daily users are students."}},{"do":{"ko":"집중 기록을 이어 가다가 젬을 하나 얻는 순간, 손에 오는 진동을 느껴 보세요.","en":"Keep up your focus until you earn a gem, and feel the vibration in your hand at that moment."},"wow":{"ko":"젬을 열 때 손에 전해지는 햅틱 애니메이션을 Apple이 따로 칭찬했어요.","en":"Apple specifically praised the tactile haptic animation that plays when you unlock a gem."}},{"do":{"ko":"무료로 하루에 쓸 수 있는 차단 범위가 어디까지인지 확인해 보세요.","en":"Check how much blocking you get for free each day."},"wow":{"ko":"강한 결제벽 대신 무료로도 실제 가치를 주자, 전환율은 20%에서 9%로 떨어졌지만 매출은 두 배가 됐어요.","en":"When it swapped a hard paywall for real free value, conversion fell from 20% to 9% but revenue doubled."}}],"make":[{"ko":"FamilyControls로 앱 하나를 고르고 막는 최소 데모를 만들어 보세요.","en":"Build a minimal FamilyControls demo that picks one app and blocks it."},{"ko":"목표를 달성하면 짧은 햅틱 패턴과 함께 수집품이 열리는 애니메이션을 만들어 보세요.","en":"Make an animation that reveals a collectible with a short haptic pattern when a goal is reached."}],"ask":{"ko":"앱을 막는 앱인데 왜 사용자는 좌절보다 성취감을 더 느낄까요?","en":"It is an app that blocks apps, so why do users feel achievement more than frustration?"}},"Rooms":{"time":20,"setup":null,"missions":[{"do":{"ko":"방에 오브젝트 하나를 놓고, 그 오브젝트의 코드를 열어 값 하나를 바꿔 보세요.","en":"Place one object in a room, open its code, and change one value."},"wow":{"ko":"꾸미기 소품마다 뒤에 Lua 코드가 있어 꾸미기가 곧 프로그래밍이 돼요. 1만 개 넘는 아이템으로 100만 개 넘는 방이 만들어졌어요.","en":"Every decoration has editable Lua code behind it, so decorating becomes programming. Users have built over 1 million rooms from 10,000+ items."}},{"do":{"ko":"다른 사람이 만든 방에 들어가 움직이는 물건을 만져 본 뒤, 어떻게 만들어졌는지 살펴보세요.","en":"Visit a room someone else built, play with something interactive, then look at how it was made."},"wow":{"ko":"리믹스를 전제로 설계돼서 남의 방을 즐기다가 그 방을 만든 방법까지 배우게 돼요.","en":"It is remixable by design, so enjoying someone's room turns into learning how they built it."}}],"make":[{"ko":"격자 위에 오브젝트를 놓고, 탭하면 그 오브젝트의 짧은 스크립트가 실행되는 프로토타입을 만들어 보세요.","en":"Prototype a grid where placed objects run a short script when tapped."},{"ko":"기본은 드래그로 놓기만 하고, 원하는 사람만 코드 보기를 여는 2단계 편집 화면을 그려 보세요.","en":"Sketch a two-level editor where dragging is the default and only those who want it open the code view."}],"ask":{"ko":"코딩을 꾸미기 놀이 뒤에 숨긴 것이 왜 처음 하는 사람의 벽을 낮췄을까요?","en":"Why did hiding code behind decorating lower the barrier for beginners?"}},"Procreate Dreams":{"time":20,"setup":{"ko":"iPad 전용 앱이고 ￦22,000 한 번 구매예요.","en":"It is iPad only and a one-time purchase of 22,000 won."},"missions":[{"do":{"ko":"무대에 요소 하나를 그리고 Performing으로 녹화하면서, 손가락으로 끌고 돌려 보세요.","en":"Draw one element on stage, record with Performing, and drag and rotate it with your finger."},"wow":{"ko":"키프레임을 하나도 찍지 않았는데 내가 움직인 그대로 애니메이션이 돼요. 앱이 키프레임과 경로를 대신 써요. 구독 없이 한 번 구매예요.","en":"Without placing a single keyframe, your movement becomes animation; the app writes the keyframes and paths, and it is a one-time purchase with no subscription."}},{"do":{"ko":"타임라인을 핀치로 늘리고 줄이며 앞뒤로 문질러 보세요.","en":"Pinch the timeline wider and narrower and scrub it back and forth."},"wow":{"ko":"멀티터치 타임라인이라 손가락으로 자유롭게 움직이고 바로 재생돼요. 좁은 가로 타임라인과 달라요.","en":"The multitouch timeline moves freely under your fingers with instant playback, unlike a cramped horizontal one."}},{"do":{"ko":"같은 장면을 프레임 단위로 몇 장 그리고, 풀스크린 플립북 모드로 넘겨 보세요.","en":"Draw a few frames of the same scene and flip through them in full-screen Flipbook mode."},"wow":{"ko":"프레임 애니메이션, 키프레임 트위닝, Performing 세 방식이 한 앱에 있어 초보자와 전문가가 같은 도구를 써요.","en":"Frame-by-frame, keyframe tweening and Performing live in one app, so beginners and pros share the same tool."}}],"make":[{"ko":"드래그하는 동안 시간과 위치를 기록했다가 그대로 재생하는 녹화 애니메이션 데모를 만들어 보세요.","en":"Build a demo that records time and position while you drag and plays it back as animation."},{"ko":"기록한 점들을 줄여 키프레임 몇 개로 바꾸고, 그 경로를 화면에 그려 보세요.","en":"Reduce the recorded points to a few keyframes and draw the path on screen."}],"ask":{"ko":"키프레임을 찍는 대신 연기하게 한 것이 왜 처음 하는 사람에게 더 쉬웠을까요?","en":"Why is acting out motion easier for beginners than placing keyframes?"}},"finity.":{"time":10,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"do":{"ko":"첫 레벨에서 줄 하나를 밀어 같은 색 세 개를 맞추고, 남은 이동 횟수를 확인해 보세요.","en":"In the first level, slide a row to line up three of one color, then check your remaining moves."},"wow":{"ko":"한 사람이 만든 단순한 퍼즐인데 이동 횟수가 정해져 있어 한 수 한 수가 무거워요. 규칙 몇 개로 깊은 수 읽기가 생겨요.","en":"It is a simple puzzle by one developer, but the move budget makes every move count, and a few rules create deep planning."}},{"do":{"ko":"줄을 천천히 끌어, 칸이 넘어갈 때 손끝에 오는 느낌에 집중해 보세요.","en":"Drag a row slowly and focus on the feel under your fingertip as it moves."},"wow":{"ko":"줄 전체를 직접 미는 조작과 촉각 피드백이 핵심이에요. 이 조작으로 ADA Interaction 결선에 올랐어요.","en":"Directly sliding whole rows with tactile feedback is the core, and that interaction made it an ADA Interaction finalist."}}],"make":[{"ko":"격자의 행과 열을 통째로 미는 SwiftUI 드래그 제스처를 만들고, 칸이 넘어갈 때마다 햅틱을 주세요.","en":"Build a SwiftUI drag gesture that slides whole rows and columns, with a haptic each time a cell passes."},{"ko":"레벨에 이동 횟수 제한 하나만 추가해, 같은 퍼즐이 얼마나 긴장되는지 비교해 보세요.","en":"Add just a move limit to a level and compare how tense the same puzzle becomes."}],"ask":{"ko":"이동 횟수 제한 하나가 왜 단순한 맞추기를 깊은 퍼즐로 바꿨을까요?","en":"Why did a single move limit turn simple matching into a deep puzzle?"}},"DEATH STRANDING DIRECTOR'S CUT":{"time":30,"setup":{"ko":"￦44,000 유료 게임이고 iPhone 15 Pro 이상이나 M1 이상의 iPad·Mac이 필요해요.","en":"It is a paid game at 44,000 won and needs an iPhone 15 Pro or an M1 or later iPad or Mac."},"missions":[{"do":{"ko":"iPhone에서 게임을 시작해, 넓은 풍경이 펼쳐지는 장면을 화면 가까이서 살펴보세요.","en":"Start the game on iPhone and study a wide landscape scene up close."},"wow":{"ko":"코지마 히데오의 콘솔 대작이 iPhone 15 Pro에서 네이티브로 돌아가요. MetalFX 업스케일링으로 콘솔에 가까운 화질을 폰에서 내요.","en":"Hideo Kojima's console epic runs natively on iPhone 15 Pro, with MetalFX Upscaling bringing near-console visuals to a phone."}},{"do":{"ko":"iPhone에서 조금 진행해 저장한 뒤, 같은 계정의 iPad나 Mac에서 이어서 해 보세요.","en":"Play a little on iPhone and save, then continue on an iPad or Mac with the same account."},"wow":{"ko":"한 번 사면 iPhone, iPad, Mac 모두에서 할 수 있고 세이브가 기기를 넘어 이어져요.","en":"One purchase covers iPhone, iPad and Mac, and your save carries across devices."}},{"do":{"ko":"길을 가다 다른 플레이어가 남긴 사다리나 밧줄, 구조물을 찾아 써 보세요.","en":"On your route, look for ladders, ropes or structures other players left, and use them."},"wow":{"ko":"직접 만나지 않는 비동기 협력이에요. 모르는 사람이 남긴 도구가 내 길을 열어 줘요.","en":"This is asynchronous cooperation: tools left by strangers you never meet open up your path."}}],"make":[{"ko":"Metal 장면을 낮은 해상도로 렌더링하고 MetalFX로 키워, 화질과 프레임을 비교해 보세요.","en":"Render a Metal scene at low resolution, upscale it with MetalFX, and compare quality and frame rate."},{"ko":"세이브 데이터를 iCloud에 저장해 두 기기에서 이어서 하는 흐름을 만들어 보세요.","en":"Store save data in iCloud and build a flow that continues on a second device."}],"ask":{"ko":"콘솔 게임이 폰에서 돈다는 것보다 세이브가 기기를 넘어 이어지는 것이 왜 더 크게 느껴질까요?","en":"Why might a save that follows you across devices feel bigger than a console game simply running on a phone?"}},"Anne":{"time":15,"setup":{"ko":"무료 앱이고, 말을 걸어 줄 사람이 한 명 있으면 좋아요.","en":"It is free; having one person to talk to you helps."},"missions":[{"do":{"ko":"눈을 감고 화면을 보지 않은 채, 탭과 스와이프로 모스 부호의 점과 선을 입력해 보세요.","en":"Close your eyes and, without looking, type Morse dots and dashes with taps and swipes."},"wow":{"ko":"화면을 보지도 듣지도 않고 제스처와 진동만으로 써요. 평범한 iPhone 하나로 시청각 장애인이 모스 부호로 대화해요.","en":"It is used entirely through gestures and vibrations, without seeing or hearing the screen, so deafblind people converse in Morse on an ordinary iPhone."}},{"do":{"ko":"옆 사람에게 평소처럼 말을 걸어 달라고 하고, 그 말이 손에 진동으로 오는 걸 느껴 보세요.","en":"Ask someone nearby to talk to you normally, and feel their words arrive as vibrations in your hand."},"wow":{"ko":"음성 인식이 말을 받아 Taptic Engine 진동 모스 부호로 들려줘요. 상대는 그냥 말하고 나는 촉각으로 읽어요.","en":"Speech recognition turns their words into Morse vibrations through the Taptic Engine; they just talk and you read by touch."}},{"do":{"ko":"모스 재생 속도를 느리게, 또 빠르게 바꿔 같은 메시지를 다시 받아 보세요.","en":"Change the Morse playback speed slower and faster and receive the same message again."},"wow":{"ko":"재생 속도를 조절하고 지난 메시지를 다시 보낼 수 있어요. 약어로 더 빨리 쓸 수도 있어요.","en":"Playback speed is adjustable, past messages can be resent, and abbreviations speed up typing."}}],"make":[{"ko":"Core Haptics로 짧은 진동과 긴 진동을 만들어, 글자 하나를 모스 부호로 재생해 보세요.","en":"Use Core Haptics to make short and long vibrations and play one letter in Morse."},{"ko":"화면을 보지 않고 쓸 수 있게, 화면 어디를 탭해도 같은 입력이 되는 전체 화면 입력판을 만들어 보세요.","en":"Build a full-screen input surface where a tap anywhere means the same thing, so it works without looking."}],"ask":{"ko":"화면을 아예 안 보는 사람을 기준으로 설계한 것이 왜 iPhone 하나로 대화를 가능하게 했을까요?","en":"Why did designing for someone who never sees the screen make conversation possible on a single iPhone?"}},"Flighty":{"time":15,"setup":{"ko":"곧 탈 항공편이 있으면 가장 좋고, 없으면 추적해 볼 항공편 하나를 정해 두세요.","en":"An upcoming flight of your own is best; otherwise choose any flight to track."},"missions":[{"do":{"ko":"추적할 항공편을 추가하고, 내 비행기로 올 기체가 지금 어디서 오고 있는지 확인해 보세요.","en":"Add a flight to track and check where the inbound aircraft for it is coming from right now."},"wow":{"ko":"출발 25시간 전부터 내 비행기로 올 기체를 추적하고, 항공사가 알리기 최대 6시간 전에 지연을 예측해요.","en":"It tracks the inbound aircraft from 25 hours before departure and predicts delays up to six hours before airlines announce them."}},{"do":{"ko":"추가한 항공편이 잠금 화면 Live Activity와 Dynamic Island에 어떻게 보이는지 확인해 보세요.","en":"Check how the flight appears in the Lock Screen Live Activity and the Dynamic Island."},"wow":{"ko":"탑승까지 남은 시간, 게이트, 좌석, 지연, 착륙 진행이 엄격한 순서로 들어가고, 여행 단계에 따라 내용이 바뀌어요.","en":"Boarding countdown, gate, seat, delay and landing progress are packed in a strict hierarchy that changes with each trip phase."}},{"do":{"ko":"캘린더에 항공편 일정이 있다면, 편명을 입력하지 말고 가져오기를 해 보세요.","en":"If a flight is in your calendar, import it instead of typing the flight number."},"wow":{"ko":"캘린더, TripIt, 이메일에서 항공편을 자동으로 가져와 편명을 칠 일이 거의 없어요.","en":"Flights come in automatically from Calendar, TripIt or email, so you rarely type a flight number."}}],"make":[{"ko":"다음 일정까지 남은 시간과 장소 하나만 보여 주는 Live Activity를 ActivityKit으로 만들어 보세요.","en":"Build an ActivityKit Live Activity that shows only the time left and the place of your next event."},{"ko":"Live Activity 상태를 출발 전, 이동 중, 도착 세 단계로 나눠 단계마다 다른 정보를 보여 주세요.","en":"Split a Live Activity into before, during and after phases, showing different information in each."}],"ask":{"ko":"항공사보다 먼저 알려 준다는 약속이 왜 이 앱을 꼭 깔아야 하는 이유가 됐을까요?","en":"Why did the promise of knowing before the airline become the reason people must install it?"}},"Any Distance":{"time":15,"setup":{"ko":"Apple 건강에 운동 기록이 있으면 바로 살펴볼 수 있어요.","en":"Having workouts in Apple Health lets you explore right away."},"missions":[{"do":{"ko":"Apple 건강에 있는 운동 기록 하나를 열어 경로 지도를 돌려 보고, AR 보기도 켜 보세요.","en":"Open a workout from Apple Health, rotate its route map, and try the AR view."},"wow":{"ko":"운동 경로가 고도까지 담긴 3D 지도로 돌아가고 AR로도 보여요. 애틀랜타의 두 사람, Luke Beard와 Dan Kuntz가 만든 앱이에요.","en":"Your route spins as a 3D map with elevation and appears in AR, from an app made by two people in Atlanta, Luke Beard and Dan Kuntz."}},{"do":{"ko":"운동 종류 목록에서 휠체어 운동이나 유모차 달리기를 찾아보세요.","en":"Look for wheelchair workouts or stroller runs in the list of workout types."},"wow":{"ko":"달리기와 자전거만이 아니라 휠체어 운동, 유모차 달리기, 리컴번트 자전거까지 90가지 넘는 운동을 지원해요.","en":"Beyond runs and rides it supports wheelchair workouts, stroller runs and recumbent biking among 90+ workout types."}},{"do":{"ko":"기록을 공유할 때 페이스, 시간, 경로를 숨기고 공유해 보세요.","en":"When you share a workout, hide the pace, time and route."},"wow":{"ko":"데이터는 기기에 남고 팔리지 않으며, 공유할 때도 보여 줄 것만 고를 수 있어요.","en":"Data stays on the device and is never sold, and even when sharing you choose what to show."}}],"make":[{"ko":"MapKit으로 운동 경로를 그리고 카메라 각도를 천천히 돌리는 3D 지도 화면을 만들어 보세요.","en":"Draw a workout route with MapKit and build a 3D map whose camera slowly rotates."},{"ko":"공유 카드에 페이스와 시간 표시를 켜고 끄는 토글을 넣어 보세요.","en":"Add toggles to a share card that show or hide pace and time."}],"ask":{"ko":"운동 기록을 숫자가 아닌 작품처럼 보여 준 것이 왜 공유하고 싶게 만들었을까요?","en":"Why does showing a workout as a designed piece, not numbers, make people want to share it?"}},"Wylde Flowers":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요하고, 소리를 켜고 해야 해요.","en":"You need an Apple Arcade subscription; play with sound on."},"missions":[{"do":{"ko":"소리를 켜고 첫 장면부터 마을 사람들과 대화를 이어 가 보세요.","en":"With sound on, keep talking with the villagers from the very first scene."},"wow":{"ko":"모바일 농사 게임에서 드물게 모든 대사에 목소리 연기가 있어요. 호주 작은 인디 스튜디오의 첫 게임으로 2022 Apple Arcade 올해의 게임이 됐어요.","en":"Rare for a mobile farming game, every line is voice-acted. A small Australian studio's first game, it became Apple Arcade Game of the Year 2022."}},{"do":{"ko":"작물을 돌보는 하루하루 사이에 마녀 이야기가 어떻게 끼어드는지 따라가 보세요.","en":"Follow how the witchcraft story slips in between your days of tending crops."},"wow":{"ko":"농사 생활 시뮬레이션에 마녀 이야기와 미스터리가 붙어 아늑한 반복에 진짜 긴장이 생겨요.","en":"A witchcraft story and mystery run alongside the farming sim, giving the cozy loop real stakes."}},{"do":{"ko":"마을 사람들을 만나며 핵심 인물들이 어떤 사람들인지 살펴보세요.","en":"As you meet the villagers, notice who makes up the core cast."},"wow":{"ko":"LGBTQIA+ 인물이 핵심 출연진 안에 있고 성별과 상관없이 연애할 수 있어요. 덤으로 붙인 기능이 아니에요.","en":"LGBTQIA+ characters are part of the core cast and romance is open across genders, not added as a side feature."}}],"make":[{"ko":"작은 게임의 대사 세 줄에 직접 녹음한 목소리를 붙여, 글만 있을 때와 비교해 보세요.","en":"Record your own voice for three lines in a small game and compare it with text only."},{"ko":"하루 일과 루프 끝에 이야기 장면 하나를 끼워 넣어, 다음 날이 궁금해지게 해 보세요.","en":"Insert one story scene at the end of a daily loop so players want to see the next day."}],"ask":{"ko":"모든 대사에 목소리를 넣은 것이 왜 작은 화면에서 이야기를 더 와닿게 했을까요?","en":"Why did voicing every line make the story land harder on a small screen?"}},"Waterllama":{"time":5,"setup":null,"missions":[{"do":{"ko":"물 한 잔을 기록해 보고, 동물 캐릭터가 차오르는 순간을 지켜보세요.","en":"Log a glass of water and watch the animal character fill up."},"wow":{"ko":"탭 한 번에 귀여운 동물이 차올라요. 이 작은 보상 하나로 App Store 평가가 10만 개를 넘었어요.","en":"One tap and a cute animal fills up, and that tiny reward has drawn 100,000+ App Store ratings."}},{"do":{"ko":"음료 목록에서 커피를 골라 기록해 보세요.","en":"Pick coffee from the drink list and log it."},"wow":{"ko":"150가지 넘는 음료에 수분과 카페인 값이 있어요. 140마리 캐릭터와 함께 지루한 기록이 수집 게임이 돼요.","en":"More than 150 drinks carry hydration and caffeine values, and with 140 characters a dull log becomes a collection game."}},{"do":{"ko":"Apple Watch가 있으면 손목에서 더블 탭으로 한 잔을 기록해 보세요.","en":"If you have an Apple Watch, log a glass from your wrist with double tap."},"wow":{"ko":"Watch 앱과 스마트 스택, 제어 센터, 잠금 화면 위젯까지 앱을 열지 않고 기록할 곳이 많아요.","en":"The Watch app, Smart Stack, Control Center and Lock Screen widgets give many ways to log without opening the app."}}],"make":[{"ko":"버튼을 누를 때마다 캐릭터 안의 물 높이가 애니메이션으로 올라가는 SwiftUI 뷰를 만들어 보세요.","en":"Build a SwiftUI view where the water level inside a character animates up with each tap."},{"ko":"기록 버튼 하나를 제어 센터나 위젯에 두어, 앱을 열지 않고 기록하게 해 보세요.","en":"Put a single log button in Control Center or a widget so people log without opening the app."}],"ask":{"ko":"물 마시기라는 지루한 기록에 캐릭터 하나를 붙인 것이 왜 매일 하게 만들었을까요?","en":"Why did adding one character to a dull water log make people do it every day?"}},"Halide Mark II":{"time":15,"setup":{"ko":"무료로 받을 수 있고, 연간 멤버십과 평생 구매 중 고를 수 있어요.","en":"It is a free download with a choice of annual membership or a lifetime purchase."},"missions":[{"do":{"ko":"Process Zero로 사진을 한 장 찍고, 기본 카메라 앱으로 같은 장면을 찍어 나란히 비교해 보세요.","en":"Take a photo with Process Zero, shoot the same scene with the built-in Camera app, and compare them side by side."},"wow":{"ko":"iPhone의 계산 처리를 통째로 건너뛰어 대비와 입자가 자연스러워요. 두세 명 팀이 'AI 제로'를 제품으로 만들었어요.","en":"It skips iPhone computational processing entirely for natural contrast and grain. A team of two or three turned zero AI into a product."}},{"do":{"ko":"화면 아무 곳이나 위아래로 쓸어 노출을, 좌우로 쓸어 초점을 바꿔 보세요.","en":"Swipe up and down anywhere to change exposure, and left and right to change focus."},"wow":{"ko":"필름 카메라처럼 슬라이더를 찾지 않고 손짓만으로 설정이 바뀌어요.","en":"Like a film camera, settings change with a gesture, without hunting for sliders."}},{"do":{"ko":"수동 초점으로 맞추면서 초점 피킹과 초점 루페가 어떻게 돕는지 보세요.","en":"Focus manually and watch how focus peaking and the focus loupe help."},"wow":{"ko":"초점이 맞은 부분이 표시되고 확대해서 볼 수 있어, 폰으로도 수동 초점이 실용적이에요.","en":"In-focus areas are marked and you can magnify them, which makes manual focus practical on a phone."}}],"make":[{"ko":"AVFoundation 카메라 프리뷰에 세로 드래그는 노출, 가로 드래그는 초점을 연결하는 데모를 만들어 보세요.","en":"Build an AVFoundation camera preview where vertical drags set exposure and horizontal drags set focus."},{"ko":"같은 장면을 처리 전과 처리 후로 나란히 보여 주는 비교 화면을 만들어 보세요.","en":"Build a comparison screen that shows the same scene before and after processing."}],"ask":{"ko":"기능을 더하는 대신 처리를 끄는 선택지를 판 것이 왜 사진가들에게 놀라웠을까요?","en":"Why was selling the option to turn processing off, rather than adding features, so striking to photographers?"}},"Voice Dream Reader":{"time":15,"setup":null,"missions":[{"do":{"ko":"웹 페이지 하나를 불러와 재생한 뒤 화면을 끄고 다른 앱으로 넘어가 보세요. 걷거나 운동하면서 계속 들어 보세요.","en":"Load a web page, start playback, then lock the screen and switch apps. Keep listening while you walk or work out."},"wow":{"ko":"화면 없이도 읽기가 그대로 이어져요. 개발자가 2011년 북극권 바로 위 노르웨이 섬에서 운전·운동 중에 글을 들으려고 만든 개인 도구였어요.","en":"Reading carries on with no screen at all. It began in 2011 as the developer's personal tool for listening to text while driving or at the gym, on a Norwegian island just north of the Arctic Circle."}},{"do":{"ko":"읽기를 틀어 둔 채로 단어와 줄 하이라이트를 눈으로 따라가 보세요.","en":"With reading playing, follow the word and line highlighting with your eyes."},"wow":{"ko":"소리와 강조가 단어·줄 단위로 맞물려 움직여요. 학습 장애가 있는 독자가 듣고 보면서 함께 이해하도록 만든 동기화예요.","en":"Sound and highlight move together word by word and line by line, a sync built so readers with learning differences can listen and see at once."}},{"do":{"ko":"종이 문서 한 장을 일부러 어두운 곳에서 스캔해 읽게 해 보세요.","en":"Scan a printed page somewhere deliberately dim and have it read aloud."},"wow":{"ko":"기기 안에서 도는 AI OCR이 어두운 환경에서도 인쇄물을 음성으로 바꿔요.","en":"An on-device AI OCR scanner turns the printed page into speech even in poor lighting."}},{"do":{"ko":"비행기 모드로 바꾸고 다른 언어 음성으로 바꿔 같은 글을 읽게 해 보세요.","en":"Switch to airplane mode, change to a voice in another language and have the same text read."},"wow":{"ko":"네트워크가 없어도 목소리가 그대로예요. 27개 언어 36개 기본 음성과 프리미엄 음성 모두 오프라인으로 돌아가요.","en":"The voice keeps going with no network. All 36 built-in voices in 27 languages, and the premium voices, work offline."}}],"make":[{"ko":"내 앱의 텍스트 화면에 AVSpeechSynthesizer로 읽기 버튼을 붙이고, 백그라운드 오디오를 켜서 화면을 꺼도 이어지게 해 보세요.","en":"Add a read-aloud button to a text screen in your app with AVSpeechSynthesizer, and enable background audio so it continues with the screen off."},{"ko":"AVSpeechSynthesizerDelegate의 willSpeakRange로 지금 읽는 단어를 하이라이트하는 프로토타입을 만들어 보세요.","en":"Prototype word highlighting that follows the speech using willSpeakRange in AVSpeechSynthesizerDelegate."}],"ask":{"ko":"운전하며 들으려던 개인 도구가 왜 난독증·저시력 사용자에게 꼭 필요한 앱이 됐을까요?","en":"Why did a personal tool for listening while driving become essential for readers with dyslexia and low vision?"}},"South of the Circle":{"time":10,"setup":{"ko":"앱스토어에서 내려간 게임이라 개발사의 공식 트레일러나 스크린샷으로 경험해야 해요.","en":"The game has left the App Store, so experience it through the developer's own trailer or screenshots."},"missions":[{"do":{"ko":"공식 트레일러에서 인물이 말하는 장면을 멈춰 가며 표정과 몸짓을 살펴보세요.","en":"Pause the official trailer on scenes where characters speak and study their faces and body language."},"wow":{"ko":"귀네스 리를 포함한 영국 배우들이 목소리뿐 아니라 전신 모션 캡처까지 직접 했어요. 모바일 게임에서 보기 드문 연기예요.","en":"British actors including Gwilym Lee did full motion capture as well as voices, a kind of performance rarely seen in a mobile game."}},{"do":{"ko":"트레일러나 스크린샷에서 남극 설원 장면 하나를 골라 쓰인 색을 세어 보세요.","en":"Pick one Antarctic snowfield shot from the trailer or screenshots and count the colors used."},"wow":{"ko":"1960년대 냉전 남극을 20세기 중반 실크스크린풍 단색 면으로 그려서, 작은 화면에서도 영화처럼 또렷하게 읽혀요.","en":"The 1960s Cold War Antarctic is drawn in flat colors inspired by mid-century screenprints, so it reads clearly and cinematically on a small screen."}},{"do":{"ko":"트레일러나 스크린샷에서 선택지가 나오는 장면을 찾아, 대사 대신 무엇을 고르게 하는지 보세요.","en":"Find a choice moment in the trailer or screenshots and see what you pick instead of a line of dialogue."},"wow":{"ko":"대사 한 줄이 아니라 감정의 태도로 대답해요. 조작은 가볍게 두고 이야기에 집중하게 하는 장치예요.","en":"You answer with an emotional stance rather than a line, which keeps interaction light and attention on the story."}}],"make":[{"ko":"내 프로토타입 화면 하나를 단색 면 서너 개로만 다시 그려, 작은 화면에서 더 잘 읽히는지 원본과 비교해 보세요.","en":"Redraw one prototype screen using only three or four flat color areas and compare how well it reads on a small screen."},{"ko":"대화 선택지를 감정 세 가지로 바꾼 버튼 화면을 SwiftUI로 만들어, 고르는 데 걸리는 시간을 재 보세요.","en":"Build a SwiftUI choice screen with three feelings instead of dialogue lines, and time how long choosing takes."}],"ask":{"ko":"감정으로 답하는 선택이 왜 대사를 고르는 선택보다 몰입을 높였을까요?","en":"Why did answering with a feeling draw players in more than choosing a line of dialogue?"}},"Attentat 1942":{"time":30,"setup":{"ko":"유료 게임($4.99)이고, 실사 영상이 많으니 소리를 켤 수 있는 조용한 곳이 좋아요.","en":"It is a paid game ($4.99), and with lots of live-action video, a quiet place with sound on works best."},"missions":[{"do":{"ko":"플레이 중 점령기 상징이 나오는 장면을 만나면, 그 장면이 어떤 맥락으로 쓰였는지 살펴보세요.","en":"When you reach a scene showing occupation-era symbols, look at the context it is used in."},"wow":{"ko":"카렐 대학교와 체코 과학원 역사학자들이 만든 게임이라, 독일 USK가 나치 상징을 담은 게임을 처음으로 승인한 사례가 됐어요.","en":"Made with Charles University and historians from the Czech Academy of Sciences, it became the first game Germany's USK rated despite showing Nazi symbols."}},{"do":{"ko":"실사 영상으로 나오는 첫 증인에게 할아버지가 체포된 일에 대해 질문을 이어가 보세요.","en":"Keep questioning the first live-action witness about your grandfather's arrest."},"wow":{"ko":"교과서 대신 생존 증인을 인터뷰하며 1942년 하이드리히 암살 뒤의 체포를 파헤쳐요. 실사 영상이라 증언이 한 사람의 이야기로 다가와요.","en":"Instead of a textbook, you interview surviving witnesses about an arrest after the 1942 Heydrich assassination, and live-action video makes each testimony personal."}},{"do":{"ko":"두 증인에게 같은 사건을 물어 답을 나란히 비교해 보세요.","en":"Ask two witnesses about the same event and compare their answers side by side."},"wow":{"ko":"증언이 서로 엇갈려요. 기억, 협력, 저항을 판단하는 몫이 플레이어에게 넘어와 점령기의 보통 사람에게 공감하게 돼요.","en":"The testimonies contradict each other, so judging memory, collaboration and resistance falls to you, building empathy with ordinary people under occupation."}},{"do":{"ko":"증언 사이에 나오는 만화풍 장면과 미니게임을 건너뛰지 말고 해 보세요.","en":"Play through the comic-style sequences and mini-games between testimonies instead of skipping them."},"wow":{"ko":"실사 영상, 만화 시퀀스, 미니게임이 섞여 있어서 증언마다 다른 질감으로 다가와요.","en":"Live-action footage, comic sequences and mini-games are mixed, so each testimony arrives with a different texture."}}],"make":[{"ko":"내 앱의 정보 하나를 두 인물의 엇갈린 짧은 증언으로 바꿔, 사용자가 직접 판단하게 하는 화면을 만들어 보세요.","en":"Turn one piece of information in your app into two short conflicting testimonies and let the user judge for themselves."},{"ko":"질문 버튼 세 개와 짧은 답 텍스트나 영상 클립으로 이루어진 인터뷰 프로토타입을 만들어 보세요.","en":"Build an interview prototype with three question buttons and a short text or video answer for each."}],"ask":{"ko":"엇갈린 증언이 왜 정답이 있는 설명보다 깊은 공감을 만들었을까요?","en":"Why did contradictory testimonies create deeper empathy than an explanation with one right answer?"}},"Universe":{"time":20,"setup":null,"missions":[{"do":{"ko":"VoiceOver를 켜고 템플릿 하나를 연 뒤, 블록을 격자에 끌어다 놓고 손가락으로 화면을 훑어 보세요.","en":"Turn on VoiceOver, open a template, drag a block onto the grid and sweep your finger across the screen."},"wow":{"ko":"격자 덕분에 VoiceOver가 블록을 위치 순서대로 읽어요. 아이폰 하나로 시각장애인도 웹사이트를 만들 수 있는 구조예요.","en":"Because of the grid, VoiceOver reads blocks in positional order, so blind creators can build a website on an iPhone too."}},{"do":{"ko":"빈 페이지에 블록 몇 개를 손가락으로 끌어 놓고 미리보기를 보세요.","en":"Drag a few blocks onto a blank page with your finger and watch the preview."},"wow":{"ko":"데스크톱 HTML 편집기를 줄인 게 아니라 블록이 격자에 착 붙어요. HTML·CSS를 몰라도 실시간 미리보기로 바로 보여요.","en":"Rather than a shrunken desktop HTML editor, blocks snap into a grid, and the real-time preview shows the result with no HTML or CSS."}},{"do":{"ko":"상점 템플릿을 골라 실물 상품이나 디지털 파일을 올리는 단계까지 가 보세요.","en":"Pick a store template and go as far as adding a physical product or a digital download."},"wow":{"ko":"도메인 연결과 쇼핑몰까지 폰 안에 들어 있어요. 아이디어에서 상점까지 폰 하나로 끝나요.","en":"Domains and a full store live inside the phone app, so you can go from idea to store on a phone alone."}}],"make":[{"ko":"내 앱의 자유 배치 화면을 격자 스냅으로 바꾸고, 칸마다 접근성 라벨과 위치 순서를 붙여 VoiceOver로 훑어보세요.","en":"Change a free-form layout in your app to snap to a grid, give each cell an accessibility label and order, then sweep it with VoiceOver."},{"ko":"SwiftUI Grid 위에서 블록을 끌어 놓으면 칸에 맞춰 붙는 드래그 앤 드롭 프로토타입을 만들어 보세요.","en":"Prototype drag and drop on a SwiftUI Grid where dropped blocks snap into cells."}],"ask":{"ko":"격자라는 제약이 왜 터치 편집과 VoiceOver 접근성을 한꺼번에 풀었을까요?","en":"Why did the constraint of a grid solve both touch editing and VoiceOver access at once?"}},"Robinhood":{"time":15,"setup":{"ko":"실제 계좌 개설이나 주문은 하지 말고 확인 직전 단계까지만 따라가 보세요.","en":"Do not actually open an account or place an order; stop just before each confirmation."},"missions":[{"do":{"ko":"계좌 개설을 시작해 민감한 정보를 묻는 화면 직전까지 가 보세요. 입력칸보다 먼저 뜨는 문구를 읽어 보세요.","en":"Start opening an account and stop just before it asks for sensitive data. Read the text that appears before the fields."},"wow":{"ko":"민감한 정보를 묻기 전에 왜 필요한지(규제상 요구)와 어떻게 보호되는지를 짧게 먼저 말해요. 이탈을 줄이는 한 줄이에요.","en":"Before asking for sensitive data it briefly says why it is needed (a regulatory requirement) and how it is protected, a line that reduces drop-off."}},{"do":{"ko":"개설 단계를 넘기며 한 화면에 질문이 몇 개인지 세어 보세요.","en":"Move through the account steps and count how many questions each screen asks."},"wow":{"ko":"한 화면에 질문 하나와 큰 입력칸뿐이에요. 복잡한 증권 계좌 개설이 일반 앱 가입처럼 느껴져요.","en":"Each screen has one question and a large field, so opening a brokerage account feels like signing up for any mobile app."}},{"do":{"ko":"종목 하나를 열고 주문 확인 직전까지 가 본 뒤, 축하 연출이 있는지 떠올려 보세요.","en":"Open a stock and go just before the order confirmation, then think about whether any celebration appears."},"wow":{"ko":"매매 뒤 컨페티 연출이 '게임화' 비판을 받자 제거됐어요. 규제와 신뢰에 맞춰 UX를 조정한 흔적이에요.","en":"Post-trade confetti was removed after criticism of gamification, a trace of UX adjusted for regulation and trust."}}],"make":[{"ko":"내 앱에서 민감한 정보를 묻는 화면 바로 앞에 이유와 보호 방식을 설명하는 한 줄을 넣어 보세요.","en":"Add one line explaining why and how data is protected right before the screen in your app that asks for sensitive data."},{"ko":"긴 가입 폼을 한 화면에 질문 하나씩으로 쪼갠 프로토타입을 만들어 원래 폼과 비교해 보세요.","en":"Split a long sign-up form into one question per screen and compare it with the original."}],"ask":{"ko":"이유를 설명하는 한 줄이 왜 민감한 질문 앞의 이탈을 줄일까요?","en":"Why does a single line of explanation reduce drop-off before a sensitive question?"}},"Proloquo2Go":{"time":20,"setup":{"ko":"가격이 ￦449,000인 고가 앱이라, 구매 전 공식 소개 자료로 먼저 살펴보는 것도 좋아요.","en":"At ￦449,000 it is expensive, so you may want to study the official material before buying."},"missions":[{"do":{"ko":"작은 그리드에서 단어 하나의 위치를 기억해 둔 뒤, 그리드 크기를 키워 같은 단어를 찾아 보세요.","en":"Remember where one word sits on a small grid, then switch to a larger grid and find the same word."},"wow":{"ko":"버튼이 9개에서 144개로 늘어도 단어 자리가 유지돼요. 손이 위치를 기억하게 하는 운동 계획 일관성이에요.","en":"Even as the grid grows from 9 to 144 buttons, the word keeps its place, a motor-planning consistency that lets the hand remember."}},{"do":{"ko":"음성 목록에서 아이 목소리를 골라 같은 문장을 말하게 해 보세요.","en":"Choose a child's voice from the voice list and have it speak the same sentence."},"wow":{"ko":"아이 목소리를 포함한 100개 넘는 자연스러운 음성이 무료예요. 사용자가 자기 나이와 정체성에 맞는 목소리로 말해요.","en":"More than 100 natural voices, including children's, are free, so users can speak in a voice that fits their age and identity."}},{"do":{"ko":"휴대폰 속 사진 한 장으로 새 버튼을 만들고 단어를 붙여 보세요.","en":"Make a new button from a photo on your phone and attach a word to it."},"wow":{"ko":"27,000개 넘는 심볼에 개인 사진과 단어까지 더할 수 있어, 글을 읽지 못하는 사용자도 자기 세계로 소통해요.","en":"On top of more than 27,000 symbols you can add personal photos and words, so people who cannot read communicate in their own world."}},{"do":{"ko":"핵심어 버튼 몇 개만 눌러 짧은 문장을 만들어 보세요.","en":"Build a short sentence by tapping just a few core-word buttons."},"wow":{"ko":"Crescendo 어휘 체계가 핵심어를 중심에 둬서, 단순한 요청을 넘어 문법이 있는 문장이 만들어져요.","en":"The Crescendo vocabulary puts core words at the center, so you get grammatical sentences, not just simple requests."}}],"make":[{"ko":"내 앱의 버튼 그리드에서 열 수를 바꿔도 주요 버튼의 위치가 그대로인지 확인하고, 아니라면 고정해 보세요.","en":"Check whether key buttons in your app's grid stay put when the column count changes, and pin them if not."},{"ko":"사진과 단어가 붙은 버튼을 누르면 AVSpeechSynthesizer로 말하는 4칸 프로토타입을 만들어 보세요.","en":"Build a four-button prototype where tapping a photo-and-word button speaks it with AVSpeechSynthesizer."}],"ask":{"ko":"그리드가 커져도 단어 위치를 지키는 게 왜 버튼을 더 넣는 것보다 중요했을까요?","en":"Why did keeping word positions fixed matter more than fitting in more buttons?"}},"TikTok":{"time":10,"setup":null,"missions":[{"do":{"ko":"로그인하지 말고 앱을 열자마자 위로 스와이프만 연달아 해 보세요. 로딩을 기다린 순간이 있었는지 세어 보세요.","en":"Without logging in, open the app and keep swiping up. Count any moment you had to wait for loading."},"wow":{"ko":"설정 없이 전체 화면 영상이 바로 나오고, 다음 영상을 미리 불러와 둬서 넘기는 즉시 재생돼요. 대기를 거의 못 느껴요.","en":"Full-screen video plays with no setup, and the next videos are preloaded so each one starts the instant you swipe. You barely feel any wait."}},{"do":{"ko":"한 주제의 영상은 끝까지 보거나 다시 보고, 나머지는 바로 넘겨 보세요. 몇 번 만에 피드가 바뀌는지 보세요.","en":"Watch videos on one topic to the end or replay them, and skip the rest. See how quickly the feed shifts."},"wow":{"ko":"팔로우가 하나도 없어도 시청 시간과 반복 재생 같은 행동 신호로 For You 피드가 내 쪽으로 기울어요.","en":"With zero follows, signals like watch time and replays tilt the For You feed toward you."}},{"do":{"ko":"마음에 드는 영상에서 원본 음원을 눌러 보세요.","en":"On a video you like, tap its original sound."},"wow":{"ko":"같은 소리를 쓴 영상 모음과 '이 소리 사용' 버튼이 나와요. 보던 사람이 곧바로 만드는 사람이 되는 고리예요.","en":"You get every video using that sound and a Use this sound button, a loop that turns a viewer into a creator on the spot."}}],"make":[{"ko":"내 앱의 목록에서 다음 항목을 미리 불러와(prefetch) 넘길 때 대기가 사라지는지 비교해 보세요.","en":"Prefetch the next items in a list in your app and compare whether the wait disappears when moving on."},{"ko":"로그인보다 콘텐츠를 먼저 보여 주는 첫 화면 프로토타입을 만들어 보세요.","en":"Prototype a first screen that shows content before any login."}],"ask":{"ko":"로그인보다 영상을 먼저 보여 준 선택이 왜 그 자체로 온보딩이 됐을까요?","en":"Why did showing video before any login work as onboarding by itself?"}},"Slack":{"time":15,"setup":{"ko":"혼자보다 동료나 친구 한 명과 같은 워크스페이스에서 해 보면 구조가 더 잘 보여요.","en":"It shows its structure best in a workspace shared with one colleague or friend."},"missions":[{"do":{"ko":"동료와 채널 하나에서 메시지 하나엔 스레드로 답하고, 다른 하나엔 이모지 리액션으로만 응답해 보세요.","en":"In a channel with a colleague, reply to one message in a thread and answer another with only an emoji reaction."},"wow":{"ko":"짧은 응답은 메시지 없이 리액션으로, 곁가지 대화는 스레드로 빠져요. 채널 본문이 놀랄 만큼 조용하게 유지돼요.","en":"Short replies become reactions and side conversations move into threads, so the channel itself stays surprisingly quiet."}},{"do":{"ko":"컴퓨터에서 Slack을 켜 둔 채로 휴대폰의 알림 설정을 따로 바꿔 보세요.","en":"With Slack open on your computer, change the notification settings on your phone separately."},"wow":{"ko":"모바일과 데스크톱의 알림 규칙을 따로 정할 수 있어요. 컴퓨터 앞에서는 휴대폰 알림을 줄이는 식의 맥락별 제어예요.","en":"Mobile and desktop notification rules are set separately, so you can quiet your phone while at your computer."}},{"do":{"ko":"채널 하나의 알림만 바꾸고, 키워드 알림도 하나 걸어 보세요.","en":"Change the notifications for just one channel and add one keyword alert."},"wow":{"ko":"전체 기본값, 채널별 설정, 키워드·방해 금지 시간으로 층이 나뉘어 복잡한 옵션을 필요한 층에서만 만져요.","en":"Settings are layered as global default, per channel, then keywords and do-not-disturb hours, so you only touch the layer you need."}},{"do":{"ko":"텍스트로 이야기하다가 그 자리에서 허들을 켜 보세요.","en":"While chatting in text, start a huddle right there."},"wow":{"ko":"텍스트 대화에서 음성·영상 대화로 바로 넘어가요.","en":"You go from text straight into a voice or video conversation."}}],"make":[{"ko":"내 앱의 알림 설정을 전체 기본값, 항목별, 예외의 세 층으로 나눈 화면을 스케치해 보세요.","en":"Sketch your app's notification settings as three layers: global default, per item, and exceptions."},{"ko":"메시지를 길게 누르면 이모지 리액션을 붙일 수 있는 목록 프로토타입을 만들어 보세요.","en":"Prototype a message list where a long press adds an emoji reaction."}],"ask":{"ko":"리액션 하나가 왜 채널의 소음을 그렇게 많이 줄였을까요?","en":"Why did a single reaction cut so much noise from a channel?"}},"Drafts":{"time":10,"setup":null,"missions":[{"do":{"ko":"앱을 완전히 닫았다가 다시 열고, 아무것도 누르지 말고 바로 타이핑해 보세요.","en":"Fully close the app, reopen it, and start typing without tapping anything."},"wow":{"ko":"열 때마다 키보드가 올라온 빈 초안이 기다려요. 제목·폴더·파일명을 묻지 않는 'Where Text Starts' 철학이에요.","en":"Every launch greets you with a blank draft and the keyboard up, the Where Text Starts philosophy that never asks for a title, folder or filename."}},{"do":{"ko":"방금 쓴 글을 액션으로 미리 알림이나 다른 앱에 보내 보세요.","en":"Send what you just wrote to Reminders or another app with an action."},"wow":{"ko":"쓰고 나서 보낼 곳을 정해요. 복사·공유·딥링크·미리 알림·파일 생성을 한 번에 실행하는 스위스 아미 나이프 구조예요.","en":"You decide where text goes after writing it, a Swiss Army knife that can copy, share, deep link, create reminders or files in one go."}},{"do":{"ko":"Action Directory에서 커뮤니티가 만든 액션 하나를 받아 실행해 보세요.","en":"Download one community action from the Action Directory and run it."},"wow":{"ko":"다른 사용자가 만든 액션을 내려받아 내 워크플로를 바로 넓혀요.","en":"Actions made by other users extend your own workflow immediately."}}],"make":[{"ko":"내 앱의 입력 화면을 열자마자 텍스트 필드에 포커스가 가고 키보드가 올라오게 바꿔 보세요.","en":"Make an input screen in your app focus its text field and raise the keyboard the moment it opens."},{"ko":"저장할 때 제목을 묻는 대신, 쓴 뒤 보낼 곳을 고르는 버튼 몇 개를 두는 프로토타입을 만들어 보세요.","en":"Prototype replacing a save-with-title step with a few buttons that choose where the text goes after writing."}],"ask":{"ko":"제목과 폴더를 묻지 않는 게 왜 기록을 더 자주 하게 만들까요?","en":"Why does not asking for a title or folder make people capture more often?"}},"Shortcuts":{"time":20,"setup":null,"missions":[{"do":{"ko":"새 단축어에서 액션 추가를 열고, 내가 쓰는 서드파티 앱 이름을 검색해 보세요.","en":"In a new shortcut, open the action picker and search for a third-party app you use."},"wow":{"ko":"다른 앱이 App Intents로 공개한 동작이 그대로 자동화 재료로 나와요. 코드 없이 앱끼리 이어져요.","en":"Actions that other apps expose through App Intents show up as building blocks, so apps connect with no code."}},{"do":{"ko":"자동화 탭에서 시간이나 위치 조건으로 개인 자동화를 하나 만들어 보세요.","en":"In the Automation tab, create a personal automation triggered by a time or location."},"wow":{"ko":"내가 실행하지 않아도 시간·위치 변화에 맞춰 스스로 돌아가요.","en":"It runs on its own when the time or your location changes, without you launching it."}},{"do":{"ko":"갤러리에서 단축어 하나를 받아 열고 블록이 어떻게 쌓였는지 보세요.","en":"Get a shortcut from the Gallery, open it and see how its blocks are stacked."},"wow":{"ko":"복잡한 자동화도 위에서 아래로 쌓은 블록이라 읽혀요. iCloud 링크로 복사해 쓰는 문화도 여기서 생겼어요.","en":"Even a complex automation reads as blocks stacked top to bottom, and iCloud links built a culture of copying and reusing them."}}],"make":[{"ko":"내 앱의 핵심 동작 하나를 AppIntent로 공개하고, 단축어 액션 목록에 뜨는지 확인해 보세요.","en":"Expose one core action of your app as an AppIntent and check that it appears in the Shortcuts action list."},{"ko":"그 인텐트로 시간 조건 개인 자동화를 만들어 실제로 실행되는지 지켜보세요.","en":"Build a time-based personal automation with that intent and watch it run."}],"ask":{"ko":"다른 앱의 동작을 재료로 쓰게 한 구조가 왜 사용자를 개발자처럼 만들었을까요?","en":"Why did letting other apps' actions become building blocks turn users into developers?"}},"인프런":{"time":15,"setup":{"ko":"재생해 볼 무료 강의 하나를 미리 찾아 두면 좋아요.","en":"Find one free course in advance so you have something to play."},"missions":[{"do":{"ko":"무료 강의 하나를 내려받은 뒤 비행기 모드로 바꾸고 재생해 보세요.","en":"Download a free lecture, switch to airplane mode and play it."},"wow":{"ko":"데이터 없이도 강의가 그대로 나와요. 모바일 학습의 가장 큰 제약인 네트워크 문제를 출퇴근길에서 지웠어요.","en":"The lecture plays with no data, removing the network problem, the biggest limit of mobile learning, from the commute."}},{"do":{"ko":"재생 중에 중요한 장면을 스크린샷 기능으로 저장하고, 화면 잠금을 켜 보세요.","en":"While playing, save an important moment with the screenshot feature and turn on screen lock."},"wow":{"ko":"필기하듯 장면을 저장하고 화면을 잠가, 모바일에서도 필기와 복습 흐름이 끊기지 않아요.","en":"You save scenes like taking notes and lock the screen, so note-taking and review keep flowing on mobile."}},{"do":{"ko":"배속을 올리고 스크립트 보기를 켜 보세요.","en":"Raise the playback speed and turn on the script view."},"wow":{"ko":"짧은 틈새 시간에 이어 보도록 배속·자막·스크립트·자동 재생이 플레이어에 다 들어 있어요.","en":"Speed, subtitles, script and autoplay are all in the player, built for picking up where you left off in short gaps."}}],"make":[{"ko":"내 앱의 콘텐츠 하나를 오프라인으로 저장하게 만들고 비행기 모드에서 열리는지 확인해 보세요.","en":"Let one piece of content in your app be saved offline and confirm it opens in airplane mode."},{"ko":"AVPlayer 화면에 배속 버튼과 화면 잠금 토글을 붙인 프로토타입을 만들어 보세요.","en":"Prototype an AVPlayer screen with a speed button and a screen-lock toggle."}],"ask":{"ko":"오프라인 다운로드가 왜 출퇴근 학습에서 가장 큰 차이를 만들었을까요?","en":"Why did offline download make the biggest difference for learning on the commute?"}},"Pine Hearts":{"time":20,"setup":null,"missions":[{"do":{"ko":"처음 실행해 첫 컷신 전에 뜨는 설정에서 컬러 블로킹 모드를 켜고 게임을 시작해 보세요.","en":"On first launch, turn on Colour Blocking in the settings that appear before the first cutscene, then start playing."},"wow":{"ko":"게임보다 접근성 설정이 먼저 나와요. 켜면 상호작용 대상과 인물이 단색으로 칠해져 무엇을 만질지 한눈에 보여요.","en":"Accessibility settings come before the game itself, and Colour Blocking paints interactive objects and characters in flat colors so you see what to touch."}},{"do":{"ko":"단순 조작을 켜고, 원래 길게 누르거나 타이밍을 맞춰야 하는 동작을 해 보세요.","en":"Turn on Simplified Controls and try an action that would normally need a long hold or timed press."},"wow":{"ko":"타이밍 입력과 길게 누르기가 한 번의 입력으로 바뀌어요. 달리기도 토글로 기본이 돼요.","en":"Timed presses and long holds become a single input, and running becomes the default with a toggle."}},{"do":{"ko":"글꼴 설정을 열어 기본 글꼴을 확인하고 크기와 자간을 바꿔 보세요.","en":"Open the font settings, check the default font, and change its size and letter spacing."},"wow":{"ko":"기본값부터 난독증 친화 글꼴이에요. 표준 글꼴로도 바꿀 수 있고 크기와 자간도 조절돼요.","en":"A dyslexia-friendly font is the default, with a standard font option plus size and letter-spacing controls."}},{"do":{"ko":"공원 방문객을 도우며 미니맵과 사이드 퀘스트 추적을 확인해 보세요.","en":"While helping park visitors, check the mini-map and side-quest tracking."},"wow":{"ko":"전투 없이 방문객을 돕는 것으로 나아가고, 미니맵과 퀘스트 추적이 길을 기억할 부담을 덜어 줘요.","en":"You progress by helping visitors, not fighting, and the mini-map and quest tracking ease the memory load of finding your way."}}],"make":[{"ko":"내 앱 첫 실행 맨 앞에 글자 크기와 대비를 고르는 접근성 설정 한 화면을 넣어 보세요.","en":"Put a single accessibility screen for text size and contrast at the very start of your app's first launch."},{"ko":"상호작용 요소만 단색으로 칠하는 '컬러 블로킹' 토글을 프로토타입에 붙여 보세요.","en":"Add a colour-blocking toggle to a prototype that paints only interactive elements in flat colors."}],"ask":{"ko":"접근성 설정을 첫 컷신보다 먼저 둔 순서가 왜 그렇게 중요했을까요?","en":"Why did placing accessibility settings before the first cutscene matter so much?"}},"The Outsiders: Athlete Tracker":{"time":10,"setup":{"ko":"iOS 26 이상이 필요하고, 건강 앱에 운동과 수면 기록이 쌓여 있어야 제대로 보여요.","en":"It needs iOS 26 or later, and it shows best with workout and sleep history already in Health."},"missions":[{"do":{"ko":"건강 앱에 기록이 쌓인 상태에서 앱을 열고, 홈의 훈련 준비도 점수 하나만 보고 오늘 운동 강도를 정해 보세요.","en":"With history in Health, open the app and decide today's workout intensity from the home Training Readiness score alone."},"wow":{"ko":"훈련 부하·수면·안정시 심박을 합친 숫자 하나가 오늘 감당할 강도를 알려 줘요. Gentler Streak 팀이 앱을 부풀리는 대신 따로 만들었어요.","en":"One number combining training load, sleep and resting heart rate tells you today's effort. The Gentler Streak team built it separately instead of bloating that app."}},{"do":{"ko":"훈련 방식을 폴라라이즈드, 피라미드, 역치 중 다른 것으로 바꿔 보세요.","en":"Switch your training approach between polarized, pyramid and threshold."},"wow":{"ko":"고른 방식에 따라 안내가 달라져요. 활동 종류마다 심박 구간도 따로 정할 수 있어요.","en":"The guidance changes with the approach you pick, and heart-rate zones can be set per activity type."}},{"do":{"ko":"캘린더 화면에서 강훈련 블록과 회복 주를 찾아보세요.","en":"Find hard training blocks and recovery weeks in the calendar view."},"wow":{"ko":"강훈련과 회복 주가 한눈에 요약되고, 지구력·심폐 체력·사이클 FTP 추세도 함께 볼 수 있어요.","en":"Hard blocks and recovery weeks are summarized at a glance, alongside trends for endurance, cardio fitness and cycling FTP."}}],"make":[{"ko":"내 앱 홈 화면을 여러 지표 대신 점수 하나와 한 줄 해석으로 바꾼 시안을 만들어 보세요.","en":"Mock up your app's home screen as one score and a one-line interpretation instead of many metrics."},{"ko":"HealthKit에서 수면과 안정시 심박을 읽어 간단한 점수를 계산하는 프로토타입을 만들어 보세요.","en":"Prototype reading sleep and resting heart rate from HealthKit and computing a simple score."}],"ask":{"ko":"여러 지표를 점수 하나로 합친 게 왜 선수에게 더 쓸모 있었을까요?","en":"Why was folding many metrics into one score more useful to athletes?"}},"(Not Boring) Camera":{"time":10,"setup":{"ko":"무료로 받을 수 있지만 전체 기능은 연 약 15달러 멤버십이에요.","en":"It downloads free, but the full app is a membership of about $15 a year."},"missions":[{"do":{"ko":"잠금 화면 컨트롤을 추가한 뒤, 잠금 화면에서 눌러 첫 사진을 찍을 때까지 시간을 재 보세요.","en":"Add the Lock Screen control, then time how long it takes from the lock screen to your first photo."},"wow":{"ko":"1초가 안 걸려요. 거대한 버튼과 햅틱 다이얼의 장난감 같은 UI인데, 촬영 단계에서 3D LUT 색보정까지 하는 앱이에요.","en":"It takes under a second. Behind a toy-like UI of giant buttons and haptic dials, it applies 3D LUT color grading at capture."}},{"do":{"ko":"어두운 방에서 한 장 찍고, 결과를 크게 확대해 노이즈를 살펴보세요.","en":"Take a photo in a dark room and zoom in to study the noise."},"wow":{"ko":"AI로 문질러 지우지 않고 센서 노이즈를 필름 그레인처럼 살려요. LUT가 입혀진 HEIC로 바로 저장돼요.","en":"Sensor noise is kept as film-like grain instead of AI smoothing, and the photo saves as a HEIC with the LUT already applied."}},{"do":{"ko":"휴대폰을 천천히 기울여 보고, 다이얼을 손가락으로 돌려 보세요.","en":"Tilt the phone slowly, then turn a dial with your finger."},"wow":{"ko":"3D 인터페이스의 조명이 움직임에 따라 바뀌고, 다이얼마다 햅틱과 스테레오 효과음이 손에 걸려요.","en":"The 3D interface's lighting shifts as you move, and every dial gives custom haptics and stereo sound."}},{"do":{"ko":"장난감 같은 화면 뒤에서 수동 셔터·ISO와 포커스 피킹을 찾아보세요.","en":"Find manual shutter, ISO and focus peaking behind the playful surface."},"wow":{"ko":"히스토그램, 제브라, ProRAW 같은 프로 기능이 놀이 같은 겉면 뒤에 숨어 있어요.","en":"Pro tools like a histogram, zebra stripes and ProRAW sit behind the playful surface."}}],"make":[{"ko":"내 앱의 주요 버튼 하나에 커스텀 햅틱과 짧은 효과음을 붙여 누르는 느낌을 비교해 보세요.","en":"Add custom haptics and a short sound to one key button in your app and compare how pressing it feels."},{"ko":"Core Image의 CIColorCube로 카메라 미리보기에 LUT를 입히는 프로토타입을 만들어 보세요.","en":"Prototype applying a LUT to a camera preview with Core Image's CIColorCube."}],"ask":{"ko":"장난감 같은 겉모습이 왜 프로 기능을 더 만지고 싶게 만들었을까요?","en":"Why did a toy-like surface make the pro features more inviting?"}},"Speechify":{"time":10,"setup":{"ko":"기본 읽기는 무료지만 프리미엄 목소리와 더 빠른 속도는 구독이 필요해요.","en":"Basic reading is free, but premium voices and higher speeds need a subscription."},"missions":[{"do":{"ko":"긴 글 하나를 열고 속도를 평소 읽는 속도보다 훨씬 올린 채 단어 하이라이트를 따라가 보세요.","en":"Open a long text, push the speed well above your normal reading pace and follow the word highlighting."},"wow":{"ko":"보통 읽기 속도를 훌쩍 넘겨도 하이라이트가 따라와요. 난독증 창업자가 자기 공부용으로 만든 도구에서 시작해 5,000만 명 넘게 쓰게 됐어요.","en":"The highlight keeps up well past normal reading speed. It began as a tool its dyslexic founder built for his own studies and now serves 50 million-plus users."}},{"do":{"ko":"책 한 페이지를 카메라로 찍어 바로 읽게 해 보세요.","en":"Photograph a book page with the camera and have it read right away."},"wow":{"ko":"카메라 OCR로 종이 페이지도 곧장 음성이 되고, 단어별 하이라이트가 붙어요.","en":"Camera OCR turns a paper page straight into audio, with word-by-word highlighting."}},{"do":{"ko":"목소리 목록에서 유명인 목소리를 골라 같은 문단을 다시 들어 보세요.","en":"Pick a celebrity voice from the list and listen to the same paragraph again."},"wow":{"ko":"스눕 독, 기네스 팰트로 같은 유명인 목소리까지 있어 기계음 느낌이 덜해요.","en":"There are even celebrity voices such as Snoop Dogg and Gwyneth Paltrow, so listening feels less robotic."}}],"make":[{"ko":"내 앱의 긴 텍스트에 0.5배부터 3배까지 고르는 읽기 속도 슬라이더를 붙여 보세요.","en":"Add a reading-speed slider to long text in your app that goes from half speed to triple speed."},{"ko":"카메라로 찍은 페이지를 Vision 텍스트 인식으로 읽어 바로 말하게 하는 프로토타입을 만들어 보세요.","en":"Prototype photographing a page, recognizing its text with Vision and speaking it immediately."}],"ask":{"ko":"난독증을 위해 만든 기능이 왜 속독하려는 사용자에게도 통했을까요?","en":"Why did a feature built for dyslexia also win over speed listeners?"}},"Pawz":{"time":10,"setup":{"ko":"Vision Pro 전용 앱이라 Apple Vision Pro가 필요해요.","en":"It is a Vision Pro only app, so you need an Apple Vision Pro."},"missions":[{"do":{"ko":"Vision Pro에서 앱을 열고, 내 방 바닥이나 책상 근처에서 펫과 놀아 보세요.","en":"Open the app on Vision Pro and play with the pet near your floor or desk."},"wow":{"ko":"가상 공간이 아니라 패스스루로 보이는 진짜 내 방에 펫이 있어요. 함께 노는 방식에 반응하며 성장해요.","en":"The pet is in your actual room through passthrough, not a virtual scene, and it grows as it reacts to how you play."}},{"do":{"ko":"펫 옆에서 호흡 명상을 시작해 보세요.","en":"Start a breathing meditation next to the pet."},"wow":{"ko":"혼자 하는 호흡이 아니라 펫과 함께하는 활동이 돼요. 명상 쉬는 시간이 내 공간 안에서 일어나요.","en":"Breathing becomes a shared activity with the pet, and the meditation break happens in your own space."}},{"do":{"ko":"미니게임에서 별을 모아 아이템으로 바꾸고 펫의 공간을 꾸며 보세요.","en":"Collect stars in the mini-game, redeem them for items and decorate the pet's space."},"wow":{"ko":"경쟁 없는 가벼운 보상 고리가 다시 올 이유를 줘요. 펫은 내가 꾸민 환경에도 반응해요.","en":"A light, non-competitive reward loop gives you a reason to return, and the pet reacts to the space you decorate."}}],"make":[{"ko":"내 앱의 휴식이나 명상 화면에 함께 숨 쉬는 캐릭터 애니메이션 하나를 붙여 보세요.","en":"Add one character animation that breathes along with the user to a break or meditation screen in your app."},{"ko":"visionOS 프로토타입에서 RealityKit으로 작은 3D 모델 하나를 방 안 평면 위에 올려 보세요.","en":"In a visionOS prototype, place one small 3D model on a real surface in the room with RealityKit."}],"ask":{"ko":"펫이 가상 공간이 아닌 내 방에 있다는 게 왜 명상 습관을 더 쉽게 만들까요?","en":"Why does having the pet in your own room rather than a virtual scene make a meditation habit easier?"}},"Neva":{"time":30,"setup":{"ko":"Mac 전용으로 안내된 유료 게임(￦33,000)이라 Mac이 필요해요.","en":"It is listed as Mac only and costs ￦33,000, so you need a Mac."},"missions":[{"do":{"ko":"첫 장면에서 주인공과 늑대 새끼가 함께 움직이는 순간을 천천히 지켜보세요.","en":"Watch slowly as the heroine and the wolf cub move together in the opening scenes."},"wow":{"ko":"보간이 거의 불가능한 전통 손그림 애니메이션이에요. GRIS 팀이 20명 규모로 4년을 들였고 애니 어워드 캐릭터 애니메이션상을 받았어요.","en":"It is traditional hand-drawn animation that is nearly impossible to interpolate. The GRIS team grew to about 20 people, spent four years, and won the Annie Award for Character Animation."}},{"do":{"ko":"퍼즐에서 막히면 네바의 이름을 불러 원하는 곳으로 보내 보세요.","en":"When a puzzle stops you, call Neva's name to send the wolf to a spot."},"wow":{"ko":"이름 부르기라는 단순한 명령 하나로 동료가 퍼즐 풀이의 일부가 돼요.","en":"One simple contextual command, calling her name, makes the companion part of solving the puzzle."}},{"do":{"ko":"전투에서 공격을 끊지 말고 연달아 이어 가며 체력을 지켜보세요.","en":"In combat, keep chaining attacks without stopping and watch your health."},"wow":{"ko":"공격을 이어 가면 체력이 차요. 회복 아이템을 찾아다니지 않아 전투 흐름이 끊기지 않아요.","en":"Chaining attacks regenerates health, so combat keeps flowing instead of sending you hunting for pickups."}},{"do":{"ko":"말이 나오지 않는 장면에서 그림과 음악만으로 무엇이 전해지는지 느껴 보세요.","en":"In a wordless scene, notice what comes across through art and music alone."},"wow":{"ko":"대사 한 마디 없이 손그림, 애니메이션, 음악만으로 이야기가 흘러가요.","en":"With no dialogue at all, the story is carried by hand-painted art, animation and score."}}],"make":[{"ko":"내 앱의 캐릭터나 아이콘 동작 하나를 손으로 그린 4~6프레임 애니메이션으로 바꿔 보간 애니메이션과 비교해 보세요.","en":"Replace one character or icon motion in your app with a hand-drawn four-to-six-frame animation and compare it with an interpolated one."},{"ko":"텍스트 없이 그림과 소리만으로 다음 행동을 알려 주는 튜토리얼 화면 하나를 만들어 보세요.","en":"Build one tutorial screen that shows the next action through visuals and sound with no text."}],"ask":{"ko":"말이 없는 게임에서 동료와의 유대가 왜 조작으로 더 깊게 전해질까요?","en":"In a wordless game, why does the bond with a companion come through more deeply through controls?"}},"Dudel Draw":{"time":10,"setup":{"ko":"iPad와 Apple Pencil이 있으면 그리기 기능을 더 잘 느낄 수 있어요.","en":"An iPad with Apple Pencil lets you feel the drawing tools best."},"missions":[{"do":{"ko":"오늘의 도형으로 그림 하나를 그리고, 친구에게도 같은 도형으로 그려 달라고 한 뒤 두 그림을 비교해 보세요.","en":"Draw something from today's shape, ask a friend to draw from the same shape, and compare the two."},"wow":{"ko":"모두에게 같은 도형 하나가 가는데 결과는 전혀 달라요. 빈 캔버스 대신 제약 하나가 시작을 쉽게 만들어요.","en":"Everyone gets the same single shape, yet the drawings come out completely different. One constraint replaces the blank canvas and makes starting easy."}},{"do":{"ko":"홈 화면에 위젯을 추가하고 다음 날 위젯을 먼저 확인해 보세요.","en":"Add the home screen widget and check it first thing the next day."},"wow":{"ko":"푸시 알림 없이도 위젯이 오늘의 도형과 내 그림을 보여 줘 다시 돌아오게 해요.","en":"With no push notification, the widget shows today's shape and your drawing and pulls you back."}},{"do":{"ko":"며칠 이어서 그리며 연속 기록이 어떻게 보이는지 확인해 보세요.","en":"Draw several days in a row and see how your streak is shown."},"wow":{"ko":"숫자 카운터 대신 작은 알이 병아리로 깨어나요. 벌주지 않는 부드러운 연속 기록이에요.","en":"Instead of a counter, a tiny egg hatches into a chicken, a gentle streak that never punishes."}},{"do":{"ko":"그리다가 두 손가락으로 한 번 탭하고, 이어서 두 번 탭해 보세요.","en":"While drawing, tap with two fingers, then double-tap with two fingers."},"wow":{"ko":"실행 취소와 다시 실행이에요. 툴바 없이도 캔버스가 깨끗하게 유지돼요.","en":"That is undo and redo, so the canvas stays clean with no toolbar."}}],"make":[{"ko":"내 앱에 매일 바뀌는 프롬프트 하나를 위젯으로 보여 주는 WidgetKit 프로토타입을 만들어 보세요.","en":"Prototype a WidgetKit widget that shows one daily prompt from your app."},{"ko":"PencilKit 캔버스 하나를 띄우고 두 손가락 탭 실행 취소를 붙여 보세요.","en":"Put up a PencilKit canvas and add two-finger-tap undo."}],"ask":{"ko":"모두에게 똑같은 도형 하나를 주는 제약이 왜 빈 캔버스보다 그리기를 쉽게 만들었을까요?","en":"Why did giving everyone the same single shape make drawing easier than a blank canvas?"}},"Lost in Play":{"time":20,"setup":null,"missions":[{"do":{"ko":"소리를 켜고, 첫 장면에서 인물들이 대화하는 순간에 귀를 기울여 보세요.","en":"With sound on, listen closely when characters talk in the opening scene."},"wow":{"ko":"대사가 한 마디도 없어요. 알아들을 수 없는 말과 몸짓, 그림 기호만으로 다 이해돼요. TV 애니메이션 출신 7명이 3년을 들여 만들었어요.","en":"There is not a single line of dialogue, yet gibberish, gestures and pictures make everything clear. Seven former TV animators spent three years on it."}},{"do":{"ko":"퍼즐에서 일부러 막힌 채로 힌트를 불러 보세요.","en":"Get stuck on a puzzle on purpose and call up a hint."},"wow":{"ko":"힌트가 답을 주지 않고 살짝 밀어 줘요. 공략을 찾으러 게임을 떠나지 않게 만든 장치예요.","en":"The hint nudges without giving the answer, designed so you never leave to search for a walkthrough."}},{"do":{"ko":"무서운 장면이 오면 화면이 어떻게 움직이는지 지켜보세요.","en":"When a scary moment comes, watch how the screen moves."},"wow":{"ko":"TV 애니메이션처럼 카메라가 흔들려요. 연출이 애니메이션의 문법을 따라요.","en":"The camera shakes like in TV animation, borrowing that medium's language."}},{"do":{"ko":"퍼즐 사이에 나오는 미니게임을 아이나 가족과 함께 해 보세요.","en":"Play the mini-games between puzzles together with a child or family member."},"wow":{"ko":"다양한 미니게임이 끼어들어 흐름이 새로워지고, 부모와 아이가 같이 하기 좋아요.","en":"Varied mini-games keep things fresh and suit parents and children playing together."}}],"make":[{"ko":"내 앱의 안내 문구 하나를 글자 없이 그림 기호와 소리만으로 바꿔 사람들이 알아듣는지 시험해 보세요.","en":"Replace one instruction in your app with pictures and sound only, and test whether people understand it."},{"ko":"답을 바로 주지 않고 단계적으로 힌트를 주는 버튼 하나를 프로토타입에 붙여 보세요.","en":"Add a hint button to a prototype that nudges in stages instead of giving the answer."}],"ask":{"ko":"대사가 없다는 제약이 왜 오히려 모든 나이와 언어의 사람에게 통했을까요?","en":"Why did having no dialogue make it work for every age and language?"}},"Gentler Streak Fitness Tracker":{"time":10,"setup":{"ko":"Apple Watch의 심박 데이터가 있어야 활동 경로가 제대로 보여요.","en":"It shows the Activity Path properly only with heart-rate data from an Apple Watch."},"missions":[{"do":{"ko":"하루는 운동을 쉬고, 다음 날 연속 기록과 활동 경로를 확인해 보세요.","en":"Skip a workout for a day, then check your streak and Activity Path the next day."},"wow":{"ko":"쉬어도 연속 기록이 끊기지 않아요. 심박 변이도·수면·운동 부하를 읽어서 오늘은 쉬라고까지 말해 줘요.","en":"Rest does not break the streak. It reads HRV, sleep and workload and will actually tell you to take today off."}},{"do":{"ko":"Apple Watch로 운동하는 도중 일부러 강도를 확 올려 보세요.","en":"During a workout with Apple Watch, push the intensity up sharply on purpose."},"wow":{"ko":"Go Gentler가 운동 중 심박을 보고 최적 구간에 머물도록 속도를 늦추거나 올리라고 알려 줘요.","en":"Go Gentler watches your heart rate mid-workout and nudges you to slow down or step up to stay in your optimal zone."}},{"do":{"ko":"개 산책이나 집안일, 정원 일을 활동으로 기록해 보세요.","en":"Log a dog walk, housework or gardening as an activity."},"wow":{"ko":"100가지 넘는 활동 유형으로 집안일까지 운동으로 쳐 줘요.","en":"With 100-plus activity types, even chores count."}}],"make":[{"ko":"내 앱의 연속 기록에 '쉬는 날' 상태를 추가해, 쉬어도 기록이 끊기지 않게 바꿔 보세요.","en":"Add a rest day state to your app's streak so resting does not break it."},{"ko":"HealthKit에서 수면과 심박 변이도를 읽어 '오늘은 쉬세요' 한 줄을 띄우는 프로토타입을 만들어 보세요.","en":"Prototype reading sleep and HRV from HealthKit and showing a single take-today-off line."}],"ask":{"ko":"쉬는 날을 실패가 아닌 성공으로 표시한 게 왜 오래 쓰게 만들까요?","en":"Why does marking rest days as success, not failure, keep people using it longer?"}},"Honkai: Star Rail":{"time":30,"setup":null,"missions":[{"do":{"ko":"첫 전투에서 궁극기를 쓰고, 연출이 끝날 때까지 손을 떼고 지켜보세요.","en":"Use an Ultimate in your first battle and take your hands off until the animation ends."},"wow":{"ko":"콘솔급 시네마틱 궁극기 연출이 폰에서 돌아가요. 출시 10일 만에 1억 달러, 모바일만으로 3개월 만에 5억 달러를 번 게임이에요.","en":"Console-grade cinematic Ultimates run on a phone. This game passed $100 million in 10 days and made $500 million on mobile alone in three months."}},{"do":{"ko":"한 손으로만 폰을 잡고 턴제 전투를 끝까지 해 보세요.","en":"Hold the phone in one hand and play a turn-based battle to the end."},"wow":{"ko":"짧은 탭 위주의 턴과 Path로 나뉜 역할 덕분에 깊은 전술이 한 손에 들어와요.","en":"Short tap-driven turns and roles defined by Paths make deep tactics playable one-handed."}},{"do":{"ko":"쉬운 전투에서 자동 전투와 배속을 켜 보세요.","en":"Turn on auto-battle and speed-up in an easy fight."},"wow":{"ko":"반복 전투는 맡기고 어려운 전투만 직접 해요. 짧은 모바일 세션을 존중하는 설계예요.","en":"You hand off the grind and play hard fights yourself, a design that respects short mobile sessions."}}],"make":[{"ko":"내 앱의 성공 순간 하나에 1~2초짜리 전체 화면 연출을 넣고, 건너뛰기 버튼도 함께 달아 보세요.","en":"Add a one-to-two-second full-screen celebration to one success moment in your app, with a skip button."},{"ko":"반복 작업에 '자동'과 '빠르게' 토글 두 개를 붙인 프로토타입을 만들어 보세요.","en":"Prototype a repetitive task with two toggles, auto and fast."}],"ask":{"ko":"턴제 전투가 왜 폰 한 손 조작과 콘솔급 연출을 함께 가능하게 했을까요?","en":"Why did turn-based combat make one-handed play and console-grade spectacle possible together?"}},"Passenger Assistance":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라 개발사의 공식 소개 영상이나 스크린샷으로 경험해야 해요.","en":"The app has left the App Store, so experience it through the developer's own video or screenshots."},"missions":[{"do":{"ko":"공식 소개 영상이나 스크린샷에서 도움 요청 예약 화면을 찾아, 단계가 몇 개인지 세어 보세요.","en":"In the official video or screenshots, find the assistance booking screens and count the steps."},"wow":{"ko":"장애인·고령 승객이 전화 대신 앱으로 역무원 도움을 요청해요. 2021년 도입 뒤 수백만 건의 여정을 도왔어요.","en":"Disabled and older passengers request staff assistance from an app instead of a phone call, and it has supported millions of journeys since 2021."}},{"do":{"ko":"영상이나 스크린샷에서 접근성 요구를 적는 프로필 화면을 찾아보세요.","en":"Look for the profile screen where accessibility needs are entered in the video or screenshots."},"wow":{"ko":"필요한 도움을 프로필에 한 번만 적으면, 여정마다 장애를 다시 설명하지 않아도 돼요.","en":"You describe your needs once in a profile and never have to re-explain your disability for each journey."}},{"do":{"ko":"스크린샷에서 메시지 화면과 색 테마 차이를 찾아보세요.","en":"Find the messaging screen and the different colour themes in the screenshots."},"wow":{"ko":"장애인 사용자, 역무원과 함께 설계해 WCAG 기준에 색 테마 네 개를 갖췄고, 메시지로 직원과 바로 이어져요.","en":"Co-designed with disabled users and rail staff, it is built to WCAG with four colour themes, and messaging connects you straight to staff."}}],"make":[{"ko":"내 앱에서 사용자가 매번 반복해 입력하는 정보 하나를 프로필에 한 번 저장해 재사용하게 바꿔 보세요.","en":"Find one thing users re-enter every time in your app and let them save it once in a profile."},{"ko":"내 앱 화면 하나를 고대비 테마로 바꿔 보고 VoiceOver로 끝까지 조작해 보세요.","en":"Switch one screen of your app to a high-contrast theme and operate it end to end with VoiceOver."}],"ask":{"ko":"한 번만 적는 프로필이 왜 장애인 승객에게 그렇게 큰 차이를 만들었을까요?","en":"Why did a profile you fill in once make such a big difference for disabled passengers?"}},"Railbound":{"time":20,"setup":{"ko":"유료 게임(￦7,700)이에요.","en":"It is a paid game (￦7,700)."},"missions":[{"do":{"ko":"첫 레벨에서 손가락 하나로 탭하고 끌어 선로를 깔아 보세요.","en":"In the first level, lay track with a single tap-and-drag of one finger."},"wow":{"ko":"제스처 하나로 등각 격자에 선로가 깔려요. 폴란드 작은 스튜디오가 이 단순함으로 스팀에서만 5만 장, 약 95% 긍정 리뷰를 얻었어요.","en":"One gesture lays track on an isometric grid. With that simplicity a tiny Polish studio sold 50,000 copies on Steam alone with about 95% positive reviews."}},{"do":{"ko":"번호 붙은 객차가 일부러 순서를 틀려 도착하게 선로를 깔아 보세요.","en":"Lay track so the numbered carriages arrive out of order on purpose."},"wow":{"ko":"규칙이 객차를 순서대로 기관차에 잇는 것 하나뿐이라 무엇이 틀렸는지 바로 알 수 있어요.","en":"The only rule is getting numbered carriages to the engine in order, so you see at once what went wrong."}},{"do":{"ko":"새 월드로 넘어가 처음 등장하는 장치를 써 보세요.","en":"Move to a new world and use the mechanic it introduces."},"wow":{"ko":"월드마다 터널, 역, 전환기 같은 장치가 하나씩 더해지고, 뒤로 갈수록 서로 섞여요.","en":"Each world adds one mechanic such as tunnels, stations or switches, and later worlds combine them."}}],"make":[{"ko":"내 앱의 핵심 조작 하나를 탭 앤 드래그 한 동작으로 줄인 프로토타입을 만들어 보세요.","en":"Prototype reducing one core interaction in your app to a single tap-and-drag."},{"ko":"기능 하나를 소개할 때 이전 것과 섞기 전에 그것만 단독으로 연습하는 단계를 하나 넣어 보세요.","en":"When introducing a feature, add one step that practices it alone before mixing it with earlier ones."}],"ask":{"ko":"조작이 단 하나뿐이라는 점이 왜 퍼즐을 더 깊게 만들었을까요?","en":"Why did having only one interaction make the puzzles deeper?"}},"Resident Evil Village":{"time":30,"setup":{"ko":"iPhone 15 Pro 이상이나 Apple 실리콘 iPad 또는 M1 이후 Mac이 필요하고, 전체 게임은 구매해야 해요.","en":"You need an iPhone 15 Pro or later, an Apple silicon iPad or an M1 or later Mac, and the full game is a purchase."},"missions":[{"do":{"ko":"지원 기기에서 첫 장면을 실행하고, 그래픽 설정이 있다면 업스케일링을 켜고 끄며 비교해 보세요.","en":"Launch the opening on a supported device and, if graphics settings allow, compare upscaling on and off."},"wow":{"ko":"콘솔 AAA 호러가 Apple silicon 네이티브로 돌아요. WWDC 2022에서 Metal 3·MetalFX 업스케일링 대표 데모였던 게임이에요.","en":"A console AAA horror game runs natively on Apple silicon. It was the WWDC 2022 stage demo for Metal 3 and MetalFX Upscaling."}},{"do":{"ko":"안개와 조명이 짙은 장면에서 멈춰 빛과 그림자를 살펴보세요.","en":"Pause in a scene thick with fog and lighting and study the light and shadow."},"wow":{"ko":"고딕 성, 공장, 짙은 조명과 안개가 Metal 3 렌더링의 혹독한 시험대 역할을 했어요.","en":"The gothic castle, factories, dense lighting and fog doubled as a demanding showcase for Metal 3 rendering."}},{"do":{"ko":"같은 구매로 다른 Apple 기기에서도 게임을 열어 보세요.","en":"Open the game on another Apple device under the same purchase."},"wow":{"ko":"iPhone 15 Pro, Apple silicon iPad, Mac에서 한 번의 구매로 이어져요.","en":"A single purchase carries across iPhone 15 Pro, Apple silicon iPads and Macs."}}],"make":[{"ko":"Metal 샘플 프로젝트 하나를 받아 렌더 해상도를 낮췄을 때 프레임이 얼마나 오르는지 재 보세요.","en":"Take a Metal sample project and measure how much the frame rate rises when you lower the render resolution."},{"ko":"MetalFX 공간 업스케일러를 샘플에 붙여 낮은 해상도 화면을 키워 원본과 비교해 보세요.","en":"Add the MetalFX spatial upscaler to a sample and compare an upscaled low-resolution frame with the original."}],"ask":{"ko":"낮게 그리고 키워 보여 주는 방식이 왜 휴대 기기에서 콘솔 게임을 가능하게 했을까요?","en":"Why did rendering low and upscaling make console games possible on portable devices?"}},"Letter Rooms":{"time":10,"setup":null,"missions":[{"do":{"ko":"VoiceOver를 켜고 화면을 가린 채로 퍼즐 하나를 끝까지 풀어 보세요.","en":"Turn on VoiceOver, cover the screen and solve one puzzle to the end."},"wow":{"ko":"글자를 섞고 옮기는 퍼즐이 소리만으로 풀려요. 1인 개발자가 독일의 시각장애인 개발자 Jan Blüher와 함께 다듬었어요.","en":"A letter-shuffling puzzle can be solved by sound alone. Its solo developer refined it with Jan Blüher, a blind developer from Germany."}},{"do":{"ko":"OpenDyslexic 글꼴로 바꾸거나 음성 제어로 글자를 옮겨 보세요.","en":"Switch to the OpenDyslexic font, or move letters with Voice Control."},"wow":{"ko":"시각뿐 아니라 운동과 읽기 차이까지 챙겼어요.","en":"It covers motor and reading differences, not only vision."}},{"do":{"ko":"어려운 레벨에서 일부러 건너뛰기를 해 보세요.","en":"On a hard level, skip it on purpose."},"wow":{"ko":"벌칙 없이 넘어가요. 단어 게임에 흔한 좌절의 벽을 없앴어요.","en":"You move on with no penalty, removing the frustration wall common in word games."}}],"make":[{"ko":"내 앱에서 드래그로 순서를 바꾸는 화면에 VoiceOver용 위로·아래로 이동 동작을 붙여 보세요.","en":"Add VoiceOver move up and move down actions to a drag-to-reorder screen in your app."},{"ko":"화면 커튼을 켜고 내 앱의 핵심 작업 하나를 소리만으로 끝낼 수 있는지 시험해 보세요.","en":"Turn on Screen Curtain and test whether one core task in your app can be finished by sound alone."}],"ask":{"ko":"눈으로 보는 퍼즐이 소리만으로도 풀리려면 무엇이 가장 중요했을까요?","en":"What mattered most for a visual puzzle to be solvable by sound alone?"}},"A Musical Story":{"time":20,"setup":{"ko":"유료 게임($4.99)이고, 이어폰을 끼고 하면 좋아요.","en":"It is a paid game ($4.99), and headphones help."},"missions":[{"do":{"ko":"이어폰을 끼고 첫 곡에서 화면보다 귀에 집중해 악기 파트를 듣고 따라 눌러 보세요.","en":"With headphones on, focus on your ears more than the screen in the first song and tap along to an instrument part."},"wow":{"ko":"노트 길을 읽는 대신 듣고 느끼며 연주해야 풀려요. 어린 시절 친구들인 프랑스 팀이 2017년부터 약 5년을 다듬은 데뷔작이에요.","en":"You solve it by listening and feeling, not reading a note highway. It is the debut of a small French team of childhood friends, refined since 2017."}},{"do":{"ko":"멜로디 하나를 끝까지 제대로 연주해 보세요.","en":"Play one melody correctly all the way through."},"wow":{"ko":"맞게 연주한 멜로디가 다음 장을 열어요. 70년대 포크록 풍 26곡이 이야기 그 자체예요.","en":"Each correctly played melody unlocks the next chapter, so the 26-track 70s folk-rock soundtrack is the story itself."}},{"do":{"ko":"장면이 바뀔 때 글이나 대사가 나오는지 지켜보세요.","en":"Watch for any text or dialogue as the scenes change."},"wow":{"ko":"말 한 마디 없이 가브리엘의 기억이 음악으로만 전해져요.","en":"Gabriel's memories are told through music alone, without a single word."}}],"make":[{"ko":"내 앱의 성공 피드백 하나를 화면 표시 대신 짧은 소리 패턴으로 바꿔 보세요.","en":"Replace one success feedback in your app with a short sound pattern instead of a visual cue."},{"ko":"소리에 맞춰 탭하면 다음 단계가 열리는 리듬 입력 프로토타입을 만들어 보세요.","en":"Prototype a rhythm input where tapping in time with a sound unlocks the next step."}],"ask":{"ko":"눈 대신 귀로 연주하게 한 선택이 왜 이야기를 더 가깝게 느끼게 했을까요?","en":"Why did playing by ear instead of by sight bring the story closer?"}},"LEGO Star Wars: Castaways":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"It requires an Apple Arcade subscription."},"missions":[{"do":{"ko":"섬의 모래나 절벽, 구조물에 가까이 다가가 조각이 어떻게 끼워졌는지 살펴보세요.","en":"Get close to the island's sand, cliffs or structures and study how the pieces fit together."},"wow":{"ko":"모래와 절벽까지 실제 브릭이에요. 7,500조각 밀레니엄 팔콘에 게임이 다운되자 빛 분석으로 안 보이는 조각을 지워 폴리곤을 약 90% 줄였어요.","en":"Even sand and cliffs are real bricks. When the 7,500-piece Millennium Falcon crashed the game, lighting analysis removed hidden bricks and cut polygons by about 90%."}},{"do":{"ko":"머리, 몸통, 다리를 서로 다른 캐릭터에서 골라 내 미니피규어를 만들어 보세요.","en":"Make your own minifigure by picking a head, torso and legs from different characters."},"wow":{"ko":"루크나 레아가 아니라 시리즈 전체 부품을 섞은 나만의 캐릭터로 놀아요.","en":"You play as your own mix of parts from across the saga, not as Luke or Leia."}},{"do":{"ko":"소셜 허브에서 다른 플레이어에게 레고 이모트를 써 보세요.","en":"Use a LEGO Emote at another player in the social hub."},"wow":{"ko":"라이선스 액션 게임이 미니게임과 협동이 있는 어울림 공간이 돼요.","en":"A licensed action game becomes a hangout space with mini-games and co-op."}}],"make":[{"ko":"내 3D 장면이나 화면에서 보이지 않는 요소를 찾아 지우고, 프레임이나 메모리가 얼마나 줄어드는지 재 보세요.","en":"Find and remove invisible elements in a 3D scene or screen of yours and measure the frame or memory savings."},{"ko":"아바타의 머리·몸통·다리를 따로 골라 조합하는 3칸 선택기 프로토타입을 만들어 보세요.","en":"Prototype a three-part avatar picker that mixes head, torso and legs separately."}],"ask":{"ko":"실제로 조립 가능한 레고 규칙을 지킨 게 왜 놀이를 더 믿음직하게 만들었을까요?","en":"Why did following real, buildable LEGO rules make the play feel more believable?"}},"1Password":{"time":15,"setup":{"ko":"새 계정을 만들면 Secret Key가 담긴 Emergency Kit를 저장할 곳을 미리 생각해 두세요.","en":"If you create a new account, plan where to keep the Emergency Kit with your Secret Key."},"missions":[{"do":{"ko":"새 계정을 만들 때 저장하는 Emergency Kit에서 Secret Key를 확인해 보세요.","en":"When creating an account, look at the Secret Key in the Emergency Kit you save."},"wow":{"ko":"비밀번호와 기기에서 만든 128비트 Secret Key를 함께 써서 암호화해, 서버가 털려도 풀 수 없어요. 2022년 캐나다 역사상 최대 투자를 받은 회사예요.","en":"Vaults are encrypted with your password plus a locally made 128-bit Secret Key, so a server breach alone cannot decrypt them. In 2022 it raised Canada's largest-ever round."}},{"do":{"ko":"며칠 동안 Face ID로만 열다가 전체 비밀번호를 다시 묻는 순간을 기다려 보세요.","en":"Unlock with Face ID only for a few days and wait for the moment it asks for your full password."},"wow":{"ko":"일부러 넣은 마찰이에요. 비밀번호를 잊지 않도록 주기적으로 다시 입력하게 해요.","en":"It is deliberate friction, asking again periodically so you never forget the password."}},{"do":{"ko":"Watchtower를 열어 경고가 몇 개 뜨는지 세어 보세요.","en":"Open Watchtower and count how many warnings appear."},"wow":{"ko":"재사용, 약한, 유출된 비밀번호와 2단계 인증 지원 사이트가 눈에 보이는 체크리스트가 돼요.","en":"Reused, weak and breached passwords and sites that support two-factor become a visible checklist."}},{"do":{"ko":"다른 앱의 로그인 화면에서 키보드 위 QuickType 막대를 보세요.","en":"On another app's login screen, look at the QuickType bar above the keyboard."},"wow":{"ko":"복사해 붙이지 않아도 저장된 로그인 정보와 패스키가 시스템 자동 입력으로 떠요.","en":"Saved logins and passkeys appear through system AutoFill, with no copy and paste."}}],"make":[{"ko":"내 앱의 로그인 필드에 textContentType을 지정해 iOS 비밀번호 자동 입력이 뜨는지 확인해 보세요.","en":"Set textContentType on your app's login fields and confirm iOS Password AutoFill appears."},{"ko":"내 앱 설정에 문제 항목을 체크리스트로 보여 주는 '점검' 화면 하나를 만들어 보세요.","en":"Build a check-up screen in your app's settings that shows issues as a checklist."}],"ask":{"ko":"Secret Key라는 번거로운 단계가 왜 신뢰를 오히려 높였을까요?","en":"Why did the extra step of a Secret Key raise trust instead of lowering it?"}},"Bird Alone":{"time":5,"setup":{"ko":"처음 부분은 무료이고 전체 게임은 $2.99 한 번 구매예요. 며칠에 걸쳐 매일 짧게 들러 보세요.","en":"The beginning is free and the full game is a one-time $2.99. Visit briefly every day over several days."},"missions":[{"do":{"ko":"오늘 새를 찾아가 짧게 대화하고, 내일 비슷한 시간에 다시 들러 보세요.","en":"Visit the bird today for a short talk, then come back around the same time tomorrow."},"wow":{"ko":"하루 몇 분씩 외로운 새와 죽음과 의미를 이야기해요. 가족을 잃은 개발자가 그 마음을 둘 곳으로 만든 게임이에요.","en":"A few minutes a day, you talk with a lonely bird about death and meaning. Its developer made it as a place for his feelings after losing a family member."}},{"do":{"ko":"새의 배를 손가락으로 문질러 보세요.","en":"Rub the bird's belly with your finger."},"wow":{"ko":"직접 만지는 터치에 새가 반응해, 화면 속에 정말 있는 것처럼 느껴져요.","en":"The bird responds to direct touch, so it feels physically present on the screen."}},{"do":{"ko":"며칠에 걸쳐 들르며 새와 계절이 어떻게 바뀌는지 보세요.","en":"Drop by over several days and watch how the bird and the seasons change."},"wow":{"ko":"실제 시간에 따라 새가 자라고 계절이 바뀌어요. 몰아서 하는 것보다 다시 오는 것을 보상해요.","en":"The bird grows and the seasons turn in real time, rewarding returning rather than bingeing."}},{"do":{"ko":"새와 함께 시를 쓰거나 그림을 그려 남겨 보세요.","en":"Write a poem or draw a picture with the bird and keep it."},"wow":{"ko":"관계가 갤러리에 남는 손에 잡히는 작품이 돼요.","en":"The relationship leaves tangible artifacts in a gallery of your creations."}}],"make":[{"ko":"내 앱에 하루 한 번만 열리는 짧은 대화나 콘텐츠 하나를 만들어 보세요.","en":"Build one short conversation or piece of content in your app that unlocks only once a day."},{"ko":"캐릭터를 손가락으로 문지르면 반응하는 제스처 애니메이션 프로토타입을 만들어 보세요.","en":"Prototype a character that reacts with animation when you rub it with a finger."}],"ask":{"ko":"하루 몇 분으로 제한한 게 왜 새와의 관계를 더 깊게 만들었을까요?","en":"Why did limiting play to a few minutes a day deepen the relationship with the bird?"}},"Genshin Impact":{"time":30,"setup":{"ko":"게임 컨트롤러가 있으면 터치 조작과 비교해 볼 수 있어요.","en":"A game controller, if you have one, lets you compare it with touch controls."},"missions":[{"do":{"ko":"처음 보이는 높은 절벽을 끝까지 올라가, 꼭대기에서 활공해 내려와 보세요.","en":"Climb the first tall cliff you see all the way up, then glide down from the top."},"wow":{"ko":"거의 어디든 오르고 날고 헤엄치는 끊김 없는 콘솔급 오픈월드가 폰에서 돌아가요. 6개월도 안 돼 모바일 매출 10억 달러를 넘겼어요.","en":"A seamless console-grade open world where you can climb, glide and swim almost anywhere runs on a phone. It passed $1 billion on mobile in under six months."}},{"do":{"ko":"전투 중에 물 원소 캐릭터로 공격한 뒤, 탭 한 번으로 불 원소 캐릭터로 바꿔 공격해 보세요.","en":"In combat, attack with a Hydro character, then tap once to swap to a Pyro character and attack."},"wow":{"ko":"원소 반응이 터져요. 복잡한 터치 콤보 없이 캐릭터 전환 한 번으로 전투에 깊이가 생겨요.","en":"An elemental reaction fires, adding depth with a single swap instead of complex touch combos."}},{"do":{"ko":"PC나 PlayStation에서 같은 계정으로 로그인해 이어서 해 보세요.","en":"Log in with the same account on PC or PlayStation and keep playing."},"wow":{"ko":"진행이 그대로 따라와요. 크로스 세이브로 어느 기기에서든 같은 모험을 이어 가요.","en":"Your progress follows you, with cross-save continuing the same adventure on any device."}}],"make":[{"ko":"내 앱의 두 기능을 이어 쓰면 보너스 효과가 나는 '반응' 규칙 하나를 프로토타입으로 만들어 보세요.","en":"Prototype one reaction rule where using two features in sequence triggers a bonus effect."},{"ko":"내 앱의 진행 상황을 CloudKit이나 iCloud 키값 저장소로 동기화해 다른 기기에서 이어지는지 확인해 보세요.","en":"Sync your app's progress with CloudKit or iCloud key-value storage and confirm it continues on another device."}],"ask":{"ko":"탭 한 번 캐릭터 전환이 왜 터치 화면에서 깊은 전투를 가능하게 했을까요?","en":"Why did a one-tap character swap make deep combat possible on a touchscreen?"}},"Shapr 3D":{"time":20,"setup":{"ko":"iPad 전용으로 안내돼 있어 iPad가 필요하고, Apple Pencil이 있어야 제대로 경험할 수 있어요.","en":"It is listed as iPad only, so you need an iPad, and an Apple Pencil to experience it properly."},"missions":[{"do":{"ko":"Apple Pencil로 사각형 하나를 그린 뒤, 손가락으로 위로 끌어 입체로 만들어 보세요.","en":"Draw a rectangle with Apple Pencil, then drag it upward with your finger into a solid."},"wow":{"ko":"메뉴 없이 펜과 손가락만으로 입체가 생겨요. 지멘스 산업용 커널 Parasolid를 클라우드 없이 iPad에서 돌린 최초의 CAD예요.","en":"A solid appears from pen and finger alone, no menus. It was the first CAD to run Siemens' industrial Parasolid kernel natively on iPad without the cloud."}},{"do":{"ko":"만든 모델을 3D 프린팅용이나 표준 CAD 형식으로 내보내 보세요.","en":"Export the model for 3D printing or to a standard CAD format."},"wow":{"ko":"iPad에서 그린 스케치가 곧바로 제조 흐름으로 넘어가요. 전문 CAD와 같은 급의 커널이라 정밀해요.","en":"An iPad sketch goes straight into manufacturing workflows, precise because it uses a professional-class kernel."}},{"do":{"ko":"Vision Pro가 있다면 같은 모델을 열어 내 공간에 실제 크기로 놓아 보세요.","en":"If you have a Vision Pro, open the same model and place it at real scale in your space."},"wow":{"ko":"CAD 모델을 실제 크기로 내 공간에서 검토해요.","en":"You review the CAD model at real scale in your own space."}}],"make":[{"ko":"내 앱의 생성 동작 하나를 메뉴 대신 그리고 끌어 올리는 두 동작 제스처로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype replacing one create action in your app with a two-step draw-then-pull gesture instead of a menu."},{"ko":"PencilKit 입력과 손가락 입력을 서로 다른 동작으로 나눠 받는 캔버스를 만들어 보세요.","en":"Build a canvas that treats Pencil input and finger input as different actions."}],"ask":{"ko":"펜은 그리고 손가락은 끌어 올리는 역할 분담이 왜 데스크톱 CAD의 메뉴를 대신할 수 있었을까요?","en":"Why could splitting roles, pen to draw and finger to pull, replace desktop CAD menus?"}},"AllTrails":{"time":15,"setup":{"ko":"실제 산책로 근처 야외에서 써 보면 유료 기능의 가치가 더 잘 느껴져요.","en":"Using it outdoors near a real trail makes the paid features' value clearer."},"missions":[{"do":{"ko":"근처 트레일 하나를 열고 오프라인 지도 다운로드를 눌러 어떤 화면이 나오는지 보세요.","en":"Open a nearby trail and tap offline map download to see what comes up."},"wow":{"ko":"신호가 끊기는 산속이라는 맥락 때문에 오프라인 지도의 가치가 바로 느껴져요. 유료 전환 지점이 가장 필요한 순간에 놓여 있어요.","en":"The no-signal mountain context makes the value of offline maps obvious, so the upgrade point sits exactly where you need it."}},{"do":{"ko":"트레일 하나를 열고 1분 안에 갈지 말지 정해 보세요.","en":"Open one trail and decide within a minute whether to go."},"wow":{"ko":"난이도, 거리, 고도, 소요 시간, 최근 리뷰와 사진이 한 화면에 있어 판단이 끝나요.","en":"Difficulty, distance, elevation, time, recent reviews and photos sit on one screen, so the decision is done."}},{"do":{"ko":"Apple Watch가 있다면 휴대폰을 꺼내지 않고 시계에서 기록을 시작해 보세요.","en":"If you have an Apple Watch, start recording from the watch without taking out your phone."},"wow":{"ko":"시계 앱으로 휴대폰 없이 기록할 수 있어요.","en":"The watch app lets you record without your phone."}}],"make":[{"ko":"내 앱의 유료 기능 하나를 사용자가 그 기능이 가장 필요한 순간에만 보이도록 위치를 옮겨 보세요.","en":"Move one paid feature in your app so it appears only at the moment users need it most."},{"ko":"목록 항목 하나에 판단에 필요한 핵심 정보 다섯 가지를 한 화면에 모은 상세 화면을 만들어 보세요.","en":"Build a detail screen that gathers the five key facts needed to decide on one list item."}],"ask":{"ko":"유료 기능을 산속이라는 맥락에 묶은 게 왜 거부감 없는 업셀이 됐을까요?","en":"Why did tying the paid feature to the mountain context make the upsell feel natural?"}},"Snapchat":{"time":10,"setup":{"ko":"친구 한 명과 함께 해 보면 스토리와 사라지는 공유의 느낌을 더 잘 알 수 있어요.","en":"Trying it with one friend makes Stories and disappearing shares easier to feel."},"missions":[{"do":{"ko":"앱을 열고, 피드를 찾기 전에 화면에 무엇이 먼저 뜨는지 보세요.","en":"Open the app and notice what appears first, before you look for any feed."},"wow":{"ko":"피드가 아니라 카메라가 바로 떠요. 보는 앱이 아니라 찍어서 보내는 앱이라는 걸 첫 화면이 말해요.","en":"The camera opens, not a feed. The first screen says this is an app for shooting and sending, not watching."}},{"do":{"ko":"카메라에 얼굴을 비추고 렌즈 하나를 골라 보세요.","en":"Point the camera at your face and pick a Lens."},"wow":{"ko":"찍기 전에 얼굴 인식 실시간 AR 효과로 먼저 놀게 돼요.","en":"Real-time face-tracking AR effects make you play before you even shoot."}},{"do":{"ko":"친구와 함께 스토리를 올리고 다음 날 다시 확인해 보세요.","en":"Post a Story with a friend and check it again the next day."},"wow":{"ko":"24시간 뒤 사라져요. 영구 게시물의 부담을 없앤 형식이에요.","en":"It disappears after 24 hours, a format that removes the weight of permanent posts."}},{"do":{"ko":"카메라 화면에서 위아래, 좌우로 스와이프해 보세요.","en":"Swipe up, down, left and right from the camera."},"wow":{"ko":"메뉴 대신 스와이프로 채팅, 스토리, 추억으로 이동해요. 처음엔 헤매지만 '우리끼리 아는 앱'의 매력이 돼요.","en":"Swipes, not menus, take you to chat, Stories and Memories. It is confusing at first, which becomes its insider charm."}}],"make":[{"ko":"내 앱의 첫 화면을 목록 대신 핵심 행동 하나(카메라, 입력 등)로 바꾼 시안을 만들어 보세요.","en":"Mock up your app's first screen as one core action, such as a camera or input, instead of a list."},{"ko":"일정 시간이 지나면 사라지는 게시물 하나를 만들고, 남은 시간을 표시하는 프로토타입을 만들어 보세요.","en":"Prototype a post that disappears after a set time and shows how much time is left."}],"ask":{"ko":"사라지는 게시물이 왜 사람들을 더 자주 공유하게 만들었을까요?","en":"Why did disappearing posts make people share more often?"}},"Microsoft Excel":{"time":15,"setup":null,"missions":[{"do":{"ko":"종이에 적거나 인쇄된 표를 카메라로 찍어 셀로 가져와 보세요.","en":"Photograph a handwritten or printed table and bring it into cells."},"wow":{"ko":"사진 속 표가 셀 데이터로 바뀌어요. 작은 화면 입력의 한계를 카메라로 메웠어요.","en":"The table in the photo becomes cell data, using the camera to get around the limits of typing on a small screen."}},{"do":{"ko":"셀 하나를 눌러 수식을 입력하면서 키보드 위를 보세요.","en":"Tap a cell, start typing a formula and look above the keyboard."},"wow":{"ko":"수식 입력줄과 숫자·함수 전용 키 행이 떠서, 작은 화면에서도 수식 입력 동선이 짧아요.","en":"A formula bar and a row of number and function keys appear, keeping formula entry short even on a small screen."}},{"do":{"ko":"셀 선택 핸들을 손가락으로 끌어 범위를 잡은 뒤 탭해 보세요.","en":"Drag the selection handle with your finger to select a range, then tap."},"wow":{"ko":"마우스 조작이 터치로 번역돼 잘라내기, 복사, 채우기 메뉴가 떠요.","en":"Mouse actions are translated into touch, bringing up cut, copy and fill."}},{"do":{"ko":"편집하다가 저장 버튼을 찾아보세요.","en":"While editing, look for a save button."},"wow":{"ko":"자동 저장과 실시간 공동 편집으로 파일 저장이라는 개념을 거의 숨겼어요.","en":"Autosave and real-time co-editing almost hide the idea of saving a file."}}],"make":[{"ko":"내 앱의 숫자 입력 필드에 자주 쓰는 기호와 단위 버튼을 담은 키보드 위 툴바를 붙여 보세요.","en":"Add a toolbar above the keyboard for a numeric field in your app with frequently used symbols and units."},{"ko":"VisionKit 문서 스캐너로 종이 표를 찍어 텍스트를 뽑아 목록에 넣는 프로토타입을 만들어 보세요.","en":"Prototype scanning a paper table with the VisionKit document scanner and putting the extracted text into a list."}],"ask":{"ko":"카메라로 표를 읽게 한 게 왜 모바일 스프레드시트의 판도를 바꿨을까요?","en":"Why did reading tables with the camera change what a mobile spreadsheet could be?"}},"Photoroom":{"time":10,"setup":{"ko":"고해상도 내보내기와 워터마크 제거 같은 기능은 Pro 구독이에요.","en":"Features like high-resolution export and watermark removal need a Pro subscription."},"missions":[{"do":{"ko":"책상 위 물건 하나를 찍거나 골라, 결과가 나올 때까지 몇 초인지 세어 보세요.","en":"Shoot or pick a photo of an object on your desk and count the seconds until the result appears."},"wow":{"ko":"고르는 순간 배경이 사라진 결과가 나와요. 핵심 가치인 누끼를 첫 사용 몇 초 안에 체험해요.","en":"The background is gone the moment you choose, so you feel the core value within seconds of first use."}},{"do":{"ko":"배경을 지운 사진에 AI 배경을 만들고 그림자를 넣어 보세요.","en":"Generate an AI background for the cut-out photo and add a shadow."},"wow":{"ko":"배경 제거 하나 위에 AI 배경, 그림자·조명 보정이 쌓여 금세 상품 사진이 돼요.","en":"On top of one background-removal feature, AI backgrounds and shadow and lighting fixes turn it into a product photo fast."}},{"do":{"ko":"마켓플레이스 규격 템플릿이나 크기 프리셋 하나를 골라 보세요.","en":"Pick a marketplace template or size preset."},"wow":{"ko":"판매자에게 맞춘 규격이 이미 준비돼 있어요.","en":"Sizes tailored to sellers are already there."}}],"make":[{"ko":"Vision의 전경 마스크 기능으로 사진 배경을 지우는 화면 하나를 프로토타입으로 만들어 보세요.","en":"Prototype a screen that removes a photo's background with Vision's foreground mask."},{"ko":"내 앱의 핵심 기능 결과를 첫 실행 10초 안에 보여 주도록 온보딩 순서를 바꿔 보세요.","en":"Reorder your app's onboarding so the core feature's result appears within ten seconds of first launch."}],"ask":{"ko":"결과를 몇 초 안에 보여 준 게 왜 유료 전환까지 이어졌을까요?","en":"Why did showing the result within seconds lead all the way to paid upgrades?"}},"밀리의 서재":{"time":15,"setup":{"ko":"구독 서비스라 해지 흐름은 실제 해지 직전까지만 따라가 보세요.","en":"It is a subscription, so follow the cancellation flow only up to the final step."},"missions":[{"do":{"ko":"책 하나를 챗북으로 열어 넘겨 보세요.","en":"Open a book as a chat book and scroll through it."},"wow":{"ko":"텍스트를 대화형으로 재구성해, 읽기 싫은 순간에도 메시지를 보듯 넘기게 돼요.","en":"Text is rebuilt as a conversation, so even when you do not feel like reading, you scroll it like messages."}},{"do":{"ko":"구독 해지를 눌러 최종 단계 직전까지 따라가며, 화면이 몇 번 붙잡는지 세어 보세요.","en":"Tap cancel subscription and follow it up to the last step, counting how many times it holds you back."},"wow":{"ko":"남은 혜택, 읽던 책, 할인 제안이 단계적으로 나와요. 국내 구독 서비스의 전형적인 해지 방어 패턴이에요.","en":"Remaining benefits, the book you were reading and a discount appear step by step, a typical Korean subscription retention pattern."}},{"do":{"ko":"내 서재와 완독 통계를 열어 보세요.","en":"Open your library and your finished-book stats."},"wow":{"ko":"쌓인 서재와 독서 기록이 해지할 때 잃을 것으로 느껴져요.","en":"Your built-up library and reading records start to feel like something you would lose by canceling."}}],"make":[{"ko":"내 앱의 긴 글 하나를 말풍선 대화 형식으로 바꾼 화면을 만들어 읽기 부담을 비교해 보세요.","en":"Turn one long text in your app into chat bubbles and compare how heavy it feels to read."},{"ko":"내 앱 해지나 탈퇴 직전에 사용자가 쌓은 기록을 보여 주는 화면 하나를 정직한 문구로 만들어 보세요.","en":"Build one honest screen before cancel or account deletion that shows the records the user has built up."}],"ask":{"ko":"쌓인 서재가 왜 할인 제안보다 강한 해지 방어가 될까요?","en":"Why might a built-up library hold subscribers more strongly than a discount offer?"}}}};
